function buildProductionToolCatalog() {
  return Object.fromEntries(
    Object.keys(toolHandlers || {}).map((toolName) => [toolName, true])
  );
}

function buildProductionLastAgentActions() {
  const actions = {};
  const completedTasks = [
    ...(Array.isArray(state.agentTasks) ? state.agentTasks : []),
    ...(Array.isArray(state.rexDecisions) ? state.rexDecisions : []),
    ...(Array.isArray(state.agentDecisions) ? state.agentDecisions : []),
  ];
  for (const item of completedTasks) {
    const agentId = normalizeAgentRosterId(
      item.agentId ||
        item.agent_id ||
        item.toAgent ||
        item.to_agent ||
        item.fromAgent ||
        item.from_agent ||
        item.agentName ||
        item.agent_name ||
        item.agent ||
        ''
    );
    if (!agentId) continue;
    const status = /fail|error|reject|denied|blocked/i.test(String(item.status || item.result || ''))
      ? 'failure'
      : 'success';
    const at = getItemTimestamp(item) || item.completedAt || item.updatedAt || item.createdAt || isoNow();
    const existing = actions[agentId];
    if (!existing || String(at).localeCompare(String(existing.at || '')) > 0) {
      actions[agentId] = { status, at };
    }
  }
  return actions;
}

function buildProductionAgentLatencySamples() {
  const samples = {};
  for (const record of Array.isArray(state.agentDecisions) ? state.agentDecisions : []) {
    const agentId = normalizeAgentRosterId(record.agentId || record.agent || record.agentName || '');
    const latency = Number(record.latencyMs || record.latency_ms || record.durationMs || record.duration_ms);
    if (!agentId || !Number.isFinite(latency)) continue;
    if (!samples[agentId]) samples[agentId] = [];
    samples[agentId].push(latency);
  }
  for (const record of [
    ...(Array.isArray(state.agentTasks) ? state.agentTasks : []),
    ...(Array.isArray(state.rexDecisions) ? state.rexDecisions : []),
  ]) {
    const metadata = record.metadata && typeof record.metadata === 'object' ? record.metadata : {};
    const agentId = normalizeAgentRosterId(
      record.agentId ||
        record.agent_id ||
        record.toAgent ||
        record.to_agent ||
        record.fromAgent ||
        record.from_agent ||
        record.agent ||
        record.agentName ||
        ''
    );
    const latency = Number(
      record.latencyMs ||
        record.latency_ms ||
        record.durationMs ||
        record.duration_ms ||
        metadata.latencyMs ||
        metadata.latency_ms ||
        metadata.durationMs ||
        metadata.duration_ms
    );
    if (!agentId || !Number.isFinite(latency)) continue;
    if (!samples[agentId]) samples[agentId] = [];
    samples[agentId].push(latency);
  }
  return samples;
}

function buildProductionTruthGateFromRuntime({
  runtimeMeta = getRuntimeMeta(),
  actionType = 'status',
  identity = null,
  conversation = null,
  senderIdentity = null,
  requireConversation = false,
  requireSkills = false,
  requireTurnContract = false,
} = {}) {
  const latestContext = state.status?.pbkIntelligenceContext || {};
  const lead =
    identity ||
    latestContext.identity ||
    (Array.isArray(state.leads) ? state.leads[0] : null) ||
    {};
  return buildProductionTruthGate({
    runtimeMeta,
    identity: lead,
    conversation: conversation || latestContext.conversation || {},
    memory: latestContext.memory || { ready: Boolean(state.status?.memoryReady) },
    skills: latestContext.skills || { ready: Boolean(state.status?.skillsReady) },
    turnContract: latestContext.turnContract || { ok: true },
    senderIdentity,
    providers: runtimeMeta.providers || {},
    actionType,
    requireConversation,
    requireSkills,
    requireTurnContract,
  });
}

async function buildProductionReadinessSnapshot({
  runtimeMeta = getRuntimeMeta(),
  health = null,
  actionType = 'status',
} = {}) {
  ensureAgentFleetCollections();
  const commandCenterHealth = health || (await buildCommandCenterHealthSnapshot(runtimeMeta));
  const intelligenceContext = state.status?.pbkIntelligenceContext || {
    memory: { ready: Boolean(state.status?.pbkIntelligenceReadiness?.required?.memory) },
    skills: { ready: Boolean(state.status?.pbkIntelligenceReadiness?.required?.skills) },
    dataFreshness: { ready: Boolean(state.status?.pbkIntelligenceReadiness?.required?.dataFreshness) },
    fleetReadiness: { ready: Boolean(state.status?.pbkIntelligenceReadiness?.ready) },
  };
  const capabilityReadiness = buildAgentCapabilityReadiness({
    agents: state.agents || [],
    toolCatalog: buildProductionToolCatalog(),
    intelligenceContext,
    latencySamples: buildProductionAgentLatencySamples(),
    lastActions: buildProductionLastAgentActions(),
    requireIntelligenceContext: false,
  });
  const stableAgentFleetMeasurement = buildStableAgentFleetMeasurement(getCurrentAgentRegistry(), {
    healthProbes: (state.agents || []).map(buildAgentHealthProbe),
    toolCatalog: buildProductionToolCatalog(),
    intelligenceContext,
    latencySamples: buildProductionAgentLatencySamples(),
    lastActions: buildProductionLastAgentActions(),
  });
  const bridgeConnection = buildBridgeConnectionStatus({
    runtimeMeta,
    health: commandCenterHealth,
  });
  const truthGate = buildProductionTruthGateFromRuntime({
    runtimeMeta,
    actionType,
    requireConversation: false,
    requireSkills: false,
    requireTurnContract: false,
  });
  const slo = productionReadinessMonitor.getSloStatus();
  const maturity = buildProductionMaturitySnapshot({ runtimeMeta });
  return {
    ok: true,
    result:
      bridgeConnection.ready && capabilityReadiness.ready && stableAgentFleetMeasurement.ready && truthGate.ready && maturity.summary.ready
        ? 'production_readiness_ready'
        : 'production_readiness_review',
    checkedAt: isoNow(),
    bridgeConnection,
    truthGate,
    slo,
    maturity,
    idempotency: productionIdempotencyStore.status(),
    agentCapabilityReadiness: capabilityReadiness,
    stableAgentFleetMeasurement,
    summary: {
      ready:
        bridgeConnection.ready &&
        truthGate.ready &&
        capabilityReadiness.ready &&
        stableAgentFleetMeasurement.ready &&
        maturity.summary.ready &&
        slo.burned.length === 0,
      blockers: [
        ...bridgeConnection.blockers.map((item) => `bridge:${item}`),
        ...truthGate.blockers.map((item) => `truth:${item}`),
        ...capabilityReadiness.degraded.map((item) => `agent:${item.id}:${item.blockedReasons[0] || 'degraded'}`),
        ...stableAgentFleetMeasurement.blockers.map((item) => `measurement:${item}`),
        ...maturity.summary.blockers.map((item) => `maturity:${item}`),
        ...slo.burned.map((item) => `slo:${item}`),
      ],
    },
  };
}

function hashString(value = '') {
  let hash = 0;
  const normalized = String(value || 'pbk').trim();
  for (let index = 0; index < normalized.length; index += 1) {
    hash = (hash * 31 + normalized.charCodeAt(index)) % 2147483647;
  }
  return Math.abs(hash || 1);
}

function jsonStringify(value) {
  return JSON.stringify(value, null, 2);
}

function sanitizeJsonForPostgres(value) {
  if (typeof value === 'string') return value.replace(/\u0000/g, '');
  if (typeof value === 'bigint') return value.toString();
  if (Array.isArray(value)) return value.map((item) => sanitizeJsonForPostgres(item));
  if (value instanceof Date) return value.toISOString();
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, nested]) => [
        key.replace(/\u0000/g, ''),
        sanitizeJsonForPostgres(nested),
      ])
    );
  }
  return value;
}

function postgresJsonStringify(value) {
  return JSON.stringify(sanitizeJsonForPostgres(value));
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function withTimeout(promise, ms, label = 'operation') {
  let timer = null;
  return Promise.race([
    promise,
    new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
    }),
  ]).finally(() => {
    if (timer) clearTimeout(timer);
  });
}

let openClawGatewayStatusCache = null;
let openClawGatewayStatusCheckedAt = 0;
let openClawGatewayStatusPromise = null;

function normalizeGatewayProbeSnapshot(value = {}) {
  const source = value && typeof value === 'object' ? value : {};
  return {
    ok: Boolean(source.ok || source.ready),
    configured: source.configured !== false,
    url: redactGatewayUrl(source.url || source.endpoint || ''),
    latencyMs: Number.isFinite(Number(source.latencyMs)) ? Number(source.latencyMs) : null,
    status: Number.isFinite(Number(source.status)) ? Number(source.status) : 0,
    readyState: Number.isFinite(Number(source.readyState)) ? Number(source.readyState) : null,
    service: String(source.service || '').slice(0, 80),
    revision: String(source.revision || '').slice(0, 80),
    error: String(source.error || '').slice(0, 240),
  };
}

function getOpenClawGatewayHeartbeat() {
  const heartbeat = state?.status?.openClawGatewayHeartbeat;
  return heartbeat && typeof heartbeat === 'object' ? heartbeat : null;
}

function getFreshOpenClawGatewayHeartbeat() {
  const heartbeat = getOpenClawGatewayHeartbeat();
  if (!heartbeat) return null;
  const receivedAt = Date.parse(heartbeat.receivedAt || heartbeat.checkedAt || heartbeat.reportedAt || '');
  if (!Number.isFinite(receivedAt)) return null;
  const ageMs = Date.now() - receivedAt;
  return {
    ...heartbeat,
    ageMs,
    fresh: ageMs >= 0 && ageMs <= OPENCLAW_GATEWAY_HEARTBEAT_MAX_AGE_MS,
  };
}

function buildOpenClawGatewayHeartbeat(body = {}, request = null) {
  const now = Date.now();
  const reportedAtMs = Date.parse(body.checkedAt || body.generatedAt || body.reportedAt || '') || now;
  const http = normalizeGatewayProbeSnapshot(body.http || body.local?.http || {});
  const websocket = normalizeGatewayProbeSnapshot(body.websocket || body.local?.websocket || {});
  const ready = Boolean(body.ready ?? body.ok ?? http.ok ?? websocket.ok);
  const hostname = String(body.host || body.hostname || body.machine || '')
    .trim()
    .slice(0, 120);
  return {
    ok: ready,
    ready,
    status: ready ? 'up' : 'degraded',
    source: String(body.source || 'openclaw-heartbeat')
      .trim()
      .slice(0, 80),
    host: hostname || 'local-openclaw',
    mode: String(body.mode || 'local')
      .trim()
      .slice(0, 40),
    receivedAt: new Date(now).toISOString(),
    reportedAt: new Date(reportedAtMs).toISOString(),
    reporterPid: Number.isFinite(Number(body.pid)) ? Number(body.pid) : null,
    platform: String(body.platform || '')
      .trim()
      .slice(0, 80),
    gatewayUrl: redactGatewayUrl(body.gatewayUrl || body.url || body.endpoint || ''),
    http,
    websocket,
    runtime: {
      uptimeSeconds: Number.isFinite(Number(body.runtime?.uptimeSeconds)) ? Number(body.runtime.uptimeSeconds) : null,
      memory:
        body.runtime?.memory && typeof body.runtime.memory === 'object'
          ? {
              rss: Number(body.runtime.memory.rss || 0),
              heapUsed: Number(body.runtime.memory.heapUsed || 0),
              heapTotal: Number(body.runtime.memory.heapTotal || 0),
            }
          : null,
    },
    note: ready ? `Local OpenClaw heartbeat from ${hostname || 'local machine'} is fresh.` : `Local OpenClaw heartbeat from ${hostname || 'local machine'} reported degraded.`,
    remoteAddress: request?.socket?.remoteAddress ? String(request.socket.remoteAddress).slice(0, 80) : '',
  };
}

async function recordOpenClawGatewayHeartbeat(body = {}, request = null) {
  const previous = getFreshOpenClawGatewayHeartbeat();
  const heartbeat = buildOpenClawGatewayHeartbeat(body, request);
  state.status.openClawGatewayHeartbeat = heartbeat;
  openClawGatewayStatusCache = null;
  openClawGatewayStatusCheckedAt = 0;
  const previousReady = Boolean(previous?.fresh && previous?.ready);
  const previousLoggedAt = Date.parse(state.status.openClawGatewayHeartbeatLoggedAt || '');
  const shouldLogHeartbeat = !previous || previousReady !== heartbeat.ready || !Number.isFinite(previousLoggedAt) || Date.now() - previousLoggedAt > 15 * 60 * 1000;
  if (shouldLogHeartbeat) {
    state.status.openClawGatewayHeartbeatLoggedAt = heartbeat.receivedAt;
    addActivity(
      state,
      makeActivity({
        actor: 'OpenClaw heartbeat',
        category: 'SYSTEM',
        status: heartbeat.ready ? 'complete' : 'warning',
        text: heartbeat.ready ? `Local OpenClaw gateway heartbeat received from ${heartbeat.host}.` : `Local OpenClaw gateway heartbeat reported degraded from ${heartbeat.host}.`,
        target: 'openclaw-gateway',
      })
    );
  }
  persistStateInBackground('openclaw-gateway-heartbeat');
  return heartbeat;
}

function redactGatewayUrl(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const parsed = new URL(raw);
    parsed.username = '';
    parsed.password = '';
    for (const key of ['token', 'api_key', 'apikey', 'key', 'auth', 'authorization']) {
      parsed.searchParams.delete(key);
    }
    return parsed.toString().replace(/\/+$/g, '');
  } catch {
    return raw.replace(/(token|api_key|apikey|key|auth|authorization)=([^&\s]+)/gi, '$1=[redacted]');
  }
}

function isLoopbackGatewayUrl(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return false;
  try {
    const parsed = new URL(raw);
    const hostname = parsed.hostname.replace(/^\[|\]$/g, '').toLowerCase();
    return hostname === 'localhost' || hostname === '::1' || hostname === '0:0:0:0:0:0:0:1' || hostname === '0.0.0.0' || /^127(?:\.\d{1,3}){0,3}$/.test(hostname);
  } catch {
    return /\b(?:localhost|127(?:\.\d{1,3}){0,3}|0\.0\.0\.0|\[?::1\]?)\b/i.test(raw);
  }
}

function shouldSkipHostedGatewayProbe(value = '') {
  return Boolean(IS_HOSTED && isLoopbackGatewayUrl(value));
}

function isOpenClawDirectGatewayConfigured() {
  return Boolean(buildGatewayWsUrl() || buildGatewayHttpUrl());
}

function buildGatewayWsUrl() {
  const raw = OPENCLAW_GATEWAY_URL || '';
  if (!raw) return '';
  if (shouldSkipHostedGatewayProbe(raw)) return '';
  if (/^https?:\/\//i.test(raw)) {
    return raw.replace(/^http:/i, 'ws:').replace(/^https:/i, 'wss:');
  }
  return raw;
}

function buildGatewayHttpUrl() {
  const explicit = OPENCLAW_GATEWAY_HTTP_URL || '';
  if (explicit) return shouldSkipHostedGatewayProbe(explicit) ? '' : explicit;
  const wsUrl = buildGatewayWsUrl();
  if (!wsUrl) return '';
  if (/^wss?:\/\//i.test(wsUrl)) {
    return wsUrl.replace(/^ws:/i, 'http:').replace(/^wss:/i, 'https:');
  }
  return '';
}

async function fetchGatewayProbe(url, timeoutMs = OPENCLAW_GATEWAY_PROBE_TIMEOUT_MS) {
  const startedAt = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: OPENCLAW_GATEWAY_TOKEN ? { Authorization: `Bearer ${OPENCLAW_GATEWAY_TOKEN}` } : {},
      signal: controller.signal,
    });
    const contentType = response.headers.get('content-type') || '';
    const body = contentType.includes('json') ? await response.json().catch(() => null) : await response.text().catch(() => '');
    return {
      ok: response.ok,
      status: response.status,
      latencyMs: Date.now() - startedAt,
      bodyKind: contentType.includes('json') ? 'json' : 'text',
      service: typeof body === 'object' && body ? body.service || body.name || '' : '',
      revision: typeof body === 'object' && body ? body.revision || body.version || '' : '',
    };
  } catch (error) {
    return {
      ok: false,
      status: 0,
      latencyMs: Date.now() - startedAt,
      error: error?.name === 'AbortError' ? `timeout_${timeoutMs}ms` : error?.message || String(error),
    };
  } finally {
    clearTimeout(timer);
  }
}

async function probeOpenClawGatewayHttp(timeoutMs = OPENCLAW_GATEWAY_PROBE_TIMEOUT_MS) {
  const base = buildGatewayHttpUrl();
  if (!base) {
    return { ok: false, configured: false, error: 'OPENCLAW_GATEWAY_HTTP_URL not configured' };
  }
  const candidates = ['/health', '/status', '/api/health', '/api/status', ''].map((suffix) => `${base}${suffix}`).filter(Boolean);
  const attempts = await Promise.all(
    candidates.map(async (url) => ({
      url: redactGatewayUrl(url),
      ...(await fetchGatewayProbe(url, timeoutMs)),
    }))
  );
  const winner = attempts.find((result) => result.ok);
  if (winner) {
    return {
      ok: true,
      configured: true,
      url: winner.url,
      latencyMs: winner.latencyMs,
      status: winner.status,
      service: winner.service,
      revision: winner.revision,
      attempts: attempts.slice(0, 3),
    };
  }
  const last = attempts.at(-1) || {};
  return {
    ok: false,
    configured: true,
    url: redactGatewayUrl(base),
    latencyMs: Number(last.latencyMs || 0),
    status: Number(last.status || 0),
    error: last.error || 'gateway_http_probe_failed',
    attempts: attempts.slice(0, 3),
  };
}

function probeOpenClawGatewaySocket(timeoutMs = OPENCLAW_GATEWAY_WS_HANDSHAKE_TIMEOUT_MS) {
  const wsUrl = buildGatewayWsUrl();
  if (!wsUrl) {
    return Promise.resolve({
      ok: false,
      configured: false,
      error: 'OPENCLAW_GATEWAY_URL not configured',
    });
  }
  return new Promise((resolve) => {
    const startedAt = Date.now();
    let settled = false;
    let socket = null;
    const finish = (result = {}) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try {
        socket?.terminate?.();
      } catch {
        // Best-effort probe cleanup only.
      }
      resolve({
        configured: true,
        url: redactGatewayUrl(wsUrl),
        latencyMs: Date.now() - startedAt,
        ...result,
      });
    };
    const timer = setTimeout(() => {
      finish({
        ok: false,
        readyState: socket?.readyState ?? WebSocket.CLOSED,
        error: `handshake_timeout_${timeoutMs}ms`,
      });
    }, timeoutMs);

    try {
      socket = new WebSocket(wsUrl, {
        headers: OPENCLAW_GATEWAY_TOKEN ? { Authorization: `Bearer ${OPENCLAW_GATEWAY_TOKEN}` } : {},
        handshakeTimeout: timeoutMs,
      });
      socket.once('open', () => {
        if (OPENCLAW_GATEWAY_TOKEN) {
          try {
            socket.send(JSON.stringify({ type: 'connect', token: OPENCLAW_GATEWAY_TOKEN }));
          } catch {
            // Token send is non-fatal; a successful WebSocket handshake is the connectivity signal.
          }
        }
        finish({ ok: true, readyState: WebSocket.OPEN });
      });
      socket.once('error', (error) => {
        finish({
          ok: false,
          readyState: socket?.readyState ?? WebSocket.CLOSED,
          error: error?.message || String(error),
        });
      });
      socket.once('close', (code, reason) => {
        if (settled) return;
        finish({
          ok: false,
          readyState: WebSocket.CLOSED,
          closeCode: code,
          error: String(reason || '').trim() || `closed_${code || 'unknown'}`,
        });
      });
    } catch (error) {
      finish({ ok: false, readyState: WebSocket.CLOSED, error: error?.message || String(error) });
    }
  });
}

async function buildOpenClawGatewayStatus({ force = false, timeoutMs = OPENCLAW_GATEWAY_PROBE_TIMEOUT_MS } = {}) {
  const now = Date.now();
  if (!force && openClawGatewayStatusCache && now - openClawGatewayStatusCheckedAt < OPENCLAW_GATEWAY_STATUS_TTL_MS) {
    return openClawGatewayStatusCache;
  }
  if (openClawGatewayStatusPromise) return openClawGatewayStatusPromise;

  openClawGatewayStatusPromise = (async () => {
    const httpTimeoutMs = Math.max(1000, Math.min(timeoutMs, OPENCLAW_GATEWAY_PROBE_TIMEOUT_MS));
    const wsTimeoutMs = Math.max(5000, Math.min(OPENCLAW_GATEWAY_WS_HANDSHAKE_TIMEOUT_MS, timeoutMs * 2));
    const directProbeConfigured = isOpenClawDirectGatewayConfigured();
    const [http, websocket] = directProbeConfigured
      ? await Promise.all([probeOpenClawGatewayHttp(httpTimeoutMs), probeOpenClawGatewaySocket(wsTimeoutMs)])
      : [
          {
            ok: false,
            configured: false,
            skipped: true,
            reason: 'heartbeat_only',
            note: 'Direct HTTP probe disabled; local OpenClaw reports through outbound heartbeat.',
          },
          {
            ok: false,
            configured: false,
            skipped: true,
            reason: 'heartbeat_only',
            note: 'Direct WebSocket probe disabled; local OpenClaw reports through outbound heartbeat.',
          },
        ];
    const heartbeat = getFreshOpenClawGatewayHeartbeat();
    const heartbeatReady = Boolean(heartbeat?.fresh && heartbeat?.ready);
    const directReady = Boolean(http.ok || websocket.ok);
    const ready = Boolean(directReady || heartbeatReady);
    const heartbeatOnlyNote = 'Heartbeat-only mode: hosted Render does not dial local OpenClaw; waiting for the local outbound heartbeat.';
    const directNote = directReady ? `${websocket.ok ? 'WebSocket' : 'HTTP'} gateway responded in ${Math.min(Number(websocket.latencyMs || Infinity), Number(http.latencyMs || Infinity))}ms.` : directProbeConfigured ? `${websocket.error || http.error || 'OpenClaw gateway did not respond'}; direct probe unavailable.` : heartbeatOnlyNote;
    const note = directReady ? directNote : heartbeatReady ? `Local OpenClaw heartbeat from ${heartbeat.host || 'local machine'} is fresh (${Math.round(heartbeat.ageMs / 1000)}s old); hosted direct probe is unavailable.` : directNote;
    const status = {
      ok: ready,
      ready,
      configured: Boolean(directProbeConfigured || heartbeat || IS_HOSTED),
      optional: true,
      directProbeConfigured,
      connectionMode: directReady ? 'direct_probe' : heartbeatReady ? 'outbound_heartbeat' : directProbeConfigured ? 'direct_probe_unavailable' : 'heartbeat_only',
      checkedAt: isoNow(),
      mode: RUNTIME_MODE,
      timeoutMs: OPENCLAW_TIMEOUT_MS,
      handshakeTimeoutMs: OPENCLAW_GATEWAY_WS_HANDSHAKE_TIMEOUT_MS,
      heartbeatIntervalMs: OPENCLAW_GATEWAY_HEARTBEAT_INTERVAL_MS,
      heartbeatTimeoutMs: OPENCLAW_GATEWAY_HEARTBEAT_TIMEOUT_MS,
      heartbeatMaxAgeMs: OPENCLAW_GATEWAY_HEARTBEAT_MAX_AGE_MS,
      tokenConfigured: Boolean(OPENCLAW_GATEWAY_TOKEN),
      websocket,
      http,
      heartbeat: heartbeat
        ? {
            ready: heartbeat.ready,
            fresh: heartbeat.fresh,
            ageMs: heartbeat.ageMs,
            host: heartbeat.host,
            mode: heartbeat.mode,
            source: heartbeat.source,
            receivedAt: heartbeat.receivedAt,
            reportedAt: heartbeat.reportedAt,
            platform: heartbeat.platform,
            gatewayUrl: heartbeat.gatewayUrl,
            http: heartbeat.http,
            websocket: heartbeat.websocket,
            note: heartbeat.note,
          }
        : null,
      note,
      runtime: {
        uptimeSeconds: Math.round(process.uptime()),
        memory: process.memoryUsage(),
      },
      runtimeWebSocket: {
        clients: runtimeBrowserSockets.size,
        heartbeatIntervalMs: OPENCLAW_GATEWAY_HEARTBEAT_INTERVAL_MS,
        heartbeatTimeoutMs: OPENCLAW_GATEWAY_HEARTBEAT_TIMEOUT_MS,
        lastOpenAt: runtimeWebSocketStats.lastOpenAt,
        lastMessageAt: runtimeWebSocketStats.lastMessageAt,
        lastCloseAt: runtimeWebSocketStats.lastCloseAt,
        staleTerminations: runtimeWebSocketStats.staleTerminations,
      },
    };
    openClawGatewayStatusCache = status;
    openClawGatewayStatusCheckedAt = Date.now();
    return status;
  })();

  try {
    return await openClawGatewayStatusPromise;
  } finally {
    openClawGatewayStatusPromise = null;
  }
}

function getOpenClawGatewayHealthComponent() {
  const cached = openClawGatewayStatusCache;
  const heartbeat = getFreshOpenClawGatewayHeartbeat();
  const directProbeConfigured = isOpenClawDirectGatewayConfigured();
  const heartbeatReady = Boolean(heartbeat?.fresh && heartbeat?.ready);
  const heartbeatOnlyConfigured = Boolean(IS_HOSTED && !directProbeConfigured);
  const configured = Boolean(directProbeConfigured || heartbeat || heartbeatOnlyConfigured);
  if (!cached) {
    return {
      label: 'OpenClaw brain gateway',
      status: heartbeatReady ? 'up' : directProbeConfigured ? 'unknown' : 'standby',
      ready: heartbeatReady,
      configured,
      optional: true,
      directProbeConfigured,
      connectionMode: heartbeatReady ? 'outbound_heartbeat' : directProbeConfigured ? 'direct_probe_pending' : 'heartbeat_only',
      endpoint: heartbeat?.gatewayUrl || redactGatewayUrl(OPENCLAW_GATEWAY_URL || OPENCLAW_GATEWAY_HTTP_URL),
      note: configured ? (heartbeatReady ? `Fresh local heartbeat is available from ${heartbeat.host || 'local machine'}; call /api/gateway/status for details.` : directProbeConfigured ? 'Gateway probe has not run yet. Call /api/gateway/status or open the dashboard to force a probe.' : 'Heartbeat-only mode: local OpenClaw reports outbound to Render; direct Render-to-local dialing is disabled.') : 'Heartbeat-only mode: local OpenClaw reports outbound to Render; direct Render-to-local dialing is disabled.',
    };
  }
  const cachedDirectProbeConfigured = Boolean(cached.directProbeConfigured || cached.websocket?.configured || cached.http?.configured);
  return {
    label: 'OpenClaw brain gateway',
    status: cached.ready ? 'up' : cachedDirectProbeConfigured ? 'degraded' : 'standby',
    ready: cached.ready,
    configured: cached.configured,
    optional: true,
    directProbeConfigured: cachedDirectProbeConfigured,
    connectionMode: cached.connectionMode || (cached.ready ? 'outbound_heartbeat' : cachedDirectProbeConfigured ? 'direct_probe_unavailable' : 'heartbeat_only'),
    endpoint: cached.heartbeat?.gatewayUrl || cached.websocket?.url || cached.http?.url || redactGatewayUrl(OPENCLAW_GATEWAY_URL || OPENCLAW_GATEWAY_HTTP_URL),
    checkedAt: cached.checkedAt,
    latencyMs: cached.websocket?.ok ? cached.websocket.latencyMs : cached.http?.ok ? cached.http.latencyMs : cached.heartbeat?.websocket?.latencyMs || cached.heartbeat?.http?.latencyMs,
    heartbeatAgeMs: cached.heartbeat?.ageMs ?? heartbeat?.ageMs ?? null,
    note: cached.note,
  };
}

function shouldReturnGatewayStatusOk(gatewayStatus = {}) {
  if (gatewayStatus.ready) return true;
  const directProbeConfigured = Boolean(gatewayStatus.websocket?.configured || gatewayStatus.http?.configured);
  return Boolean(gatewayStatus.optional || !directProbeConfigured);
}

function getSecurityMeta() {
  return {
    bridgeBearerRequired: Boolean(BRIDGE_API_KEY),
    hostedBridgeAuthFailClosed: HOSTED_BRIDGE_AUTH_MISCONFIGURED,
    allowUnauthenticatedHostedBridge: ALLOW_UNAUTHENTICATED_HOSTED_BRIDGE,
    totpRequired: TOTP_REQUIRED,
    totpConfigured: Boolean(TOTP_SECRET),
    totpEnrolled: Boolean(state?.settings?.security?.totpEnrolledAt),
    totpEnrollmentAvailable: Boolean(TOTP_SECRET && !TOTP_REQUIRED),
    protectedOpsPasscodeConfigured: Boolean(PROTECTED_OPS_PASSCODE),
    teamPasscodeConfigured: Boolean(TEAM_PASSCODE),
    teamApprovalLimit: TEAM_APPROVAL_LIMIT,
    teamSessionTtlMs: TEAM_SESSION_TTL_MS,
    providerWritesApprovalGated: getRuntimeOperatingMode() !== 'autopilot',
    voicePrewarmEnabled: VOICE_PREWARM_ENABLED,
    publicAvaChatEnabled: PUBLIC_AVA_CHAT_ENABLED,
    publicAvaChatExplicitlyConfigured: PUBLIC_AVA_CHAT_ENABLED_CONFIGURED,
    publicAvaChatKeyRequired: Boolean(PUBLIC_AVA_CHAT_KEY),
  };
}

function safeCompareString(left = '', right = '') {
  const leftBuffer = Buffer.from(String(left || ''));
  const rightBuffer = Buffer.from(String(right || ''));
  if (!leftBuffer.length || leftBuffer.length !== rightBuffer.length) return false;
  return timingSafeEqual(leftBuffer, rightBuffer);
}

function verifyExternalWebhookRequest(request) {
  const bearer = String(request.headers?.authorization || '')
    .replace(/^Bearer\s+/i, '')
    .trim();
  const providedSecret = String(request.headers?.['x-pbk-webhook-secret'] || request.headers?.['x-webhook-secret'] || request.headers?.['x-pbk-signature'] || '').trim();

  if (BRIDGE_API_KEY && bearer && safeCompareString(bearer, BRIDGE_API_KEY)) {
    return { ok: true, method: 'bridge-bearer' };
  }
  if (EXTERNAL_WEBHOOK_SECRET && providedSecret && safeCompareString(providedSecret, EXTERNAL_WEBHOOK_SECRET)) {
    return { ok: true, method: 'webhook-secret' };
  }
  if (!IS_HOSTED && !BRIDGE_API_KEY && !EXTERNAL_WEBHOOK_SECRET) {
    return { ok: true, method: 'local-dev-open' };
  }
  return {
    ok: false,
    error: EXTERNAL_WEBHOOK_SECRET || BRIDGE_API_KEY ? 'External webhook authentication failed.' : 'Set PBK_EXTERNAL_WEBHOOK_SECRET or PBK_BRIDGE_API_KEY before enabling external webhooks.',
  };
}

function isTeamPasscodeValid(passcode = '') {
  const candidate = String(passcode || '').trim();
  return Boolean(TEAM_PASSCODE && candidate && safeCompareString(candidate, TEAM_PASSCODE));
}

function getTeamSessionSecret() {
  return `${BRIDGE_API_KEY || 'local-bridge'}:${TEAM_PASSCODE || 'no-team-passcode'}`;
}

function signTeamSessionPayload(payload = '') {
  return createHmac('sha256', getTeamSessionSecret()).update(payload).digest('base64url');
}

function createTeamSessionToken({ actor = 'PBK team', role = 'team' } = {}) {
  const expiresAt = Date.now() + TEAM_SESSION_TTL_MS;
  const payload = Buffer.from(
    JSON.stringify({
      role,
      actor: String(actor || 'PBK team').slice(0, 80),
      expiresAt,
      nonce: randomUUID(),
    })
  ).toString('base64url');
  const signature = signTeamSessionPayload(payload);
  return {
    token: `${payload}.${signature}`,
    expiresAt: new Date(expiresAt).toISOString(),
    ttlMs: TEAM_SESSION_TTL_MS,
  };
}

function verifyTeamSessionToken(token = '') {
  const value = String(token || '').trim();
  const [payload, signature] = value.split('.');
  if (!payload || !signature) return { ok: false, error: 'missing_team_session' };
  if (!safeCompareString(signature, signTeamSessionPayload(payload))) {
    return { ok: false, error: 'invalid_team_session' };
  }
  let decoded = null;
  try {
    decoded = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
  } catch {
    return { ok: false, error: 'invalid_team_session_payload' };
  }
  if (!decoded?.expiresAt || Number(decoded.expiresAt) < Date.now()) {
    return { ok: false, error: 'expired_team_session' };
  }
  return {
    ok: true,
    role: decoded.role || 'team',
    actor: decoded.actor || 'PBK team',
    expiresAt: new Date(Number(decoded.expiresAt)).toISOString(),
  };
}

function hasTeamAuthCredentials(request = {}, body = {}) {
  return Boolean(
    request.headers?.['x-pbk-team-token']
    || request.headers?.['x-team-token']
    || request.headers?.['x-pbk-team-passcode']
    || request.headers?.['x-team-passcode']
    || body.teamToken
    || body.team_token
    || body.teamPasscode
    || body.team_passcode
    || body.teamAuthRequired === true
    || body.requireTeamAuth === true
  );
}

function getTeamAuthMeta(request = {}, body = {}) {
  const headerToken = String(request.headers?.['x-pbk-team-token'] || request.headers?.['x-team-token'] || '').trim();
  const bodyToken = String(body?.teamToken || body?.team_token || '').trim();
  const token = headerToken || bodyToken;
  if (token) {
    const verified = verifyTeamSessionToken(token);
    if (verified.ok) return { ...verified, source: 'session-token' };
  }
  const headerPasscode = String(request.headers?.['x-pbk-team-passcode'] || request.headers?.['x-team-passcode'] || '').trim();
  const bodyPasscode = String(body?.teamPasscode || body?.team_passcode || '').trim();
  if (isTeamPasscodeValid(headerPasscode || bodyPasscode)) {
    return {
      ok: true,
      role: 'team',
      actor: body?.actor || 'PBK team',
      source: 'passcode',
      expiresAt: new Date(Date.now() + TEAM_SESSION_TTL_MS).toISOString(),
    };
  }
  return {
    ok: false,
    source: 'none',
    error: TEAM_PASSCODE ? 'team_auth_required' : 'team_passcode_not_configured',
  };
}

function getTeamPermissions() {
  return {
    canViewLeads: true,
    canCreateCampaignDrafts: true,
    canApproveRoutineOffers: true,
    canApproveProviderActions: !/^(0|false|no|off)$/i.test(String(process.env.PBK_TEAM_CAN_APPROVE_PROVIDER_ACTIONS || 'true').trim()),
    canApproveOfferUpTo: TEAM_APPROVAL_LIMIT,
    canPlaceCalls: !/^(0|false|no|off)$/i.test(String(process.env.PBK_TEAM_CAN_PLACE_CALLS || 'true').trim()),
    canSendSms: !/^(0|false|no|off)$/i.test(String(process.env.PBK_TEAM_CAN_SEND_SMS || 'true').trim()),
    canSendEmail: !/^(0|false|no|off)$/i.test(String(process.env.PBK_TEAM_CAN_SEND_EMAIL || 'true').trim()),
    canSendContracts: false,
    canDeleteLeads: !/^(0|false|no|off)$/i.test(String(process.env.PBK_TEAM_CAN_DELETE_LEADS || 'true').trim()),
    canDeleteData: false,
    canChangeGuardrails: false,
    canManageSkills: /^(1|true|yes|on)$/i.test(String(process.env.PBK_TEAM_CAN_MANAGE_SKILLS || '').trim()),
    canToggleKillSwitch: false,
  };
}

function authorizeDirectTeamBridgeRequest({
  method = 'GET',
  pathname = '',
  body = {},
  permissions = {},
} = {}) {
  const normalizedMethod = String(method || 'GET').toUpperCase();
  const normalizedPath = String(pathname || '').toLowerCase();
  const toolName = String(body.toolName || body.tool || body.name || '').trim();
  const normalizedToolName = toolName.toLowerCase();
  const confirmedLeadDelete =
    normalizedMethod === 'DELETE' &&
    /^\/api\/leads\/[^/]+$/.test(normalizedPath) &&
    String(body.reason || body.deleteReason || '').trim() === 'operator_confirmed_delete';

  const deny = (permission, action) => ({
    ok: false,
    statusCode: 403,
    error: `This PBK team session is not permitted to ${action}.`,
    code: 'team_permission_denied',
    permission,
  });

  if (confirmedLeadDelete && permissions.canDeleteLeads !== true) {
    return deny('canDeleteLeads', 'delete confirmed leads');
  }

  if (normalizedMethod === 'DELETE' && !confirmedLeadDelete && permissions.canDeleteData !== true) {
    return deny('canDeleteData', 'delete PBK data');
  }

  const contractTool = /^(?:sendcontract|senddocusign|prepare_and_send_contract|preparecontract|sendnegotiationapproval)$/i.test(toolName);
  const contractRoute =
    normalizedMethod !== 'GET' &&
    (
      /(?:contract|docusign|document-deliver)/.test(normalizedPath) ||
      normalizedPath === '/api/underwriting/sign'
    );
  if ((contractTool || contractRoute) && permissions.canSendContracts !== true) {
    return deny('canSendContracts', 'send or modify contracts');
  }

  const smsTool = /^(?:telnyx_sms|send_verification_sms)$/i.test(toolName);
  const smsRoute =
    normalizedMethod !== 'GET' &&
    /(?:\/api\/messages|\/api\/conversation|\/api\/conversations|\/api\/sms|\/api\/inbox)/.test(normalizedPath) &&
    /sms|message|conversation|inbox/.test(normalizedPath);
  if ((smsTool || smsRoute) && permissions.canSendSms !== true) {
    return deny('canSendSms', 'send SMS messages');
  }

  const emailTool = /^(?:sendcoldemail|pbk_send_update)$/i.test(toolName);
  const emailRoute =
    normalizedMethod !== 'GET' &&
    /(?:\/api\/cold-email|\/api\/messages|\/api\/conversation|\/api\/conversations|\/api\/email|\/api\/inbox)/.test(normalizedPath) &&
    /email|message|conversation|inbox/.test(normalizedPath);
  if ((emailTool || emailRoute) && permissions.canSendEmail !== true) {
    return deny('canSendEmail', 'send emails');
  }

  const callTool = /^(?:telnyx_call|pbk_call_operator)$/i.test(toolName);
  const callRoute =
    normalizedMethod !== 'GET' &&
    /(?:\/api\/calls|\/api\/operator\/call|\/api\/call)/.test(normalizedPath);
  if ((callTool || callRoute) && permissions.canPlaceCalls !== true) {
    return deny('canPlaceCalls', 'place calls');
  }

  const killSwitchTool = /^(?:pbk_kill_switch|killswitch|togglekillswitch)$/i.test(toolName);
  const killSwitchRoute =
    normalizedMethod !== 'GET' && /(?:kill-switch|killswitch)/.test(normalizedPath);
  if ((killSwitchTool || killSwitchRoute) && permissions.canToggleKillSwitch !== true) {
    return deny('canToggleKillSwitch', 'change the PBK kill switch');
  }

  const skillGovernanceTool =
    /^(?:approveskillversion|activateskillversion|rollbackskillactivation|createskillcandidate|reloadskills|ingestskill)$/i.test(toolName);
  const skillGovernanceRoute =
    normalizedMethod !== 'GET' &&
    /(?:\/api\/skills\/(?:candidates|ingest|import-from-article|versions\/[^/]+\/(?:approve|activate)|activations\/[^/]+\/rollback|reload|outcomes)(?:\/|$))/.test(normalizedPath);
  if ((skillGovernanceTool || skillGovernanceRoute) && permissions.canManageSkills !== true) {
    return deny('canManageSkills', 'manage Ava skills and governance');
  }

  const guardrailTool =
    /^(?:admin_update_env_var|admin_restart_openclaw|admin_run_away_worker|routeadmincommand|requestadminaction)$/i.test(toolName) ||
    /^admin_/.test(normalizedToolName);
  const guardrailRoute =
    normalizedMethod !== 'GET' &&
    /(?:\/api\/admin(?:\/|$)|\/api\/auth\/totp|\/api\/settings(?:\/|$)|\/api\/guardrails|\/api\/desktop-sidecar\/command)/.test(normalizedPath);
  if ((guardrailTool || guardrailRoute) && permissions.canChangeGuardrails !== true) {
    return deny('canChangeGuardrails', 'change infrastructure or security guardrails');
  }

  return { ok: true, statusCode: 200 };
}

function getTeamApprovalRestriction(approval = {}, status = '', permissions = getTeamPermissions()) {
  const normalizedStatus = String(status || '')
    .toLowerCase()
    .replace(/-/g, '_');
  if (normalizedStatus !== 'approved') return null;
  const type = String(approval.type || approval.approvalAction || '').toLowerCase();
  const action = String(approval.approvalAction || approval.action || '').toLowerCase();
  const amount = Math.max(toNumber(approval.offerPrice, 0), toNumber(approval.amount, 0), toNumber(approval.metadata?.offerPrice, 0));
  if (amount > TEAM_APPROVAL_LIMIT) {
    return `Offer is ${currency(amount)}, above the team limit of ${currency(TEAM_APPROVAL_LIMIT)}. Admin approval required.`;
  }
  if (/(contract|docusign|admin|kill|delete|campaign|prompt|rex-decision|nurture|local_command|executelocalcommand|desktop|sidecar|automation)/i.test(`${type} ${action}`)) {
    return 'This approval can trigger a contract, provider write, admin change, campaign, or prompt application. Admin approval required.';
  }
  if (
    /(provider|outbound|sms|email|call|send)/i.test(`${type} ${action}`) &&
    permissions.canApproveProviderActions !== true
  ) {
    return 'This approval can trigger a provider write. Admin approval required.';
  }
  return null;
}

function isDemoRuntimeApproval(approval = {}) {
  const source = String(approval.source || approval.fixture || approval.kind || approval.importSource || '').toLowerCase();
  const text = [approval.id, approval.taskId, approval.leadId, approval.leadName, approval.address, approval.title, approval.description, approval.notes, approval.fileName, approval.templateName, approval.type].filter(Boolean).join(' ');
  return source.includes('demo') || source.includes('fixture') || /approval-offer-202-cherry|approval-contract-robert-chen|approval-batch-akron|lead-diane-kowalski|lead-robert-chen|daily_probate_import\.csv|Diane Kowalski|Robert Chen|Akron Probate Batch|202 Cherry Ln|55 Birch Rd/i.test(text);
}

function isPendingRuntimeApproval(approval = {}) {
  return String(approval?.status || '').toLowerCase() === 'pending' && !isDemoRuntimeApproval(approval);
}

function getPendingRuntimeApprovals(approvals = []) {
  return (Array.isArray(approvals) ? approvals : []).filter(isPendingRuntimeApproval);
}

function getPendingAdminTasks(adminTasks = []) {
  return (Array.isArray(adminTasks) ? adminTasks : []).filter((task) => String(task?.status || '').toLowerCase() === 'pending');
}

function decodeBase32Secret(secret = '') {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const normalized = String(secret || '')
    .toUpperCase()
    .replace(/^OTPAUTH:\/\/[^?]+\?/i, '')
    .replace(/.*SECRET=([^&]+).*/i, '$1')
    .replace(/[^A-Z2-7]/g, '');
  let bits = '';
  for (const char of normalized) {
    const value = alphabet.indexOf(char);
    if (value < 0) continue;
    bits += value.toString(2).padStart(5, '0');
  }
  const bytes = [];
  for (let index = 0; index + 8 <= bits.length; index += 8) {
    bytes.push(parseInt(bits.slice(index, index + 8), 2));
  }
  return Buffer.from(bytes);
}

function generateTotpCode(secret = TOTP_SECRET, counter = Math.floor(Date.now() / 30000)) {
  const key = decodeBase32Secret(secret);
  if (!key.length) return '';
  const counterBuffer = Buffer.alloc(8);
  counterBuffer.writeUInt32BE(Math.floor(counter / 0x100000000), 0);
  counterBuffer.writeUInt32BE(counter >>> 0, 4);
  const hmac = createHmac('sha1', key).update(counterBuffer).digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const value = ((hmac[offset] & 0x7f) << 24) | ((hmac[offset + 1] & 0xff) << 16) | ((hmac[offset + 2] & 0xff) << 8) | (hmac[offset + 3] & 0xff);
  return String(value % 1000000).padStart(6, '0');
}

function verifyTotpCode(token = '', secret = TOTP_SECRET, windowSize = TOTP_WINDOW) {
  const normalized = String(token || '').replace(/\s+/g, '');
  if (!/^\d{6}$/.test(normalized) || !secret) return false;
  const currentCounter = Math.floor(Date.now() / 30000);
  for (let offset = -windowSize; offset <= windowSize; offset += 1) {
    const candidate = generateTotpCode(secret, currentCounter + offset);
    if (!candidate) continue;
    const left = Buffer.from(candidate);
    const right = Buffer.from(normalized);
    if (left.length === right.length && timingSafeEqual(left, right)) return true;
  }
  return false;
}

function getTotpEnrollmentPayload() {
  const secret = String(TOTP_SECRET || '')
    .toUpperCase()
    .replace(/^OTPAUTH:\/\/[^?]+\?/i, '')
    .replace(/.*SECRET=([^&]+).*/i, '$1')
    .replace(/[^A-Z2-7]/g, '');
  const issuer = 'PBK Command Center';
  const account = 'operator';
  const label = `${issuer}:${account}`;
  return {
    configured: Boolean(secret),
    required: TOTP_REQUIRED,
    enrolled: Boolean(state?.settings?.security?.totpEnrolledAt),
    issuer,
    account,
    secret,
    otpauthUrl: secret ? `otpauth://totp/${encodeURIComponent(label)}?secret=${encodeURIComponent(secret)}&issuer=${encodeURIComponent(issuer)}&algorithm=SHA1&digits=6&period=30` : '',
    manualEntry: secret ? secret.replace(/(.{4})/g, '$1 ').trim() : '',
  };
}

function requiresTotpForPath(pathname = '') {
  if (!TOTP_REQUIRED) return false;
  return pathname.startsWith('/api/admin') || matchesPath(pathname, ['/api/operator/call', '/api/ava/call-operator', '/api/safety/kill-switch', '/api/provider-writes/kill-switch', '/api/admin/request', '/api/admin/route', '/api/local-callback/trigger', '/api/v1/local-callback/trigger']);
}

function enforceTotp(request, response, pathname = '') {
  if (!requiresTotpForPath(pathname)) return false;
  if (!TOTP_SECRET) {
    json(response, 503, {
      ok: false,
      error: 'TOTP is required but PBK_TOTP_SECRET is not configured.',
    });
    return true;
  }
  const token = String(request.headers['x-pbk-totp'] || request.headers['x-otp'] || '').trim();
  if (!verifyTotpCode(token)) {
    json(response, 401, {
      ok: false,
      error: 'TOTP verification required.',
      hint: 'Send the current 6-digit code in X-PBK-TOTP for protected admin/operator actions.',
    });
    return true;
  }
  return false;
}

function escapeHtml(value = '') {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function parseJsonObjectEnv(raw = '') {
  const value = String(raw || '').trim();
  if (!value) return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function normalizeStageToken(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
}

function toReadableStageName(value = '') {
  const normalized = normalizeStageToken(value);
  if (!normalized) return '';
  const special = {
    dnc: 'DNC',
  };
  if (special[normalized]) return special[normalized];
  return normalized
    .split('-')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function safeFilename(value = '') {
  return String(value || 'PBK_Document')
    .replace(/[^a-z0-9_-]+/gi, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 90);
}

function getLocalChromePath() {
  const candidates = ['C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', 'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe'];

  return candidates.find((candidate) => {
    try {
      return Boolean(candidate && existsSync(candidate));
    } catch {
      return false;
    }
  });
}

async function launchPdfBrowserWithRetry() {
  let lastError = null;

  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      const localChromePath = getLocalChromePath();
      return await puppeteer.launch({
        args: chromium.args,
        defaultViewport: chromium.defaultViewport,
        executablePath: localChromePath || (await chromium.executablePath()),
        headless: 'new',
      });
    } catch (error) {
      lastError = error;
      if (attempt < 3) {
        await sleep(800);
      }
    }
  }

  throw lastError;
}

