async function persistActivityLogRecords(entries = []) {
  if (!Array.isArray(entries) || entries.length === 0) return false;
  const pool = getPgPool();
  if (!pool) return false;
  const seen = new Set();
  const activityLogBatchSize = Math.max(
    1,
    Math.min(50, Number(process.env.PBK_ACTIVITY_LOG_BATCH_SIZE || 25))
  );
  const uniqueEntries = entries
    .filter((entry) => entry?.id && !seen.has(entry.id) && seen.add(entry.id))
    .slice(0, activityLogBatchSize);
  if (!uniqueEntries.length) return false;
  const values = [];
  const rows = uniqueEntries.map((entry, index) => {
    const createdAt = entry.at || entry.createdAt || entry.created_at || isoNow();
    const metadata = {
      ...entry,
      leadId: entry.leadId || entry.lead_id || '',
      leadName: entry.leadName || entry.lead_name || '',
      address: entry.address || '',
      target: entry.target || '',
    };
    values.push(
      entry.id,
      entry.workspaceId || entry.workspace_id || 'pbk',
      entry.leadId || entry.lead_id || null,
      entry.leadName || entry.lead_name || '',
      entry.address || '',
      entry.actor || 'System',
      entry.category || 'INFO',
      entry.status || 'success',
      entry.text || '',
      entry.target || '',
      entry.source || 'runtime',
      JSON.stringify(metadata),
      createdAt,
      entry.updatedAt || entry.updated_at || isoNow()
    );
    const offset = index * 14;
    return `($${offset + 1},$${offset + 2},$${offset + 3},$${offset + 4},$${offset + 5},$${offset + 6},$${offset + 7},$${offset + 8},$${offset + 9},$${offset + 10},$${offset + 11},$${offset + 12}::jsonb,$${offset + 13},$${offset + 14})`;
  });
  try {
    await ensureActivityLogSchema(pool);
    await pool.query(
      `INSERT INTO public.activity_log (
        id, workspace_id, lead_id, lead_name, address, actor, category, status,
        text, target, source, metadata, created_at, updated_at
      )
      VALUES ${rows.join(',')}
      ON CONFLICT (id) DO UPDATE SET
        workspace_id = EXCLUDED.workspace_id,
        lead_id = EXCLUDED.lead_id,
        lead_name = EXCLUDED.lead_name,
        address = EXCLUDED.address,
        actor = EXCLUDED.actor,
        category = EXCLUDED.category,
        status = EXCLUDED.status,
        text = EXCLUDED.text,
        target = EXCLUDED.target,
        source = EXCLUDED.source,
        metadata = EXCLUDED.metadata,
        updated_at = EXCLUDED.updated_at`,
      values
    );
    return true;
  } catch (error) {
    if (!activityLogPersistenceWarned) {
      console.warn('[pbk-local-openclaw] activity_log batch persistence skipped:', error?.message || error);
      activityLogPersistenceWarned = true;
    }
    return false;
  }
}

function buildStatePersistenceDiagnostics(nextState = {}, serialized = '', error = null, phase = 'query') {
  const topLevelCounts = {};
  if (nextState && typeof nextState === 'object') {
    for (const [key, value] of Object.entries(nextState)) {
      if (Array.isArray(value)) topLevelCounts[key] = value.length;
      else if (value && typeof value === 'object') topLevelCounts[key] = Object.keys(value).length;
    }
  }
  return {
    ok: !error,
    phase,
    code: String(error?.code || error?.name || ''),
    error: error ? String(error?.message || error).slice(0, 500) : '',
    byteLength: serialized ? Buffer.byteLength(serialized, 'utf8') : 0,
    topLevelCounts,
    postgresReady: getPostgresHealthMeta().ready,
    checkedAt: isoNow(),
  };
}

function isTransientPostgresStatePersistError(error = null) {
  const code = String(error?.code || error?.name || '').trim();
  const message = String(error?.message || error || '');
  return (
    ['57P01', '57P02', '57P03', '53300', '08000', '08001', '08003', '08004', '08006', '08007', '08P01', 'ECONNRESET', 'ETIMEDOUT', 'EPIPE'].includes(code) ||
    /not yet accepting connections|terminating connection|connection terminated|connection ended unexpectedly|timeout|too many connections/i.test(message)
  );
}

function getStatePersistRetryAttempts() {
  return Math.max(1, Math.min(8, Number(process.env.PBK_STATE_PERSIST_RETRY_ATTEMPTS || (IS_HOSTED ? 5 : 1))));
}

function getStatePersistRetryDelayMs(attempt = 1) {
  const base = Math.max(50, Math.min(1000, Number(process.env.PBK_STATE_PERSIST_RETRY_BASE_MS || 250)));
  return Math.min(3000, base * Math.max(1, 2 ** (Number(attempt || 1) - 1)));
}

async function persistStateToDb(nextState) {
  const pool = getPgPool();
  if (!pool) return false;
  let serialized = '';
  let attempt = 0;
  const maxAttempts = getStatePersistRetryAttempts();
  try {
    serialized = postgresJsonStringify(nextState);
    for (attempt = 1; attempt <= maxAttempts; attempt += 1) {
      try {
        await pool.query(
          `INSERT INTO bridge_state (id, data, updated_at)
           VALUES ('singleton', $1::jsonb, NOW())
           ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, updated_at = NOW()`,
          [serialized]
        );
        break;
      } catch (error) {
        if (attempt >= maxAttempts || !isTransientPostgresStatePersistError(error)) throw error;
        await sleep(getStatePersistRetryDelayMs(attempt));
      }
    }
    await persistActivityLogRecords(nextState.activity || []);
    markPostgresHealth(true);
    lastStateDbPersist = buildStatePersistenceDiagnostics(nextState, serialized, null, 'query');
    lastStateDbPersist.retryAttempts = attempt;
    runtimeStateProvenance.source = 'render-postgres';
    runtimeStateProvenance.loadedFrom ||= 'render-postgres';
    runtimeStateProvenance.fallbackReason = '';
    runtimeStateProvenance.lastPersistAt = isoNow();
    return true;
  } catch (error) {
    lastStateDbPersist = buildStatePersistenceDiagnostics(
      nextState,
      serialized,
      error,
      serialized ? 'query' : 'serialize'
    );
    lastStateDbPersist.retryAttempts = attempt || 1;
    lastStateDbPersist.retryable = isTransientPostgresStatePersistError(error);
    markPostgresHealth(false, error?.message || error);
    if (!stateDbPersistWarned) {
      console.warn('[pbk-local-openclaw] postgres state persist unavailable; hosted state requires Postgres:', error?.message || error);
      stateDbPersistWarned = true;
    }
    return false;
  }
}

async function ensureRuntimeDir() {
  await mkdir(RUNTIME_DIR, { recursive: true });
}

async function loadStateFromRuntimeFile() {
  try {
    const raw = await readFile(STATE_FILE, 'utf8');
    return hydrateState(JSON.parse(raw));
  } catch {
    return null;
  }
}

async function persistState(nextState) {
  clearBridgeReadCache('persist_state');
  nextState.status.lastUpdatedAt = isoNow();
  updateDerivedStatus(nextState);
  if (DATABASE_URL) {
    const persisted = await persistStateToDb(nextState);
    if (persisted) {
      scheduleRuntimeStateBroadcast('persist');
      return;
    }
    runtimeStateProvenance.source = 'render-postgres-unavailable';
    runtimeStateProvenance.fallbackReason =
      getPostgresHealthMeta().error ||
      lastStateDbLoad.error ||
      'Render Postgres state persistence is required and unavailable.';
    runtimeStateProvenance.lastPersistAt = isoNow();
    const error = new Error('postgres_state_persist_required');
    error.code = 'postgres_state_persist_required';
    error.details = {
      reason: runtimeStateProvenance.fallbackReason,
      lastStateDbPersist,
      lastStateDbLoad,
    };
    throw error;
  }
  await ensureRuntimeDir();
  await writeFile(STATE_FILE, jsonStringify(nextState), 'utf8');
  runtimeStateProvenance.source = 'local-bridge-state';
  runtimeStateProvenance.loadedFrom ||= runtimeStateProvenance.source;
  runtimeStateProvenance.fallbackReason = '';
  runtimeStateProvenance.lastPersistAt = isoNow();
  scheduleRuntimeStateBroadcast('persist');
}

function persistStateInBackground(context = 'background') {
  void persistState(state).catch((error) => {
    console.warn(
      `[pbk-local-openclaw] ${context} state persist failed:`,
      error?.message || error
    );
  });
}

