async function loadApprovalRecordsFromPg({ statusFilter = '', limit = 60 } = {}) {
  const normalizedStatus = String(statusFilter || '').trim().toLowerCase();
  const params = [Math.max(1, Math.min(200, Number(limit) || 60))];
  const where = ["COALESCE(workspace_id, 'pbk') = 'pbk'"];
  if (normalizedStatus) {
    params.push(normalizedStatus);
    where.push(`LOWER(status) = $${params.length}`);
  }
  const result = await queryPgRows(
    `SELECT
       id,
       workspace_id AS "workspaceId",
       type,
       status,
       lead_id AS "leadId",
       contract_id AS "contractId",
       requested_by AS "requestedBy",
       summary,
       risk,
       payload,
       decided_at AS "decidedAt",
       created_at AS "createdAt",
       updated_at AS "updatedAt"
     FROM public.approvals
     WHERE ${where.join(' AND ')}
     ORDER BY updated_at DESC, created_at DESC
     LIMIT $1`,
    params
  );
  if (!result.ok) return result;
  return {
    ok: true,
    rows: result.rows.map(normalizePgApprovalRecord),
  };
}

async function backfillContractRecordsToPg(contracts = state.contracts || []) {
  const records = Array.isArray(contracts) ? contracts.filter((contract) => contract?.id) : [];
  let persisted = 0;
  const failures = [];
  for (let index = 0; index < records.length; index += 25) {
    const batch = records.slice(index, index + 25);
    const results = await Promise.all(batch.map((contract) => persistContractRecordToPg(contract)));
    results.forEach((result, resultIndex) => {
      if (result.ok) {
        persisted += 1;
      } else {
        failures.push({
          id: String(batch[resultIndex]?.id || ''),
          reason: result.error || result.reason || 'contract_persistence_failed',
        });
      }
    });
  }
  return {
    ok: failures.length === 0,
    result: failures.length ? 'contract_backfill_partial' : 'contract_backfill_completed',
    total: records.length,
    persisted,
    failed: failures.length,
    failures: failures.slice(0, 20),
  };
}

