async function loadContractRecordsFromPg({ statusFilter = 'all', limit = 200 } = {}) {
  const normalizedStatus = String(statusFilter || 'all').trim().toLowerCase();
  const params = [Math.max(1, Math.min(500, Number(limit) || 200))];
  const where = ["COALESCE(workspace_id, 'pbk') = 'pbk'"];
  if (normalizedStatus && normalizedStatus !== 'all') {
    params.push(normalizedStatus);
    where.push(
      `(LOWER(status) = $${params.length} OR
        CASE
          WHEN LOWER(status) IN ('void', 'voided', 'cancelled', 'canceled', 'rejected') THEN 'void'
          WHEN LOWER(status) IN ('funded', 'closed') THEN 'funded'
          WHEN LOWER(status) IN ('completed', 'signed') THEN 'signed'
          WHEN LOWER(status) IN ('viewed', 'opened', 'review', 'reviewing', 'updated') THEN 'viewed'
          WHEN LOWER(status) IN ('sent', 'delivered') THEN 'sent'
          ELSE 'draft'
        END = $${params.length})`
    );
  }
  const result = await queryPgRows(
    `SELECT
       id,
       lead_id AS "leadId",
       workspace_id AS "workspaceId",
       amount::float AS amount,
       selected_path AS "selectedPath",
       selected_path_label AS "selectedPathLabel",
       timeline,
       earnest_deposit AS "earnestDeposit",
       status,
       provider,
       envelope_id AS "envelopeId",
       document_title AS "documentTitle",
       preview_url AS "previewUrl",
       pdf_url AS "pdfUrl",
       master_package_query AS "masterPackageQuery",
       pdf_generated_at AS "pdfGeneratedAt",
       notes,
       approval_id AS "approvalId",
       template_id AS "templateId",
       template_fields AS "templateFields",
       template_field_map AS "templateFieldMap",
       contract_path AS "contractPath",
       contract_type AS "contractType",
       template_path AS "templatePath",
       template_file AS "templateFile",
       negotiation_file AS "negotiationFile",
       negotiation_prompt AS "negotiationPrompt",
       underwriting_status AS "underwritingStatus",
       underwriting_reviewer_email AS "underwritingReviewerEmail",
       underwriting_reviewer_name AS "underwritingReviewerName",
       seller_notice AS "sellerNotice",
       payload,
       created_at AS "createdAt",
       updated_at AS "updatedAt"
     FROM public.contracts
     WHERE ${where.join(' AND ')}
     ORDER BY updated_at DESC, created_at DESC
     LIMIT $1`,
    params
  );
  if (!result.ok) return result;
  return {
    ok: true,
    rows: result.rows.map(normalizePgContractRecord),
  };
}

async function upsertContract(stateRef, contract) {
  const existingIndex = stateRef.contracts.findIndex((item) => item.id === contract.id);
  const nextContract =
    existingIndex >= 0
      ? {
          ...stateRef.contracts[existingIndex],
          ...contract,
          updatedAt: isoNow(),
        }
      : contract;
  const persistence = await persistContractRecordToPg(nextContract);
  if (!persistence.ok && persistence.reason !== 'no_database') {
    throw new Error(
      `Contract persistence failed: ${persistence.error || persistence.reason || 'unknown_error'}`
    );
  }
  if (existingIndex >= 0) {
    stateRef.contracts.splice(existingIndex, 1, nextContract);
  } else {
    stateRef.contracts.unshift(nextContract);
  }
  limitStateArrays(stateRef);
  updateDerivedStatus(stateRef);
  return nextContract;
}

function findLeadContext(params = {}) {
  const allowImplicitContext =
    params.allowImplicitContext === true ||
    params.allow_implicit_context === true ||
    params.useActiveCallContext === true;
  const fallbackImport = allowImplicitContext ? state.leadImports[0] || {} : {};
  const fallbackApproval = allowImplicitContext ? state.approvals[0] || {} : {};
  const fallbackCall = allowImplicitContext
    ? state.calls.find((call) => isActiveLiveCall(call)) || state.calls[0] || {}
    : {};
  const explicitLeadId = String(params.leadId || params.lead_id || '').trim();
  const explicitPhone = normalizePhone(params.phone || params.to || params.number);
  const explicitLeadName = getSpokenLeadName(params.leadName || params.name || '');
  const explicitAddress = String(params.address || '').trim();
  const hasExplicitContext = Boolean(explicitLeadId || explicitPhone || explicitLeadName || explicitAddress);
  const explicitIdentifiers = {
    leadId: explicitLeadId,
    phone: explicitPhone,
    leadName: explicitLeadName,
    address: explicitAddress,
    email: params.email || '',
  };
  const matchedLeadImport = hasExplicitContext ? (state.leadImports || []).find((lead) => leadMatchesIdentifiers(lead, explicitIdentifiers)) || null : null;
  const matchedCall = hasExplicitContext
    ? (state.calls || []).find((call) =>
        leadMatchesIdentifiers(
          {
            id: call.id,
            leadId: call.leadId,
            leadName: call.leadName,
            phone: call.phone,
            address: call.address,
          },
          explicitIdentifiers
        )
      ) || null
    : null;
  const matchedApproval = hasExplicitContext
    ? (state.approvals || []).find((approval) =>
        leadMatchesIdentifiers(
          {
            id: approval.id,
            leadId: approval.leadId,
            leadName: approval.leadName,
            phone: approval.phone,
            address: approval.address,
          },
          explicitIdentifiers
        )
      ) || null
    : null;
  const derivedLeadId = hasExplicitContext ? `lead-${slugify(`${explicitLeadName || 'seller'}-${explicitAddress || explicitPhone || 'manual'}`)}` : '';
  const matchedLeadName = getSpokenLeadName(matchedLeadImport?.seller?.name || matchedLeadImport?.leadName || matchedLeadImport?.name || matchedCall?.leadName || matchedApproval?.leadName || '');
  const matchedAddress = matchedLeadImport?.property?.address || matchedLeadImport?.address || matchedCall?.address || matchedApproval?.address || '';
  const matchedPhone = normalizePhone(matchedLeadImport?.seller?.phone || matchedLeadImport?.phone || matchedCall?.phone || matchedApproval?.phone || '');
  const matchedEmail = matchedLeadImport?.seller?.email || matchedLeadImport?.email || matchedApproval?.email || '';
  const fallback = {
    leadId:
      explicitLeadId ||
      matchedLeadImport?.leadId ||
      matchedLeadImport?.id ||
      matchedCall?.leadId ||
      matchedApproval?.leadId ||
      derivedLeadId ||
      (hasExplicitContext
        ? ''
        : fallbackApproval.leadId || fallbackImport.leadId || fallbackCall.leadId) ||
      '',
    leadName: explicitLeadName || matchedLeadName || (hasExplicitContext ? '' : fallbackApproval.leadName || fallbackImport?.seller?.name || fallbackCall.leadName || 'Unknown seller'),
    address: explicitAddress || matchedAddress || (hasExplicitContext ? '' : fallbackApproval.address || fallbackImport?.property?.address || fallbackCall.address || 'Unknown property'),
    phone: explicitPhone || matchedPhone || (hasExplicitContext ? '' : normalizePhone(fallbackCall.phone) || normalizePhone(fallbackImport?.seller?.phone) || ''),
    email: params.email || matchedEmail || (hasExplicitContext ? '' : fallbackImport?.seller?.email || ''),
  };
  return fallback;
}

function getRecentLeadActivity(context = {}, explicitActivity = '') {
  if (explicitActivity) {
    return String(explicitActivity)
      .split('\n')
      .map((item) => item.trim())
      .filter(Boolean)
      .slice(0, 5);
  }
  const search = [context.leadId, context.leadName, context.address].filter(Boolean).join(' ').toLowerCase();
  return (state.activity || [])
    .filter((item) => {
      if (!search) return true;
      const haystack = [item.leadId, item.leadName, item.target, item.address, item.text, item.category].filter(Boolean).join(' ').toLowerCase();
      return haystack.includes(context.leadId || '__no_lead__') || (context.leadName && haystack.includes(String(context.leadName).toLowerCase().split(/\s+/)[0])) || (context.address && haystack.includes(String(context.address).toLowerCase().split(',')[0]));
    })
    .slice(0, 5)
    .map((item) => `${item.category || 'Activity'}: ${item.text || item.target || 'Runtime event'}`);
}

function compactObject(input = {}) {
  return Object.fromEntries(Object.entries(input || {}).filter(([, value]) => value !== undefined));
}

function plainRecord(value = {}) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function hasRecordValues(value = {}) {
  return Object.keys(plainRecord(value)).length > 0;
}

function normalizeLeadLookupValue(value = '') {
  return String(value || '').trim();
}

function uniqueLeadLookupValues(values = [], transform = (value) => String(value || '').trim()) {
  return [...new Set(values.map(transform).filter(Boolean))];
}

function findLeadImportByLookup(value = '') {
  const raw = normalizeLeadLookupValue(value);
  if (!raw) return null;
  let decoded = raw;
  try {
    decoded = decodeURIComponent(raw);
  } catch {
    decoded = raw;
  }
  const normalized = decoded.toLowerCase();
  const addressKey = normalizeAddressKey(decoded);
  return (
    (state.leadImports || []).find((lead) => {
      const addressValues = [lead.property?.address, lead.address, lead.propertyAddress, lead.property_address];
      const phoneValues = [lead.seller?.phone, lead.phone];
      const candidates = [lead.id, lead.leadId, lead.importId, lead.externalId, lead.external_id, lead.seller?.email, lead.email, lead.seller?.phone, lead.phone, lead.seller?.name, lead.leadName, lead.name, lead.property?.address, lead.address, lead.propertyAddress, lead.property_address, ...phoneValues.map((item) => normalizePhone(item)), ...addressValues.map((item) => slugify(item || '')), ...addressValues.map((item) => normalizeAddressKey(item || ''))].filter(Boolean).map((item) =>
        String(item || '')
          .trim()
          .toLowerCase()
      );
      return candidates.includes(normalized) || (addressKey && candidates.includes(addressKey));
    }) || null
  );
}

function searchLeadImports(params = {}) {
  const query = String(params.query || params.search || params.q || params.text || '')
    .trim()
    .toLowerCase();
  const status = String(params.status || '')
    .trim()
    .toLowerCase();
  const minScore = params.minScore ?? params.min_score;
  const minScoreNumber = minScore === undefined || minScore === '' ? null : toNumber(minScore, 0);
  const limit = Math.max(1, Math.min(100, toNumber(params.limit, 25)));
  const tokens = query
    .replace(/[^a-z0-9+\s@.-]+/g, ' ')
    .split(/\s+/)
    .map((item) => item.trim())
    .filter((item) => item.length >= 2);
  const leads = (state.leadImports || []).filter((lead) => {
    const leadStatus = String(lead.status || lead.stage || lead.pipelineStatus || '').toLowerCase();
    const score = toNumber(lead.motivationScore ?? lead.score ?? lead.leadScore ?? lead.aiScore, 0);
    const haystack = [lead.id, lead.leadId, lead.importId, lead.seller?.name, lead.leadName, lead.name, lead.seller?.phone, lead.phone, lead.seller?.email, lead.email, lead.property?.address, lead.address, lead.propertyAddress, lead.property_address, lead.status, lead.stage, lead.tags].flat().filter(Boolean).join(' ').toLowerCase();
    const queryMatch = !tokens.length || tokens.every((token) => haystack.includes(token));
    const statusMatch = !status || leadStatus === status || leadStatus.includes(status);
    const scoreMatch = minScoreNumber === null || score >= minScoreNumber;
    return queryMatch && statusMatch && scoreMatch;
  });
  return {
    ok: true,
    result: 'live',
    query,
    count: leads.length,
    leads: sortNewest(leads).slice(0, limit),
  };
}

const FUZZY_LEAD_LOOKUP_CACHE_TTL_MS = 30_000;
const FUZZY_LEAD_LOOKUP_ERROR_TTL_MS = 5_000;
const FUZZY_LEAD_LOOKUP_CACHE_MAX = 100;
const fuzzyLeadLookupCache = new Map();

function getFuzzyLeadLookupCacheKey({ query = '', threshold = 0.3, limit = 8 } = {}) {
  return JSON.stringify([
    String(query || '').trim().toLowerCase(),
    Number(threshold || 0.3).toFixed(3),
    Number(limit || 8),
  ]);
}

function cloneFuzzyLeadLookupResult(result = {}, cacheStatus = '') {
  return {
    ...result,
    cache: cacheStatus || result.cache || 'miss',
    cached: cacheStatus === 'hit',
  };
}

function trimFuzzyLeadLookupCache() {
  while (fuzzyLeadLookupCache.size > FUZZY_LEAD_LOOKUP_CACHE_MAX) {
    const oldestKey = fuzzyLeadLookupCache.keys().next().value;
    if (!oldestKey) break;
    fuzzyLeadLookupCache.delete(oldestKey);
  }
}

function normalizeFuzzyLeadRow(row = {}) {
  const leadId = String(row.lead_id || row.leadId || '').trim();
  const leadName = String(row.lead_name || row.leadName || '').trim();
  const address = String(row.address || '').trim();
  const email = String(row.email || '').trim();
  const phone = normalizePhone(row.phone || '');
  const source = String(row.source || 'postgres').trim();
  const similarity = Number(row.similarity_score ?? row.similarity ?? 0);
  return {
    id: leadId,
    leadId,
    leadName,
    name: leadName,
    address,
    email,
    phone,
    stage: String(row.stage || '').trim(),
    source,
    score: toNumber(row.score, 0),
    similarity: Number.isFinite(similarity) ? Number(similarity.toFixed(3)) : 0,
    matchMode: 'pg_trgm_similarity',
    raw: row.raw && typeof row.raw === 'object' ? row.raw : {},
    seller: {
      name: leadName,
      email,
      phone,
    },
    property: {
      address,
    },
  };
}

async function runFuzzyLeadLookupFromDb(params = {}) {
  const query = String(params.query || params.search || params.q || params.text || '').trim();
  const threshold = Math.max(0.05, Math.min(1, Number(params.threshold || params.minSimilarity || params.min_similarity || 0.3)));
  const limit = Math.max(1, Math.min(50, Number(params.limit || 8)));
  if (!query) {
    return {
      ok: true,
      result: 'empty_query',
      query,
      count: 0,
      leads: [],
    };
  }
  const pool = getPgPool();
  if (!pool) {
    return {
      ok: false,
      result: 'postgres_unavailable',
      reason: 'postgres_unavailable',
      query,
      count: 0,
      leads: [],
    };
  }
  const cacheKey = getFuzzyLeadLookupCacheKey({ query, threshold, limit });
  const cached = fuzzyLeadLookupCache.get(cacheKey);
  const now = Date.now();
  if (cached && cached.expiresAt > now) {
    if (cached.promise) {
      const shared = await cached.promise;
      return cloneFuzzyLeadLookupResult(shared, 'shared_inflight');
    }
    if (cached.result) {
      return cloneFuzzyLeadLookupResult(cached.result, 'hit');
    }
  }

  const lookupPromise = (async () => {
    try {
      const db = await pool.query(
        'SELECT * FROM public.pbk_fuzzy_lead_lookup($1::text, $2::double precision, $3::integer)',
        [query, threshold, limit]
      );
      markPostgresHealth(true);
      const leads = (db.rows || []).map(normalizeFuzzyLeadRow);
      return {
        ok: true,
        result: 'postgres_fuzzy_lookup',
        query,
        threshold,
        count: leads.length,
        leads,
      };
    } catch (error) {
      markPostgresHealth(false, error?.message || error);
      return {
        ok: false,
        result: 'postgres_fuzzy_lookup_failed',
        reason: 'postgres_fuzzy_lookup_failed',
        query,
        threshold,
        count: 0,
        leads: [],
        error: error?.message || String(error),
      };
    }
  })();
  fuzzyLeadLookupCache.set(cacheKey, {
    expiresAt: now + FUZZY_LEAD_LOOKUP_CACHE_TTL_MS,
    promise: lookupPromise,
  });
  trimFuzzyLeadLookupCache();

  try {
    const result = await lookupPromise;
    fuzzyLeadLookupCache.set(cacheKey, {
      expiresAt:
        Date.now() +
        (result.ok ? FUZZY_LEAD_LOOKUP_CACHE_TTL_MS : FUZZY_LEAD_LOOKUP_ERROR_TTL_MS),
      result,
    });
    trimFuzzyLeadLookupCache();
    return cloneFuzzyLeadLookupResult(result, 'miss');
  } catch (error) {
    fuzzyLeadLookupCache.delete(cacheKey);
    return {
      ok: false,
      result: 'postgres_fuzzy_lookup_failed',
      reason: 'postgres_fuzzy_lookup_failed',
      query,
      threshold,
      count: 0,
      leads: [],
      error: error?.message || String(error),
    };
  }
}

function leadMatchesIdentifiers(lead = {}, identifiers = {}) {
  const leadId = String(identifiers.leadId || identifiers.id || '').trim();
  const email = String(identifiers.email || '')
    .trim()
    .toLowerCase();
  const phone = normalizePhone(identifiers.phone || identifiers.to || '');
  const address = String(identifiers.address || identifiers.propertyAddress || '')
    .trim()
    .toLowerCase();
  const addressKey = normalizeAddressKey(address);
  const name = String(identifiers.leadName || identifiers.name || '')
    .trim()
    .toLowerCase();
  const leadAddress = String(lead.property?.address || lead.address || lead.propertyAddress || lead.property_address || '')
    .trim()
    .toLowerCase();
  const leadAddressKey = normalizeAddressKey(leadAddress);

  if (leadId && [lead.id, lead.leadId, lead.importId, lead.externalId, lead.external_id].some((value) => String(value || '').trim() === leadId)) return true;
  if (
    email &&
    String(lead.seller?.email || lead.email || '')
      .trim()
      .toLowerCase() === email
  )
    return true;
  if (phone && normalizePhone(lead.seller?.phone || lead.phone || '') === phone) return true;
  if (address && leadAddress === address) return true;
  if (addressKey && leadAddressKey === addressKey) return true;
  if (
    name &&
    String(lead.seller?.name || lead.leadName || lead.name || '')
      .trim()
      .toLowerCase() === name
  )
    return true;
  return false;
}

function normalizePbkDealPath(value = '', fallback = 'cash') {
  const raw = String(value || '')
    .trim()
    .toLowerCase();
  if (!raw) return fallback;
  if (/\b(rbp|retail buyer|retail-buyer)\b/.test(raw)) return 'rbp';
  if (/\b(cf|creative finance|seller finance|seller-finance|wrap)\b/.test(raw)) return 'cf';
  if (/\b(mt|mortgage takeover|subject to|subject-to|subto|sub-to|takeover)\b/.test(raw)) return 'mt';
  if (/\b(land|parcel|acreage|lot)\b/.test(raw)) return 'land';
  if (/\b(cash|as-is|as is|wholesale|standard-purchase|cash-offer)\b/.test(raw)) return 'cash';
  return fallback;
}

function getPathDisplayLabel(pathValue = 'cash') {
  const normalized = normalizePbkDealPath(pathValue);
  const labels = {
    cash: 'Cash Offer',
    rbp: 'Retail Buyer Program',
    cf: 'Creative Finance',
    mt: 'Mortgage Takeover',
    land: 'Land',
  };
  return labels[normalized] || labels.cash;
}

function getPathDocuSignTemplateName(pathValue = 'cash') {
  const normalized = normalizePbkDealPath(pathValue);
  const templateNames = {
    cash: 'PBK_Cash_Offer_v1',
    rbp: 'PBK_RBP_v1',
    cf: 'PBK_Creative_Finance_v1',
    mt: 'PBK_Mortgage_Takeover_v1',
    land: 'PBK_Land_v1',
  };
  return templateNames[normalized] || templateNames.cash;
}

function inferLeadSelectedPath(lead = {}, fallback = 'cash') {
  const callContext = lead.callContext || lead.call_context || {};
  const property = lead.property || {};
  const rawPath = [lead.selectedPath, lead.selected_path, lead.path, lead.dealPath, callContext.selectedPath, callContext.selected_path, callContext.path, callContext.dealPath, callContext.contractPath, callContext.selectedPathLabel].find(Boolean);
  if (rawPath) return normalizePbkDealPath(rawPath, fallback);
  if (/land|parcel|acreage/i.test([property.type, property.propertyType, property.address, lead.type].filter(Boolean).join(' '))) {
    return 'land';
  }
  return fallback;
}

function normalizeLeadTags(value = []) {
  return Array.isArray(value)
    ? value.map((tag) => String(tag || '').trim()).filter(Boolean)
    : String(value || '')
        .split(',')
        .map((tag) => tag.trim())
        .filter(Boolean);
}

function parseBantPayload(value, fallback = {}) {
  if (value === undefined) return fallback || {};
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return { ...(fallback || {}), ...value };
  }
  const raw = String(value || '').trim();
  if (!raw) return fallback || {};
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? { ...(fallback || {}), ...parsed }
      : fallback || {};
  } catch {
    return fallback || {};
  }
}

function getLeadActivityItems(context = {}) {
  const search = [context.leadId, context.leadName, context.address].filter(Boolean).join(' ').toLowerCase();
  return sortNewest(state.activity || []).filter((item) => {
    if (!search) return false;
    const haystack = [item.leadId, item.leadName, item.target, item.address, item.text, item.category].filter(Boolean).join(' ').toLowerCase();
    return (context.leadId && haystack.includes(String(context.leadId).toLowerCase())) || (context.leadName && haystack.includes(String(context.leadName).toLowerCase().split(/\s+/)[0])) || (context.address && haystack.includes(String(context.address).toLowerCase().split(',')[0]));
  });
}

function buildLeadFullView(leadOrId = {}) {
  const lead = typeof leadOrId === 'string' ? findLeadImportByLookup(leadOrId) : leadOrId;
  if (!lead) return null;
  const seller = lead.seller || {};
  const property = lead.property || {};
  const selectedPath = inferLeadSelectedPath(lead);
  const callContext = {
    ...(lead.call_context || {}),
    ...(lead.callContext || {}),
    selected_path: selectedPath,
    selectedPath,
    selectedPathLabel: getPathDisplayLabel(selectedPath),
  };
  const contractContext = plainRecord(lead.contractContext || lead.contract_context || lead.contracts);
  const approvalContext = plainRecord(lead.approvalContext || lead.approval_context || lead.approvals);
  const context = findLeadContext({
    leadId: lead.leadId || lead.id,
    leadName: seller.name || lead.leadName || lead.name,
    address: property.address || lead.address,
    phone: seller.phone || lead.phone,
    email: seller.email || lead.email,
  });
  const calls = sortNewest(state.calls || []).filter((call) => (context.leadId && call.leadId === context.leadId) || (context.address && String(call.address || '').toLowerCase() === String(context.address).toLowerCase()) || (context.phone && normalizePhone(call.phone) === normalizePhone(context.phone)) || (context.leadName && String(call.leadName || '').toLowerCase() === String(context.leadName).toLowerCase()));
  const messages = sortNewest(state.messages || []).filter((message) => (context.leadId && message.leadId === context.leadId) || (context.address && String(message.address || '').toLowerCase() === String(context.address).toLowerCase()) || (context.email && String(message.email || '').toLowerCase() === String(context.email).toLowerCase()) || (context.phone && normalizePhone(message.phone) === normalizePhone(context.phone)));
  const contracts = sortNewest(state.contracts || []).filter((contract) => (context.leadId && contract.leadId === context.leadId) || (context.address && String(contract.address || '').toLowerCase() === String(context.address).toLowerCase()) || (context.email && String(contract.email || '').toLowerCase() === String(context.email).toLowerCase()));
  const analyzerRuns = sortNewest(state.analyzerRuns || []).filter((run) => (context.leadId && run.leadId === context.leadId) || (context.address && String(run.address || '').toLowerCase() === String(context.address).toLowerCase()));
  const activity = getLeadActivityItems(context);
  const fullLead = {
    ...lead,
    id: lead.id || context.leadId,
    leadId: lead.leadId || context.leadId,
    name: seller.name || lead.name || context.leadName,
    phone: seller.phone || lead.phone || context.phone,
    email: seller.email || lead.email || context.email,
    address: property.address || lead.address || context.address,
    property_type: property.propertyType || property.type || lead.property_type || (selectedPath === 'land' ? 'Land' : 'Single Family'),
    motivation_score: lead.motivation_score ?? lead.motivationScore ?? lead.score ?? null,
    selected_path: selectedPath,
    selectedPath,
    selectedPathLabel: getPathDisplayLabel(selectedPath),
    docusignTemplateName: getPathDocuSignTemplateName(selectedPath),
    seller,
    property,
    contractContext,
    contract_context: contractContext,
    approvalContext,
    approval_context: approvalContext,
    callContext,
    call_context: callContext,
    bant: normalizeBantInfo(lead.bant || {}, callContext.bant || {}),
    activity,
    calls,
    messages,
    contracts,
    analyzerRuns,
  };
  return {
    ok: true,
    lead: fullLead,
    calls,
    messages,
    contracts,
    activity,
    analyzerRuns,
  };
}

function summarizeTranscriptForLead(call = {}, fallbackSummary = '') {
  if (fallbackSummary) return String(fallbackSummary).trim();
  if (Array.isArray(call.transcript) && call.transcript.length) {
    const text = call.transcript
      .map((line) => String(line?.text || line?.body || '').trim())
      .filter(Boolean)
      .slice(-4)
      .join(' ');
    if (text) return text.slice(0, 420);
  }
  return String(call.body || call.script || 'No summary captured yet.').slice(0, 420);
}

function buildLeadLastCallDetails(leadId = '') {
  const full = buildLeadFullView(leadId);
  if (!full) return null;
  const lead = full.lead || {};
  const callContext = lead.callContext || {};
  const latestCall = full.calls?.[0] || full.messages?.find((message) => String(message.channel || '').toLowerCase() === 'call') || null;
  if (!latestCall && !Object.keys(callContext).length) {
    return {
      ok: true,
      leadId: lead.leadId || lead.id || leadId,
      call: null,
    };
  }
  const transcript = Array.isArray(latestCall?.transcript) ? latestCall.transcript : [];
  const sentiment = callContext.sentiment ?? callContext.sentimentScore ?? latestCall?.sentiment ?? null;
  const lastOffer = callContext.last_offer ?? callContext.lastOffer ?? callContext.offer ?? latestCall?.lastOffer ?? null;
  const summary = summarizeTranscriptForLead(latestCall || {}, callContext.summary || callContext.callSummary || '');
  return {
    ok: true,
    leadId: lead.leadId || lead.id || leadId,
    call: latestCall
      ? {
          ...latestCall,
          transcript,
          summary,
          sentiment,
          last_offer: lastOffer,
        }
      : {
          id: `call-context-${lead.leadId || lead.id || leadId}`,
          status: 'context-only',
          transcript,
          summary,
          sentiment,
          last_offer: lastOffer,
        },
    last_offer: lastOffer,
    sentiment,
    summary,
    transcript,
    call_context: callContext,
  };
}

function buildLeadMessageDraft({ context = {}, channel = 'sms', stage = 'followup', activity = [] } = {}) {
  const firstName =
    String(context.leadName || 'there')
      .trim()
      .split(/\s+/)[0] || 'there';
  const address = context.address || 'the property';
  const hasActivity = Array.isArray(activity) && activity.length > 0;
  const activitySuffix = hasActivity ? ' I reviewed the latest notes so this matches where we left off.' : '';
  const drafts = {
    opening: `Hi ${firstName}, this is Ava with Probono Key Realty. We are interested in possibly purchasing ${address} as-is. Is now a good time to talk for two minutes?`,
    followup: `Hi ${firstName}, this is Ava with Probono Key Realty checking back on ${address}.${activitySuffix} Would today or tomorrow be better for a quick update?`,
    negotiating: `Hi ${firstName}, I reviewed the numbers again on ${address}. If we keep this simple, as-is, and on your timeline, what would need to be true for you to feel good about moving forward?`,
    closing: `Hi ${firstName}, underwriting has the file ready on ${address}. I can send the summary and walk you through the contract whenever you have five minutes.`,
    contract: `Hi ${firstName}, the contract packet for ${address} is ready. I can send it now and stay available to walk through each page with you.`,
    lost: `Hi ${firstName}, I know the timing may not have been right on ${address}. If anything changes, I am happy to revisit the numbers with no pressure.`,
  };
  const body = drafts[stage] || drafts.followup;
  if (channel === 'email') {
    return `Subject: Quick update on ${address}\n\n${body}\n\nBest,\nAva\nProbono Key Realty`;
  }
  return body;
}

function extractCommandContext(command = '') {
  const raw = String(command || '').trim();
  if (!raw) return {};
  if (looksLikeAvaTtsDiagnosticCommand(raw)) return {};

  const phoneMatch = raw.match(/(\+?1?[\s.(+-]*\d{3}[\s).-]*\d{3}[\s.-]*\d{4})/);
  const analyzeMatch = raw.match(/\b(?:analyze|run analyzer on|mao on)\s+(.+)$/i);
  const addressMatch = analyzeMatch || raw.match(/\bat\s+(.+?)(?:\s+(?:now|today|tomorrow|asap|please|right now)\b|$)/i) || raw.match(/\bfor\s+(\d{1,5}[^,]+,\s*[A-Za-z .'-]+(?:,\s*[A-Z]{2})?)/i);
  const nameMatch = raw.match(/\b(?:call|dial)\s+(.+?)(?:\s+at\s+|\s+for\s+|$)/i) || raw.match(/\b(?:text|sms|message)\s+to\s+(.+?)(?:\s+at\s+|\s+for\s+|$)/i) || raw.match(/\bsend(?: a)?(?: contract| docusign)? to\s+(.+?)(?:\s+at\s+|\s+for\s+|$)/i) || raw.match(/\bwork this lead and report back on\s+(.+?)(?:\s+at\s+|\s+for\s+|$)/i);

  const leadName = nameMatch?.[1]?.trim() || '';
  const address = addressMatch?.[1]?.trim().replace(/[.?!]+$/, '') || '';
  const phone = phoneMatch?.[1] ? normalizePhone(phoneMatch[1]) : '';

  return {
    ...(leadName ? { leadName } : {}),
    ...(address ? { address } : {}),
    ...(phone ? { phone } : {}),
  };
}

const TOOL_FIRST_MIN_CONFIDENCE = Math.max(0.5, Math.min(0.99, Number(process.env.PBK_TOOL_FIRST_MIN_CONFIDENCE || 0.8)));
const TOOL_FIRST_REVIEW_CONFIDENCE = Math.max(0.3, Math.min(TOOL_FIRST_MIN_CONFIDENCE, Number(process.env.PBK_TOOL_FIRST_REVIEW_CONFIDENCE || 0.65)));
const TOOL_FIRST_INTENT_TO_TOOL = {
  lead_search: 'search_leads',
  deal_analysis: 'analyze_deal',
  contract_prep: 'prepare_contract',
  outbound_call: 'telnyx_call',
  memory_recall: 'pbk_recall_memory',
  memory_store: 'remember_personal_fact',
  market_research: 'web_search_plus',
};

function extractToolFirstAddress(command = '', context = {}, params = {}) {
  const explicit = String(params.address || params.propertyAddress || params.property_address || '').trim();
  if (explicit) return explicit;
  const contextAddress = String(context.address || '').trim();
  if (contextAddress && !/^unknown property$/i.test(contextAddress)) return contextAddress;
  const raw = String(command || '').trim();
  const patterns = [/\b(?:analyze|analysis|mao|arv|offer|comps?|numbers?)\s+(?:for|on|at)?\s*(\d{1,6}\s+[^?.,\n]+?)(?:\s+(?:please|now|today|asap|and|then)\b|[?.!]|$)/i, /\b(?:property|address)\s+(?:is|at|for)?\s*(\d{1,6}\s+[^?.,\n]+?)(?:\s+(?:please|now|today|asap|and|then)\b|[?.!]|$)/i, /\b(\d{1,6}\s+[A-Za-z0-9 .'-]+(?:lane|ln|street|st|drive|dr|court|ct|avenue|ave|road|rd|circle|cir|boulevard|blvd|place|pl|way)\b[^?.,\n]*)/i];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) return match[1].trim().replace(/[.?!]+$/, '');
  }
  return '';
}

function detectToolFirstIntent(command = '', params = {}, context = {}) {
  const text = String(command || '').trim();
  const lower = text.toLowerCase();
  if (!text) return null;
  const address = extractToolFirstAddress(text, context, params);
  const hasLeadContext = Boolean(context.leadId || context.leadName || context.address || context.phone);
  const rules = [
    {
      intent: 'lead_search',
      confidence: 0.94,
      test: /\b(find|search|lookup|look up|pull|show)\b.*\b(leads?|seller|homeowner|prospects?)\b/i,
    },
    {
      intent: 'deal_analysis',
      confidence: 0.95,
      test: /\b(mao|arv|analy[sz]e|analysis|run numbers|offer number|repair estimate|profit)\b/i,
    },
    {
      intent: 'contract_prep',
      confidence: 0.92,
      test: /\b(prepare|draft|create|write|build)\b.*\b(contract|agreement|purchase agreement|docusign|docu sign)\b/i,
    },
    {
      intent: 'outbound_call',
      confidence: 0.91,
      test: /\b(call|dial|phone)\b.*\b(lead|seller|homeowner|prospect|them|number|phone)\b/i,
    },
    {
      intent: 'memory_recall',
      confidence: 0.9,
      test: /\b(what did|what has|remember|recall|past|previous|last time|notes?)\b.*\b(said|say|discuss|conversation|call|seller|lead)\b/i,
    },
    {
      intent: 'memory_store',
      confidence: 0.91,
      test: /\b(remember|note|save|store)\b.*\b(that|seller|lead|he|she|they|family|child|pet|callback|preference)\b/i,
    },
    {
      intent: 'market_research',
      confidence: 0.88,
      test: /\b(market trend|current market|rates?|inventory|days on market|comps in|zip|neighborhood trend|research)\b/i,
    },
  ];
  const matched = rules.find((rule) => rule.test.test(text));
  if (!matched) return null;
  const toolName = TOOL_FIRST_INTENT_TO_TOOL[matched.intent];
  return {
    ...matched,
    toolName,
    required: matched.confidence >= TOOL_FIRST_MIN_CONFIDENCE,
    review: matched.confidence >= TOOL_FIRST_REVIEW_CONFIDENCE,
    address,
    hasLeadContext,
  };
}

function stripNegatedActionInstructions(command = '') {
  let text = String(command || '');
  const negatedAction = /\b(?:do not|don't|dont|never|without approval,?\s*do not|please do not)\b[^.?!\n;]*(?:\bcall\b|\bdial\b|\btext\b|\bsms\b|\bemail\b|\bcampaign\b|\bcontract\b|\bagreement\b|\bdocusign\b|\bdocu sign\b|\bschedule\b|\bbook\b|\bapprove\b|\bdelete\b|\bkill switch\b)[^.?!\n;]*/gi;
  text = text.replace(negatedAction, ' ');
  return text.replace(/\s+/g, ' ').trim();
}

function looksLikeAvaTextResponseCommand(command = '', params = {}) {
  if (params.responseOnly === true || params.answerOnly === true || params.conversationOnly === true) return true;
  const raw = String(command || '').trim();
  if (!raw) return false;
  const intentText = stripNegatedActionInstructions(raw);
  const normalized = intentText.toLowerCase();
  const asksForWords = /\b(what should ava say|how should ava respond|respond to|reply to|answer this|give me (?:a |an |one )?.*response|write (?:a |an )?.*response|draft (?:a |an )?.*response|say to|talk track|next best phrase|seller says|seller said|objection|rebuttal|one sentence.*response|production smoke response)\b/i.test(normalized);
  if (!asksForWords) return false;
  const explicitProviderWrite = /\b(send|call|dial|text|sms|email|campaign|contract|docusign|docu sign|schedule|book|approve|delete)\b/i.test(normalized) && !/\b(what should|how should|respond|reply|answer|say|talk track|next best phrase)\b/i.test(normalized);
  return !explicitProviderWrite;
}

function looksLikeAvaTtsDiagnosticCommand(command = '', params = {}) {
  if (params.ttsDiagnostic === true || params.voiceDiagnostic === true) return true;
  const raw = String(command || params.command || params.text || '').trim();
  if (!raw) return false;
  const normalized = raw.toLowerCase();
  const mentionsVoiceLayer = /\b(ava\s+)?(?:tts|text[-\s]?to[-\s]?speech|elevenlabs|voice\s+(?:output|chat|bubble|stream|audio|playback)|spoken response|audio playback|chat bubble)\b/i.test(normalized);
  const mentionsBugOrProvider = /\b(bug|error|failed|returned|quota|token|robot|robotic|sound|sounds|creating|created|fake|lead|leads|lerad|lerads|text is ready)\b/i.test(normalized);
  return mentionsVoiceLayer && mentionsBugOrProvider;
}

function hasExplicitCrmWriteIntent(command = '') {
  const normalized = stripNegatedActionInstructions(command).toLowerCase();
  if (!normalized) return false;
  return [/\b(update|sync|log|save|write|record)\b[^.?!\n;]{0,80}\b(crm|streak|lead record|pipeline)\b/i, /\b(crm|streak|lead record|pipeline)\b[^.?!\n;]{0,80}\b(update|sync|log|save|write|record)\b/i, /\b(save this|log this|record this)\b[^.?!\n;]{0,80}\b(crm|streak|lead)\b/i].some((pattern) => pattern.test(normalized));
}

function looksLikeReadOnlyAvaCommand(command = '', params = {}) {
  if (looksLikeAvaTtsDiagnosticCommand(command, params)) return true;
  if (params.readOnly === true || params.noProviderWrites === true || params.providerWrites === false) return true;
  const raw = String(command || '').trim();
  if (!raw) return false;
  const intentText = stripNegatedActionInstructions(raw) || raw;
  const normalized = intentText.toLowerCase();
  const explicitNoWrites = /\b(read[-\s]?only|no provider writes?|without provider writes?|do not (?:run|execute|perform|make|create|send|call|message|approve|reject|cancel)|don't (?:run|execute|perform|make|create|send|call|message|approve|reject|cancel)|never (?:run|execute|perform|make|create|send|call|message|approve|reject|cancel))\b/i.test(raw);
  const asksForStatus = /\b(check|tell me|summari[sz]e|show|inspect|audit|debug|status|health|working|next safe action|what should|what is)\b/i.test(normalized) && /\b(pbk|system|command center|ava|rex|agent|agents|providers?|voice|chat|approval|approvals?|revenue engine|intelligence)\b/i.test(normalized);
  return explicitNoWrites || (asksForStatus && !hasExplicitCrmWriteIntent(raw));
}

function buildToolFirstArgs(detected = {}, command = '', params = {}, context = {}) {
  const common = {
    ...params,
    leadId: params.leadId || context.leadId,
    leadName: params.leadName || context.leadName,
    address: params.address || detected.address || context.address,
    phone: params.phone || context.phone,
    email: params.email || context.email,
    source: params.source || 'tool-first-router',
  };
  if (detected.intent === 'lead_search')
    return {
      query: params.query || detected.address || command,
      limit: params.limit || 10,
      source: 'tool-first-router',
    };
  if (detected.intent === 'deal_analysis') return { ...common, deal: params.deal || {} };
  if (detected.intent === 'contract_prep')
    return {
      ...common,
      notes: params.notes || command,
      amount: params.amount || params.offerPrice,
    };
  if (detected.intent === 'outbound_call')
    return {
      ...common,
      script: params.script || command,
      deepgramSentiment: params.deepgramSentiment ?? true,
    };
  if (detected.intent === 'memory_recall') return { ...common, query: params.query || command, limit: params.limit || 3 };
  if (detected.intent === 'memory_store')
    return {
      ...common,
      factType: params.factType || params.fact_type || 'seller_note',
      factValue: params.factValue || params.fact_value || command,
    };
  if (detected.intent === 'market_research')
    return {
      query: params.query || command,
      requestedBy: params.actor || params.requestedBy || 'Rex',
    };
  return common;
}

function buildToolFirstAnswer(detected = {}, toolResult = {}, command = '') {
  const toolName = detected.toolName || 'tool';
  if (detected.intent === 'deal_analysis' && toolResult) {
    return `I ran the numbers first. ARV is ${currency(toolResult.arv)}, MAO is ${currency(toolResult.mao)}, and target offer is ${currency(toolResult.targetOffer)}. Want me to prep the next step from this analysis?`;
  }
  if (detected.intent === 'lead_search') {
    const count = Number(toolResult.count ?? toolResult.leads?.length ?? 0);
    const first = toolResult.leads?.[0];
    return count ? `I searched live leads and found ${count}. The top match is ${first?.seller?.name || first?.leadName || first?.name || 'a seller'} at ${first?.property?.address || first?.address || 'the saved property'}.` : 'I searched live leads and did not find a match yet. Want me to create a new lead from what you have?';
  }
  if (detected.intent === 'contract_prep') {
    return toolResult.ok ? `I prepared the contract packet as a draft and kept it inside the PBK approval flow. Review it before anything goes to the seller.` : `I tried to prepare the contract, but the bridge returned: ${toolResult.error || toolResult.message || 'contract prep unavailable'}.`;
  }
  if (detected.intent === 'outbound_call') {
    return toolResult.result === 'queued_for_approval' ? 'I routed the call through approval first, so Ava will not dial until you approve it.' : `I routed the call request through ${toolName}.`;
  }
  if (detected.intent === 'memory_recall') {
    const count = Number(toolResult.memories?.length || toolResult.results?.length || 0);
    return count ? `I checked memory and found ${count} relevant note${count === 1 ? '' : 's'}.` : 'I checked memory and did not find a matching note yet.';
  }
  if (detected.intent === 'memory_store') return toolResult.ok ? 'I saved that to Ava’s memory.' : `I tried to save that memory, but got: ${toolResult.error || 'memory unavailable'}.`;
  if (detected.intent === 'market_research') return toolResult.answer || toolResult.summary || `I pulled current research for: ${command}`;
  return `I used ${toolName} before answering.`;
}

async function recordToolMissedFeedback({ command = '', detected = {}, context = {}, reason = '' } = {}) {
  if (!command || !detected?.toolName) return null;
  return recordPbkFeedbackRecord({
    leadId: context.leadId || '',
    callId: '',
    agentName: 'Ava',
    agentAction: 'tool_first_router_review',
    humanDecision: 'tool_missed',
    transcriptSnippet: command,
    outcomeLabel: reason || 'tool_first_below_required_confidence',
    metadata: {
      expected_tool: detected.toolName,
      intent: detected.intent,
      confidence: detected.confidence,
      tool_missed: true,
      leadName: context.leadName,
      address: context.address,
    },
  });
}

async function executeToolFirstIntent(detected = {}, command = '', params = {}, context = {}) {
  const toolName = detected.toolName;
  const handler = toolHandlers[toolName];
  if (!handler) {
    await recordToolMissedFeedback({ command, detected, context, reason: 'tool_handler_missing' });
    return null;
  }
  const args = buildToolFirstArgs(detected, command, params, context);
  const start = Date.now();
  let response = null;
  let success = false;
  let errorMessage = '';
  try {
    const guardedTools = new Set(['telnyx_call', 'telnyx_sms', 'sendDocuSign', 'sendContract', 'prepare_and_send_contract']);
    response = guardedTools.has(toolName) ? await invokeToolWithOperatingGuard(toolName, args) : await handler(args);
    success = response?.ok !== false;
    return {
      ok: true,
      routedTo: toolName,
      toolFirst: {
        result: 'tool_first_required',
        intent: detected.intent,
        confidence: detected.confidence,
        toolName,
        args,
      },
      response,
      answer: buildToolFirstAnswer(detected, response, command),
    };
  } catch (error) {
    errorMessage = error?.message || String(error);
    response = { ok: false, error: errorMessage };
    return {
      ok: false,
      routedTo: toolName,
      toolFirst: {
        result: 'tool_first_required',
        intent: detected.intent,
        confidence: detected.confidence,
        toolName,
        args,
      },
      response,
      answer: `I tried to use ${toolName} first, but it failed: ${errorMessage}`,
    };
  } finally {
    await recordPbkToolUsage({
      toolName,
      intent: detected.intent,
      leadId: context.leadId,
      callId: params.callId || params.call_id || '',
      agentName: params.agentName || params.actor || 'Ava',
      success,
      latencyMs: Date.now() - start,
      errorMessage,
      context: {
        command,
        args: redactApprovalParamPreview(args),
        tool_first_required: true,
        confidence: detected.confidence,
      },
      source: 'tool-first-router',
      routedTo: toolName,
    });
  }
}

function buildAnalyzerSummary(params = {}) {
  const deal = params.deal || {};
  const address = params.address || deal.address || 'Unknown address';
  const seed = hashString(address);
  const propertyValues = getPropertyAnalysisValues(params.propertyData || deal.propertyData || {});
  const fallbackArv = Math.round((120000 + (seed % 150000)) / 5000) * 5000;
  const fallbackRepairs = Math.round((16000 + (seed % 42000)) / 500) * 500;
  const arv = toMoneyNumber(params.arv, 0) || toMoneyNumber(deal.arv, 0) || propertyValues.arv || averagePrices({ comps: propertyValues.compObject }) || averagePrices(deal) || fallbackArv;
  const repairsMid = toMoneyNumber(params.repairsMid, 0) || toMoneyNumber(params.repairs, 0) || toMoneyNumber(deal?.repairs?.mid, 0) || propertyValues.repairsMid || fallbackRepairs;
  const fee = toNumber(params.fee, 0) || toNumber(deal.fee, 9000) || 9000;
  const mao = toMoneyNumber(params.mao, 0) || toMoneyNumber(deal.mao60, 0) || propertyValues.mao || Math.max(0, Math.round((arv - repairsMid) * 0.68 - fee));
  const targetOffer = toMoneyNumber(params.offerPrice, 0) || toMoneyNumber(deal.offer, 0) || toMoneyNumber(deal.agreedPrice, 0) || propertyValues.targetOffer || Math.max(0, Math.round(mao * 0.85));
  const estProfit = Math.max(0, mao - targetOffer);

  return {
    id: params.id || `run-${slugify(address) || randomUUID()}`,
    leadId: params.leadId || deal.leadId || '',
    address,
    arv,
    repairsMid,
    mao,
    targetOffer,
    estProfit,
    comps: propertyValues.comps,
    enrichment: params.enrichment || null,
    status: params.status || 'complete',
    createdAt: isoNow(),
  };
}

function scoreBrainDocMatch(doc, query) {
  const haystack = [doc.title, doc.excerpt, doc.summary, doc.topic, doc.salesMentor, doc.techniqueType, ...(doc.revenueStreams || []), ...(doc.tags || [])].join(' ').toLowerCase();

  return query
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .reduce((score, token) => score + (haystack.includes(token) ? 1 : 0), 0);
}

function stripHtml(value = '') {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function decodeXmlEntities(value = '') {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_match, code) => String.fromCharCode(Number(code)));
}

function inferBrainBlogTags(text = '') {
  const normalized = String(text || '').toLowerCase();
  const tags = [];
  if (/\bprobate|executor|estate\b/.test(normalized)) tags.push('Probate');
  if (/\bsubject[-\s]?to|subto|mortgage|payment\b/.test(normalized)) tags.push('Subject-To', 'Creative Finance');
  if (/\bseller finance|owner finance|terms\b/.test(normalized)) tags.push('Seller Financing');
  if (/\bmao|arv|repair|comp|assignment|cash offer\b/.test(normalized)) tags.push('Cash Deals', 'Analyzer');
  if (/\bobjection|think about|wife|price|more money|follow up\b/.test(normalized)) tags.push('Objection Handling', 'Negotiation');
  if (/\btcpa|consent|dnc|compliance|legal\b/.test(normalized)) tags.push('Legal & TCPA');
  if (/\bmarket|inventory|rates|foreclosure|dom\b/.test(normalized)) tags.push('Market Reports');
  return normalizeStringList(tags.length ? tags : ['Wholesaling']);
}

function inferSalesMentor(text = '') {
  const normalized = String(text || '').toLowerCase();
  if (normalized.includes('jordan belfort') || normalized.includes('straight line')) return 'Jordan Belfort';
  if (normalized.includes('alex mineo')) return 'Alex Mineo';
  if (normalized.includes('cory boatright')) return 'Cory Boatright';
  if (normalized.includes('brent daniels') || normalized.includes('talk to people') || normalized.includes('ttp')) return 'Brent Daniels';
  return 'PBK Research';
}

function inferTechniqueType(text = '') {
  const normalized = String(text || '').toLowerCase();
  if (/\bobjection|rebuttal|think about|wife|more money\b/.test(normalized)) return 'objection_handling';
  if (/\bscript|pitch|talk track|opening\b/.test(normalized)) return 'closing_script';
  if (/\bfollow up|nurture|sequence\b/.test(normalized)) return 'follow_up';
  if (/\bsubject[-\s]?to|seller finance|creative finance|terms\b/.test(normalized)) return 'creative_finance';
  if (/\btcpa|dnc|consent|legal|compliance\b/.test(normalized)) return 'compliance';
  if (/\bmarket|inventory|rates|dom|foreclosure\b/.test(normalized)) return 'market_research';
  if (/\bmao|arv|comp|repair|analyzer\b/.test(normalized)) return 'deal_analysis';
  return 'sales_knowledge';
}

function inferRevenueStreams(text = '', tags = []) {
  const normalized = `${String(text || '').toLowerCase()} ${normalizeStringList(tags).join(' ').toLowerCase()}`;
  const streams = [];
  if (/\bsubject[-\s]?to|subto\b/.test(normalized)) streams.push('Subject-To');
  if (/\bseller financing|seller finance|creative finance|terms\b/.test(normalized)) streams.push('Creative Finance', 'Seller Financing');
  if (/\bcash|mao|arv|repair|assignment|wholesale\b/.test(normalized)) streams.push('Cash Deals', 'Wholesaling');
  if (/\bnovation\b/.test(normalized)) streams.push('Novation');
  if (/\bprobate\b/.test(normalized)) streams.push('Probate');
  if (/\btcpa|compliance|dnc\b/.test(normalized)) streams.push('Legal & TCPA');
  return normalizeStringList(streams.length ? streams : ['Wholesaling']);
}

function buildBrainBlogSummary(content = '') {
  const text = stripHtml(content).slice(0, 900);
  if (!text) return 'No summary generated yet.';
  const sentence = text.split(/(?<=[.!?])\s+/).find((item) => item.length > 40) || text;
  return sentence.slice(0, 320);
}

function buildBrainBlogTakeaways(content = '', tags = []) {
  const normalizedTags = normalizeStringList(tags);
  const takeaways = [];
  if (normalizedTags.includes('Objection Handling')) takeaways.push('Identify the hidden uncertainty before repeating the offer.');
  if (normalizedTags.includes('Creative Finance') || normalizedTags.includes('Subject-To')) takeaways.push('Frame terms around relief, risk disclosure, and underwriting approval.');
  if (normalizedTags.includes('Cash Deals')) takeaways.push('Anchor the offer in ARV, repairs, and exit risk rather than ego or pressure.');
  if (normalizedTags.includes('Legal & TCPA')) takeaways.push('Keep compliance language explicit before any outreach or AI-assisted call.');
  if (!takeaways.length) takeaways.push(stripHtml(content).slice(0, 160) || 'Review the full source before applying this tactic.');
  return takeaways.slice(0, 4);
}

function normalizeBrainBlogPost(input = {}) {
  const now = isoNow();
  const title = String(input.title || input.name || 'Untitled Brain post')
    .trim()
    .slice(0, 180);
  const rawContent = String(input.content || input.transcript || input.body || input.summary || '').trim();
  const content = stripHtml(rawContent || input.description || input.excerpt || '');
  const sourceUrl = String(input.sourceUrl || input.url || input.link || '').trim();
  const sourceType = String(input.sourceType || input.kind || 'manual')
    .trim()
    .toLowerCase();
  const sourceName = String(input.sourceName || input.source || input.feedName || 'Brain Blog').trim();
  const tags = normalizeStringList([...inferBrainBlogTags(`${title} ${sourceName} ${content}`), ...normalizeStringList(input.tags || [])]);
  const salesMentor = String(input.salesMentor || input.mentor || '').trim() || inferSalesMentor(`${title} ${sourceName} ${content}`);
  const techniqueType = String(input.techniqueType || '').trim() || inferTechniqueType(`${title} ${content}`);
  const revenueStreams = normalizeStringList(input.revenueStreams || input.revenue_streams || inferRevenueStreams(`${title} ${content}`, tags));
  const summary = String(input.summary || '').trim() || buildBrainBlogSummary(content);
  const keyTakeaways = normalizeStringList(input.keyTakeaways || input.key_takeaways || buildBrainBlogTakeaways(content || summary, tags));
  const contentHash = String(input.contentHash || '').trim() || `blog-${Math.abs(hashString(`${sourceUrl}\n${title}\n${content || summary}`))}`;
  return {
    id: String(input.id || `brain-blog-${contentHash.replace(/^blog-/, '')}`).trim(),
    title,
    sourceUrl,
    sourceType,
    sourceName,
    salesMentor,
    techniqueType,
    revenueStreams,
    content,
    summary,
    keyTakeaways,
    tags,
    status: input.status || 'ready',
    contentHash,
    metadata: input.metadata && typeof input.metadata === 'object' ? input.metadata : {},
    publishedAt: input.publishedAt || input.published_at || input.pubDate || input.createdAt || now,
    createdAt: input.createdAt || now,
    updatedAt: now,
    trainedAt: input.trainedAt || input.trained_at || null,
  };
}

function brainBlogPostToDoc(post = {}) {
  return {
    id: post.id,
    kind: 'brain-blog',
    topic: (post.revenueStreams || [])[0] || 'Wholesaling',
    title: post.title,
    source: post.sourceName || post.sourceUrl || 'Brain Blog',
    excerpt: post.summary || post.content || '',
    summary: post.summary || post.content || '',
    citation: `${post.salesMentor || 'PBK Research'} - ${post.sourceName || post.sourceUrl || 'Brain Blog'}`,
    tags: normalizeStringList([...(post.tags || []), ...(post.revenueStreams || []), post.salesMentor, post.techniqueType]),
    createdAt: post.publishedAt || post.createdAt,
    salesMentor: post.salesMentor,
    techniqueType: post.techniqueType,
    revenueStreams: post.revenueStreams || [],
    blogPost: true,
  };
}

function filterBrainBlogPosts(posts = [], filters = {}) {
  const tag = String(filters.tag || '')
    .trim()
    .toLowerCase();
  const mentor = String(filters.mentor || filters.salesMentor || '')
    .trim()
    .toLowerCase();
  const revenueStream = String(filters.revenueStream || filters.stream || '')
    .trim()
    .toLowerCase();
  const type = String(filters.techniqueType || filters.type || '')
    .trim()
    .toLowerCase();
  return sortNewest(posts || []).filter((post) => {
    const tagHaystack = normalizeStringList([...(post.tags || []), ...(post.revenueStreams || [])])
      .join(' ')
      .toLowerCase();
    if (tag && !tagHaystack.includes(tag)) return false;
    if (
      mentor &&
      !String(post.salesMentor || '')
        .toLowerCase()
        .includes(mentor)
    )
      return false;
    if (
      revenueStream &&
      !normalizeStringList(post.revenueStreams || [])
        .join(' ')
        .toLowerCase()
        .includes(revenueStream)
    )
      return false;
    if (
      type &&
      !String(post.techniqueType || '')
        .toLowerCase()
        .includes(type)
    )
      return false;
    return true;
  });
}

function extractXmlText(block = '', tagNames = []) {
  for (const tagName of tagNames) {
    const match = String(block).match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
    if (match) return decodeXmlEntities(match[1]);
  }
  return '';
}

function extractXmlLink(block = '') {
  const atom = String(block).match(/<link\s+[^>]*href=["']([^"']+)["'][^>]*>/i);
  if (atom) return decodeXmlEntities(atom[1]);
  return stripHtml(extractXmlText(block, ['link']));
}

function parseRssItems(xml = '', feed = {}) {
  const blocks = [...(String(xml).match(/<item\b[\s\S]*?<\/item>/gi) || []), ...(String(xml).match(/<entry\b[\s\S]*?<\/entry>/gi) || [])];
  return blocks
    .slice(0, 16)
    .map((block) => {
      const title = stripHtml(extractXmlText(block, ['title']));
      const sourceUrl = extractXmlLink(block);
      const publishedAt = stripHtml(extractXmlText(block, ['pubDate', 'published', 'updated', 'dc:date']));
      const description = extractXmlText(block, ['content:encoded', 'summary', 'description']);
      return normalizeBrainBlogPost({
        title,
        sourceUrl,
        sourceType: feed.sourceType || 'rss',
        sourceName: feed.name || feed.sourceName || feed.url || 'RSS feed',
        publishedAt,
        content: stripHtml(description),
        tags: feed.tags || [],
        revenueStreams: feed.revenueStreams || [],
        metadata: { feedUrl: feed.url },
      });
    })
    .filter((post) => post.title && (post.content || post.summary));
}

function getBrainBlogFeeds(overrideFeeds = null) {
  if (Array.isArray(overrideFeeds) && overrideFeeds.length) return overrideFeeds;
  if (BRAIN_BLOG_FEEDS_RAW) {
    try {
      const parsed = JSON.parse(BRAIN_BLOG_FEEDS_RAW);
      if (Array.isArray(parsed)) return parsed;
    } catch {
      return BRAIN_BLOG_FEEDS_RAW.split(/\n|,/g)
        .map((url) => ({ url: url.trim(), name: url.trim(), sourceType: 'rss' }))
        .filter((feed) => feed.url);
    }
  }
  return BRAIN_BLOG_DEFAULT_FEEDS;
}

async function harvestBrainBlogFeeds({ feeds = null, limit = 8 } = {}) {
  const feedList = getBrainBlogFeeds(feeds).slice(0, Math.max(1, Number(limit || 8)));
  const posts = [];
  const errors = [];
  for (const feed of feedList) {
    const url = String(feed.url || '').trim();
    if (!url) continue;
    try {
      const response = await fetch(url, { headers: { 'User-Agent': 'PBK-Brain-Harvester/1.0' } });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const xml = await response.text();
      posts.push(...parseRssItems(xml, feed));
    } catch (error) {
      errors.push({ url, error: error?.message || 'Feed fetch failed.' });
    }
  }
  return { posts: posts.slice(0, Math.max(1, Number(limit || 8))), errors, feeds: feedList };
}

function extractZipCode(value = '') {
  const match = String(value || '').match(/\b\d{5}(?:-\d{4})?\b/);
  return match ? match[0].slice(0, 5) : '';
}

function normalizePropertyType(value = '') {
  const raw = String(value || '').toLowerCase();
  if (raw.includes('duplex')) return 'duplex';
  if (raw.includes('multi')) return 'multifamily';
  if (raw.includes('condo')) return 'condo';
  if (raw.includes('land')) return 'land';
  return 'single-family';
}

function buildDealScenarioSet(input = {}) {
  const arv = Math.max(0, toMoneyNumber(input.arv || input.ARV, 185000));
  const repairs = Math.max(0, toMoneyNumber(input.repairs || input.repairEstimate || input.repairsMid, 38000));
  const offer = Math.max(0, toMoneyNumber(input.offer || input.offerPrice || input.targetOffer || input.price, 78000));
  const assignmentFee = Math.max(0, toMoneyNumber(input.assignmentFee || input.fee, 10000));
  const holdingCost = Math.max(1000, toMoneyNumber(input.holdingCost, Math.round(arv * 0.015)));
  const exitCostRate = Math.max(0.04, Math.min(0.12, Number(input.exitCostRate || 0.08)));
  const scenarios = [
    { name: 'Pessimistic', arvMultiplier: 0.92, repairsMultiplier: 1.22, probability: 0.25 },
    { name: 'Most likely', arvMultiplier: 1, repairsMultiplier: 1, probability: 0.55 },
    { name: 'Optimistic', arvMultiplier: 1.07, repairsMultiplier: 0.86, probability: 0.2 },
  ].map((scenario) => {
    const scenarioArv = Math.round(arv * scenario.arvMultiplier);
    const scenarioRepairs = Math.round(repairs * scenario.repairsMultiplier);
    const exitCost = Math.round(scenarioArv * exitCostRate);
    const totalCost = offer + scenarioRepairs + holdingCost + exitCost + assignmentFee;
    const profit = scenarioArv - totalCost;
    const roi = totalCost > 0 ? profit / totalCost : 0;
    return {
      ...scenario,
      arv: scenarioArv,
      repairs: scenarioRepairs,
      holdingCost,
      exitCost,
      assignmentFee,
      offer,
      totalCost,
      profit,
      roi,
      verdict: profit < 0 ? 'loss-risk' : roi >= 0.14 ? 'strong' : roi >= 0.08 ? 'thin' : 'counter',
    };
  });
  const profits = scenarios.map((scenario) => scenario.profit);
  const probabilityOfLoss = scenarios.filter((scenario) => scenario.profit < 0).reduce((sum, scenario) => sum + scenario.probability, 0);
  const expectedProfit = Math.round(scenarios.reduce((sum, scenario) => sum + scenario.profit * scenario.probability, 0));
  const recommendation = probabilityOfLoss > 0.35 ? 'walk_or_restructure' : expectedProfit >= 15000 ? 'offer' : expectedProfit >= 6000 ? 'counter_or_terms' : 'counter_lower';
  return {
    arv,
    repairs,
    offer,
    assignmentFee,
    holdingCost,
    exitCostRate,
    scenarios,
    expectedProfit,
    profitRange: { low: Math.min(...profits), high: Math.max(...profits) },
    probabilityOfLoss,
    recommendation,
  };
}

function scoreBuyerMatch(buyer = {}, deal = {}) {
  const zip = extractZipCode(deal.address || deal.zipCode || '');
  const propertyType = normalizePropertyType(deal.propertyType || '');
  const price = toMoneyNumber(deal.offer || deal.offerPrice || deal.price || deal.targetOffer, 0);
  const repairs = toMoneyNumber(deal.repairs || deal.repairsMid || deal.repairEstimate, 0);
  let score = 0;
  const reasons = [];
  if (!zip || normalizeStringList(buyer.zipCodes || []).includes(zip)) {
    score += zip ? 30 : 12;
    reasons.push(zip ? `Zip ${zip} fits criteria.` : 'No zip provided; market criteria not disqualified.');
  }
  if (!buyer.propertyTypes?.length || normalizeStringList(buyer.propertyTypes).includes(propertyType)) {
    score += 20;
    reasons.push(`${propertyType} fits property type.`);
  }
  if (!price || (price >= toNumber(buyer.priceMin, 0) && price <= toNumber(buyer.priceMax, Number.MAX_SAFE_INTEGER))) {
    score += 25;
    reasons.push('Offer price fits buyer range.');
  }
  if (!repairs || repairs <= toNumber(buyer.maxRepairs, Number.MAX_SAFE_INTEGER)) {
    score += 15;
    reasons.push('Repair load fits buyer appetite.');
  }
  const roi = Number(deal.roi || deal.expectedRoi || 0);
  if (!roi || roi >= toNumber(buyer.desiredRoi, 0.1) * 0.85) {
    score += 10;
    reasons.push('ROI appears close to target.');
  }
  return {
    buyerId: buyer.id,
    buyerName: buyer.name,
    score: Math.min(100, score),
    status: score >= 70 ? 'strong' : score >= 45 ? 'possible' : 'weak',
    reasons,
    buyer,
  };
}

function buildSystemAuditReport(stateRef = {}) {
  const totalLeads = Math.max(1, (stateRef.leadImports || []).length);
  const activity = stateRef.activity || [];
  const warnings = activity.filter((item) => ['warning', 'failed', 'error'].includes(String(item.status || '').toLowerCase()));
  const avgLatencyMs = Math.round(toNumber(stateRef.status?.avgLatencyMs, 420));
  const estimatedMonthlyAiCost = Math.round((toNumber(stateRef.status?.queryCountToday, 0) * 0.0025 + (stateRef.brainDocs || []).length * 0.0006) * 30 * 100) / 100;
  const costPerLead = Math.round((estimatedMonthlyAiCost / totalLeads) * 100) / 100;
  const errorRate = Math.round((warnings.length / Math.max(1, activity.length)) * 1000) / 10;
  const recommendations = [];
  if (errorRate > 10) recommendations.push('Error rate is elevated. Check provider auth and fallback routing before scaling outreach.');
  if (avgLatencyMs > 900) recommendations.push('Latency is high. Prefer cached analyzer results and shorter Rex context for call-time actions.');
  if (costPerLead > 1.25) recommendations.push('Cost per lead is climbing. Route classification and summary tasks to the cheaper default model.');
  if (!recommendations.length) recommendations.push('Runtime looks stable. Keep dangerous provider writes approval-gated and continue weekly cost reviews.');
  return {
    id: `system-audit-${Date.now()}`,
    status: errorRate > 10 || avgLatencyMs > 900 ? 'watch' : 'healthy',
    estimatedMonthlyAiCost,
    costPerLead,
    errorRate,
    avgLatencyMs,
    recommendations,
    createdAt: isoNow(),
    updatedAt: isoNow(),
  };
}

