function isAvaLiveAddressMetaQuestion(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean) return false;
  return /\b(?:do|did|don'?t|should|shouldn'?t|can|could)\s+you\s+(?:already\s+)?(?:have|got|get|know)\s+(?:my|the)?\s*(?:property\s+)?address\b/i.test(clean) || /\byou\s+(?:already\s+)?(?:have|got|should\s+have|know)\s+(?:my|the)?\s*(?:property\s+)?address\b/i.test(clean) || /\b(?:i\s+)?(?:gave|sent|told)\s+you\s+(?:my|the)?\s*(?:property\s+)?address\b/i.test(clean) || /\bwhat\s+(?:address|property)\s+(?:do|did)\s+you\s+(?:have|pull|show)\b/i.test(clean) || /\byou\s+called\s+me\b.*\b(?:address|property)\b/i.test(clean);
}

function hasStrongAvaOwnerRoleAssertion(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean || isAvaLiveAddressMetaQuestion(clean)) return false;
  return /\b(i\s+(?:own|own\s+it|own\s+the\s+(?:house|home|property|place)|am\s+the\s+owner)|i'?m\s+(?:the\s+)?(?:property\s+)?owner|(?:i\s+am|i'?m)\s+(?:the\s+)?(?:seller|homeowner)|we\s+own|my\s+(?:house|home|place)\b|our\s+(?:house|home|place)\b|i\s+inherited|we\s+inherited|owner\s+of\s+the\s+(?:house|home|property)|(?:on|yeah\s+on)\s+(?:the\s+)?property\s+owner|(?:the\s+)?property\s+owner\b)\b/i.test(clean);
}

function isAvaLivePathLockBlockedTranscript(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean) return true;
  return isAvaLiveAddressMetaQuestion(clean) || isTelnyxLiveAudioCheckUtterance(clean) || isTelnyxLiveGreetingOnlyUtterance(clean) || isTelnyxLiveAckOnlyUtterance(clean) || /\b(?:same thing|repeating|already told you|you asked that already)\b/i.test(clean);
}

function hasAvaLivePathLockEvidence(transcript = '', bant = {}, best = {}) {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean || isAvaLivePathLockBlockedTranscript(clean)) return false;
  const hasBantEvidence = Boolean(normalizeBantValue(bant.need) || normalizeBantValue(bant.urgency) || normalizeBantValue(bant.timeline) || normalizeBantValue(bant.budget));
  const hasScoredEvidence = Array.isArray(best.evidence) && best.evidence.length > 0 && Number(best.score || 0) >= 0.4;
  return AVA_PATH_LOCK_MOTIVATION_RE.test(clean) || AVA_PATH_LOCK_FACT_RE.test(clean) || hasBantEvidence || hasScoredEvidence;
}

