function buildAvaMasterclassKnowledgeFacts(now = isoNow()) {
  return AVA_MASTERCLASS_KNOWLEDGE.map((fact) => ({
    tenantId: 'pbk',
    confidence: 0.99,
    source: 'pbk-immutable-seed',
    sourceId: fact.sourceId || AVA_MASTERCLASS_SOURCE_ID,
    createdAt: now,
    updatedAt: now,
    ...fact,
    metadata: {
      immutable: true,
      safety: 'ethical_conversation_masterclass',
      revision: AVA_MASTERCLASS_KNOWLEDGE_REVISION,
      sourceFile: fact.sourceFile || 'knowledge/ava-wholesale-conversation-masterclass.md',
      topic: fact.predicate,
      tags: fact.tags,
    },
  }));
}

function getPbkCoreDoctrineText() {
  return PBK_CORE_DEAL_PATHS.map((path, index) => `${index + 1}. ${path.label}: ${path.purpose}. Pass-off: ${path.passOff}.`).join('\n');
}

function looksLikePbkDoctrineQuery(query = '') {
  const normalized = String(query || '').toLowerCase();
  if (!normalized) return false;
  return /\b(who are you|what are you|rex|ava|deal path|paths|cash offer|cash wholesale|retail buyer|rbp|creative finance|mortgage takeover|subject-to|subto|land|bant|script|objection|heart of the business|probono key|pbk|wholesale\.agent|call mode|deal analyzer)\b/i.test(normalized);
}

function buildRexDoctrineAnswer(stateRef, query = '', matches = []) {
  const normalized = String(query || '').toLowerCase();
  const pendingApprovals = getPendingRuntimeApprovals(stateRef.approvals).length;
  const providerMode = stateRef.status?.mode || 'approval';
  const identity = "Rex here. I am PBK's research, strategy, and memory agent. Ava is the acquisition specialist who uses the analyzer, BANT+, scripts, objections, and approval guardrails to move sellers toward the right contract path.";
  const guardrails = ['Ava never blends paths. Cash Offer, RBP, Creative Finance, Mortgage Takeover, and Land keep separate openings, acquisition scripts, and objection engines.', 'Ava never gives seller-facing numbers until BANT+ is complete: budget, authority, need, timeline, and urgency.', 'Ava should say Probono Key Realty and Cash Offer consistently, never "Cash Wholesale" and never lead with the word "wholesaler."', `Provider mode is ${providerMode}; ${pendingApprovals} approval item${pendingApprovals === 1 ? '' : 's'} are currently pending.`];
  let answer = `${identity}\n\nPBK's five deal paths:\n${getPbkCoreDoctrineText()}\n\nOperating rules:\n- ${guardrails.join('\n- ')}\n\nDeal Analyzer and Call Mode use the same path stack: Opening, Acquisition, and Objection Engine. Calculators, live inputs, trackers, and PDF generation stay tied to the selected path.`;
  if (/scam|fake|trust/i.test(normalized)) {
    answer += '\n\nScam/fake handler: acknowledge the concern, offer verifiable office/site proof, state that PBK asks for no upfront money or sensitive info, then exit gracefully if trust is not restored.';
  }
  if (/slack|command/i.test(normalized)) {
    answer += '\n\nSlack command routing: /rex answers strategy and memory questions; /ava routes acquisition commands, corrections, instructions, and script notes through the same bridge memory and approval-safe tooling.';
  }
  const useful = matches
    .filter((doc) => doc && !String(doc.kind || '').includes('conversation-memory'))
    .slice(0, 2)
    .map((doc) => doc.title || doc.source)
    .filter(Boolean);
  if (useful.length) answer += `\n\nRelevant memory nearby: ${useful.join('; ')}.`;
  return {
    query: String(query || '').trim(),
    answer,
    matches: [],
    citations: ['PBK runtime doctrine', 'wholesale.agent.md', 'Deal Analyzer path script library'],
    doctrine: {
      paths: PBK_CORE_DEAL_PATHS,
      guardrails,
    },
  };
}

function getAvaMasterclassKnowledgeMatches(query = '', limit = 4) {
  const normalized = String(query || '')
    .trim()
    .toLowerCase();
  const scored = buildAvaMasterclassKnowledgeFacts()
    .map((fact) => ({
      ...fact,
      score: scorePbkTextMatch(normalized, `${fact.subject} ${fact.predicate} ${fact.object}`, fact.metadata) + Number(fact.confidence || 0),
    }))
    .filter((fact) => !normalized || fact.score > 0)
    .sort((left, right) => right.score - left.score)
    .slice(0, Math.max(1, Math.min(8, Number(limit || 4))));
  return scored;
}

function looksLikeAvaMasterclassCommand(command = '') {
  const normalized = String(command || '').toLowerCase();
  if (!normalized) return false;
  return /\b(masterclass|teach|training|train|coach|playbook|script|scripts|small talk|rapport|sports|politics|deflect|deflection|ego|emotional intelligence|phone eq|listening|interpretation|authority|understanding|7[-\s]?figure|seven[-\s]?figure|best books|influence|never split|spin selling|challenger|mortgage takeover|subject-to|subto|creative finance|novation|rbp|cash land|land offer|dumb|robotic|query-like|stuck|loop|probe|probing|natural|fluid|microphone|voice pipeline|transcript)\b/i.test(normalized) && /\b(ava|rex|ai|closer|agent|sales|wholesale|seller|call|phone|conversation|operator)\b/i.test(normalized);
}

function looksLikeAgentDoctrineCommand(command = '') {
  const normalized = String(command || '').toLowerCase();
  return /\b(ava|rex)\b/i.test(normalized) && /\b(who are you|what are you|explain|remember|instruction|instructions|bant|deal path|paths|script|objection|cash offer|doctrine|playbook|aware|small talk|rapport|sports|politics|ego|emotional intelligence|phone eq|listening|authority|understanding|seven figure|7-figure|books|mortgage takeover|creative finance|novation|rbp|land|dumb|robotic|query-like|stuck|loop|probe|probing|natural|fluid|microphone|voice|transcript|conversation flow|troubleshoot)\b/i.test(normalized);
}

function buildAvaDoctrineCommandResult(command = '', context = {}) {
  const masterclassMatches = getAvaMasterclassKnowledgeMatches(command, 5);
  const normalizedCommand = String(command || '').toLowerCase();
  const voiceOrQualityConcern = /\b(dumb|robotic|query-like|stuck|loop|probe|probing|natural|fluid|microphone|voice|transcript|conversation flow|troubleshoot)\b/i.test(normalizedCommand);
  const masterclassLines = masterclassMatches.map((fact) => `- ${String(fact.predicate || '').replace(/_/g, ' ')}: ${fact.object}`).filter(Boolean);
  return {
    ok: true,
    agent: 'ava',
    answer: ['Ava here. I am Ava Chen, Senior Wholesale Acquisition Specialist for Probono Key Realty.', 'My job is to qualify sellers, protect the MAO, keep each PBK path clean, and move qualified deals toward the right contract without pressure.', '', 'What I am locked onto:', `- BANT+ before seller-facing numbers: ${BANT_FIELDS.join(', ')}.`, '- Path discipline: Cash Offer, RBP, Creative Finance, Mortgage Takeover, and Land all keep their own Opening, Acquisition, and Objection Engine scripts.', '- Cash Offer wording stays consistent. I do not call it Cash Wholesale to sellers.', '- Scam/fake objections get verification, no defensiveness, and a graceful exit if trust is not restored.', '- Contracts, calls, SMS, email, and offer actions remain approval-safe unless operating mode explicitly allows them.', voiceOrQualityConcern ? '- If Ava sounds dumb or robotic, diagnose the pipeline first: no microphone audio or no Deepgram transcript starves her brain. Then verify the command is routed through agent_brain/strategist with pbk_knowledge, not a short fallback response.' : '', voiceOrQualityConcern ? '- Recovery behavior: name the broken lane, fall back to text, acknowledge the last real words, ask one BANT+ probing question, and do not pretend she heard a caller when the transcript is empty.' : '', context.address ? `- Current context address: ${context.address}.` : '', masterclassLines.length ? '' : '', masterclassLines.length ? 'Relevant pbk_knowledge masterclass:' : '', ...masterclassLines].filter(Boolean).join('\n'),
    doctrine: {
      paths: PBK_CORE_DEAL_PATHS,
      bantFields: BANT_FIELDS,
      masterclassRevision: AVA_MASTERCLASS_KNOWLEDGE_REVISION,
    },
    knowledgeFacts: masterclassMatches,
    command,
  };
}

function normalizeClosingContext(params = {}) {
  const context = params.context && typeof params.context === 'object' ? params.context : {};
  const deal = params.deal && typeof params.deal === 'object' ? params.deal : context.deal && typeof context.deal === 'object' ? context.deal : {};
  const conversation = params.conversation && typeof params.conversation === 'object' ? params.conversation : context.conversation && typeof context.conversation === 'object' ? context.conversation : {};
  const query = String(params.query || params.q || params.prompt || params.text || params.command || params.lastUserUtterance || conversation.lastUserUtterance || '').trim();
  const selectedPath = String(params.selectedPath || params.selected_path || params.path || deal.selectedPath || deal.selected_path || deal.path || context.selectedPath || context.selected_path || '')
    .trim()
    .toLowerCase();
  const sellerType =
    String(params.sellerType || params.seller_type || params.audience || context.sellerType || context.seller_type || (selectedPath === 'rbp' ? 'seller' : ''))
      .trim()
      .toLowerCase() || 'seller';
  const stage =
    String(params.stage || params.conversationStage || params.conversation_stage || conversation.stage || '')
      .trim()
      .toLowerCase() || 'objection_handling';
  const sentiment = params.sentiment ?? params.sentimentScore ?? params.sentiment_score ?? conversation.sentiment ?? context.sentiment ?? null;

  return {
    query,
    selectedPath,
    seller_type: sellerType,
    sellerType,
    stage,
    sentiment: sentiment === null || sentiment === undefined || sentiment === '' ? null : Math.max(0, Math.min(1, toNumber(sentiment, 0.5))),
    address: String(params.address || deal.address || context.address || '').trim(),
    leadName: String(params.leadName || params.lead_name || deal.leadName || context.leadName || '').trim(),
    agentName: String(params.agentName || params.agent || context.agentName || 'Ava').trim(),
  };
}

function classifyClosingObjection(query = '', context = {}) {
  const text = `${query} ${context.stage || ''} ${context.selectedPath || ''}`.toLowerCase();
  if (/\b(due[-\s]?on[-\s]?sale|loan called|lender call|subject[-\s]?to|subto|mortgage takeover|still in my name)\b/i.test(text)) return 'due_on_sale';
  if (/\b(sc[a@]m|fake|trust|proof|legit|real company|how do i know|verify|can you close)\b/i.test(text)) return 'trust_verification';
  if (/\b(think about|not sure|maybe|sleep on it|talk it over|circle back|follow up later)\b/i.test(text)) return 'needs_to_think';
  if (/\b(wife|husband|spouse|partner|brother|sister|mom|dad|child|kids|co[-\s]?owner|attorney|lawyer|decision maker|signer)\b/i.test(text)) return 'decision_maker';
  if (/\b(higher offer|another offer|better offer|someone else|other buyer|competing offer)\b/i.test(text)) return 'competing_offer';
  if (/\b(list|listing|realtor|agent|mls|open market|get more on market)\b/i.test(text)) return 'list_with_agent';
  if (/\b(price|number|offer|too low|lowball|more money|need more|worth more|counter)\b/i.test(text)) return 'price_too_low';
  if (/\b(fast|soon|asap|quick|today|this week|cash now|need cash|urgent)\b/i.test(text)) return 'timeline_urgency';
  return 'general_discovery';
}

function getClosingObjectionPlaybook(objectionType = 'general_discovery', context = {}) {
  const path = String(context.selectedPath || '').toLowerCase();
  const playbooks = {
    price_too_low: {
      skill: 'value_based_negotiation',
      technique: 'net-proceeds reframe',
      nextBestPhrase: 'I hear you. It sounds like you were hoping for a higher number. Let me slow down and show you what is shaping this: repairs, closing risk, holding time, and the certainty of no changes after closing.',
      closeQuestion: 'If the math is clear and the close is clean, what number would make this feel worth moving forward today?',
      tone: 'calm, consultative, not defensive',
      pacing: 'slow down before the number and pause after the reframe',
      doNotSay: ['Do not call it a lowball.', 'Do not raise price without a trade like faster close, no inspection, or signed today.', 'Do not invent comps or repair costs.'],
    },
    needs_to_think: {
      skill: 'calibrated_question_close',
      technique: 'isolate the real concern',
      nextBestPhrase: 'That makes sense. Usually when someone says they need to think, it is one of three things: the price, the timing, or trusting the process. Which one is the real thing for you?',
      closeQuestion: 'What would need to be true for you to feel comfortable taking the next step today?',
      tone: 'patient and direct',
      pacing: 'warm pause after listing the three concerns',
      doNotSay: ['Do not pressure or shame the seller.', 'Do not ask yes/no questions that let the stall continue.', 'Do not send a contract until authority and comfort are clear.'],
    },
    list_with_agent: {
      skill: 'market_option_reframe',
      technique: 'cash backstop versus listing uncertainty',
      nextBestPhrase: 'Listing can absolutely be a valid option. The tradeoff is time, showings, repairs, commissions, and the risk of price reductions. My lane is different: a clean backstop number with certainty, so you can compare the net instead of just the headline price.',
      closeQuestion: 'Would it help if I showed you the estimated net from listing versus the clean cash option side by side?',
      tone: 'respectful, agent-safe, no bypass energy',
      pacing: 'steady and collaborative',
      doNotSay: ['Do not bash agents.', 'Do not claim listing cannot work.', 'Do not use RBP/novation language with an agent-facing path unless approved by PBK rules.'],
    },
    competing_offer: {
      skill: 'competing_offer_diagnosis',
      technique: 'verify certainty without badmouthing',
      nextBestPhrase: 'That is good if it is real and closes. The only thing I would want you to verify is whether it is cash or financed, whether earnest money is already at title, and whether they can close without renegotiating after inspection.',
      closeQuestion: 'Would you be open to keeping my offer as a clean backup so you are protected if that one changes?',
      tone: 'confident and non-jealous',
      pacing: 'matter-of-fact, no urgency spike',
      doNotSay: ['Do not badmouth the other buyer.', 'Do not match an unverified offer.', 'Do not imply PBK can close above MAO.'],
    },
    trust_verification: {
      skill: 'trust_verification',
      technique: 'proof without defensiveness',
      nextBestPhrase: 'That is a fair question. You should verify anyone you work with. I can walk you through who we are, what happens before anything is signed, and what proof we can provide without asking you for money or sensitive information upfront.',
      closeQuestion: 'What would make you feel comfortable enough to continue the conversation: company info, proof of funds, title process, or a written summary?',
      tone: 'transparent and grounded',
      pacing: 'slow, reassuring, no sales pressure',
      doNotSay: ['Do not pretend to be human.', 'Do not ask for sensitive personal information upfront.', 'Do not get defensive about scam concerns.'],
    },
    decision_maker: {
      skill: 'decision_maker_alignment',
      technique: 'invite authority into the room',
      nextBestPhrase: 'I respect that. For something this important, it usually works better if the decision-makers hear the same information at the same time. I do not want you carrying the whole conversation back alone.',
      closeQuestion: 'Who else needs to be comfortable with this, and can we bring them into a quick three-way call?',
      tone: 'protective and collaborative',
      pacing: 'gentle authority',
      doNotSay: ['Do not treat the decision-maker as an obstacle.', 'Do not accept a verbal yes if required signers are missing.', 'Do not bypass a spouse, co-owner, attorney, or agent.'],
    },
    due_on_sale: {
      skill: 'subject_to_compliance_guardrail',
      technique: 'risk disclosure plus attorney review',
      nextBestPhrase: 'Good question. With subject-to or mortgage takeover, the loan can stay in the seller name until payoff, and there is a due-on-sale risk. I cannot guarantee lender behavior, so we explain the risk plainly and recommend attorney review before anyone signs.',
      closeQuestion: 'Would it help if I sent the plain-English structure summary so your agent or attorney can review it?',
      tone: 'plain, careful, legally safe',
      pacing: 'slow and precise',
      doNotSay: ['Do not say there is no risk.', 'Do not give legal advice.', 'Do not guarantee the lender will not call the loan.'],
    },
    timeline_urgency: {
      skill: 'urgency_to_next_step',
      technique: 'speed/certainty tradeoff',
      nextBestPhrase: 'If speed is the priority, the cleanest path is usually the one with the fewest moving parts: as-is, no repairs, title handles the paperwork, and we keep the number inside what underwriting can actually approve.',
      closeQuestion: 'If I can get this approved at a clean number today, are you ready to move to paperwork?',
      tone: 'decisive and calm',
      pacing: 'brisk but not rushed',
      doNotSay: ['Do not exploit distress.', 'Do not promise a closing date until title and approvals confirm it.', 'Do not skip DNC/TCPA or approval gates.'],
    },
    general_discovery: {
      skill: 'four_layer_pain_probe',
      technique: 'diagnose before prescribing',
      nextBestPhrase: 'Before I talk numbers, let me understand the situation correctly. What is the biggest thing you need solved with this property: speed, price, repairs, debt, or just getting it off your plate?',
      closeQuestion: 'If we solve that one thing, what would change for you in the next 30 to 90 days?',
      tone: 'curious and steady',
      pacing: 'one question at a time',
      doNotSay: ['Do not present an offer before BANT+ is complete.', 'Do not guess facts the analyzer or PBK tools can retrieve.', 'Do not blend deal-path scripts.'],
    },
  };
  const selected = playbooks[objectionType] || playbooks.general_discovery;
  const pathGuardrails = [];
  if (path === 'rbp') pathGuardrails.push('RBP/novation is seller-only; do not use it as an agent-facing pitch.');
  if (path === 'mt' || path === 'mortgage_takeover' || path === 'subject_to') pathGuardrails.push('Mortgage takeover language must disclose due-on-sale risk and stay agent-friendly.');
  if (path === 'cf' || path === 'creative_finance') pathGuardrails.push('Creative finance must explain seller upside, safeguards, and tradeoffs without forcing it on cash-needed sellers.');
  if (path === 'land') pathGuardrails.push('Land conversations must qualify utilities, access, zoning, acreage, and builder math before price.');
  return {
    ...selected,
    doNotSay: [...selected.doNotSay, ...pathGuardrails],
  };
}

async function retrieveClosingKnowledge(params = {}) {
  const context = normalizeClosingContext(params);
  const objectionType = params.objectionType || params.objection_type || classifyClosingObjection(context.query, context);
  const searchQuery = [context.query, objectionType.replace(/_/g, ' '), context.selectedPath, context.seller_type, context.stage, 'seven figure closer Ava PBK sales masterclass objection close'].filter(Boolean).join(' ');
  const knowledge = await queryPbkKnowledgeRecords({
    tenantId: params.tenantId || params.tenant_id || 'pbk',
    query: searchQuery,
    limit: params.limit || 6,
  });
  const brain = answerBrainQuery(state, searchQuery);
  const brainMatches = Array.isArray(brain?.matches) ? brain.matches.slice(0, 3) : [];
  return {
    context: {
      ...context,
      objectionType,
      searchQuery,
    },
    knowledgeFacts: Array.isArray(knowledge?.facts) ? knowledge.facts.slice(0, 6) : [],
    brainMatches,
    citations: [...(Array.isArray(knowledge?.facts) ? knowledge.facts.slice(0, 4).map((fact) => `${fact.subject || 'PBK Knowledge'} - ${String(fact.predicate || '').replace(/_/g, ' ')}`) : []), ...(Array.isArray(brain?.citations) ? brain.citations.slice(0, 2) : [])].filter(Boolean),
  };
}

async function buildClosingIntelligenceAdvice(params = {}) {
  const retrieval = await retrieveClosingKnowledge(params);
  const context = retrieval.context;
  const playbook = getClosingObjectionPlaybook(context.objectionType, context);
  const reaction = buildRealTimeConversationReaction({
    ...params,
    ...context,
    objectionType: context.objectionType,
  });
  const emotionalMemory = buildEmotionalMemoryPromptContext({ ...params, ...context });
  const emotionalTags = await inferEmotionalTagsRecord(
    {
      ...params,
      ...context,
      transcript: context.query || params.transcript || params.text || params.lastUserUtterance || '',
    },
    { persist: true }
  );
  const [memoryContext, similarDealProof] = await Promise.all([recallConversationMemoryForDeal({ ...params, ...context, limit: 4 }), retrieveSimilarDealProof({ ...params, ...context, limit: 2 })]);
  const factSupport = retrieval.knowledgeFacts.slice(0, 3).map((fact) => ({
    id: fact.id,
    predicate: fact.predicate,
    summary: fact.object,
    confidence: fact.confidence,
    tags: fact.metadata?.tags || fact.tags || [],
  }));
  const promptFrame = buildSevenFigurePromptFrame({
    ...params,
    ...context,
    objectionType: context.objectionType,
    playbook,
    reaction,
    emotionalMemory,
    emotionalTags: emotionalTags.ok ? emotionalTags : null,
    memoryContext,
    similarDealProof,
    factSupport,
  });
  const advice = {
    skill: playbook.skill,
    technique: playbook.technique,
    stage: context.stage,
    objectionType: context.objectionType,
    selectedPath: context.selectedPath || 'unknown',
    seller_type: context.seller_type,
    nextBestPhrase: playbook.nextBestPhrase,
    closeQuestion: playbook.closeQuestion,
    tone: playbook.tone,
    pacing: playbook.pacing,
    doNotSay: playbook.doNotSay,
    support: factSupport,
    promptFrame,
    reaction,
    prosody: reaction.prosody,
    emotionalMemory,
    emotionalTags: emotionalTags.ok ? emotionalTags : null,
    memories: memoryContext.memories,
    similarDeals: similarDealProof.deals,
    socialProofPhrase: similarDealProof.sellerSafePhrase,
    noveltyRecovery: reaction.noveltyRecovery,
    confidence: Math.max(0.62, Math.min(0.98, 0.72 + Math.min(0.18, retrieval.knowledgeFacts.length * 0.03))),
  };
  const synthesized =
    params.synthesize === true || params.deepSeek === true
      ? await synthesizeClosingAnswerWithDeepSeek({
          ...params,
          context,
          playbook,
          advice,
          emotionalMemory,
          memoryContext,
          similarDealProof,
          factSupport,
        })
      : null;
  if (synthesized?.ok && synthesized.answer) {
    advice.deepSeekAnswer = synthesized.answer;
    advice.nextBestPhrase = normalizeAvaSpokenScript(synthesized.answer) || advice.nextBestPhrase;
    advice.provider = synthesized.provider;
  }
  return {
    ok: true,
    result: 'closing_intelligence',
    source: 'pbk_knowledge',
    query: context.query,
    selectedPath: advice.selectedPath,
    seller_type: advice.seller_type,
    stage: context.stage,
    objectionType: context.objectionType,
    nextBestPhrase: advice.nextBestPhrase,
    closeQuestion: advice.closeQuestion,
    doNotSay: advice.doNotSay,
    confidence: advice.confidence,
    advice,
    promptFrame,
    reaction,
    prosody: reaction.prosody,
    emotionalMemory,
    emotionalTags: emotionalTags.ok ? emotionalTags : null,
    memories: memoryContext.memories,
    similarDeals: similarDealProof.deals,
    socialProofPhrase: similarDealProof.sellerSafePhrase,
    noveltyRecovery: reaction.noveltyRecovery,
    synthesizedAnswer: synthesized?.answer || '',
    knowledgeFacts: retrieval.knowledgeFacts,
    brainMatches: retrieval.brainMatches,
    citations: retrieval.citations.length ? retrieval.citations : ['Ava wholesale conversation masterclass', 'PBK knowledge graph'],
  };
}

function buildAvaProsodyProfile(params = {}) {
  const text = String(params.text || params.transcript || params.query || params.lastUserUtterance || '').toLowerCase();
  const detected = params.intent && typeof params.intent === 'object' ? params.intent : classifyPbkIntent(text);
  const rawSentiment = params.sentiment ?? params.sentimentScore ?? params.sentiment_score ?? params.pbkScore ?? params.score;
  const sentiment = rawSentiment === null || rawSentiment === undefined || rawSentiment === '' ? (estimatePbkLiveSentiment(text).pbkScore ?? 0.55) : Math.max(0, Math.min(1, toNumber(rawSentiment, 0.55)));
  const emotion = String(params.emotion || params.sentimentLabel || detected.communicationProfile?.emotionalState || inferSellerEmotion({ ...params, text })).toLowerCase();
  let profile = 'steady_consultative';
  let speed = 0.98;
  let stability = 0.48;
  let similarityBoost = 0.78;
  let pauseMs = 650;
  let pitchGuidance = 'neutral';
  let delivery = 'calm, clear, medium pace';

  if (sentiment < 0.35 || /angry|frustrated|defensive|distrust/.test(emotion)) {
    profile = 'de_escalation';
    speed = 0.84;
    stability = 0.62;
    similarityBoost = 0.82;
    pauseMs = 1100;
    pitchGuidance = 'slightly lower';
    delivery = 'slow down, lower the tone, label the concern, and pause before the next question';
  } else if (sentiment < 0.55 || /hesitant|guarded|unsure/.test(emotion)) {
    profile = 'trust_builder';
    speed = 0.92;
    stability = 0.56;
    similarityBoost = 0.8;
    pauseMs = 850;
    pitchGuidance = 'warm-neutral';
    delivery = 'warm, patient, one question at a time';
  } else if (sentiment > 0.72 || detected.intent === 'ready_to_close') {
    profile = 'closing_momentum';
    speed = 1.04;
    stability = 0.44;
    similarityBoost = 0.77;
    pauseMs = 450;
    pitchGuidance = 'slightly brighter';
    delivery = 'confident and concise; move to one clear next step';
  } else if (/grieving|overwhelmed/.test(emotion)) {
    profile = 'grief_safe';
    speed = 0.86;
    stability = 0.68;
    similarityBoost = 0.82;
    pauseMs = 1250;
    pitchGuidance = 'soft and lower';
    delivery = 'very slow, dignified, no humor, reduce the burden';
  }

  const turnCount = Math.max(0, Math.round(toNumber(params.turnCount ?? params.turn_count ?? params.conversationTurnCount, 0)));
  const intensity = clampProsodyNumber(params.intensity ?? params.emotionIntensity ?? (/angry|frustrated|grieving|overwhelmed|urgent|excited/.test(emotion) ? 0.72 : 0.5), 0, 1, 0.5);
  const tags = deriveDynamicProsodyTags({
    text,
    emotion,
    intensity,
    profile,
    turnCount,
    sentiment,
    lastObjectionSecondsAgo: params.lastObjectionSecondsAgo ?? params.last_objection_seconds_ago,
  });
  const learned = suggestProsodyFromActiveModel({
    emotion,
    profile,
    sentiment,
    intensity,
    stability,
    speed,
    similarityBoost,
  });
  if (learned?.applied) {
    stability = learned.stability;
    speed = learned.speed;
    similarityBoost = learned.similarityBoost;
  }

  const interactionStyle = selectWarmthDominance({
    emotion,
    sentiment,
    hesitation: params.hesitation,
    buyingSignal: params.buyingSignal ?? params.buying_signal,
    readyToClose: detected.intent === 'ready_to_close',
    pathLocked: params.pathLocked === true || params.path_locked === true,
    bantComplete: params.bantComplete === true || params.bant_complete === true,
    shouldHandoff: params.shouldHandoff === true || params.should_handoff === true,
    shouldStopContact:
      params.shouldStopContact === true ||
      params.should_stop_contact === true ||
      /\b(stop calling|do not call|don't call|remove me|unsubscribe)\b/i.test(text),
  });
  const styled = applyWarmthDominance(
    {
      speed,
      stability,
      similarityBoost,
      pauseMs,
    },
    interactionStyle
  );
  speed = styled.speed;
  stability = styled.stability;
  similarityBoost = styled.similarityBoost;
  pauseMs = styled.pauseMs;
  delivery = `${delivery}; ${interactionStyle.instruction}`;

  return {
    profile,
    sentiment,
    emotion,
    intensity,
    speed,
    stability,
    similarityBoost,
    similarity_boost: similarityBoost,
    pauseMs,
    pitchGuidance,
    delivery,
    interactionStyle,
    tags,
    audioTags: {
      enabled: ELEVENLABS_AUDIO_TAGS_ENABLED,
      planned: tags,
      reason: ELEVENLABS_AUDIO_TAGS_ENABLED ? 'enabled_by_environment' : 'disabled_for_low_latency_model_safety',
    },
    ssml: {
      enabled: ELEVENLABS_SSML_ENABLED,
      reason: ELEVENLABS_SSML_ENABLED ? 'enabled_by_environment' : 'disabled_for_provider_compatibility',
    },
    learningModel: learned,
    voiceSettings: {
      stability,
      similarity_boost: similarityBoost,
      speed,
      use_speaker_boost: true,
    },
  };
}

function clampProsodyNumber(value, min, max, fallback) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(min, Math.min(max, number));
}

function normalizeProsodyTag(value = '') {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/^\[|\]$/g, '')
    .replace(/[^a-z0-9_-]+/g, '_');
}

function deriveDynamicProsodyTags(params = {}) {
  const text = String(params.text || '').toLowerCase();
  const emotion = String(params.emotion || params.profile || '').toLowerCase();
  const profile = String(params.profile || '').toLowerCase();
  const intensity = clampProsodyNumber(params.intensity, 0, 1, 0.5);
  const sentiment = clampProsodyNumber(params.sentiment, 0, 1, 0.55);
  const turnCount = Math.max(0, Math.round(toNumber(params.turnCount ?? params.turn_count, 0)));
  const lastObjectionSecondsAgo = Number(params.lastObjectionSecondsAgo ?? params.last_objection_seconds_ago ?? 999);
  const tags = new Set();

  if ((/joy|happy|excited/.test(emotion) || profile === 'closing_momentum' || sentiment > 0.76) && intensity >= 0.65) {
    tags.add('excited');
    if (intensity >= 0.78 && turnCount <= 12) tags.add('laughs');
  }
  if (/sad|grief|overwhelmed/.test(emotion) || profile === 'grief_safe' || /\b(worried|scared|overwhelmed|lost my|passed away)\b/.test(text)) {
    tags.add('softly');
    if (intensity >= 0.55) tags.add('sighs');
  }
  if (/fear|anxious|worried/.test(emotion) || /\b(scared|nervous|not sure|trust|scam)\b/.test(text)) {
    tags.add('softly');
    if (intensity >= 0.72) tags.add('whispers');
  }
  if (/angry|frustrated|defensive|distrust/.test(emotion) || profile === 'de_escalation' || lastObjectionSecondsAgo < 15) {
    tags.add('softly');
    tags.delete('laughs');
    tags.delete('excited');
  }
  if (/\b(today|quickly|now|urgent|asap|deadline)\b/.test(text) && sentiment >= 0.45) {
    tags.add('focused');
    if (sentiment > 0.65) tags.add('excited');
  }

  return Array.from(tags).map(normalizeProsodyTag).filter(Boolean).slice(0, 4);
}

function supportsElevenLabsAudioTags(modelId = '') {
  if (ELEVENLABS_AUDIO_TAGS_ENABLED) return true;
  return /\bv3\b|eleven_v3|eleven-?v3/i.test(String(modelId || ''));
}

function escapeSsmlText(value = '') {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function injectDynamicProsodyTags(text = '', tags = [], options = {}) {
  const modelId = String(options.modelId || '').trim();
  const normalized = [...new Set((Array.isArray(tags) ? tags : []).map(normalizeProsodyTag).filter(Boolean))];
  const enabled = supportsElevenLabsAudioTags(modelId);
  const cleanText = String(text || '');
  if (!enabled || !normalized.length) {
    return {
      text: cleanText,
      applied: false,
      tags: normalized,
      reason: normalized.length ? 'audio_tags_disabled_for_live_model' : 'no_tags_planned',
    };
  }
  const bracketTags = normalized.map((tag) => `[${tag}]`);
  let tagged = cleanText;
  const midSentenceTag = bracketTags.find((tag) => /\[(laughs|sighs|softly|whispers)\]/i.test(tag));
  if (midSentenceTag && /[,.!?]\s+/.test(tagged)) {
    tagged = tagged.replace(/([,.!?])\s+/, `$1 ${midSentenceTag} `);
  }
  tagged = `${bracketTags.slice(0, 2).join(' ')} ${tagged}`.replace(/\s+/g, ' ').trim();
  return {
    text: tagged,
    applied: true,
    tags: normalized,
    reason: 'audio_tags_injected',
  };
}

function buildProsodySsml(text = '', prosody = {}) {
  if (!ELEVENLABS_SSML_ENABLED) {
    return {
      text: String(text || ''),
      applied: false,
      reason: 'ssml_disabled_for_provider_compatibility',
    };
  }
  const speed = clampProsodyNumber(prosody.speed, 0.7, 1.35, 1);
  const pauseMs = Math.round(clampProsodyNumber(prosody.pauseMs, 150, 1400, 500));
  let escaped = escapeSsmlText(text);
  if (/de_escalation|trust_builder|grief_safe/i.test(String(prosody.profile || ''))) {
    escaped = escaped.replace(/\b(understand|hear you|fair|comfortable|concern)\b/gi, '<prosody rate="slow" pitch="-2%">$1</prosody>');
  }
  if (/closing_momentum/i.test(String(prosody.profile || ''))) {
    escaped = escaped.replace(/\b(today|next step|move forward|quickly|close)\b/gi, '<prosody rate="fast" pitch="+2%">$1</prosody>');
  }
  escaped = escaped.replace(/([.!?])\s+/g, `$1<break time="${pauseMs}ms"/> `);
  return {
    text: `<speak><prosody rate="${speed.toFixed(2)}">${escaped}</prosody></speak>`,
    applied: true,
    reason: 'ssml_applied',
  };
}

function applyProsodyTextControls(text = '', prosody = {}, options = {}) {
  const modelId = String(options.modelId || '').trim();
  const tagResult = injectDynamicProsodyTags(text, prosody.tags || prosody.audioTags?.planned || [], { modelId });
  const ssmlResult = buildProsodySsml(tagResult.text, prosody);
  return {
    text: ssmlResult.applied ? ssmlResult.text : tagResult.text,
    originalText: String(text || ''),
    tags: tagResult.tags,
    appliedTags: tagResult.applied,
    tagReason: tagResult.reason,
    ssmlApplied: ssmlResult.applied,
    ssmlReason: ssmlResult.reason,
    modelId,
  };
}

function getActiveProsodyModel() {
  const models = Array.isArray(state.prosodyModels) ? state.prosodyModels : [];
  return sortNewest(models).find((model) => model?.active === true && plainObject(model.modelJson || model.model_json).emotionAverages);
}

function suggestProsodyFromActiveModel(params = {}) {
  const model = getActiveProsodyModel();
  if (!model) return { applied: false, reason: 'no_active_model' };
  const modelJson = plainObject(model.modelJson || model.model_json);
  const emotionAverages = plainObject(modelJson.emotionAverages);
  const keyCandidates = [String(params.emotion || '').toLowerCase(), String(params.profile || '').toLowerCase(), 'global'].filter(Boolean);
  let suggestion = null;
  let matchedKey = '';
  for (const key of keyCandidates) {
    const candidate = plainObject(emotionAverages[key]);
    if (Number(candidate.sampleCount || 0) >= 3) {
      suggestion = candidate;
      matchedKey = key;
      break;
    }
  }
  if (!suggestion) return { applied: false, reason: 'insufficient_matching_samples', modelId: model.id };
  return {
    applied: true,
    reason: 'active_success_model',
    modelId: model.id,
    matchedKey,
    sampleCount: Number(suggestion.sampleCount || 0),
    stability: clampProsodyNumber(suggestion.stability, 0.2, 0.9, params.stability ?? 0.5),
    speed: clampProsodyNumber(suggestion.speed, 0.7, 1.35, params.speed ?? 1),
    similarityBoost: clampProsodyNumber(suggestion.similarityBoost, 0.5, 0.95, params.similarityBoost ?? 0.78),
  };
}

function buildRealTimeConversationReaction(params = {}) {
  const query = String(params.query || params.text || params.transcript || params.lastUserUtterance || '').trim();
  const detected = classifyPbkIntent(query);
  const objectionType = params.objectionType || classifyClosingObjection(query, params);
  const prosody = buildAvaProsodyProfile({ ...params, text: query, intent: detected });
  const sentiment = prosody.sentiment;
  let trigger = 'continue';
  let skillToLoad = getClosingObjectionPlaybook(objectionType, params).skill;
  let nextTactic = 'Ask one calibrated question and keep the seller in the frame.';
  let immediatePhrase = '';

  if (detected.intent === 'not_interested' || /\b(stop calling|do not call|take me off|remove me)\b/i.test(query)) {
    trigger = 'compliance_exit';
    skillToLoad = 'dnc_boundary';
    nextTactic = 'Stop persuasion, apologize, confirm opt-out, and mark DNC.';
    immediatePhrase = 'I understand. I will stop outreach and make sure this number is marked do-not-call.';
  } else if (sentiment < 0.35 || /angry|frustrated|distrustful/.test(prosody.emotion)) {
    trigger = 'de_escalate';
    skillToLoad = 'de_escalation';
    nextTactic = 'Label the emotion, slow the pace, and ask what would make the seller comfortable.';
    immediatePhrase = 'I hear that this is frustrating. Let me slow down and make sure I understand what matters most to you right now.';
  } else if (detected.intent === 'ready_to_close' || (sentiment > 0.72 && /\b(send|sign|move forward|sounds good|let's do it)\b/i.test(query))) {
    trigger = 'close';
    skillToLoad = 'rule_of_three_close';
    nextTactic = 'Confirm price, timeline, and decision authority before paperwork.';
    immediatePhrase = 'That sounds like we may have a path. Before I prepare anything, let me confirm the price, timeline, and who needs to sign.';
  } else if (objectionType === 'general_discovery' && query && !/\b(address|property|timeline|condition|price|offer|agent|cash|mortgage|repair|close|sign|trust|scam)\b/i.test(query)) {
    trigger = 'novel_objection';
    skillToLoad = 'confession_with_bridge';
    nextTactic = 'Do not bluff. Bridge to a clarifying question and retrieve deeper knowledge.';
    immediatePhrase = 'That is a fair question. Let me make sure I answer the right thing instead of guessing.';
  }

  const noveltyRecovery =
    trigger === 'novel_objection'
      ? {
          pattern: 'confession_with_bridge',
          phrase: `${immediatePhrase} Are you mainly concerned about the money, the timeline, or the risk?`,
          followUp: 'If the answer needs legal, tax, title, or lender-specific review, offer a written summary and human follow-up.',
        }
      : null;

  return {
    ok: true,
    trigger,
    intent: detected.intent,
    confidence: detected.confidence,
    objectionType,
    skillToLoad,
    nextTactic,
    immediatePhrase,
    prosody,
    noveltyRecovery,
    shouldHandoff: prosody.sentiment < 0.25 || detected.communicationProfile?.safety?.offerHumanTransfer === true,
    shouldStopContact: detected.communicationProfile?.safety?.stopIfRequested === true || trigger === 'compliance_exit',
  };
}

function buildSevenFigurePromptFrame(params = {}) {
  const memories = Array.isArray(params.memoryContext?.memories) ? params.memoryContext.memories : [];
  const similarDeals = Array.isArray(params.similarDealProof?.deals) ? params.similarDealProof.deals : [];
  const support = Array.isArray(params.factSupport) ? params.factSupport : [];
  const emotionalMemory = params.emotionalMemory?.ok ? params.emotionalMemory : null;
  const emotionalTags = params.emotionalTags?.ok ? params.emotionalTags : null;
  return {
    role: 'Ava is a top 1% approval-gated real estate acquisitions closer: calm authority, tactical empathy, no desperation, no fake certainty.',
    internalChecklist: ['What is the seller really afraid of or trying to protect?', 'What emotional memory or emotional tag from prior turns must change the timing, tone, or offer pressure?', 'Which frame keeps PBK as the calm expert instead of a desperate buyer?', 'What missing BANT+ fact must be discovered before numbers or paperwork?', 'Which proof point is safe to use: analyzer math, similar PBK deal, memory, or retrieved knowledge?', 'What is the one next step: clarify, de-escalate, verify, close, hand off, or stop contact?'],
    stageInstruction:
      {
        discovery: 'Diagnose before prescribing. Ask one open question and uncover impact.',
        objection_handling: 'Acknowledge first, reframe second, ask a calibrated question third.',
        negotiation: 'Trade concessions; never raise price without speed, certainty, inspection, or signature tradeoff.',
        closing: 'Confirm the rule of three: price, timeline, authority. Then prepare approval-gated paperwork.',
      }[String(params.stage || '').toLowerCase()] || 'Keep the response short, useful, and grounded in PBK facts.',
    usableContext: {
      objectionType: params.objectionType || '',
      selectedPath: params.selectedPath || params.selected_path || '',
      memoryCount: memories.length,
      emotionalMemoryPresent: Boolean(emotionalMemory),
      emotionalDominant: emotionalMemory?.dominantEmotion || '',
      emotionalPolicyHint: emotionalMemory?.policyHint || '',
      emotionalTagSource: emotionalTags?.source || '',
      emotionalPrimaryTag: emotionalTags?.strategy?.primaryTag || '',
      similarDealCount: similarDeals.length,
      supportCount: support.length,
      socialProofPhrase: params.similarDealProof?.sellerSafePhrase || '',
    },
    emotionalMemory: emotionalMemory
      ? {
          schemaVersion: emotionalMemory.schemaVersion,
          dominantEmotion: emotionalMemory.dominantEmotion,
          intensity: emotionalMemory.intensity,
          emotionState: emotionalMemory.emotionState,
          context: emotionalMemory.context,
          lastUtterance: emotionalMemory.lastUtterance,
          policyHint: emotionalMemory.policyHint,
          promptInstruction: emotionalMemory.promptInstruction,
          updatedAt: emotionalMemory.updatedAt,
        }
      : null,
    emotionalTags: emotionalTags
      ? {
          schemaVersion: emotionalTags.schemaVersion,
          source: emotionalTags.source,
          tags: emotionalTags.tags,
          tagSignature: emotionalTags.tagSignature,
          strategy: emotionalTags.strategy,
          memory: emotionalTags.memory,
        }
      : null,
    spokenRules: ['Never list the hidden checklist out loud.', 'Never invent comps, legal advice, lender behavior, or closed-deal proof.', 'If confidence is low, ask one clarifying question instead of filling dead air.', 'If the seller is angry, slow down and de-escalate before selling.', emotionalMemory?.promptInstruction || '', emotionalTags?.strategy?.promptInstruction || ''].filter(Boolean),
  };
}

function normalizeDealCandidateText(candidate = {}) {
  const metadata = candidate.metadata && typeof candidate.metadata === 'object' ? candidate.metadata : {};
  return [candidate.address, candidate.propertyAddress, candidate.leadName, candidate.selectedPath, candidate.path, candidate.contractType, candidate.status, candidate.city, candidate.state, candidate.condition, candidate.arv, candidate.mao, candidate.price, candidate.amount, metadata.address, metadata.selectedPath, metadata.condition].filter(Boolean).join(' ');
}

function collectSimilarDealCandidates() {
  const candidates = [];
  for (const contract of state.contracts || []) {
    candidates.push({
      id: contract.id || `contract-${candidates.length}`,
      source: 'contracts',
      leadId: contract.leadId || '',
      leadName: contract.leadName || contract.sellerName || '',
      address: contract.address || contract.propertyAddress || '',
      selectedPath: contract.selectedPath || contract.path || contract.contractType || '',
      status: contract.status || '',
      amount: contract.amount || contract.price || contract.offerPrice || 0,
      closed: /\b(completed|signed|closed|executed)\b/i.test(String(contract.status || '')),
      daysToClose: contract.daysToClose || contract.metadata?.daysToClose || '',
      createdAt: contract.createdAt || contract.updatedAt || '',
      metadata: contract.metadata || {},
    });
  }
  for (const run of state.analyzerRuns || []) {
    candidates.push({
      id: run.id || `analyzer-${candidates.length}`,
      source: 'analyzerRuns',
      leadId: run.leadId || '',
      leadName: run.leadName || '',
      address: run.address || run.propertyAddress || '',
      selectedPath: run.selectedPath || run.path || run.result?.selectedPath || '',
      status: run.status || 'analyzed',
      amount: run.offerPrice || run.price || run.result?.offerPrice || run.result?.mao || 0,
      arv: run.arv || run.result?.arv || 0,
      mao: run.mao || run.result?.mao || 0,
      repairs: run.repairs || run.result?.repairs || 0,
      closed: false,
      createdAt: run.createdAt || run.updatedAt || '',
      metadata: run.metadata || {},
    });
  }
  for (const memory of state.pbkMemories || []) {
    if (!/\b(closed|signed|accepted|similar|deal recap|seller win)\b/i.test(String(memory.content || ''))) continue;
    candidates.push({
      id: memory.id || `memory-${candidates.length}`,
      source: 'pbkMemories',
      leadId: memory.leadId || '',
      leadName: memory.metadata?.leadName || '',
      address: memory.metadata?.address || '',
      selectedPath: memory.metadata?.selectedPath || memory.metadata?.path || '',
      status: memory.metadata?.status || 'memory',
      amount: memory.metadata?.amount || memory.metadata?.offerPrice || 0,
      closed: /\b(closed|signed|accepted)\b/i.test(String(memory.content || '')),
      createdAt: memory.createdAt || '',
      summary: memory.content,
      metadata: memory.metadata || {},
    });
  }
  return candidates;
}

async function retrieveSimilarDealProof(params = {}) {
  const context = findLeadContext(params);
  const query = [params.query, params.address || context.address, params.selectedPath || params.path || params.selected_path, params.condition, params.arv, params.repairs].filter(Boolean).join(' ');
  const limit = Math.max(1, Math.min(5, Number(params.limit || 2)));
  const candidates = collectSimilarDealCandidates()
    .map((candidate) => {
      const text = normalizeDealCandidateText(candidate);
      const pathMatch =
        String(candidate.selectedPath || '').toLowerCase() &&
        String(query || '')
          .toLowerCase()
          .includes(String(candidate.selectedPath || '').toLowerCase());
      const score = scorePbkTextMatch(query || context.address || candidate.address, `${text} ${candidate.summary || ''}`, candidate.metadata) + (candidate.closed ? 0.35 : 0) + (pathMatch ? 0.18 : 0);
      return { ...candidate, score };
    })
    .filter((candidate) => candidate.score > 0)
    .sort((left, right) => right.score - left.score || new Date(right.createdAt || 0) - new Date(left.createdAt || 0))
    .slice(0, limit);
  const sellerSafePhrase = candidates.length ? (candidates[0].closed ? `We have closed a similar ${candidates[0].selectedPath || 'deal'} file before, so I can compare this against a real PBK process instead of guessing.` : `I can compare this against similar PBK analyzer files, but I will not call it a closed comp unless it is actually closed.`) : '';
  return {
    ok: true,
    result: 'similar_deals',
    query,
    deals: candidates.map((candidate) => ({
      id: candidate.id,
      source: candidate.source,
      address: candidate.address,
      selectedPath: candidate.selectedPath,
      status: candidate.status,
      amount: candidate.amount,
      closed: candidate.closed,
      score: Number(candidate.score.toFixed(3)),
      sellerSafeSummary: candidate.closed ? `Similar closed ${candidate.selectedPath || 'deal'}${candidate.amount ? ` around ${formatReadableCurrency(candidate.amount)}` : ''}.` : `Similar PBK file (${candidate.status || candidate.source}) for context only.`,
    })),
    sellerSafePhrase,
  };
}

async function recallConversationMemoryForDeal(params = {}) {
  const context = findLeadContext(params);
  const query = String(params.query || params.transcript || params.text || context.address || context.leadName || '').trim();
  const memory = await recallPbkMemoryRecords({
    ...params,
    leadId: params.leadId || context.leadId,
    query,
    limit: params.limit || 5,
    includeGlobal: params.includeGlobal === true,
  });
  return {
    ok: true,
    result: 'conversation_memory',
    memories: (memory.memories || []).map((item) => ({
      id: item.id,
      leadId: item.leadId,
      memoryType: item.memoryType,
      content: item.content,
      importance: item.importance,
      source: item.source,
      createdAt: item.createdAt,
      recallScore: item.recallScore,
    })),
    count: memory.count || 0,
  };
}

async function runTavilySearch(query = '', params = {}) {
  const cleanQuery = String(query || '').trim();
  if (!cleanQuery)
    return {
      ok: false,
      result: 'invalid_request',
      answer: 'Search query is required.',
      citations: [],
    };
  if (!TAVILY_API_KEY) {
    return {
      ok: false,
      result: 'provider_missing',
      answer: 'Tavily search is not configured. Add PBK_TAVILY_API_KEY.',
      citations: [],
    };
  }
  try {
    const response = await fetch(TAVILY_SEARCH_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${TAVILY_API_KEY}`,
      },
      body: JSON.stringify({
        query: cleanQuery,
        search_depth: params.searchDepth || params.search_depth || 'basic',
        max_results: Math.max(1, Math.min(5, Number(params.maxResults || params.max_results || 3))),
        include_answer: true,
      }),
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      return {
        ok: false,
        result: 'provider_error',
        answer: payload?.error || `Tavily returned ${response.status}`,
        citations: [],
        payload,
      };
    }
    const results = Array.isArray(payload?.results) ? payload.results : [];
    return {
      ok: true,
      result: 'live',
      provider: 'Tavily',
      query: cleanQuery,
      answer:
        payload?.answer ||
        results
          .map((item) => item.content || item.snippet || '')
          .filter(Boolean)
          .join('\n')
          .slice(0, 1200),
      citations: results
        .map((item) => item.url)
        .filter(Boolean)
        .slice(0, 5),
      results,
    };
  } catch (error) {
    return {
      ok: false,
      result: 'provider_error',
      answer: error?.message || 'Tavily search failed.',
      citations: [],
    };
  }
}

const WEB_SEARCH_SPIKE_KEYWORD_NEURONS = [
  ['urgent', 30],
  ['delay', 31],
  ['risk', 32],
  ['foreclosure', 33],
  ['probate', 34],
  ['inheritance', 35],
  ['tax', 36],
  ['interest rate', 37],
  ['mortgage', 38],
  ['comps', 39],
  ['market', 40],
  ['price', 41],
  ['cash', 42],
  ['creative finance', 43],
  ['seller finance', 44],
  ['subject to', 45],
  ['repair', 46],
  ['closing', 47],
  ['contract', 48],
  ['approval', 49],
  ['compliance', 50],
  ['dnc', 51],
  ['script', 52],
  ['objection', 53],
  ['agent', 54],
  ['listing', 55],
  ['tenant', 56],
  ['vacant', 57],
  ['deadline', 58],
  ['opportunity', 59],
];

const WEB_SEARCH_SPIKE_SPECIAL_NEURONS = {
  live: 245,
  fallback: 246,
  tavily: 247,
  openai: 248,
  deepseek: 249,
  negativeSentiment: 250,
  positiveSentiment: 251,
  confidence: 252,
  uncertainty: 253,
};

function clampUnit(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return 0;
  return Math.max(0, Math.min(1, parsed));
}

function escapeRegExp(value = '') {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function compactPreview(value = '', maxLength = 180) {
  const text = String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
  if (text.length <= maxLength) return text;
  return `${text.slice(0, Math.max(0, maxLength - 3)).trim()}...`;
}

function buildWebSearchSpikeText(result = {}) {
  const parts = [result.answer, result.summary, result.text];
  if (Array.isArray(result.results)) {
    for (const item of result.results.slice(0, 5)) {
      parts.push(item?.title, item?.content, item?.snippet, item?.raw_content);
    }
  }
  if (result.fallback?.answer) parts.push(result.fallback.answer);
  return parts.filter(Boolean).join('\n').replace(/\s+/g, ' ').trim();
}

function countKeywordOccurrences(text = '', keyword = '') {
  const cleanKeyword = String(keyword || '').trim();
  if (!cleanKeyword) return 0;
  const pattern = cleanKeyword.includes(' ') ? escapeRegExp(cleanKeyword).replace(/\s+/g, '\\s+') : `\\b${escapeRegExp(cleanKeyword)}\\b`;
  const matches = String(text || '').match(new RegExp(pattern, 'gi'));
  return matches ? matches.length : 0;
}

function estimateWebSearchSentiment(text = '') {
  const lower = String(text || '').toLowerCase();
  const positive = ['opportunity', 'success', 'approved', 'growth', 'closed', 'benefit', 'strong', 'improved', 'safe'];
  const negative = ['risk', 'urgent', 'delay', 'foreclosure', 'breach', 'failed', 'error', 'scam', 'lawsuit', 'problem'];
  const positiveHits = positive.reduce((sum, word) => sum + countKeywordOccurrences(lower, word), 0);
  const negativeHits = negative.reduce((sum, word) => sum + countKeywordOccurrences(lower, word), 0);
  if (!positiveHits && !negativeHits) return 0;
  return Math.max(-1, Math.min(1, (positiveHits - negativeHits) / Math.max(1, positiveHits + negativeHits)));
}

function getWebSearchProviderKey(result = {}) {
  const raw = [result.provider?.name, result.provider?.provider, result.provider?.mode, result.provider?.model, typeof result.provider === 'string' ? result.provider : '', result.result].filter(Boolean).join(' ').toLowerCase();
  if (/tavily/.test(raw)) return 'tavily';
  if (/deepseek|deepseek_brain/.test(raw)) return 'deepseek';
  if (/openai|gpt|responses-web-search|web_search/.test(raw)) return 'openai';
  if (/brain/.test(raw)) return 'pbk_brain';
  return 'unknown';
}

function buildSearchResultToSpikes(result = {}, params = {}) {
  const text = buildWebSearchSpikeText(result);
  const lower = text.toLowerCase();
  const features = WEB_SEARCH_SPIKE_KEYWORD_NEURONS.map(([keyword, neuronId]) => ({
    keyword,
    neuronId,
    count: countKeywordOccurrences(lower, keyword),
  }))
    .filter((feature) => feature.count > 0)
    .sort((left, right) => right.count - left.count || left.neuronId - right.neuronId)
    .slice(0, Math.max(3, Math.min(12, Number(params.maxSpikeFeatures || 10))));
  const maxCount = Math.max(1, ...features.map((feature) => feature.count));
  const neuronIds = [];
  const strengths = [];
  const addSpike = (neuronId, strength) => {
    if (!Number.isFinite(Number(neuronId))) return;
    neuronIds.push(Number(neuronId));
    strengths.push(Number(clampUnit(strength).toFixed(3)));
  };
  for (const feature of features) {
    feature.strength = Number((0.25 + 0.75 * (feature.count / maxCount)).toFixed(3));
    addSpike(feature.neuronId, feature.strength);
  }

  const providerKey = getWebSearchProviderKey(result);
  if (result.live) addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.live, 0.85);
  if (!result.live) addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.fallback, 0.75);
  if (providerKey === 'tavily') addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.tavily, 0.9);
  if (providerKey === 'openai') addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.openai, 0.75);
  if (providerKey === 'deepseek') addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.deepseek, 0.8);

  const sentiment = estimateWebSearchSentiment(text);
  if (sentiment < -0.2) addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.negativeSentiment, Math.abs(sentiment));
  if (sentiment > 0.2) addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.positiveSentiment, sentiment);
  addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.confidence, result.ok === false ? 0.25 : result.live ? 0.9 : 0.55);
  if (!result.live || /uncertain|verify|fallback|not configured|could not/i.test(String(result.answer || ''))) {
    addSpike(WEB_SEARCH_SPIKE_SPECIAL_NEURONS.uncertainty, result.live ? 0.35 : 0.75);
  }

  return {
    version: 'pbk-web-search-spikes-v1',
    source: 'web-search',
    provider: providerKey,
    live: Boolean(result.live),
    targetAgents: Array.isArray(params.targetAgents) && params.targetAgents.length ? params.targetAgents : ['ava', 'rex'],
    neuronIds,
    strengths,
    features: features.map(({ keyword, neuronId, count, strength }) => ({
      keyword,
      neuronId,
      count,
      strength,
    })),
    sentiment: Number(sentiment.toFixed(3)),
    textPreview: compactPreview(text, 180),
  };
}

function buildWebSearchSpikeInjection(result = {}, params = {}) {
  return buildSearchResultToSpikes(result, params);
}

function buildWebSearchSymbolicFacts(query = '', result = {}, spikeInjection = {}) {
  const timestamp = isoNow();
  return [
    {
      name: 'webSearch.queryPreview',
      value: compactPreview(query, 120),
      confidence: 1,
      source: '/api/brain/web-search',
      timestamp,
    },
    {
      name: 'webSearch.provider',
      value: getWebSearchProviderKey(result),
      confidence: 1,
      source: '/api/brain/web-search',
      timestamp,
    },
    {
      name: 'webSearch.hasLiveData',
      value: Boolean(result.live),
      confidence: 1,
      source: '/api/brain/web-search',
      timestamp,
    },
    {
      name: 'webSearch.answerPreview',
      value: compactPreview(result.answer || '', 240),
      confidence: result.ok === false ? 0.3 : result.live ? 0.9 : 0.6,
      source: '/api/brain/web-search',
      timestamp,
    },
    {
      name: 'webSearch.citations',
      value: Array.isArray(result.citations) ? result.citations.slice(0, 5) : [],
      confidence: Array.isArray(result.citations) && result.citations.length ? 0.8 : 0.4,
      source: '/api/brain/web-search',
      timestamp,
    },
    {
      name: 'webSearch.spikeFeatureCount',
      value: Array.isArray(spikeInjection.features) ? spikeInjection.features.length : 0,
      confidence: 0.8,
      source: '/api/brain/web-search',
      timestamp,
    },
  ];
}

function didOpenAiQuotaFail(result = {}) {
  const text = [result.result, result.answer, result.error, result.provider?.error, result.provider?.message].filter(Boolean).join(' ').toLowerCase();
  return /\b(quota|rate limit|insufficient_quota|billing|429)\b/.test(text);
}

function logWebSearchProviderTelemetry(query = '', result = {}, startedAt = Date.now()) {
  const fallbackChain = Array.isArray(result.fallbackChain) ? result.fallbackChain : [];
  const openAiFallback = fallbackChain.find((item) => String(item.provider || '').toLowerCase() === 'openai') || {};
  const logEntry = {
    event: 'pbk_web_search_provider',
    timestamp: isoNow(),
    endpoint: '/api/brain/web-search',
    provider: getWebSearchProviderKey(result),
    result: result.result || 'unknown',
    live: Boolean(result.live),
    ok: result.ok !== false,
    tavilySecretPresent: Boolean(TAVILY_API_KEY),
    openaiQuotaError: didOpenAiQuotaFail(openAiFallback) || didOpenAiQuotaFail(result),
    latencyMs: Math.max(0, Date.now() - startedAt),
    queryPreview: compactPreview(query, 80),
    fallbackChain: fallbackChain.map((item) => ({
      provider: item.provider,
      ok: Boolean(item.ok),
      result: item.result || 'unknown',
    })),
  };
  console.log(JSON.stringify(logEntry));
}

function decorateWebSearchForAgentCognition(query = '', params = {}, result = {}, startedAt = Date.now()) {
  const spikeInjection = params.includeSpikes === false ? null : buildWebSearchSpikeInjection(result, params);
  const decorated = {
    ...result,
    snnSpikeInjection: spikeInjection,
    symbolicFacts: params.includeSymbolicFacts === false ? [] : buildWebSearchSymbolicFacts(query, result, spikeInjection || {}),
  };
  logWebSearchProviderTelemetry(query, decorated, startedAt);
  return decorated;
}

async function runDeepSeekWebSearchFallback(query = '', params = {}, context = {}) {
  const cleanQuery = String(query || '').trim();
  const brainFallback = context.fallback || answerBrainQuery(state, cleanQuery);
  const providerErrors = Array.isArray(context.providerErrors) ? context.providerErrors : [];
  const deepSeekMeta = getDeepSeekProviderMeta();
  if (!deepSeekMeta.ready) {
    return {
      ok: false,
      result: 'deepseek_missing_with_brain_fallback',
      live: false,
      query: cleanQuery,
      answer: `DeepSeek fallback is not configured. ${deepSeekMeta.missing.join(', ') || 'Add PBK_DEEPSEEK_API_KEY.'}\n\nFallback from PBK Brain: ${brainFallback?.answer || 'No local brain match yet.'}`,
      citations: brainFallback?.citations || ['PBK Brain fallback'],
      fallback: {
        source: 'PBK Brain',
        ...brainFallback,
      },
      provider: deepSeekMeta,
      providerErrors,
    };
  }

  const messages = [
    {
      role: 'system',
      content: ['You are Rex, PBK research strategist.', 'DeepSeek is the LLM. Tavily is only the live-search retriever.', 'The live web retriever may be unavailable. If so, do not pretend the answer is current.', 'Use the PBK Brain fallback below, state the live-data limitation in one sentence, and turn the stored knowledge into a practical PBK operator answer.', 'Keep the response concise, plain English, and action-oriented.'].join(' '),
    },
    {
      role: 'user',
      content: [`Question: ${cleanQuery}`, `Provider status: ${providerErrors.map((item) => `${item.provider}: ${item.result || 'unknown'} ${item.error || ''}`).join(' | ') || 'none'}`, `PBK Brain fallback answer: ${brainFallback?.answer || 'No stored match.'}`, `PBK citations: ${(brainFallback?.citations || []).join(', ') || 'none'}`].join('\n'),
    },
  ];
  const result = await runDeepSeekChatCompletion(messages, {
    source: 'rex-web-search-deepseek-fallback',
    responseFormat: 'text',
    temperature: 0.25,
    maxTokens: 450,
  });
  if (!result.ok) {
    return {
      ok: false,
      result: 'deepseek_error_with_brain_fallback',
      live: false,
      query: cleanQuery,
      answer: `DeepSeek fallback could not complete: ${result.error || 'unknown provider error'}\n\nFallback from PBK Brain: ${brainFallback?.answer || 'No local brain match yet.'}`,
      citations: brainFallback?.citations || ['PBK Brain fallback'],
      fallback: {
        source: 'PBK Brain',
        ...brainFallback,
      },
      provider: result.provider || deepSeekMeta,
      providerErrors,
    };
  }

  return {
    ok: true,
    result: 'deepseek_brain_fallback',
    live: false,
    query: cleanQuery,
    answer: result.answer || brainFallback?.answer || 'No local brain match yet.',
    citations: brainFallback?.citations || ['PBK Brain fallback'],
    fallback: {
      source: 'PBK Brain',
      ...brainFallback,
    },
    provider: result.provider || deepSeekMeta,
    providerErrors,
    usage: result.usage || null,
  };
}

async function runLiveWebSearch(query = '', params = {}) {
  const startedAt = Date.now();
  const tavily = await runTavilySearch(query, params);
  if (tavily.ok) return decorateWebSearchForAgentCognition(query, params, { ...tavily, live: true }, startedAt);
  const openAi = await runOpenAiWebSearch(query, { ...params, fallback: false });
  if (openAi.ok) {
    return decorateWebSearchForAgentCognition(
      query,
      params,
      {
        ...openAi,
        live: true,
        fallbackChain: [
          {
            provider: 'tavily',
            ok: tavily.ok,
            result: tavily.result,
            error: tavily.answer || tavily.error || '',
          },
          {
            provider: 'openai',
            ok: openAi.ok,
            result: openAi.result,
            error: openAi.answer || openAi.error || '',
          },
        ],
      },
      startedAt
    );
  }
  const providerErrors = [
    {
      provider: 'tavily',
      ok: tavily.ok,
      result: tavily.result,
      error: tavily.answer || tavily.error || '',
    },
    {
      provider: 'openai',
      ok: openAi.ok,
      result: openAi.result,
      error: openAi.answer || openAi.error || '',
    },
  ];
  const deepSeek = await runDeepSeekWebSearchFallback(query, params, {
    fallback: openAi.fallback,
    providerErrors,
  });
  return decorateWebSearchForAgentCognition(
    query,
    params,
    {
      ...(deepSeek.ok ? deepSeek : openAi),
      fallbackChain: [
        ...providerErrors,
        {
          provider: 'deepseek',
          ok: deepSeek.ok,
          result: deepSeek.result,
          error: deepSeek.answer || deepSeek.error || '',
        },
      ],
    },
    startedAt
  );
}

function buildCallQaScore(params = {}) {
  const transcript = String(params.transcript || params.text || params.body || '').trim();
  const lower = transcript.toLowerCase();
  const hasPainProbe = /\b(why|what made|how long|what happens|if nothing changes|personally|90 days|behind you|timeline|condition)\b/i.test(lower);
  const hasObjection = /\b(too low|think about|higher offer|scam|trust|list|agent|wife|husband|attorney|lawyer)\b/i.test(lower);
  const handledObjection = hasObjection && /\b(i hear|that makes sense|fair question|help me understand|what would need|let me show|net|certainty)\b/i.test(lower);
  const offerPresented = /\b(offer|number|price|cash|as-is|close|mao|arv|net)\b/i.test(lower);
  const nextStep = /\b(send|schedule|contract|agreement|docusign|follow up|call back|three-way|paperwork|next step)\b/i.test(lower);
  const tone = buildHumanCommunicationProfile(transcript, classifyPbkIntent(transcript));
  const toneMatched = !tone.safety.avoidJokes || !/\b(lol|haha|joke|funny)\b/i.test(lower);
  const breakdown = {
    painProbe: hasPainProbe ? 20 : 8,
    objectionHandling: hasObjection ? (handledObjection ? 25 : 10) : 18,
    offerPresentation: offerPresented ? 20 : 7,
    nextStep: nextStep ? 20 : 6,
    toneRapport: toneMatched ? 15 : 5,
  };
  const total = Object.values(breakdown).reduce((sum, value) => sum + value, 0);
  const weaknesses = [];
  if (!hasPainProbe) weaknesses.push('Pain probe was shallow; Ava needs at least one impact or personal consequence question.');
  if (hasObjection && !handledObjection) weaknesses.push('Main objection appeared but was not acknowledged and reframed clearly.');
  if (!offerPresented) weaknesses.push('Offer/value proposition was not presented clearly.');
  if (!nextStep) weaknesses.push('Call lacked a concrete next step.');
  if (!toneMatched) weaknesses.push('Tone mismatch risk; sensitive seller context needs slower delivery and no humor.');
  return {
    total,
    grade: total >= 85 ? 'A' : total >= 72 ? 'B' : total >= 60 ? 'C' : 'needs_coaching',
    breakdown,
    weaknesses,
    nextActions: weaknesses.length ? weaknesses.map((weakness) => `Coach: ${weakness}`) : ['Keep collecting outcomes; this call passed the QA gate.'],
  };
}

async function persistCallQaScoreToPg(record = {}) {
  const result = await queryPgRows(
    `INSERT INTO public.pbk_call_qa_scores (
      id, tenant_id, lead_id, call_id, agent_name, score, grade,
      breakdown, weaknesses, next_actions, transcript_snippet, metadata, created_at
    )
    VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9::jsonb,$10::jsonb,$11,$12::jsonb,$13)
    ON CONFLICT (id) DO NOTHING`,
    [record.id, record.tenantId, record.leadId, record.callId, record.agentName, record.score, record.grade, JSON.stringify(record.breakdown || {}), JSON.stringify(record.weaknesses || []), JSON.stringify(record.nextActions || []), record.transcriptSnippet || '', JSON.stringify(record.metadata || {}), record.createdAt]
  );
  return result.ok;
}

function plainObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

const EMOTION_KEYS = ['joy', 'sadness', 'anger', 'fear'];

function normalizeEmotionState(input = {}, fallbackSentiment = '') {
  const source = plainObject(input.emotionState || input.emotion || input);
  const state = {};
  let sum = 0;
  for (const key of EMOTION_KEYS) {
    const value = Math.max(0, Number(source[key] || 0));
    state[key] = Number.isFinite(value) ? value : 0;
    sum += state[key];
  }
  if (!sum) {
    const sentiment = String(source.sentiment || fallbackSentiment || '').toLowerCase();
    if (/angry|anger|mad|frustrat/.test(sentiment)) {
      Object.assign(state, { joy: 0.02, sadness: 0.08, anger: 0.75, fear: 0.15 });
    } else if (/fear|scared|uncertain|worr/.test(sentiment)) {
      Object.assign(state, { joy: 0.03, sadness: 0.12, anger: 0.05, fear: 0.8 });
    } else if (/sad|negative|grief|overwhelm/.test(sentiment)) {
      Object.assign(state, { joy: 0.03, sadness: 0.72, anger: 0.05, fear: 0.2 });
    } else if (/positive|happy|joy|excited/.test(sentiment)) {
      Object.assign(state, { joy: 0.8, sadness: 0.05, anger: 0.03, fear: 0.12 });
    } else {
      Object.assign(state, { joy: 0.25, sadness: 0.25, anger: 0.2, fear: 0.3 });
    }
    sum = EMOTION_KEYS.reduce((total, key) => total + state[key], 0);
  }
  for (const key of EMOTION_KEYS) {
    state[key] = Number((state[key] / sum).toFixed(4));
  }
  const dominant = EMOTION_KEYS.reduce((best, key) => (state[key] > state[best] ? key : best), EMOTION_KEYS[0]);
  return {
    ...state,
    dominant,
    intensity: state[dominant],
  };
}

function mergeEmotionState(previous = {}, next = {}, alpha = 0.3) {
  const prior = normalizeEmotionState(previous);
  const incoming = normalizeEmotionState(next);
  const merged = {};
  for (const key of EMOTION_KEYS) {
    merged[key] = prior[key] && previous?.dominant ? alpha * incoming[key] + (1 - alpha) * prior[key] : incoming[key];
  }
  return normalizeEmotionState(merged);
}

function buildAgentDecisionStateVector(record = {}) {
  const context = plainObject(record.context);
  const emotionState = normalizeEmotionState(record.emotionState || context.emotionState || context.emotion);
  return {
    agentId: record.agentId,
    actionType: record.actionType,
    leadId: record.leadId,
    callId: record.callId,
    campaignId: record.campaignId,
    source: record.source,
    stage: String(context.stage || context.conversationStage || context.status || '').trim(),
    selectedPath: String(context.selectedPath || context.path || context.dealPath || '').trim(),
    objectionType: String(context.objectionType || context.lastObjection || context.objection || '').trim(),
    sentimentBefore: Number.isFinite(Number(context.sentimentBefore ?? context.sentiment ?? context.sellerSentiment)) ? Number(context.sentimentBefore ?? context.sentiment ?? context.sellerSentiment) : null,
    dominantEmotion: emotionState.dominant,
    emotionIntensity: emotionState.intensity,
    emotionJoy: emotionState.joy,
    emotionSadness: emotionState.sadness,
    emotionAnger: emotionState.anger,
    emotionFear: emotionState.fear,
    riskLevel: String(context.riskLevel || context.risk || '').trim(),
    channel: String(context.channel || context.surface || '').trim(),
  };
}

function summarizeAgentDecisionBuffer(decisions = state.agentDecisions || []) {
  const records = Array.isArray(decisions) ? decisions : [];
  const trainingReady = records.filter((item) => item.trainingReady);
  return {
    totalDecisions: records.length,
    trainingReadyCount: trainingReady.length,
    averageReward: averageNumeric(trainingReady.map((item) => item.reward)),
    lastDecisionAt: getItemTimestamp(records[0] || {}) || null,
    replayBuffer: 'pbk_agent_decisions',
  };
}

