async function runAutonomousRexGoalDiscoveryRecord(params = {}) {
  const tenantId = normalizeTenantId(params.tenantId || params.tenant_id || 'pbk');
  const kpis = buildRexAutonomyKpiSnapshot({ ...params, tenantId });
  const goals = proposeAutonomousRexGoals(kpis, {
    now: params.now || isoNow(),
    minCallsForModel: params.minCallsForModel || params.min_calls_for_model || 500,
    targetConversionRate: params.targetConversionRate || params.target_conversion_rate || 0.18,
  });
  const actions = goals.map((goal) => ({
    actionId: goal.actionId,
    actionType: goal.actionType,
    label: goal.label || goal.title,
    target: goal.target,
    riskLevel: goal.riskLevel || 'low',
    source: 'rex_autonomy',
    reason: goal.reason || goal.description,
    expectedImpact: goal.successMetric,
    recommendation: goal,
    providerWritesBlocked: true,
    approvalRequired: goal.approvalRequired !== false,
    metadata: {
      ...(goal.metadata || {}),
      kpis,
    },
  }));
  const storedActions = await storeRevenueActions(actions, { tenantId });
  const run = {
    id: params.id || `rex-autonomy-goals-${Date.now()}-${randomUUID().slice(0, 8)}`,
    tenantId,
    runType: 'goal_discovery',
    kpis,
    goals,
    status: 'complete',
    source: 'rex-autonomy',
    createdAt: isoNow(),
  };
  const postgres = await persistRexAutonomyRunToPg(run);
  const focus = goals.map((goal, index) => `${index + 1}. ${goal.title}: ${goal.successMetric}`).join(' ');
  upsertAvaActiveMemory({
    id: `rex-autonomous-focus-${new Date().toISOString().slice(0, 10)}`,
    memoryType: 'rex-autonomous-goals',
    objectionTag: 'rex_daily_autonomy',
    prompt: 'Before Ava calls, retrieve today Rex autonomous focus.',
    response: focus,
    summary: focus,
    score: 0.93,
    outcome: 'rex_autonomous_goal_discovery',
    source: 'rex-autonomy',
    metadata: { kpis, goals },
  });
  void publishPbkEvent(
    EventTypes.REX_GOALS_PROPOSED,
    {
      runId: run.id,
      goalCount: goals.length,
      goals: goals.map((goal) => ({
        actionId: goal.actionId,
        title: goal.title,
        priority: goal.priority,
      })),
    },
    'rex-autonomy'
  );
  addActivity(
    state,
    makeActivity({
      actor: params.actor || 'Rex Autonomy',
      category: 'REX',
      status: 'success',
      text: `Rex proposed ${goals.length} autonomous goal${goals.length === 1 ? '' : 's'} from current PBK KPIs.`,
      target: 'rex-autonomous-goals',
    })
  );
  await persistState(state);
  return {
    ok: true,
    result: 'rex_autonomous_goals_proposed',
    providerWritesBlocked: true,
    kpis,
    goals,
    actions: storedActions,
    run,
    storage: { localState: true, postgres },
  };
}

async function handleRexLeadImportedRecord(params = {}) {
  const idempotencyKey = String(
    params.idempotencyKey || params.idempotency_key || params.eventId || params.event_id || ''
  ).trim();
  const idempotencyHash = idempotencyKey
    ? createHash('sha256').update(idempotencyKey).digest('hex').slice(0, 24)
    : '';
  const action = selectRexProactiveLeadAction(params, {
    nowLocalHour: params.nowLocalHour ?? params.now_local_hour,
    hotLeadThreshold: params.hotLeadThreshold || params.hot_lead_threshold || 80,
    reviewThreshold: params.reviewThreshold || params.review_threshold || 65,
  });
  let task = null;
  let decision = null;
  if (['queue_call', 'schedule_for_calling_window', 'create_rex_decision'].includes(action.action)) {
    task = await recordAgentHandoffTask({
      id: idempotencyHash ? `pbk-agent-task-rex-lead-${idempotencyHash}` : undefined,
      tenantId: params.tenantId || params.tenant_id || 'pbk',
      fromAgent: 'Rex',
      toAgent: 'Ava',
      taskType: action.action === 'queue_call' ? 'hot_lead_call_queue' : 'hot_lead_follow_up_review',
      status: action.action === 'queue_call' ? 'queued' : 'pending',
      summary: action.reason,
      correlationId: action.leadId || params.correlationId || params.correlation_id || '',
      providerWrites: 'blocked',
      metadata: {
        ...action,
        lead: {
          leadId: action.leadId,
          phone: action.phone,
          motivationScore: action.motivationScore,
        },
        source: params.source || 'lead.imported',
      },
    });
    decision = await createRexDecision(
      {
        id: idempotencyHash ? `rex-decision-lead-import-${idempotencyHash}` : undefined,
        requestApproval: false,
        source: 'rex-proactive-lead-trigger',
        actor: 'Rex',
        status: action.action === 'queue_call' ? 'proactive_queued' : 'proposed',
        tool: 'revenue_engine_next_best_action',
        params: {
          leadId: action.leadId,
          phone: action.phone,
          action: action.action,
          motivationScore: action.motivationScore,
          providerWritesBlocked: true,
        },
        rationale: action.reason,
        targetType: 'lead',
        targetId: action.leadId,
        targetLabel: action.leadId || action.phone || 'hot lead',
      },
      { requestApproval: false, actor: 'Rex', source: 'rex-proactive-lead-trigger' }
    );
  }
  void publishPbkEvent(
    EventTypes.REX_PROACTIVE_TRIGGERED,
    {
      action: action.action,
      leadId: action.leadId,
      motivationScore: action.motivationScore,
      taskId: task?.id || '',
      decisionId: decision?.decision?.id || '',
    },
    'rex-autonomy'
  );
  await persistState(state);
  return {
    ok: true,
    result: 'rex_lead_import_processed',
    providerWritesBlocked: true,
    action,
    task,
    decision: decision?.decision || null,
  };
}

function getCommandCenterClosedLoopSettings() {
  const settings = ensureRuntimeSettings(state);
  const configured = plainObject(settings.commandCenterClosedLoop);
  const enabled = Boolean(COMMAND_CENTER_CLOSED_LOOP_ENABLED || configured.enabled);
  return {
    enabled,
    lowRiskAutopilot: Boolean(COMMAND_CENTER_LOW_RISK_AUTOPILOT_ENABLED || configured.lowRiskAutopilot),
    providerWritesBlocked: configured.providerWritesBlocked !== false,
    targetMonthlyRevenue: toMoneyNumber(configured.targetMonthlyRevenue, REVENUE_TARGET_MONTHLY),
    targetAnnualRevenue: toMoneyNumber(configured.targetAnnualRevenue, REVENUE_TARGET_ANNUAL),
    loops: {
      callAnalyzer: configured.loops?.callAnalyzer !== false,
      rexGoalAlignment: configured.loops?.rexGoalAlignment !== false,
      prosodyTraining: configured.loops?.prosodyTraining !== false,
      emotionalLearning: configured.loops?.emotionalLearning !== false,
    },
    lastActivatedAt: configured.activatedAt || '',
    activatedBy: configured.activatedBy || '',
  };
}

async function activateCommandCenterClosedLoop(params = {}) {
  const tenantId = normalizeTenantId(params.tenantId || params.tenant_id);
  const actor = String(params.actor || params.requestedBy || params.requested_by || 'PBK Command Center').trim();
  const targetMonthlyRevenue = Math.max(1, toMoneyNumber(params.targetMonthlyRevenue ?? params.target_monthly_revenue, REVENUE_TARGET_MONTHLY));
  const targetAnnualRevenue = Math.max(targetMonthlyRevenue * 12, toMoneyNumber(params.targetAnnualRevenue ?? params.target_annual_revenue, REVENUE_TARGET_ANNUAL));
  const lowRiskAutopilot = params.lowRiskAutopilot !== false && params.low_risk_autopilot !== false;
  const loops = {
    callAnalyzer: params.callAnalyzer !== false && params.call_analyzer !== false,
    rexGoalAlignment: params.rexGoalAlignment !== false && params.rex_goal_alignment !== false,
    prosodyTraining: params.prosodyTraining !== false && params.prosody_training !== false,
    emotionalLearning: params.emotionalLearning !== false && params.emotional_learning !== false,
  };
  const settings = ensureRuntimeSettings(state);
  settings.commandCenterClosedLoop = {
    enabled: true,
    lowRiskAutopilot,
    providerWritesBlocked: true,
    targetMonthlyRevenue,
    targetAnnualRevenue,
    loops,
    activatedAt: isoNow(),
    activatedBy: actor,
  };
  settings.autopilot = {
    ...plainObject(settings.autopilot),
    lowRiskActions: lowRiskAutopilot,
    highRiskRequiresApproval: true,
    providerWritesBlocked: true,
  };
  settings.updatedAt = isoNow();
  settings.updatedBy = actor;
  state.status.commandCenterClosedLoop = {
    enabled: true,
    lowRiskAutopilot,
    providerWritesBlocked: true,
    targetMonthlyRevenue,
    targetAnnualRevenue,
    loops,
    activatedAt: settings.commandCenterClosedLoop.activatedAt,
  };

  const results = {};
  if (params.runNow !== false && params.run_now !== false) {
    if (loops.callAnalyzer)
      results.callAnalyzer = await analyzeRecentAvaCalls({
        tenantId,
        actor: 'Rex Call Analyzer',
        limit: params.callLimit || 20,
        source: 'activation',
      });
    if (loops.emotionalLearning)
      results.emotionalLearning = await improveEmotionalLearningMemoryRecord({
        source: 'command-center-activation',
      });
    if (loops.prosodyTraining)
      results.prosodyTraining = await trainAndPersistProsodyModel({
        tenantId,
        minSamples: params.minProsodySamples || 25,
      });
    if (loops.rexGoalAlignment) {
      results.rexGoalAlignment = await buildRevenueGoalAlignment({
        tenantId,
        actor: 'Rex Goal Alignment',
        targetMonthlyRevenue,
        targetAnnualRevenue,
      });
    }
  }
  const compactResults = {
    callAnalyzer: results.callAnalyzer
      ? {
          result: results.callAnalyzer.result,
          analyzed: results.callAnalyzer.analyzed || 0,
          summary: results.callAnalyzer.summary || {},
        }
      : null,
    emotionalLearning: results.emotionalLearning
      ? {
          result: results.emotionalLearning.result,
          promoted: results.emotionalLearning.promoted || 0,
          minWeight: results.emotionalLearning.minWeight || null,
        }
      : null,
    prosodyTraining: results.prosodyTraining
      ? {
          result: results.prosodyTraining.result,
          modelStatus: results.prosodyTraining.model?.status || '',
          sampleCount: results.prosodyTraining.model?.sampleCount || 0,
          successCount: results.prosodyTraining.model?.successCount || 0,
        }
      : null,
    rexGoalAlignment: results.rexGoalAlignment
      ? {
          result: results.rexGoalAlignment.result,
          targetMonthlyRevenue: results.rexGoalAlignment.targetMonthlyRevenue,
          monthlyRunRate: results.rexGoalAlignment.monthlyRunRate,
          gap: results.rexGoalAlignment.gap,
          actionCount: results.rexGoalAlignment.actions?.length || 0,
          topFailureTags: results.rexGoalAlignment.failureSummary?.topFailureTags || [],
        }
      : null,
  };

  const activation = {
    id: `command-center-activation-${Date.now()}-${randomUUID().slice(0, 8)}`,
    tenantId,
    activatedBy: actor,
    status: 'active',
    targetMonthlyRevenue,
    targetAnnualRevenue,
    lowRiskAutopilot,
    providerWritesBlocked: true,
    loops,
    results: compactResults,
    runSummary: {
      callAnalyses: results.callAnalyzer?.analyzed || 0,
      revenueActions: results.rexGoalAlignment?.actions?.length || 0,
      prosodyTraining: results.prosodyTraining?.result || 'not_run',
      emotionalLearningPromoted: results.emotionalLearning?.promoted || 0,
    },
    metadata: {
      schemaVersion: 'pbk-command-center-activation-v1',
      requestedRunNow: params.runNow !== false && params.run_now !== false,
    },
    createdAt: isoNow(),
    updatedAt: isoNow(),
  };
  if (!Array.isArray(state.commandCenterActivations)) state.commandCenterActivations = [];
  upsertById(state, 'commandCenterActivations', activation);
  void persistCommandCenterActivationToPg(activation);
  addActivity(
    state,
    makeActivity({
      actor,
      category: 'COMMAND_CENTER',
      status: 'active',
      text: `Activated PBK closed-loop Command Center toward $${Math.round(targetMonthlyRevenue).toLocaleString()}/month.`,
      target: 'ava-rex-closed-loop',
    })
  );
  await persistState(state);
  return {
    ok: true,
    result: 'command_center_closed_loop_activated',
    activation,
    providerWritesBlocked: true,
    approvalMode: 'high_risk_approval_required',
    state: buildStateSnapshot(),
  };
}

async function getCommandCenterClosedLoopStatus(params = {}) {
  const settings = getCommandCenterClosedLoopSettings();
  const revenueStatus = buildRevenueEngineStatus({
    requestedBy: params.requestedBy || 'closed-loop-status',
  });
  const prosody = await getProsodyAnalytics({
    tenantId: params.tenantId || params.tenant_id || 'pbk',
    days: params.days || 14,
  });
  return {
    ok: true,
    result: 'command_center_closed_loop_status',
    generatedAt: isoNow(),
    ...settings,
    providerWritesBlocked: true,
    operatingMode: getRuntimeOperatingMode(),
    highRiskApprovalRequired: true,
    recentActivation: sortNewest(state.commandCenterActivations || [])[0] || null,
    recentRevenueActions: sortNewest(state.revenueActions || []).slice(0, 12),
    recentCallAnalyses: sortNewest(state.callAnalyses || []).slice(0, 12),
    revenueEngine: revenueStatus,
    prosody: prosody.summary,
    gaps: [...(countPendingFounderWork().total ? [`${countPendingFounderWork().total} approval/admin items still need business review.`] : []), ...((prosody.summary?.measured || 0) < 10 ? ['Prosody model still needs measured outcomes before trusting automatic tuning.'] : []), ...((state.calls || []).length ? [] : ['No recent live calls in bridge state for call-analysis sub-agents.'])],
  };
}

function getAvaCallIntelligenceSettings() {
  const settings = ensureRuntimeSettings(state);
  const configured = plainObject(settings.avaCallIntelligence);
  const enabled = configured.enabled !== undefined ? configured.enabled !== false : AVA_CALL_INTELLIGENCE_ENABLED;
  const strategistMode = String(configured.strategistMode || configured.strategist_mode || AVA_CALL_INTELLIGENCE_STRATEGIST_MODE || TELNYX_LIVE_REPLY_STRATEGIST_MODE || 'inline')
    .trim()
    .toLowerCase();
  const strategistTimeoutMs = Math.max(350, Math.min(4000, Number(configured.strategistTimeoutMs || configured.strategist_timeout_ms || AVA_CALL_INTELLIGENCE_TIMEOUT_MS || TELNYX_LIVE_REPLY_STRATEGIST_TIMEOUT_MS)));
  return {
    enabled,
    strategistMode,
    strategistTimeoutMs,
    useScripts: configured.useScripts !== false,
    useBant: configured.useBant !== false,
    useMemory: configured.useMemory !== false,
    useProsody: configured.useProsody !== false,
    useToolRouter: configured.useToolRouter !== false,
    useRexOversight: configured.useRexOversight !== false,
    useCallAnalyzer: configured.useCallAnalyzer !== false,
    useRevenueGoal: configured.useRevenueGoal !== false,
    useEmotionalLearning: configured.useEmotionalLearning !== false,
    useSimilarDeals: configured.useSimilarDeals !== false,
    providerWritesBlocked: configured.providerWritesBlocked !== false,
    highRiskApprovalRequired: configured.highRiskApprovalRequired !== false,
    activatedAt: configured.activatedAt || '',
    activatedBy: configured.activatedBy || '',
  };
}

function getTelnyxLiveReplyStrategistMode() {
  const settings = getAvaCallIntelligenceSettings();
  if (!settings.enabled) return 'off';
  const mode = String(settings.strategistMode || TELNYX_LIVE_REPLY_STRATEGIST_MODE || 'inline')
    .trim()
    .toLowerCase();
  if (mode === 'off') return 'off';
  if (isAvaFullIntelligenceMode() && mode === 'background') return 'inline';
  return mode || 'inline';
}

function getTelnyxLiveReplyStrategistTimeoutMs() {
  const settings = getAvaCallIntelligenceSettings();
  const configured = Number(settings.strategistTimeoutMs || TELNYX_LIVE_REPLY_STRATEGIST_TIMEOUT_MS || 1200);
  if (isAvaFullIntelligenceMode()) return Math.max(1000, Math.min(4000, configured || TELNYX_LIVE_REPLY_STRATEGIST_TIMEOUT_MS || 3000));
  return configured;
}

const contextAwareScriptCatalogByWorkspace = new Map();
const contextAwareScriptCatalogLoadedAtByWorkspace = new Map();
const contextAwareScriptCatalogRefreshPromises = new Map();
const CONTEXT_AWARE_SCRIPT_CATALOG_REFRESH_MS = Math.max(
  30_000,
  Number(process.env.PBK_SCRIPT_CATALOG_REFRESH_MS || 60_000)
);

function getContextAwareScriptWorkspaceId(params = {}) {
  return String(params.workspaceId || params.workspace_id || 'pbk').trim() || 'pbk';
}

function getContextAwareScriptCatalog(workspaceId = 'pbk') {
  return contextAwareScriptCatalogByWorkspace.get(workspaceId) || [];
}

function calculateContextAwareLearnedWeight(
  usageCount = 0,
  conversionCount = 0,
  rewardAverage = null,
  rewardCount = 0
) {
  const uses = Math.max(0, Number(usageCount || 0));
  const conversions = Math.max(0, Math.min(uses, Number(conversionCount || 0)));
  const rewards = Math.max(0, Number(rewardCount || 0));
  const normalizedReward = Number.isFinite(Number(rewardAverage))
    ? Math.max(-1, Math.min(1, Number(rewardAverage)))
    : null;
  if (!uses && !rewards) return 0;
  const posteriorRate = (conversions + 1) / (uses + 2);
  const conversionConfidence = Math.min(1, uses / 24);
  const conversionSignal = ((posteriorRate - 0.5) * 2) * conversionConfidence;
  if (normalizedReward == null || !rewards) {
    return Number(conversionSignal.toFixed(4));
  }
  const rewardConfidence = Math.min(1, rewards / 16);
  const rewardSignal = normalizedReward * rewardConfidence;
  return Number((rewardSignal * 0.7 + conversionSignal * 0.3).toFixed(4));
}

function normalizeContextAwareScriptCatalogRow(row = {}) {
  const metadata = plainObject(row.metadata);
  const usageCount = Math.max(0, Number(row.usage_count ?? row.usageCount ?? 0));
  const conversionCount = Math.max(
    0,
    Number(row.conversion_count ?? row.conversionCount ?? 0)
  );
  const rewardAverage = Number.isFinite(
    Number(row.reward_average ?? row.rewardAverage)
  )
    ? Number(row.reward_average ?? row.rewardAverage)
    : null;
  const rewardCount = Math.max(
    0,
    Number(row.reward_count ?? row.rewardCount ?? 0)
  );
  return {
    id: String(row.id || '').trim(),
    title: String(row.title || row.name || '').trim(),
    content: String(row.content || row.script || '').trim(),
    tags: Array.isArray(row.tags) ? row.tags : [],
    pathKey: String(row.path_key || row.pathKey || '').trim(),
    allowedRoles: Array.isArray(row.allowed_roles || row.allowedRoles)
      ? row.allowed_roles || row.allowedRoles
      : ['owner', 'agent', 'decision_helper'],
    metadata,
    usageCount,
    conversionCount,
    dealValue: Math.max(0, Number(row.deal_value ?? row.dealValue ?? 0)),
    rewardAverage,
    rewardCount,
    learnedWeight: calculateContextAwareLearnedWeight(
      usageCount,
      conversionCount,
      rewardAverage,
      rewardCount
    ),
  };
}

async function loadContextAwareScriptCatalog(workspaceId = 'pbk') {
  const normalizedWorkspaceId = String(workspaceId || 'pbk').trim() || 'pbk';
  const existingCatalog = getContextAwareScriptCatalog(normalizedWorkspaceId);
  const result = await queryPgRows(
    `SELECT
       scripts.id, scripts.title, scripts.content, scripts.tags,
       scripts.path_key, scripts.allowed_roles, scripts.metadata,
       scripts.usage_count, scripts.conversion_count, scripts.deal_value,
       outcome_stats.reward_average, outcome_stats.reward_count
     FROM public.scripts scripts
     LEFT JOIN (
       SELECT
         workspace_id,
         script_id,
         AVG(reward) FILTER (WHERE reward IS NOT NULL) AS reward_average,
         COUNT(reward) FILTER (WHERE reward IS NOT NULL) AS reward_count
       FROM public.pbk_script_outcome_events
       GROUP BY workspace_id, script_id
     ) outcome_stats
       ON outcome_stats.workspace_id = scripts.workspace_id
      AND outcome_stats.script_id = scripts.id
     WHERE scripts.workspace_id = $1 AND scripts.active = TRUE
     ORDER BY
       COALESCE(outcome_stats.reward_average, 0) DESC,
       scripts.conversion_count DESC,
       scripts.usage_count DESC,
       scripts.updated_at DESC`,
    [normalizedWorkspaceId]
  );
  if (!result.ok) {
    return {
      ok: false,
      result: 'script_catalog_refresh_failed',
      error: result.error || '',
      workspaceId: normalizedWorkspaceId,
      count: existingCatalog.length,
    };
  }
  const catalog = (result.rows || [])
    .map(normalizeContextAwareScriptCatalogRow)
    .filter((script) => script.id && script.content);
  const loadedAt = isoNow();
  contextAwareScriptCatalogByWorkspace.set(normalizedWorkspaceId, catalog);
  contextAwareScriptCatalogLoadedAtByWorkspace.set(normalizedWorkspaceId, loadedAt);
  return {
    ok: true,
    result: 'script_catalog_refreshed',
    workspaceId: normalizedWorkspaceId,
    count: catalog.length,
    loadedAt,
  };
}

async function refreshContextAwareScriptCatalog(workspaceId = 'pbk') {
  const normalizedWorkspaceId = String(workspaceId || 'pbk').trim() || 'pbk';
  if (!contextAwareScriptCatalogRefreshPromises.has(normalizedWorkspaceId)) {
    const refreshPromise = loadContextAwareScriptCatalog(normalizedWorkspaceId)
      .finally(() => {
        contextAwareScriptCatalogRefreshPromises.delete(normalizedWorkspaceId);
      });
    contextAwareScriptCatalogRefreshPromises.set(normalizedWorkspaceId, refreshPromise);
  }
  return contextAwareScriptCatalogRefreshPromises.get(normalizedWorkspaceId);
}

function buildAvaScriptRotationSnapshot(params = {}) {
  ensureAgentFleetCollections();
  const query = String(params.query || params.transcript || params.text || '').toLowerCase();
  const contextScripts = buildContextAwareScriptLibrary(params);
  const contextAwareSelection = selectContextAwareScript({
    scripts: contextScripts,
    pathKey: params.pathKey || params.path_key || params.selectedPath || params.selected_path || params.pathDecision?.selectedPath || '',
    sentiment: params.sentiment ?? params.sellerSentiment ?? params.seller_sentiment ?? params.session?.sellerSentiment ?? 0,
    callerRole: params.callerRole || params.caller_role || params.session?.callerRole || '',
    lastObjection: params.lastObjection || params.last_objection || params.objectionTag || params.objection_tag || params.warManual?.objection?.tag || '',
    transcript: query,
    recentScriptIds: params.recentScriptIds || params.recent_script_ids || params.session?.recentScriptIds || [],
    recentAvaLines: params.recentAvaLines || params.recent_ava_lines || params.session?.recentAvaLines || [],
    leadId: params.leadId || params.lead_id || params.session?.leadId || '',
    callId: params.callId || params.call_id || params.session?.callId || '',
    explorationRate: params.explorationRate ?? params.exploration_rate ?? 0.06,
  });
  const ava = findAgentRecord('ava') || {};
  const emotionalPhase = detectAvaEmotionalPhase({
    transcript: query,
    emotion:
      params.emotion ||
      params.sellerEmotion ||
      params.warManual?.emotionalState?.id ||
      params.warManual?.emotionalState?.label ||
      '',
    intent: params.intent || params.sellerIntent || '',
    objection:
      params.lastObjection ||
      params.last_objection ||
      params.objectionTag ||
      params.objection_tag ||
      params.warManual?.objection?.tag ||
      '',
    phase: params.stage || params.leadStage || params.session?.stage || '',
  });
  const builtInEmotionalSkills = listAvaBuiltInEmotionalScriptSkills();
  const registrySkills = Array.isArray(ava.skills) ? ava.skills : [];
  const registrySkillIds = new Set(
    registrySkills.flatMap((skill) =>
      [skill.id, skill.versionId, skill.activationId].filter(Boolean).map(String)
    )
  );
  const mergedAvaSkills = [
    ...registrySkills,
    ...builtInEmotionalSkills.filter(
      (skill) =>
        !registrySkillIds.has(String(skill.id || '')) &&
        !registrySkillIds.has(String(skill.versionId || '')) &&
        !registrySkillIds.has(String(skill.activationId || ''))
    ),
  ];
  const bridgeSkills = mergedAvaSkills
    .map((skill) => ({
      id: skill.id || skill.versionId || '',
      versionId: skill.versionId || '',
      activationId: skill.activationId || '',
      name: skill.name || '',
      category: skill.category || skill.triggerPolicy?.category || '',
      emotionalScript: skill.emotionalScript === true,
      risk: skill.risk || '',
      confidence: Number(skill.confidence || 0),
      level: skill.level || '',
      status: skill.status || '',
      priority: Number(skill.priority || 100),
      evidence: skill.evidence || '',
      instructions: skill.instructions || skill.evidence || '',
      response: skill.response || '',
      nextQuestion: skill.nextQuestion || '',
      triggerPolicy: skill.triggerPolicy || {},
      toolAllowlist: Array.isArray(skill.toolAllowlist) ? skill.toolAllowlist : [],
      scope: skill.scope || {},
      rolloutMode: skill.rolloutMode || '',
      rolloutPercent: skill.rolloutPercent,
      source: skill.source || '',
      targetAgents: Array.isArray(skill.targetAgents) ? skill.targetAgents : [],
      builtIn: skill.builtIn === true,
      revision: skill.revision || '',
    }))
    .filter((skill) => skill.name)
    .sort((left, right) => Number(right.confidence || 0) - Number(left.confidence || 0));
  const governedSkillSelection = selectGovernedAvaSkill({
    skills: bridgeSkills,
    transcript: query,
    lastObjection:
      params.lastObjection ||
      params.last_objection ||
      params.objectionTag ||
      params.warManual?.objection?.tag ||
      '',
    emotion:
      params.emotion ||
      params.sellerEmotion ||
      params.warManual?.emotionalState?.id ||
      params.warManual?.emotionalState?.label ||
      '',
    emotionalPhase,
    stage: params.stage || params.leadStage || params.session?.stage || '',
    path:
      params.pathKey ||
      params.selectedPath ||
      params.pathDecision?.selectedPath ||
      params.session?.selectedPath ||
      '',
    intent: params.intent || params.sellerIntent || '',
    workspaceId: params.workspaceId || params.workspace_id || 'pbk',
    leadId: params.leadId || params.lead_id || params.session?.leadId || '',
    callId: params.callId || params.call_id || params.session?.callId || '',
    campaignId: params.campaignId || params.campaign_id || params.session?.campaignId || '',
    sessionId: params.sessionId || params.session_id || params.session?.sessionId || '',
    currentSkillId:
      params.currentGovernedSkillId ||
      params.session?.activeGovernedSkillId ||
      '',
  });
  const activeMemories = sortNewest(state.avaActiveMemories || [])
    .filter((memory) => {
      const haystack = [memory.objectionTag, memory.memoryType, memory.prompt, memory.response, memory.summary].filter(Boolean).join(' ').toLowerCase();
      return !query || scorePbkTextMatch(query, haystack, memory.metadata) > 0 || /revenue|goal|objection|script|call/i.test(haystack);
    })
    .slice(0, 6)
    .map((memory) => ({
      tag: memory.objectionTag || memory.memoryType || 'memory',
      phrase: memory.response || memory.summary || memory.prompt || '',
      score: Number(memory.score || 0),
      source: memory.source || 'ava_memory',
    }));
  return {
    activeSkillCount: bridgeSkills.length || Number(ava.skillsTotal || 0),
    emotionalPhase,
    builtInEmotionalSkillCount: builtInEmotionalSkills.length,
    selectedSkills: [
      ...(governedSkillSelection.selectedSkill ? [governedSkillSelection.selectedSkill] : []),
      ...bridgeSkills.filter(
        (skill) => skill.id !== governedSkillSelection.selectedSkill?.id
      ),
    ].slice(0, 6),
    governedSkillSelection,
    activeMemories,
    contextAwareSelection: contextAwareSelection.ok
      ? {
          selectedScript: contextAwareSelection.selectedScript,
          score: contextAwareSelection.score,
          reasonCodes: contextAwareSelection.reasonCodes,
          scoredScripts: contextAwareSelection.scoredScripts,
          exploration: contextAwareSelection.exploration,
        }
      : null,
    selectedScript: contextAwareSelection.selectedScript
      ? {
          id: contextAwareSelection.selectedScript.id,
          title: contextAwareSelection.selectedScript.title,
          pathKey: contextAwareSelection.selectedScript.pathKey,
          content: contextAwareSelection.selectedScript.content,
          reasonCodes: contextAwareSelection.reasonCodes,
          score: contextAwareSelection.score,
        }
      : null,
    rotationRule: contextAwareSelection.rotationRule || 'Do not repeat a prior Ava line. Rotate skill, memory, BANT question, or proof angle every turn.',
  };
}

function buildRuntimePBKIntelligenceContext(params = {}) {
  ensureAgentFleetCollections();
  const session = params.session || {};
  const contextCall = params.contextCall || params.call || {};
  const architecture = params.architecture || {};
  const transcript = String(params.transcript || params.query || params.text || '').trim();
  const scripts =
    params.scripts ||
    architecture.scripts ||
    buildAvaScriptRotationSnapshot({
      ...params,
      session,
      contextCall,
      query: transcript,
      pathDecision: params.pathDecision || architecture.pathDecision || session.pathDecision || {},
    });
  const activeMemories = Array.isArray(scripts.activeMemories) ? scripts.activeMemories : [];
  const longHorizonMemory = architecture.memory?.longHorizon || architecture.longHorizonMemory?.compactState || null;
  const recentOutcomes = sortNewest(state.skillOutcomes || [])
    .filter((outcome) => {
      const leadId = String(contextCall.leadId || session.leadId || '').trim();
      const callId = String(contextCall.id || contextCall.callId || session.callId || '').trim();
      return (
        (!leadId || !outcome.leadId || outcome.leadId === leadId) &&
        (!callId || !outcome.callId || outcome.callId === callId)
      );
    })
    .slice(0, 8);
  return buildPBKIntelligenceContext({
    workspaceId: params.workspaceId || params.workspace_id || 'pbk',
    lead: {
      id: contextCall.leadId || session.leadId || params.leadId || '',
      leadId: contextCall.leadId || session.leadId || params.leadId || '',
      leadName: contextCall.leadName || session.leadName || params.leadName || '',
      name: contextCall.leadName || session.leadName || params.leadName || '',
      address: contextCall.address || session.address || params.address || '',
      phone: contextCall.phone || contextCall.from || session.phone || params.phone || '',
      email: contextCall.email || session.email || params.email || '',
    },
    call: {
      ...contextCall,
      id: contextCall.id || contextCall.callId || session.callId || params.callId || '',
      callId: contextCall.callId || contextCall.id || session.callId || params.callId || '',
      leadId: contextCall.leadId || session.leadId || params.leadId || '',
      phone: contextCall.phone || contextCall.from || session.phone || params.phone || '',
      transcript: Array.isArray(session.transcript) ? session.transcript.slice(-12) : contextCall.transcript || [],
      status: contextCall.status || session.status || 'active',
    },
    transcript,
    memory: {
      coaching: activeMemories,
      episodic: longHorizonMemory ? [longHorizonMemory] : [],
      recent: Array.isArray(session.liveKnowledge) ? session.liveKnowledge.slice(0, 5) : [],
      lastRecallAt: activeMemories.length || longHorizonMemory ? isoNow() : null,
      stale: Boolean(params.memoryStale || session.memoryStale),
    },
    skills: {
      active: Array.isArray(scripts.selectedSkills) ? scripts.selectedSkills : [],
      recentOutcomes,
      stale: Boolean(params.skillsStale || session.skillsStale),
    },
    turnContract: params.turnContract || session.avaLiveTurnContract || null,
    agents: state.agents || buildDefaultAgentFleet(),
    sentiment: session.sentiment?.pbkScore ?? params.sentiment ?? contextCall.sentiment ?? null,
    leadStale: Boolean(params.leadStale),
    lastSyncAt: session.lastRedisSyncResult || contextCall.updatedAt || session.updatedAt || isoNow(),
  });
}

function applyRuntimePBKIntelligenceContextToSession(session = {}, context = {}) {
  if (!context || typeof context !== 'object') return session;
  session.pbkIntelligenceContext = context;
  session.pbkIntelligenceReadiness = context.fleetReadiness || null;
  session.pbkIntelligenceContextUpdatedAt = context.generatedAt || isoNow();
  if (state && typeof state === 'object') {
    if (!state.status || typeof state.status !== 'object') state.status = {};
    state.status.pbkIntelligenceContext = summarizeRuntimePBKIntelligenceContext(context);
    state.status.pbkIntelligenceReadiness = context.fleetReadiness || null;
    state.status.lastPBKIntelligenceContextAt = context.generatedAt || isoNow();
  }
  return session;
}

function buildAvaLiveCallStartCache({ session = {}, contextCall = null, transcript = '', reason = 'call_start' } = {}) {
  const cachedAt = isoNow();
  const safeContextCall = contextCall && typeof contextCall === 'object' ? contextCall : {};
  const leadProfile = {
    leadId: safeContextCall.leadId || session.leadId || '',
    leadName: getSpokenLeadName(safeContextCall.leadName || session.leadName || ''),
    address: safeContextCall.address || session.address || '',
    phone: normalizePhone(safeContextCall.phone || safeContextCall.from || session.phone || ''),
    email: safeContextCall.email || session.email || '',
    status: safeContextCall.status || session.status || '',
    source: safeContextCall.source || session.leadSource || safeContextCall.participantRole || '',
  };
  const bantState = buildLiveCallBantStatus(session, safeContextCall);
  const scripts = buildAvaScriptRotationSnapshot({
    session,
    contextCall: safeContextCall,
    transcript,
    query: transcript,
    pathDecision: session.pathDecision || safeContextCall.pathDecision || {},
    selectedPath: session.selectedPath || safeContextCall.selectedPath || safeContextCall.selected_path || '',
    callerRole: session.callerRole || safeContextCall.callerRole || '',
  });
  const facts = {
    sellerTargetPrice:
      session.avaLiveFactLedger?.sellerTargetPrice ||
      session.sellerAskingPrice ||
      session.desiredNet ||
      safeContextCall.sellerTargetPrice ||
      safeContextCall.askingPrice ||
      '',
    fullAddress: session.avaLiveFactLedger?.fullAddress || leadProfile.address || '',
    partialAddress: session.avaLiveFactLedger?.partialAddress || session.partialAddress || '',
    condition:
      session.avaLiveFactLedger?.condition ||
      session.propertyCondition ||
      safeContextCall.condition ||
      '',
    timeline:
      session.avaLiveFactLedger?.timeline ||
      session.timeline ||
      safeContextCall.timeline ||
      '',
    authority:
      session.avaLiveFactLedger?.authority ||
      session.callerRole ||
      safeContextCall.callerRole ||
      '',
    pain:
      session.avaLiveFactLedger?.pain ||
      session.sellerPain ||
      safeContextCall.motivation ||
      '',
    selectedPath: session.selectedPath || safeContextCall.selectedPath || safeContextCall.selected_path || '',
    pathLocked: Boolean(session.pathLocked || safeContextCall.pathLocked),
  };
  const memorySummary = {
    coachingCount: Array.isArray(scripts.activeMemories) ? scripts.activeMemories.length : 0,
    coachingTags: Array.isArray(scripts.activeMemories)
      ? scripts.activeMemories.map((memory) => memory.tag || memory.source || 'memory').slice(0, 6)
      : [],
    liveKnowledgeCount: Array.isArray(session.liveKnowledge) ? session.liveKnowledge.length : 0,
    recentSellerTurns: collectAvaRecentSellerTurns(session, safeContextCall, 4).map((turn) =>
      String(turn.transcript || turn.text || '').slice(0, 180)
    ),
  };
  const pbkIntelligenceContext = buildRuntimePBKIntelligenceContext({
    session,
    contextCall: safeContextCall,
    transcript,
    scripts,
    turnContract: session.avaLiveTurnContract || null,
  });
  const cache = {
    ok: true,
    revision: '2026-06-17-ava-live-call-speed-cache-v1',
    reason,
    cachedAt,
    leadProfile,
    facts,
    activeSkills: {
      count: scripts.activeSkillCount || 0,
      selected: Array.isArray(scripts.selectedSkills)
        ? scripts.selectedSkills.slice(0, 6).map((skill) => ({
            id: skill.id || skill.versionId || '',
            name: skill.name || '',
            confidence: skill.confidence ?? skill.score ?? null,
            status: skill.status || '',
          }))
        : [],
      governedSelection: scripts.governedSkillSelection
        ? {
            result: scripts.governedSkillSelection.result || '',
            action: scripts.governedSkillSelection.action || '',
            selectedSkillId: scripts.governedSkillSelection.selectedSkill?.id || '',
            selectedSkillName: scripts.governedSkillSelection.selectedSkill?.name || '',
          }
        : null,
    },
    memorySummary,
    bantState,
    pbkIntelligenceContext: summarizeRuntimePBKIntelligenceContext(pbkIntelligenceContext),
  };
  return { cache, pbkIntelligenceContext };
}

function refreshAvaLiveCallStartCache(session = {}, contextCall = null, options = {}) {
  if (!session || typeof session !== 'object') return null;
  const { cache, pbkIntelligenceContext } = buildAvaLiveCallStartCache({
    session,
    contextCall,
    transcript: options.transcript || '',
    reason: options.reason || 'call_start',
  });
  session.avaLiveCallStartCache = cache;
  session.liveCallStartCache = cache;
  session.lastLiveCallStartCacheAt = cache.cachedAt;
  applyRuntimePBKIntelligenceContextToSession(session, pbkIntelligenceContext);
  return cache;
}

function getAgentActionContextIds(params = {}, context = {}) {
  return {
    leadId: String(params.leadId || params.lead_id || context.leadId || context.id || '').trim(),
    callId: String(params.callId || params.call_id || params.call?.id || params.call?.callId || context.callId || '').trim(),
  };
}

function buildAgentActionPBKIntelligenceContextInput(params = {}, command = '', context = {}) {
  const ids = getAgentActionContextIds(params, context);
  return buildRuntimePBKIntelligenceContext({
    ...params,
    query: command,
    text: command,
    leadId: ids.leadId,
    callId: ids.callId,
    leadName: context.leadName || context.name || params.leadName || params.name || '',
    address: context.address || params.address || '',
    phone: context.phone || params.phone || '',
    email: context.email || params.email || '',
    turnContract: params.turnContract || params.pbkIntelligenceContext?.turnContract || null,
    contextCall: {
      ...(params.call && typeof params.call === 'object' ? params.call : {}),
      id: ids.callId,
      callId: ids.callId,
      leadId: ids.leadId,
      leadName: context.leadName || context.name || params.leadName || params.name || '',
      address: context.address || params.address || '',
      phone: context.phone || params.phone || '',
      email: context.email || params.email || '',
      transcript: params.transcript || params.messages || [],
      status: params.status || 'agent_action',
    },
  });
}

function isFullAgentActionPBKIntelligenceContext(context = {}) {
  return Boolean(
    context &&
      typeof context === 'object' &&
      context.identity &&
      context.turnContract &&
      context.memory &&
      context.skills
  );
}

function publishAgentActionPBKIntelligenceContext(context = {}) {
  if (!context || typeof context !== 'object') return null;
  if (!state.status || typeof state.status !== 'object') state.status = {};
  state.status.pbkIntelligenceContext = summarizeRuntimePBKIntelligenceContext(context);
  state.status.pbkIntelligenceReadiness = context.fleetReadiness || null;
  state.status.lastPBKIntelligenceContextAt = context.savedAt || context.generatedAt || isoNow();
  return state.status.pbkIntelligenceContext;
}

async function prepareAgentActionPBKIntelligenceContext(params = {}, command = '', context = {}) {
  const ids = getAgentActionContextIds(params, context);
  const input =
    isFullAgentActionPBKIntelligenceContext(params.pbkIntelligenceContext)
      ? params.pbkIntelligenceContext
      : buildAgentActionPBKIntelligenceContextInput(params, command, context);
  const result = await withPBKIntelligenceContext(
    {
      leadId: ids.leadId,
      callId: ids.callId,
      input,
      agents: state.agents || buildDefaultAgentFleet(),
      source: 'agent-action',
    },
    async (agentContext) => {
      const outcome = {
        ...(agentContext.outcome || {}),
        actionTaken: 'agent_action.received',
        sellerReaction: 'routing_started',
      };
      return {
        ok: true,
        source: 'agent-action',
        outcome,
        pbkIntelligenceContext: agentContext,
      };
    }
  );
  const agentContext = result?.pbkIntelligenceContext || input;
  publishAgentActionPBKIntelligenceContext(agentContext);
  return agentContext;
}

async function finalizeAgentActionPBKIntelligenceContext(params = {}, command = '', context = {}, routedTo = '', response = null, agentContext = null) {
  const ids = getAgentActionContextIds(params, context);
  const input =
    agentContext ||
    (isFullAgentActionPBKIntelligenceContext(params.pbkIntelligenceContext)
      ? params.pbkIntelligenceContext
      : buildAgentActionPBKIntelligenceContextInput(params, command, context));
  const result = await withPBKIntelligenceContext(
    {
      leadId: ids.leadId,
      callId: ids.callId,
      input,
      agents: state.agents || buildDefaultAgentFleet(),
      source: 'agent-action',
    },
    async (agentContext) => {
      const outcome = {
        ...(agentContext.outcome || {}),
        actionTaken: routedTo || 'runAgentCommand',
        sellerReaction: response?.ok === false ? 'failed' : 'completed',
        appointmentSet: Boolean(response?.appointment || response?.scheduled || response?.result === 'appointment_scheduled'),
        contractSent: Boolean(response?.envelopeId || response?.contractSent || response?.result === 'docusign_sent'),
      };
      return {
        ok: true,
        source: 'agent-action',
        outcome,
        pbkIntelligenceContext: agentContext,
      };
    }
  );
  const nextContext = result?.pbkIntelligenceContext || input;
  publishAgentActionPBKIntelligenceContext(nextContext);
  return nextContext;
}

function summarizeRuntimePBKIntelligenceContext(context = {}) {
  if (!context || typeof context !== 'object') return null;
  return {
    revision: context.revision || '',
    contextId: context.contextId || '',
    generatedAt: context.generatedAt || '',
    identity: {
      leadId: context.identity?.leadId || '',
      callId: context.identity?.callId || '',
      normalizedPhone: context.identity?.normalizedPhone || '',
      normalizedEmail: context.identity?.normalizedEmail || '',
      ready: Boolean(context.identity?.ready),
      duplicateIds: context.identity?.duplicateIds || [],
    },
    readiness: context.fleetReadiness || null,
    memoryReady: Boolean(context.memory?.ready),
    skillsReady: Boolean(context.skills?.ready),
    dataFreshnessReady: Boolean(context.dataFreshness?.ready),
    activeSkill: context.turnContract?.activeSkill || null,
    intent: context.turnContract?.intent || '',
    objection: context.turnContract?.objection || '',
    phase: context.turnContract?.phase || '',
    missingFacts: context.turnContract?.missingFacts || [],
    forbiddenRepeats: context.turnContract?.forbiddenRepeats || [],
    agentHandoffs: context.agentHandoffs || [],
    outcome: context.outcome || null,
  };
}

function buildContextAwareScriptLibrary(params = {}) {
  const workspaceId = getContextAwareScriptWorkspaceId(params);
  const catalog = getContextAwareScriptCatalog(workspaceId);
  const catalogLoadedAt = contextAwareScriptCatalogLoadedAtByWorkspace.get(workspaceId) || '';
  const catalogAgeMs = catalogLoadedAt
    ? Date.now() - Date.parse(catalogLoadedAt)
    : Number.POSITIVE_INFINITY;
  if (catalogAgeMs >= CONTEXT_AWARE_SCRIPT_CATALOG_REFRESH_MS) {
    void refreshContextAwareScriptCatalog(workspaceId).catch((error) => {
      console.warn(
        '[pbk-local-openclaw] context-aware script catalog refresh skipped:',
        error?.message || error
      );
    });
  }
  const provided = Array.isArray(params.scriptsLibrary || params.scripts_library || params.scripts) ? params.scriptsLibrary || params.scripts_library || params.scripts : [];
  if (provided.length) {
    return provided.map((script) => {
      const catalogMatch = catalog.find(
        (item) =>
          item.id === String(script.id || '') ||
          (item.pathKey === String(script.pathKey || script.path_key || '') &&
            item.title === String(script.title || script.name || ''))
      );
      return catalogMatch ? { ...script, ...catalogMatch } : script;
    });
  }
  if (catalog.length) return catalog;
  if (workspaceId !== 'pbk') return [];
  const bundle = buildAvaWarManualRuntimeSeedBundle();
  return (bundle.scripts || []).map((script) => ({
    id: script.id,
    title: script.title,
    content: script.content,
    tags: script.tags || [],
    pathKey: script.pathKey || '',
    allowedRoles: script.allowedRoles || ['owner', 'agent', 'decision_helper'],
    metadata: script.metadata || {},
  }));
}

async function persistContextAwareScriptExposureToPg(selection = {}, params = {}) {
  const script = selection.selectedScript || selection.selected || {};
  if (!script?.id) return false;
  const workspaceId = String(
    params.workspaceId || params.workspace_id || 'pbk'
  ).trim() || 'pbk';
  const result = await queryPgRows(
    `UPDATE public.scripts
     SET usage_count = COALESCE(usage_count, 0) + 1,
         last_selected_at = NOW(),
         metadata = COALESCE(metadata, '{}'::jsonb) || $2::jsonb,
         updated_at = NOW()
     WHERE id = $1 AND workspace_id = $3
     RETURNING id`,
    [
      script.id,
      JSON.stringify({
        lastContextAwareSelection: {
          callId: params.callId || params.call_id || '',
          leadId: params.leadId || params.lead_id || '',
          score: selection.score || 0,
          reasonCodes: selection.reasonCodes || [],
          selectedAt: isoNow(),
        },
      }),
      workspaceId,
    ]
  );
  return result.ok && result.rows.length > 0;
}

async function selectContextAwareScriptRecord(params = {}) {
  const selection = selectContextAwareScript({
    ...params,
    scripts: buildContextAwareScriptLibrary(params),
  });
  let postgres = false;
  if (selection.ok && params.persistExposure !== false && params.persist_exposure !== false) {
    postgres = await persistContextAwareScriptExposureToPg(selection, params);
    void publishPbkEvent(
      EventTypes.SCRIPT_VARIANT_SELECTED,
      {
        scriptId: selection.selectedScript?.id || '',
        workspaceId: getContextAwareScriptWorkspaceId(params),
        title: selection.selectedScript?.title || '',
        callId: params.callId || params.call_id || '',
        leadId: params.leadId || params.lead_id || '',
        reasonCodes: selection.reasonCodes || [],
        score: selection.score || 0,
      },
      'script-rotator'
    );
  }
  return {
    ...selection,
    providerWritesBlocked: true,
    storage: { postgres },
  };
}

async function getCurrentScriptRecord(params = {}) {
  const selection = await selectContextAwareScriptRecord({
    ...params,
    persistExposure: params.persistExposure ?? params.persist_exposure ?? false,
  });
  return {
    ...selection,
    result: selection.ok ? 'current_script_selected' : selection.result,
    source: 'context-aware-script-rotator',
  };
}

async function recordContextAwareScriptOutcomeRecord(params = {}) {
  const scriptId = String(params.scriptId || params.script_id || params.id || '').trim();
  if (!scriptId) return { ok: false, result: 'invalid_request', error: 'scriptId is required.' };
  const workspaceId = String(
    params.workspaceId || params.workspace_id || 'pbk'
  ).trim() || 'pbk';
  const scripts = buildContextAwareScriptLibrary(params);
  const script = scripts.find((item) => String(item.id || '') === scriptId) || {
    id: scriptId,
    metadata: {},
  };
  const outcomeText = String(
    params.outcome || params.outcomeLabel || params.outcome_label || ''
  ).trim();
  const explicitSuccess =
    typeof params.success === 'boolean' ? params.success : null;
  const success =
    explicitSuccess ??
    (/\b(rejected|lost|dnc|do not call|no interest|hung up|angry)\b/i.test(
      outcomeText
    )
      ? false
      : /\b(accepted|signed|closed|won|appointment|callback|qualified|contract sent)\b/i.test(
          outcomeText
        )
        ? true
        : null);
  const reward = Number.isFinite(Number(params.reward))
    ? Math.max(-1, Math.min(1, Number(params.reward)))
    : success === true
      ? 1
      : success === false
        ? -1
        : 0.15;
  const stats = recordScriptOutcomeStats(script, {
    ...params,
    success: success === true,
  });
  const dealValue = Math.max(0, toMoneyNumber(params.dealValue ?? params.deal_value ?? params.assignmentFee ?? params.assignment_fee, 0));
  const callId = String(params.callId || params.call_id || '').trim();
  const leadId = String(params.leadId || params.lead_id || '').trim();
  const outcomeEventId = String(
    params.outcomeEventId ||
      params.outcome_event_id ||
      (callId
        ? `script-outcome-${createHash('sha256')
            .update(`${workspaceId}|${callId}|${scriptId}`)
            .digest('hex')
            .slice(0, 32)}`
        : `script-outcome-${Date.now()}-${randomUUID().slice(0, 8)}`)
  );
  const result = await queryPgRows(
    `WITH inserted AS (
       INSERT INTO public.pbk_script_outcome_events (
         id, workspace_id, script_id, lead_id, call_id, outcome_label,
         success, reward, deal_value, metadata, created_at
       )
       SELECT $2, $10, $1, $3, $4, $5, $6, $7, $8, $9::jsonb, NOW()
       WHERE EXISTS (
         SELECT 1
         FROM public.scripts
         WHERE id = $1 AND workspace_id = $10
       )
       ON CONFLICT (workspace_id, id) DO NOTHING
       RETURNING id, outcome_label, success, reward, deal_value
     ),
     updated AS (
       UPDATE public.scripts
       SET conversion_count = COALESCE(conversion_count, 0) + CASE WHEN $6 IS TRUE THEN 1 ELSE 0 END,
           deal_value = COALESCE(deal_value, 0) + $8,
           last_outcome_at = NOW(),
           metadata = COALESCE(metadata, '{}'::jsonb) || $9::jsonb,
           updated_at = NOW()
       WHERE id = $1
         AND workspace_id = $10
         AND EXISTS (SELECT 1 FROM inserted)
       RETURNING id, usage_count, conversion_count, deal_value
     ),
     canonical AS (
       SELECT id, outcome_label, success, reward, deal_value
       FROM inserted
       UNION ALL
       SELECT
         events.id,
         events.outcome_label,
         events.success,
         events.reward,
         events.deal_value
       FROM public.pbk_script_outcome_events events
       WHERE events.id = $2
         AND events.workspace_id = $10
         AND events.script_id = $1
         AND NOT EXISTS (SELECT 1 FROM inserted)
       LIMIT 1
     )
     SELECT
       scripts.id,
       scripts.usage_count,
       scripts.conversion_count,
       scripts.deal_value,
       EXISTS (SELECT 1 FROM inserted) AS inserted,
       canonical.id AS canonical_event_id,
       canonical.outcome_label AS canonical_outcome_label,
       canonical.success AS canonical_success,
       canonical.reward AS canonical_reward,
       canonical.deal_value AS canonical_deal_value
     FROM public.scripts scripts
     LEFT JOIN canonical ON TRUE
     WHERE scripts.id = $1 AND scripts.workspace_id = $10`,
    [
      scriptId,
      outcomeEventId,
      leadId,
      callId,
      outcomeText || stats.lastOutcomeLabel || 'observed',
      success,
      reward,
      dealValue,
      JSON.stringify({
        ...plainObject(params.metadata),
        lastContextAwareOutcome: {
          callId,
          leadId,
          outcome: stats.lastOutcomeLabel,
          success,
          reward,
          recordedAt: isoNow(),
        },
      }),
      workspaceId,
    ]
  );
  const returned = result.rows?.[0] || {};
  const canonicalEventId = String(returned.canonical_event_id || '').trim();
  const canonicalOutcome =
    String(returned.canonical_outcome_label || '').trim() ||
    stats.lastOutcomeLabel;
  const canonicalSuccess =
    typeof returned.canonical_success === 'boolean'
      ? returned.canonical_success
      : success;
  const canonicalReward =
    returned.canonical_reward != null &&
    Number.isFinite(Number(returned.canonical_reward))
    ? Number(returned.canonical_reward)
    : reward;
  const canonicalDealValue =
    returned.canonical_deal_value != null &&
    Number.isFinite(Number(returned.canonical_deal_value))
    ? Number(returned.canonical_deal_value)
    : dealValue;
  const finalStats = returned.id
    ? {
        usageCount: Number(returned.usage_count ?? stats.usageCount),
        conversionCount: Number(
          returned.conversion_count ?? stats.conversionCount
        ),
        dealValue: Number(returned.deal_value ?? stats.dealValue),
        lastOutcomeLabel: canonicalOutcome,
        lastSelectedAt: stats.lastSelectedAt,
      }
    : stats;
  const inserted = Boolean(returned.inserted);
  if (returned.id && canonicalEventId && inserted) {
    await recordAgentDecisionRecord({
      id: `agent-decision-${slugify(workspaceId)}-${outcomeEventId}`,
      agentId: 'ava',
      agentName: 'Ava',
      actionType: 'context_aware_script_outcome',
      source: params.source || 'script-rotator',
      leadId,
      callId,
      context: {
        scriptId,
        title: script.title || '',
        pathKey: script.pathKey || '',
      },
      parameters: {
        reasonCodes: params.reasonCodes || params.reason_codes || [],
      },
      outcome: {
        label: canonicalOutcome,
        success: canonicalSuccess,
        dealValue: canonicalDealValue,
      },
      reward: canonicalReward,
      metadata: {
        outcomeEventId,
        idempotentReplay: !inserted,
      },
    });
    await refreshContextAwareScriptCatalog(workspaceId);
  }
  if (inserted) {
    void publishPbkEvent(
      EventTypes.SCRIPT_OUTCOME_RECORDED,
      {
        scriptId,
        callId,
        leadId,
        outcome: finalStats.lastOutcomeLabel,
        stats: finalStats,
        reward: canonicalReward,
        idempotent: false,
      },
      'script-rotator'
    );
  }
  return {
    ok: result.ok && Boolean(returned.id) && Boolean(canonicalEventId),
    result:
      result.ok && returned.id && canonicalEventId
        ? inserted
          ? 'script_outcome_recorded'
          : 'script_outcome_already_recorded'
        : result.ok && returned.id
          ? 'script_outcome_id_conflict'
        : 'script_outcome_record_failed',
    scriptId,
    stats: finalStats,
    reward: canonicalReward,
    idempotent: !inserted,
    storage: {
      postgres: result.ok && Boolean(returned.id) && Boolean(canonicalEventId),
    },
    error:
      result.ok && returned.id && canonicalEventId
        ? ''
        : result.ok && returned.id
          ? 'Outcome event ID already belongs to a different script.'
          : result.error || 'Script row was not found for the recorded outcome.',
  };
}

function normalizeContextAwareSpokenText(value = '') {
  return sanitizeAvaSpokenOutput(value)
    .toLowerCase()
    .replace(/[^a-z0-9$%]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

async function rememberContextAwareScriptSelection(session = {}, architecture = {}, spokenText = '') {
  const selection = architecture?.scripts?.contextAwareSelection || session.contextAwareScriptSelection || null;
  const script = selection?.selectedScript || architecture?.scripts?.selectedScript || {};
  const scriptId = script?.id || session.contextAwareScriptSelection?.selectedScript?.id || '';
  const normalizedScript = normalizeContextAwareSpokenText(script?.content || '');
  const normalizedSpoken = normalizeContextAwareSpokenText(spokenText);
  const scriptWasSpoken =
    normalizedScript.length >= 20
    && normalizedSpoken.length >= 20
    && (normalizedSpoken.includes(normalizedScript) || normalizedScript.includes(normalizedSpoken));
  if (!scriptId || !scriptWasSpoken) return false;
  const workspaceId = String(
    session.workspaceId || session.workspace_id || session.tenantId || session.tenant_id || 'pbk'
  ).trim() || 'pbk';
  const exposurePersisted = await persistContextAwareScriptExposureToPg(
    selection || { selectedScript: script },
    {
      workspaceId,
      callId: session.callId || '',
      leadId: session.leadId || '',
    }
  );
  if (!exposurePersisted) return false;
  if (!Array.isArray(session.recentScriptIds)) session.recentScriptIds = [];
  session.recentScriptIds = [scriptId, ...session.recentScriptIds.filter((id) => id !== scriptId)].slice(0, 8);
  if (!Array.isArray(session.contextAwareScriptHistory)) {
    session.contextAwareScriptHistory = [];
  }
  session.contextAwareScriptHistory = [
    {
      scriptId,
      title: script.title || '',
      pathKey: script.pathKey || '',
      reasonCodes: selection?.reasonCodes || [],
      score: selection?.score || 0,
      selectedAt: isoNow(),
      spokenAt: isoNow(),
      spokenPreview: String(spokenText || '').slice(0, 320),
    },
    ...session.contextAwareScriptHistory.filter(
      (item) => item?.scriptId !== scriptId
    ),
  ].slice(0, 8);
  void publishPbkEvent(
    EventTypes.SCRIPT_VARIANT_SELECTED,
    {
      scriptId,
      workspaceId,
      title: script.title || '',
      callId: session.callId || '',
      leadId: session.leadId || '',
      reasonCodes: selection?.reasonCodes || [],
      score: selection?.score || 0,
    },
    'ava-live-call'
  );
  return true;
}

function getAvaIntelligenceMode(params = {}) {
  return (
    String(params.intelligenceMode || params.intelligence_mode || PBK_INTELLIGENCE_MODE || 'full')
      .trim()
      .toLowerCase() || 'full'
  );
}

function isAvaFullIntelligenceMode(params = {}) {
  return !/^(off|false|0|basic|conditional|minimal)$/i.test(getAvaIntelligenceMode(params));
}

function normalizeAvaBestContextText(value = '') {
  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isAvaWeakContextTranscript(value = '') {
  const clean = normalizeAvaBestContextText(value).toLowerCase();
  if (!clean) return true;
  if (/^(right|yeah|yes|yep|ok|okay|sure|mm hmm|uh huh|it'?s|submission|thanks|thank you|cool|alright|all right|hmm)[.!?\s]*$/i.test(clean)) return true;
  const words = clean.split(/\s+/).filter(Boolean);
  return words.length <= 1;
}

function getAvaTurnTranscriptText(turn = {}) {
  if (typeof turn === 'string') return normalizeAvaBestContextText(turn);
  return normalizeAvaBestContextText(turn.transcript || turn.text || turn.message || turn.content || turn.utterance || '');
}

function isAvaSellerTurn(turn = {}) {
  if (typeof turn === 'string') return true;
  const speaker = String(turn.speaker || turn.role || turn.from || turn.source || '')
    .trim()
    .toLowerCase();
  if (!speaker) return true;
  if (/\b(ava|assistant|bot|system|tool|strategist|rex|hermes)\b/i.test(speaker)) return false;
  return /\b(seller|caller|owner|lead|human|user|customer|agent|realtor|broker)\b/i.test(speaker);
}

function collectAvaRecentSellerTurns(session = {}, contextCall = null, limit = 6) {
  const sources = [
    { label: 'session.transcript', turns: session?.transcript },
    { label: 'session.transcripts', turns: session?.transcripts },
    { label: 'contextCall.transcript', turns: contextCall?.transcript },
    { label: 'contextCall.transcripts', turns: contextCall?.transcripts },
    { label: 'contextCall.messages', turns: contextCall?.messages },
  ];
  const turns = [];
  for (const source of sources) {
    if (!Array.isArray(source.turns)) continue;
    source.turns.forEach((turn, index) => {
      const text = getAvaTurnTranscriptText(turn);
      if (!text || !isAvaSellerTurn(turn)) return;
      turns.push({
        source: source.label,
        index,
        speaker: typeof turn === 'string' ? 'seller' : String(turn.speaker || turn.role || turn.from || 'seller').slice(0, 40),
        transcript: sanitizeAvaSpokenOutput(text).slice(0, 420),
        capturedAt: typeof turn === 'object' ? turn.capturedAt || turn.timestamp || turn.createdAt || turn.at || '' : '',
      });
    });
  }
  const seen = new Set();
  return turns
    .reverse()
    .filter((turn) => {
      const key = turn.transcript.toLowerCase();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, limit)
    .reverse();
}

function selectAvaBestContextTranscript(params = {}) {
  const session = params.session || {};
  const contextCall = params.contextCall || params.call || null;
  const currentTranscript = sanitizeAvaSpokenOutput(normalizeAvaBestContextText(params.transcript || params.query || params.text || '')).slice(0, 700);
  const weakTranscript = isAvaWeakContextTranscript(currentTranscript);
  const recentTurns = collectAvaRecentSellerTurns(session, contextCall, Number(params.limit || 6));
  let bestTranscript = currentTranscript;
  let source = 'current_transcript';
  if (weakTranscript || !bestTranscript) {
    const promoted = [...recentTurns].reverse().find((turn) => {
      const text = normalizeAvaBestContextText(turn.transcript);
      return text && !isAvaWeakContextTranscript(text) && text.toLowerCase() !== currentTranscript.toLowerCase();
    });
    if (promoted?.transcript) {
      bestTranscript = promoted.transcript;
      source = promoted.source || 'recent_seller_turn';
    }
  }
  const resumedFromPriorContext = Boolean(bestTranscript && source !== 'current_transcript');
  return {
    revision: PBK_AVA_FULL_INTELLIGENCE_REVISION,
    mode: getAvaIntelligenceMode(params),
    currentTranscript,
    bestTranscript: bestTranscript || currentTranscript,
    source,
    weakTranscript,
    resumedFromPriorContext,
    recentTurns,
  };
}

function buildAvaLiveTurnContext(params = {}) {
  const session = params.session || {};
  const contextCall = params.contextCall || params.call || null;
  const latestTranscript = normalizeAvaBestContextText(params.transcript || params.query || params.text || '').slice(0, 700);
  const bestContext = selectAvaBestContextTranscript({
    ...params,
    session,
    contextCall,
    transcript: latestTranscript,
    query: latestTranscript,
  });
  const supportTranscript = isAvaFullIntelligenceMode(params) ? normalizeAvaBestContextText(bestContext.bestTranscript || '').slice(0, 1200) : '';
  const parts = [latestTranscript];
  if (supportTranscript && supportTranscript.toLowerCase() !== latestTranscript.toLowerCase()) parts.push(supportTranscript);
  return {
    latestTranscript,
    supportTranscript,
    intelligenceTranscript: parts.filter(Boolean).join(' ').replace(/\s+/g, ' ').trim(),
    bestContext,
  };
}

function isAvaLiveNetNumberAnswer(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean) return false;
  return /\b(net\s+number|highest\s+net|most\s+(?:money|cash)|top\s+dollar|bottom\s+line|walk\s+away|payoff|number\s+i\s+need|what\s+i\s+net)\b/i.test(clean);
}

function isAvaLivePriorityAnswer(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean) return false;
  return isAvaLiveNetNumberAnswer(clean) || /\b(speed|fast|quick|timeline|certainty|sure\s+thing|repairs?|condition|payoff|price)\b/i.test(clean);
}

function isAvaLiveRepeatComplaint(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean) return false;
  return /\b(i already told you|already told you|i told you|told you that|said this already|you just said that|you already said that|you asked that already|you said the same thing|same thing|he said the same thing|she said the same thing|repeating yourself|stop repeating|gave you the address)\b/i.test(clean);
}

function isAvaLiveSellerMoneyContext(transcript = '') {
  const clean = normalizeTelnyxRepairTranscript(transcript);
  if (!clean || !extractAvaLiveMoneyAmount(clean)) return false;
  const hasMoneyLanguage =
    isAvaLiveNetNumberAnswer(clean) ||
    isAvaLiveOfferRequest(clean) ||
    /\b(asking|ask|price|offer|pay|paid|cash|net|walk away|need|want|looking for|hoping for|take|accept|worth|owed|payoff|mortgage|loan balance|bottom line|target)\b/i.test(clean);
  if (hasMoneyLanguage) return true;
  if (/\b(street|st|drive|dr|road|rd|avenue|ave|lane|ln|boulevard|blvd|court|ct|circle|cir|way|zip|postal|phone|number is)\b/i.test(clean)) {
    return false;
  }
  return /\b\d{2,3}\s*(k|thousand|grand|m|million)\b/i.test(clean);
}

function rememberAvaLiveSellerMoney(session = {}, transcript = '', supportTranscript = '') {
  if (!session || typeof session !== 'object') return '';
  if (!session.bant || typeof session.bant !== 'object') session.bant = {};
  const current = normalizeTelnyxRepairTranscript(transcript);
  const support = normalizeTelnyxRepairTranscript(supportTranscript);
  const combined = [current, support].filter(Boolean).join(' ');
  const money = isAvaLiveSellerMoneyContext(current)
    ? extractAvaLiveMoneyAmount(current)
    : isAvaLiveSellerMoneyContext(combined)
      ? extractAvaLiveMoneyAmount(combined)
      : '';
  if (!money) return '';
  session.sellerAskingPrice = money;
  session.desiredNet = session.desiredNet || money;
  if (!normalizeBantValue(session.bant.budget)) session.bant.budget = money;
  return money;
}

function applyAvaLiveTurnFacts(session = {}, transcript = '', supportTranscript = '') {
  if (!session || typeof session !== 'object') return;
  const clean = normalizeTelnyxRepairTranscript(transcript);
  const combined = [clean, normalizeTelnyxRepairTranscript(supportTranscript)].filter(Boolean).join(' ');
  if (!session.bant || typeof session.bant !== 'object') session.bant = {};
  rememberAvaLiveSellerMoney(session, transcript, supportTranscript);
  if (PBK_AGENT_ROLE_RE.test(transcript)) {
    applyAvaCallerRoleToSession(session, {
      revision: PBK_CALLER_ROLE_REVISION,
      role: PBK_CALLER_ROLES.AGENT,
      confidence: 0.93,
      evidence: [`Latest caller turn identified agent role: ${String(transcript || '').slice(0, 100)}`],
      needsClarification: false,
    });
  } else if (hasStrongAvaOwnerRoleAssertion(transcript)) {
    applyAvaCallerRoleToSession(session, {
      revision: PBK_CALLER_ROLE_REVISION,
      role: PBK_CALLER_ROLES.OWNER,
      confidence: 0.91,
      evidence: [`Latest caller turn identified owner role: ${String(transcript || '').slice(0, 100)}`],
      needsClarification: false,
    });
    session.authorityConfirmed = true;
    session.decisionMakerConfirmed = true;
    session.authorityConfirmedAt = session.authorityConfirmedAt || isoNow();
    if (!normalizeBantValue(session.bant.authority)) session.bant.authority = 'caller identified as property owner';
  }
  if (isAvaLiveNetNumberAnswer(clean)) {
    session.sellerPriority = 'net_number';
    session.goalPreference = 'highest_net';
    if (!normalizeBantValue(session.bant.need)) session.bant.need = 'highest net number';
  } else if (/\b(all of them|all three|all four|everything|all that)\b/i.test(clean)) {
    session.sellerPriority = 'balanced';
    session.goalPreference = 'balanced';
    if (!normalizeBantValue(session.bant.need)) session.bant.need = 'balanced priorities: price, speed, and certainty';
    if (!normalizeBantValue(session.bant.timeline)) session.bant.timeline = 'speed matters to seller';
    if (!normalizeBantValue(session.bant.urgency)) session.bant.urgency = 'seller wants price, speed, and certainty';
  } else if (/\bspeed|fast|quick|timeline\b/i.test(clean)) {
    session.sellerPriority = 'speed';
    if (!normalizeBantValue(session.bant.need)) session.bant.need = 'speed';
    if (!normalizeBantValue(session.bant.timeline)) session.bant.timeline = clean;
  } else if (/\bcertainty|sure\s+thing|simple|clean\b/i.test(clean)) {
    session.sellerPriority = 'certainty';
    if (!normalizeBantValue(session.bant.need)) session.bant.need = 'certainty';
    if (!normalizeBantValue(session.bant.urgency)) session.bant.urgency = 'certainty matters to seller';
  } else if (/\brepairs?|condition\b/i.test(clean)) {
    session.sellerPriority = 'repairs';
    if (!normalizeBantValue(session.bant.need)) session.bant.need = 'avoid repairs';
  }
  const locationMatch = combined.match(/\bproperty\s+in\s+([a-z][a-z\s]{2,40})(?:[.?!]|$)/i);
  if (locationMatch?.[1] && !session.address) {
    const region = locationMatch[1].trim().replace(/\s+/g, ' ');
    session.propertyRegion = region;
    session.partialAddress = `Property in ${region}`;
  }
}

function buildAvaFullIntelligenceContext(params = {}) {
  const architecture = params.architecture || {};
  const pathDecision = params.pathDecision || architecture.pathDecision || {};
  const warManual = params.warManual || architecture.warManual || {};
  const activeListening = params.activeListening || architecture.activeListening || {};
  const goalInference = params.goalInference || architecture.goalInference || params.session?.goalInference || {};
  const bestContext = params.bestContext || selectAvaBestContextTranscript(params);
  const usedScripts = [pathDecision.selectedPath || '', pathDecision.scriptTrigger ? 'path_script_trigger' : '', activeListening.callFlow?.nextStepId || '', warManual.path?.key || warManual.pathPicker?.selectedPath || '', warManual.objection?.tag ? `objection:${warManual.objection.tag}` : ''].filter(Boolean).slice(0, 8);
  return {
    revision: PBK_AVA_FULL_INTELLIGENCE_REVISION,
    mode: getAvaIntelligenceMode(params),
    enabled: isAvaFullIntelligenceMode(params),
    context: {
      currentTranscript: bestContext.currentTranscript,
      bestTranscript: bestContext.bestTranscript,
      source: bestContext.source,
      weakTranscript: Boolean(bestContext.weakTranscript),
      resumedFromPriorContext: Boolean(bestContext.resumedFromPriorContext),
      recentTurns: bestContext.recentTurns,
    },
    layers: {
      callerRole: true,
      bant: true,
      pathDecision: true,
      warManual: true,
      activeListening: true,
      scripts: true,
      memory: true,
      goalInference: true,
      prosody: true,
      safety: true,
    },
    usedScripts,
    objectionTriggered: warManual.objection?.tag || '',
    goalInference: goalInference.revision
      ? {
          revision: goalInference.revision,
          topGoal: goalInference.topGoal || null,
          uncertainty: goalInference.uncertainty,
          uncertaintyHigh: Boolean(goalInference.uncertaintyHigh),
          user_goals: goalInference.user_goals || [],
        }
      : {},
    probeDepth: Number(params.probeDepth || params.probe_depth || params.session?.probeDepth || params.session?.pathProbeTurnCount || pathDecision.probeTurnCount || 0),
    resume: {
      canResume: Boolean(bestContext.bestTranscript),
      source: bestContext.source,
      key: params.session?.callId || params.contextCall?.id || params.contextCall?.callId || params.leadId || params.phone || '',
    },
  };
}

function buildAvaCallArchitectureContext(params = {}) {
  const session = params.session || {};
  const contextCall = params.contextCall || params.call || {};
  const context = findLeadContext({
    ...params,
    leadId: contextCall.leadId || session.leadId || params.leadId,
    leadName: contextCall.leadName || session.leadName || params.leadName,
    address: contextCall.address || session.address || params.address,
    phone: contextCall.phone || session.phone || params.phone,
  });
  const turnContext = buildAvaLiveTurnContext({ ...params, session, contextCall });
  const bestContext = turnContext.bestContext;
  const rawTranscript = turnContext.latestTranscript || String(params.transcript || params.query || params.text || '').trim();
  const transcript = rawTranscript;
  const intelligenceTranscript = turnContext.intelligenceTranscript || rawTranscript;
  applyAvaLiveTurnFacts(session, rawTranscript, turnContext.supportTranscript);
  const knownBant = normalizeBantInfo(contextCall.bant || {}, contextCall.raw?.bant || {}, contextCall.raw || {}, params.bant || {});
  const bant = normalizeBantInfo(knownBant, session.bant || {}, extractBantFromTranscript(intelligenceTranscript, knownBant));
  const missingBant = getMissingBantFields(bant);
  let scripts = buildAvaScriptRotationSnapshot({
    ...params,
    session,
    contextCall,
    query: intelligenceTranscript,
  });
  const callerRole = applyAvaCallerRoleToSession(
    session,
    detectAvaCallerRole({
      ...params,
      session,
      contextCall,
      context,
      transcript,
      query: intelligenceTranscript,
    })
  );
  const recentAnalyses = sortNewest(state.callAnalyses || [])
    .filter((analysis) => !context.leadId || !analysis.leadId || analysis.leadId === context.leadId)
    .slice(0, 5)
    .map((analysis) => ({
      callId: analysis.callId || '',
      score: Number(analysis.score || 0),
      failureTags: analysis.failureTags || [],
      scriptSuggestions: analysis.scriptSuggestions || [],
      toolSuggestions: analysis.toolSuggestions || [],
    }));
  const recentRevenueActions = sortNewest(state.revenueActions || [])
    .slice(0, 5)
    .map((action) => ({
      actionId: action.actionId || action.id || '',
      label: action.label || '',
      status: action.status || '',
      target: action.target || '',
      approvalRequired: action.approvalRequired !== false,
    }));
  const nextBantQuestion = missingBant.length ? buildBantRequiredResult({ leadId: context.leadId, address: context.address }, missingBant, bant).recommendedQuestion : '';
  const pathDecision = inferAvaDealPathDecision({
    ...params,
    session,
    contextCall,
    context,
    transcript,
    query: intelligenceTranscript,
    bant,
    selectedPath: params.selectedPath || params.selected_path || contextCall.selectedPath || contextCall.selected_path || context.selectedPath || context.selected_path || '',
    callerRole: callerRole.role,
    turnCount: params.turnCount || params.turn_count || session.turnCount || (Array.isArray(session.transcript) ? session.transcript.length : 0),
  });
  const goalInference = updateAvaGoalInference(session, {
    ...params,
    session,
    contextCall,
    context,
    transcript,
    query: intelligenceTranscript,
    bant,
    pathDecision,
    callerRole: callerRole.role,
  });
  const masterProbe = buildAvaMasterProbe({
    ...params,
    session,
    contextCall,
    context,
    transcript,
    query: intelligenceTranscript,
    bant,
    pathDecision,
    callerRoleDecision: pathDecision.callerRole || callerRole,
  });
  const warManual = buildAvaWarManualContext({
    ...params,
    session,
    contextCall,
    context,
    transcript,
    query: intelligenceTranscript,
    bant,
    pathDecision,
    callerRole: callerRole.role,
    selectedPath: pathDecision.selectedPath,
    turnCount: params.turnCount || params.turn_count || session.turnCount || (Array.isArray(session.transcript) ? session.transcript.length : 0),
  });
  scripts = buildAvaScriptRotationSnapshot({
    ...params,
    session,
    contextCall,
    query: intelligenceTranscript,
    pathDecision,
    pathKey: pathDecision.selectedPath,
    selectedPath: pathDecision.selectedPath,
    callerRole: callerRole.role,
    lastObjection: warManual.objection?.tag || '',
    warManual,
  });
  const contextScriptId = scripts.contextAwareSelection?.selectedScript?.id || scripts.selectedScript?.id || '';
  if (contextScriptId) {
    session.contextAwareScriptSelection = scripts.contextAwareSelection;
  }
  if (scripts.governedSkillSelection?.action === 'clear') {
    delete session.activeGovernedSkillId;
    session.governedSkillSelection = scripts.governedSkillSelection;
  } else if (scripts.governedSkillSelection?.selectedSkill?.id) {
    session.activeGovernedSkillId = scripts.governedSkillSelection.selectedSkill.id;
    session.governedSkillSelection = scripts.governedSkillSelection;
  }
  const activeListening = buildAvaActiveListeningContext({
    ...params,
    session,
    contextCall,
    context,
    transcript,
    query: intelligenceTranscript,
    bant,
    pathDecision,
    warManual,
    callerRole: callerRole.role,
    selectedPath: pathDecision.selectedPath,
    turnCount: params.turnCount || params.turn_count || session.turnCount || (Array.isArray(session.transcript) ? session.transcript.length : 0),
  });
  const fullIntelligence = buildAvaFullIntelligenceContext({
    ...params,
    session,
    contextCall,
    transcript: rawTranscript,
    query: rawTranscript,
    bestContext,
    pathDecision,
    warManual,
    activeListening,
    scripts,
    goalInference,
    probeDepth: session.probeDepth || session.pathProbeTurnCount || pathDecision.probeTurnCount || 0,
  });
  const architectureTurnCount = Number(params.turnCount || params.turn_count || session.turnCount || (Array.isArray(session.transcript) ? session.transcript.length : 0) || 0);
  const longHorizonMemory = compactLongHorizonMemoryCore({
    transcript: intelligenceTranscript || rawTranscript,
    notes: bestContext.bestTranscript || '',
    bant,
    emotion: normalizeEmotionState(params.emotionState || params.emotion || params.currentEmotion || session.emotionState || contextCall.emotionState || contextCall.emotion, params.sentiment),
    turnCount: architectureTurnCount,
    memoryWindow: 20,
    minRetentionTokens: 512,
    bantRequired: true,
    emotionRequired: true,
    env: process.env,
  });
  const pbkIntelligenceContext = buildRuntimePBKIntelligenceContext({
    ...params,
    session,
    contextCall,
    transcript: rawTranscript,
    scripts,
    turnContract: params.turnContract || session.avaLiveTurnContract || null,
    architecture: {
      scripts,
      memory: {
        longHorizon: longHorizonMemory?.compactState || null,
      },
      longHorizonMemory,
    },
    sentiment: params.sentiment ?? contextCall.sentiment ?? session.sentiment?.pbkScore ?? null,
  });
  applyRuntimePBKIntelligenceContextToSession(session, pbkIntelligenceContext);
  return {
    schemaVersion: 'pbk-ava-call-intelligence-v1',
    enabled: getAvaCallIntelligenceSettings().enabled,
    lead: {
      leadId: context.leadId,
      leadName: context.leadName,
      address: context.address,
      phone: context.phone,
    },
    bant: {
      known: bant,
      missing: missingBant,
      complete: missingBant.length === 0,
      nextQuestion: nextBantQuestion,
    },
    callerRole,
    goalInference,
    masterProbe,
    pathDecision,
    dealPath: pathDecision,
    warManual,
    activeListening,
    fullIntelligence,
    scripts,
    longHorizonMemory,
    pbkIntelligenceContext: summarizeRuntimePBKIntelligenceContext(pbkIntelligenceContext),
    pbkIntelligenceReadiness: pbkIntelligenceContext.fleetReadiness || null,
    memory: {
      longHorizon: longHorizonMemory?.compactState || null,
      mem1: longHorizonMemory?.model || null,
    },
    rexOversight: {
      recentCallAnalyses: recentAnalyses,
      recentRevenueActions,
      dailyRevenueFocus: getAvaActiveMemorySummary(3),
    },
    toolRouter: {
      safeReadTools: ['getAvaConversationIntelligence', 'retrieveClosingIntelligence', 'retrieveSimilarDeals', 'recallConversationMemory', 'scoreCallQuality', 'analyzeDeal'],
      approvalGatedTools: ['telnyx_call', 'telnyx_sms', 'sendDocuSign', 'prepare_and_send_contract', 'launch_campaign', 'admin_provider_change'],
      rule: 'Use read-only intelligence immediately. Queue or request approval for provider writes, offers, contracts, campaigns, admin changes, deletes, and seller-facing numbers.',
    },
    prosody: {
      enabled: true,
      provider: 'ElevenLabs',
      modelId: ELEVENLABS_MODEL_ID,
      voiceId: ELEVENLABS_VOICE_ID,
      learningRows: Array.isArray(state.prosodyDecisions) ? state.prosodyDecisions.length : 0,
      activeModel: Boolean(getActiveProsodyModel()),
    },
    safety: {
      providerWritesBlocked: true,
      highRiskApprovalRequired: true,
      neverPresentSellerFacingNumbersUntilBantComplete: true,
    },
  };
}

function setAgentRuntimeActive(agentId = '', patch = {}) {
  ensureAgentFleetCollections();
  const agent = findAgentRecord(agentId);
  if (!agent) return null;
  const nextAgent = {
    ...agent,
    ...patch,
    status: patch.status || 'active',
    lastSeen: isoNow(),
    updatedAt: isoNow(),
    updatedBy: patch.updatedBy || 'Ava Call Intelligence Activation',
    config: {
      ...(agent.config || {}),
      ...(patch.config || {}),
      lastAction: 'activate_call_intelligence',
    },
  };
  upsertById(state, 'agents', nextAgent);
  return nextAgent;
}

async function activateAvaCallIntelligence(params = {}) {
  const actor = String(params.actor || params.requestedBy || params.requested_by || 'PBK Command Center').trim();
  const settings = ensureRuntimeSettings(state);
  const callSettings = {
    enabled: true,
    strategistMode: String(params.strategistMode || params.strategist_mode || AVA_CALL_INTELLIGENCE_STRATEGIST_MODE || 'inline')
      .trim()
      .toLowerCase(),
    strategistTimeoutMs: Math.max(350, Math.min(2500, Number(params.strategistTimeoutMs || params.strategist_timeout_ms || AVA_CALL_INTELLIGENCE_TIMEOUT_MS))),
    useScripts: params.useScripts !== false,
    useBant: params.useBant !== false,
    useMemory: params.useMemory !== false,
    useProsody: params.useProsody !== false,
    useWarManual: params.useWarManual !== false,
    useActiveListening: params.useActiveListening !== false,
    useToolRouter: params.useToolRouter !== false,
    useRexOversight: params.useRexOversight !== false,
    useCallAnalyzer: params.useCallAnalyzer !== false,
    useRevenueGoal: params.useRevenueGoal !== false,
    useEmotionalLearning: params.useEmotionalLearning !== false,
    useSimilarDeals: params.useSimilarDeals !== false,
    providerWritesBlocked: true,
    highRiskApprovalRequired: true,
    activatedAt: isoNow(),
    activatedBy: actor,
  };
  settings.avaCallIntelligence = callSettings;
  settings.updatedAt = isoNow();
  settings.updatedBy = actor;
  state.status.avaCallIntelligence = {
    enabled: true,
    strategistMode: callSettings.strategistMode,
    strategistTimeoutMs: callSettings.strategistTimeoutMs,
    providerWritesBlocked: true,
    highRiskApprovalRequired: true,
    activatedAt: callSettings.activatedAt,
  };

  const ava = setAgentRuntimeActive('ava', {
    status: 'active',
    activity: 'Call intelligence active: scripts, BANT+, $100K War Manual, active listening/call-flow, memory, prosody, tool router, Rex oversight, and safety gates online.',
    updatedBy: actor,
    config: { avaCallIntelligence: callSettings },
  });
  const rex = setAgentRuntimeActive('rex', {
    status: 'active',
    activity: 'Daily goal alignment, call analysis, script/prosody recommendations, and $1M/month oversight active.',
    updatedBy: actor,
    config: { revenueGoalOversight: true, targetMonthlyRevenue: REVENUE_TARGET_MONTHLY },
  });
  const hermesReady = getHermesProviderMeta().ready;
  const hermes = setAgentRuntimeActive('hermes', {
    status: hermesReady ? 'active' : 'standby',
    activity: hermesReady ? 'Suggest-only call pattern analysis ready; provider writes blocked.' : 'Suggest-only analyst lane registered; external Hermes provider not required for Ava call activation.',
    updatedBy: actor,
    config: { suggestOnly: true, providerWritesBlocked: true },
  });

  upsertAvaActiveMemory({
    id: 'ava-call-intelligence-architecture-active',
    memoryType: 'call-intelligence-activation',
    objectionTag: 'architecture_active',
    prompt: 'Before every live call response, use the activated PBK call intelligence bundle.',
    response: 'Ava must use scripts, BANT+, the $100K War Manual, active-listening call_flow/call_flow_edges, seller-word mirroring, responseRequired turn-taking, L.I.S.T.E.N. probe, fifty_plus_objection_decoder, emotional/prosody guidance, similar-deal proof, tool router, and Rex revenue focus while keeping provider writes approval-gated.',
    score: 0.98,
    outcome: 'active',
    source: 'ava-call-intelligence-activation',
    metadata: { callSettings },
  });

  const results = {};
  if (params.runNow !== false && params.run_now !== false) {
    if (callSettings.useCallAnalyzer)
      results.callAnalyzer = await analyzeRecentAvaCalls({
        actor: 'Rex Call Analyzer',
        limit: params.callLimit || 20,
        source: 'ava-call-intelligence-activation',
      });
    if (callSettings.useRevenueGoal)
      results.rexGoalAlignment = await buildRevenueGoalAlignment({
        actor: 'Rex Goal Alignment',
        targetMonthlyRevenue: params.targetMonthlyRevenue || REVENUE_TARGET_MONTHLY,
      });
  }

  addActivity(
    state,
    makeActivity({
      actor,
      category: 'AVA_CALL_INTELLIGENCE',
      status: 'active',
      text: 'Activated Ava live-call intelligence without starting provider writes.',
      target: 'ava-live-call-brain',
    })
  );
  await persistState(state);
  return {
    ok: true,
    result: 'ava_call_intelligence_activated',
    providerWritesBlocked: true,
    highRiskApprovalRequired: true,
    callSettings,
    agents: { ava, rex, hermes },
    runSummary: {
      callAnalyses: results.callAnalyzer?.analyzed || 0,
      revenueActions: results.rexGoalAlignment?.actions?.length || 0,
    },
    status: await getAvaCallIntelligenceStatus(params),
  };
}

async function getAvaCallIntelligenceStatus(params = {}) {
  const settings = getAvaCallIntelligenceSettings();
  const orchestration = buildAgentOrchestrationSnapshot();
  const ava = orchestration.agents.find((agent) => agent.id === 'ava') || null;
  const rex = orchestration.agents.find((agent) => agent.id === 'rex') || null;
  const telnyx = getTelnyxProviderMeta();
  const deepgram = getDeepgramProviderMeta(process.env);
  const eleven = getElevenLabsProviderMeta(process.env);
  const architecture = buildAvaCallArchitectureContext({
    tenantId: params.tenantId || params.tenant_id || 'pbk',
    transcript: params.transcript || params.query || '',
    leadId: params.leadId || params.lead_id || '',
  });
  const avaPaused = /paused|muted|human_takeover/i.test(String(ava?.status || ''));
  const gaps = [...(!settings.enabled ? ['Ava call intelligence is disabled in runtime settings.'] : []), ...(avaPaused ? [`Ava agent runtime still reports ${ava?.status}; activate call intelligence to clear the dashboard pause state.`] : []), ...(!PBK_TELNYX_BRIDGE_AVA_REPLY_ENABLED ? ['Telnyx bridge Ava replies are disabled by PBK_TELNYX_BRIDGE_AVA_REPLY_ENABLED.'] : []), ...(!telnyx.voiceReady ? ['Telnyx voice provider is not fully ready.'] : []), ...(!deepgram.ready ? ['Deepgram live STT is not fully ready.'] : []), ...(!eleven.ready ? ['ElevenLabs TTS is not fully ready.'] : []), ...((architecture.prosody.learningRows || 0) < 10 ? ['Prosody learning is active but still needs measured call outcomes.'] : [])];
  return {
    ok: settings.enabled && !avaPaused,
    result: settings.enabled && !avaPaused ? 'ava_call_intelligence_active' : 'ava_call_intelligence_degraded',
    generatedAt: isoNow(),
    settings,
    agents: { ava, rex },
    voice: {
      telnyxBridgeAvaReplyEnabled: PBK_TELNYX_BRIDGE_AVA_REPLY_ENABLED,
      liveReplyMode: getTelnyxLiveReplyStrategistMode(),
      strategistTimeoutMs: getTelnyxLiveReplyStrategistTimeoutMs(),
      telnyx: { ready: Boolean(telnyx.voiceReady), missing: telnyx.voiceMissing || [] },
      deepgram: { ready: Boolean(deepgram.ready), missing: deepgram.missing || [] },
      elevenLabs: {
        ready: Boolean(eleven.ready),
        voiceId: eleven.voiceId,
        model: eleven.model,
        warnings: eleven.warnings || [],
      },
    },
    architecture,
    safety: {
      providerWritesBlocked: true,
      highRiskApprovalRequired: true,
      activationStartsOutboundActions: false,
    },
    gaps,
  };
}

