function buildQuotasSnapshot() {
  const todaysDocumentDeliveries = state.documentDeliveries.filter((entry) => String(entry.createdAt || '').slice(0, 10) === isoNow().slice(0, 10)).length;
  return {
    instantly: {
      configured: Boolean(INSTANTLY_API_KEY),
      senderProfiles: 2,
      suggestedRemainingDaily: INSTANTLY_API_KEY ? Math.max(0, 5000 - state.messages.filter((item) => item.channel === 'email').length) : 0,
      note: INSTANTLY_API_KEY ? 'Bridge is ready for campaign admin actions.' : 'Add PBK_INSTANTLY_API_KEY to enable live quota visibility.',
    },
    telnyx: {
      configured: Boolean(TELNYX_API_KEY),
      phoneNumbersConfigured: getEffectiveTelnyxFromNumber() ? 1 : 0,
      defaultFromNumber: getEffectiveTelnyxFromNumber(),
      activeCalls: state.calls.filter((item) => isActiveLiveCall(item)).length,
      note: TELNYX_API_KEY ? 'Voice and messaging runtime is reporting locally.' : 'Add PBK_TELNYX_API_KEY and PBK_TELNYX_FROM_NUMBER for live quota visibility.',
    },
    docs: {
      deliveredToday: todaysDocumentDeliveries,
      queuedAdminTasks: getPendingAdminTasks(state.adminTasks).length,
      openContracts: state.contracts.filter((contract) => !['completed', 'void', 'rejected'].includes(String(contract.status || '').toLowerCase())).length,
    },
  };
}

function buildPrometheusMetrics() {
  const runtime = getRuntimeMeta();
  const quotas = buildQuotasSnapshot();
  const pendingApprovals = getPendingRuntimeApprovals(state.approvals).length;
  const pendingAdminTasks = getPendingAdminTasks(state.adminTasks).length;
  const liveCalls = state.calls.filter((item) => isActiveLiveCall(item)).length;
  const openContracts = quotas.docs.openContracts;
  const documentDeliveriesToday = quotas.docs.deliveredToday;
  const totalMessages = state.messages.length;
  const sourcesIndexed = state.brainDocs.length + (state.brainBlogPosts || []).length;
  const analyzeRuns = state.analyzerRuns.length;
  const providerMap = {
    telnyx: getTelnyxProviderMeta(),
    instantly: getInstantlyProviderMeta(),
    googleCalendar: getGoogleCalendarProviderMeta(),
    streak: getStreakProviderMeta(),
    crmSync: getCrmSyncProviderMeta(),
    docusign: getDocuSignProviderMeta(),
    batchdata: getBatchDataProviderMeta(),
    slack: getSlackProviderMeta(),
    render: getRenderProviderMeta(),
    campaignWorker: getCampaignWorkerMeta(),
  };

  const lines = ['# HELP pbk_runtime_hosted Whether the PBK bridge is running in hosted mode.', '# TYPE pbk_runtime_hosted gauge', `pbk_runtime_hosted ${runtime.hosted ? 1 : 0}`, '# HELP pbk_runtime_auth_required Whether the PBK bridge requires a bearer token.', '# TYPE pbk_runtime_auth_required gauge', `pbk_runtime_auth_required ${runtime.authRequired ? 1 : 0}`, '# HELP pbk_runtime_production_ready Whether the runtime reports itself as production ready.', '# TYPE pbk_runtime_production_ready gauge', `pbk_runtime_production_ready ${runtime.productionReady ? 1 : 0}`, '# HELP pbk_approvals_pending Number of pending approval items.', '# TYPE pbk_approvals_pending gauge', `pbk_approvals_pending ${pendingApprovals}`, '# HELP pbk_admin_tasks_pending Number of pending Rex admin tasks.', '# TYPE pbk_admin_tasks_pending gauge', `pbk_admin_tasks_pending ${pendingAdminTasks}`, '# HELP pbk_calls_live Number of currently live calls.', '# TYPE pbk_calls_live gauge', `pbk_calls_live ${liveCalls}`, '# HELP pbk_contracts_open Number of non-terminal contracts.', '# TYPE pbk_contracts_open gauge', `pbk_contracts_open ${openContracts}`, '# HELP pbk_documents_delivered_today Number of seller document deliveries recorded today.', '# TYPE pbk_documents_delivered_today counter', `pbk_documents_delivered_today ${documentDeliveriesToday}`, '# HELP pbk_messages_total Number of messages tracked in runtime state.', '# TYPE pbk_messages_total gauge', `pbk_messages_total ${totalMessages}`, '# HELP pbk_brain_sources_indexed Number of indexed brain sources.', '# TYPE pbk_brain_sources_indexed gauge', `pbk_brain_sources_indexed ${sourcesIndexed}`, '# HELP pbk_analyzer_runs_total Number of analyzer runs tracked in runtime state.', '# TYPE pbk_analyzer_runs_total gauge', `pbk_analyzer_runs_total ${analyzeRuns}`];

  Object.entries(providerMap).forEach(([provider, meta]) => {
    lines.push(`# HELP pbk_provider_ready Whether provider ${provider} is ready.`);
    lines.push('# TYPE pbk_provider_ready gauge');
    lines.push(`pbk_provider_ready{provider="${provider}"} ${meta?.ready ? 1 : 0}`);
    lines.push(`# HELP pbk_provider_configured Whether provider ${provider} is configured.`);
    lines.push('# TYPE pbk_provider_configured gauge');
    lines.push(`pbk_provider_configured{provider="${provider}"} ${meta?.configured ? 1 : 0}`);
  });

  return `${lines.join('\n')}\n`;
}

async function fireWebhook(url, payload) {
  if (!url) return { ok: false, skipped: true };
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 2500);
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    return {
      ok: response.ok,
      status: response.status,
    };
  } catch (error) {
    return {
      ok: false,
      error:
        error?.name === 'AbortError'
          ? 'Webhook request timed out after 2500ms'
          : error instanceof Error
            ? error.message
            : 'Webhook request failed',
    };
  } finally {
    clearTimeout(timeout);
  }
}

function encodeClientState(payload = {}) {
  return Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
}

function decodeTelnyxClientState(value = '') {
  const raw = String(value || '').trim();
  if (!raw) return {};
  try {
    const decoded = Buffer.from(raw, 'base64').toString('utf8');
    const parsed = JSON.parse(decoded);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function getTelnyxFromNumber(params = {}) {
  return normalizePhone(params.from || params.fromNumber || params.selectedFromNumber || params.selected_from_number || getEffectiveTelnyxFromNumber());
}

function getTelnyxWebhookUrl(params = {}) {
  return String(params.webhookUrl || TELNYX_WEBHOOK_URL || '').trim();
}

function getTelnyxDeepgramStreamUrl(params = {}) {
  const explicit = String(params.streamUrl || params.deepgramStreamUrl || '').trim();
  if (explicit) return explicit;
  if (!PUBLIC_BASE_URL) return '';
  const base = PUBLIC_BASE_URL.replace(/^http:/i, 'ws:').replace(/^https:/i, 'wss:');
  const url = new URL(`${base}/api/webhooks/telnyx/media`);
  if (TELNYX_MEDIA_STREAM_TOKEN) url.searchParams.set('token', TELNYX_MEDIA_STREAM_TOKEN);
  return url.toString();
}

function extractTelnyxError(body) {
  if (!body) return 'Telnyx request failed.';
  if (typeof body === 'string') return body;
  if (Array.isArray(body.errors) && body.errors.length > 0) {
    return body.errors
      .map((item) => item?.detail || item?.title || item?.code || 'Unknown Telnyx error')
      .filter(Boolean)
      .join('; ');
  }
  if (body.error) {
    return typeof body.error === 'string' ? body.error : body.error.message || 'Telnyx request failed.';
  }
  if (body.message) return body.message;
  if (body.detail) return body.detail;
  return 'Telnyx request failed.';
}

async function fireTelnyxRequest(method, endpoint, payload, options = {}) {
  if (!TELNYX_API_KEY) {
    return {
      ok: false,
      skipped: true,
      error: 'PBK_TELNYX_API_KEY is not set.',
    };
  }

  try {
    const url = new URL(`https://api.telnyx.com/v2${endpoint}`);
    if (options.query && typeof options.query === 'object') {
      Object.entries(options.query).forEach(([key, value]) => {
        if (value === undefined || value === null || value === '') return;
        if (Array.isArray(value)) {
          value.forEach((item) => url.searchParams.append(key, String(item)));
          return;
        }
        url.searchParams.set(key, String(value));
      });
    }

    const response = await executeProviderCircuitGuard(
      'telnyx',
      () =>
        fetch(url, {
          method: String(method || 'POST').toUpperCase(),
          headers: {
            Authorization: `Bearer ${TELNYX_API_KEY}`,
            Accept: 'application/json',
            ...(payload !== undefined ? { 'Content-Type': 'application/json' } : {}),
          },
          ...(payload !== undefined ? { body: JSON.stringify(payload) } : {}),
        }),
      async () =>
        new Response(JSON.stringify({ error: { message: 'Telnyx circuit is open.' } }), {
          status: 503,
          headers: { 'Content-Type': 'application/json' },
        })
    );

    const text = await response.text();
    let body = null;
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        body = text;
      }
    }

    return {
      ok: response.ok,
      status: response.status,
      body,
      error: response.ok ? '' : extractTelnyxError(body),
    };
  } catch (error) {
    return {
      ok: false,
      error: error instanceof Error ? error.message : 'Telnyx request failed.',
    };
  }
}

function sanitizeTelnyxMdrRecord(body = {}) {
  const data = body?.data && typeof body.data === 'object' ? body.data : {};
  const recipients = Array.isArray(data.to)
    ? data.to.map((recipient) => ({
        phoneNumber: maskPhoneForDiagnostics(recipient?.phone_number || recipient?.phoneNumber || recipient?.number || ''),
        status: String(recipient?.status || '').trim(),
        updatedAt: recipient?.updated_at || recipient?.updatedAt || '',
      }))
    : [];
  const providerErrors = Array.isArray(data.errors)
    ? data.errors.map((error) => ({
        code: String(error?.code || '').trim(),
        title: String(error?.title || '').trim(),
        detail: String(error?.detail || '').trim(),
      }))
    : [];
  const primaryStatus = recipients.find((recipient) => recipient.status)?.status || String(data.status || '').trim();

  return {
    id: data.id || '',
    direction: data.direction || '',
    type: data.type || '',
    status: primaryStatus,
    messagingProfileId: data.messaging_profile_id || data.messagingProfileId || '',
    from: data.from
      ? {
          phoneNumber: maskPhoneForDiagnostics(data.from.phone_number || data.from.phoneNumber || ''),
          carrier: data.from.carrier || '',
          lineType: data.from.line_type || data.from.lineType || '',
        }
      : null,
    recipients,
    webhook: {
      webhookUrlPresent: Boolean(data.webhook_url),
      webhookFailoverUrlPresent: Boolean(data.webhook_failover_url),
      useProfileWebhooks: data.use_profile_webhooks,
    },
    costPresent: Boolean(data.cost),
    errors: providerErrors,
    createdAt: data.created_at || data.createdAt || '',
    updatedAt: data.updated_at || data.updatedAt || '',
    validUntil: data.valid_until || data.validUntil || '',
  };
}

async function getTelnyxMessageDeliveryStatus(messageId = '') {
  const id = String(messageId || '').trim();
  if (!id) {
    return {
      ok: false,
      status: 400,
      result: 'missing_message_id',
      error: 'Telnyx message id is required.',
    };
  }

  const result = await fireTelnyxRequest('GET', `/messages/${encodeURIComponent(id)}`, undefined);
  if (!result.ok) {
    return {
      ok: false,
      status: result.status || 502,
      result: 'provider_error',
      error: result.error || 'Telnyx MDR lookup failed.',
      provider: 'telnyx',
    };
  }

  const mdr = sanitizeTelnyxMdrRecord(result.body || {});
  return {
    ok: true,
    status: result.status || 200,
    result: 'live',
    provider: 'telnyx',
    deliveryStatus: mdr.status,
    messageId: mdr.id || id,
    mdr,
  };
}

async function searchAvailableTelnyxNumbers(params = {}) {
  const quantity = Number(params.quantity || 1);
  const query = {
    'filter[country_code]': params.countryCode || 'US',
    'filter[phone_number_type]': params.phoneNumberType || 'local',
    'filter[limit]': Math.max(1, Math.min(quantity, 20)),
    'filter[best_effort]': params.bestEffort === false ? 'false' : 'true',
    'filter[features]': Array.isArray(params.features) && params.features.length ? params.features : ['sms', 'emergency'],
  };
  if (params.areaCode) query['filter[national_destination_code]'] = String(params.areaCode);
  if (params.locality) query['filter[locality]'] = String(params.locality);
  if (params.administrativeArea) query['filter[administrative_area]'] = String(params.administrativeArea);

  return fireTelnyxRequest('GET', '/available_phone_numbers', undefined, { query });
}

async function orderTelnyxNumbers(params = {}) {
  const phoneNumbers = Array.isArray(params.phoneNumbers) ? params.phoneNumbers.filter(Boolean) : [];
  if (!phoneNumbers.length) {
    return {
      ok: false,
      error: 'At least one phone number is required to create a Telnyx number order.',
    };
  }

  const payload = {
    phone_numbers: phoneNumbers.map((phoneNumber) => ({ phone_number: phoneNumber })),
    ...(params.connectionId ? { connection_id: params.connectionId } : {}),
    ...(params.messagingProfileId ? { messaging_profile_id: params.messagingProfileId } : {}),
    ...(params.customerReference ? { customer_reference: params.customerReference } : {}),
  };

  return fireTelnyxRequest('POST', '/number_orders', payload);
}

async function listTelnyxPhoneNumbers(params = {}) {
  const query = {
    ...(params.phoneNumber ? { 'filter[phone_number]': params.phoneNumber } : {}),
    ...(params.countryIso ? { 'filter[country_iso_alpha2]': params.countryIso } : {}),
  };
  return fireTelnyxRequest('GET', '/phone_numbers', undefined, { query });
}

async function getTelnyxCallControlApplication(applicationId = '') {
  const id = String(applicationId || '').trim();
  if (!id) return { ok: false, skipped: true, error: 'Missing Telnyx Call Control application id.' };
  return fireTelnyxRequest('GET', `/call_control_applications/${encodeURIComponent(id)}`);
}

function normalizeTelnyxNumberRecord(record = {}) {
  const phoneNumber = record.phone_number || record.phoneNumber || record.number || '';
  const connectionId = String(record.connection_id || record.connectionId || '').trim();
  const messagingProfileId = String(record.messaging_profile_id || record.messagingProfileId || '').trim();
  return {
    id: record.id || phoneNumber,
    phone_number: phoneNumber,
    phoneNumber,
    label: record.name || record.label || record.customer_reference || '',
    customerReference: record.customer_reference || record.customerReference || '',
    region: record.region_code || record.region || record.country_iso_alpha2 || '',
    status: record.status || '',
    connectionId,
    connection_id: connectionId,
    connectionMatchesBridge: Boolean(connectionId && TELNYX_CONNECTION_ID && connectionId === TELNYX_CONNECTION_ID),
    messagingProfileId,
    messaging_profile_id: messagingProfileId,
    messagingProfileMatchesBridge: Boolean(messagingProfileId && TELNYX_MESSAGING_PROFILE_ID && messagingProfileId === TELNYX_MESSAGING_PROFILE_ID),
  };
}

async function getTelnyxNumberOptions() {
  const defaultNumber = getEffectiveTelnyxFromNumber();
  const fallbackNumbers = defaultNumber
    ? [
        normalizeTelnyxNumberRecord({
          id: 'env-default',
          phone_number: defaultNumber,
          label: 'Bridge default',
          region: 'env',
        }),
      ]
    : [];
  if (!TELNYX_API_KEY) {
    return {
      ok: false,
      result: 'provider_missing',
      verbiage: 'Phone provider not configured - add Telnyx API key before loading live numbers.',
      numbers: fallbackNumbers,
      defaultNumber,
      missing: ['PBK_TELNYX_API_KEY'],
    };
  }
  const telnyxResult = await listTelnyxPhoneNumbers();
  if (!telnyxResult.ok) {
    return {
      ok: false,
      result: 'provider_missing',
      verbiage: telnyxResult.error || 'Telnyx numbers could not be loaded.',
      numbers: fallbackNumbers,
      defaultNumber,
      telnyx: telnyxResult,
    };
  }
  const rawNumbers = Array.isArray(telnyxResult.body?.data) ? telnyxResult.body.data : [];
  const numbers = rawNumbers.map(normalizeTelnyxNumberRecord).filter((number) => number.phone_number);
  if (defaultNumber && !numbers.some((number) => normalizePhone(number.phone_number) === normalizePhone(defaultNumber))) {
    numbers.unshift(fallbackNumbers[0]);
  }
  return {
    ok: true,
    result: 'live',
    verbiage: numbers.length ? 'Telnyx numbers loaded' : 'Telnyx is configured but no phone numbers were returned.',
    numbers,
    defaultNumber,
  };
}

async function buildTelnyxVoiceRoutingDiagnostic() {
  const numberResult = await getTelnyxNumberOptions();
  const numbers = Array.isArray(numberResult.numbers) ? numberResult.numbers : [];
  const defaultNumber = normalizePhone(numberResult.defaultNumber || getEffectiveTelnyxFromNumber());
  const defaultNumberRecord = numbers.find((number) => normalizePhone(number.phoneNumber || number.phone_number) === defaultNumber) || null;
  const expectedWebhookUrl = getTelnyxWebhookUrl();
  const expectedWebhookUrls = [expectedWebhookUrl, PUBLIC_BASE_URL ? `${PUBLIC_BASE_URL.replace(/\/+$/, '')}/api/webhooks/telnyx/inbound` : '', PUBLIC_BASE_URL ? `${PUBLIC_BASE_URL.replace(/\/+$/, '')}/webhooks/telnyx/inbound` : ''].filter(Boolean);
  const expectedMediaStreamUrl = getTelnyxDeepgramStreamUrl();
  const defaultConnectionId = String(defaultNumberRecord?.connectionId || '').trim();
  const configuredConnectionId = String(TELNYX_CONNECTION_ID || '').trim();
  const connectionMatchesBridge = Boolean(defaultConnectionId && configuredConnectionId && defaultConnectionId === configuredConnectionId);
  const applicationResult = configuredConnectionId ? await getTelnyxCallControlApplication(configuredConnectionId) : { ok: false, skipped: true };
  const application = applicationResult.ok ? applicationResult.body?.data || applicationResult.body || {} : null;
  const applicationWebhookUrl = String(application?.webhook_event_url || application?.webhookEventUrl || '').trim();
  const normalizedApplicationWebhookUrl = applicationWebhookUrl.replace(/\/+$/, '');
  const webhookMatchesBridge = Boolean(normalizedApplicationWebhookUrl && expectedWebhookUrls.some((item) => item.replace(/\/+$/, '') === normalizedApplicationWebhookUrl));
  const issues = [];

  if (!numberResult.ok) issues.push(numberResult.error || numberResult.verbiage || 'Telnyx numbers could not be loaded.');
  if (!defaultNumber) issues.push('PBK_TELNYX_FROM_NUMBER is not configured.');
  if (defaultNumber && !defaultNumberRecord) issues.push(`Default number ${defaultNumber} was not returned by Telnyx.`);
  if (!configuredConnectionId) issues.push('PBK_TELNYX_CONNECTION_ID is not configured.');
  if (defaultNumberRecord && !defaultConnectionId) issues.push(`Default number ${defaultNumber} did not return a connection_id; verify the number is assigned to a Call Control app/connection in Telnyx.`);
  if (defaultConnectionId && configuredConnectionId && defaultConnectionId !== configuredConnectionId) {
    issues.push(`Default number ${defaultNumber} is attached to Telnyx connection ${defaultConnectionId}, but Render is configured for ${configuredConnectionId}.`);
  }
  if (!expectedWebhookUrl) issues.push('PBK_TELNYX_WEBHOOK_URL or PBK_PUBLIC_BASE_URL is not configured.');
  if (!expectedMediaStreamUrl) issues.push('PBK_PUBLIC_BASE_URL or PBK_BRIDGE_PUBLIC_URL is required for media streaming.');
  if (configuredConnectionId && !applicationResult.ok) {
    issues.push(`Telnyx Call Control application ${configuredConnectionId} could not be read: ${applicationResult.error || applicationResult.status || 'unknown error'}.`);
  }
  if (applicationResult.ok && !applicationWebhookUrl) {
    issues.push(`Telnyx Call Control application ${configuredConnectionId} did not return webhook_event_url.`);
  }
  if (applicationWebhookUrl && !webhookMatchesBridge) {
    issues.push(`Telnyx Call Control application webhook_event_url is ${applicationWebhookUrl}, expected one of ${expectedWebhookUrls.join(' or ')}.`);
  }

  return {
    ok: issues.length === 0,
    result: issues.length === 0 ? 'telnyx_voice_routing_ready' : 'telnyx_voice_routing_needs_attention',
    generatedAt: isoNow(),
    defaultNumber,
    expectedWebhookUrl,
    expectedInboundWebhookUrls: expectedWebhookUrls,
    expectedMediaStreamUrl: redactGatewayUrl(expectedMediaStreamUrl),
    streamTrack: DEEPGRAM_STREAM_TRACK,
    streamCodec: DEEPGRAM_STREAM_CODEC,
    bridgeConnectionId: configuredConnectionId,
    defaultNumberConnectionId: defaultConnectionId,
    connectionMatchesBridge,
    callControlApplication: application
      ? {
          id: application.id || configuredConnectionId,
          active: application.active,
          applicationName: application.application_name || application.name || '',
          webhookEventUrl: applicationWebhookUrl,
          webhookEventFailoverUrl: application.webhook_event_failover_url || '',
          webhookApiVersion: application.webhook_api_version || '',
          webhookTimeoutSecs: application.webhook_timeout_secs ?? application.webhookTimeoutSecs ?? null,
          webhookMatchesBridge,
        }
      : {
          id: configuredConnectionId,
          readOk: false,
          error: applicationResult.error || '',
          status: applicationResult.status || null,
        },
    bridgeMessagingProfileId: TELNYX_MESSAGING_PROFILE_ID,
    defaultNumberMessagingProfileId: String(defaultNumberRecord?.messagingProfileId || '').trim(),
    messagingProfileMatchesBridge: Boolean(defaultNumberRecord?.messagingProfileMatchesBridge),
    defaultNumberRecord,
    numbers,
    issues,
    nextStep: issues.length ? 'In Telnyx, assign the PBK number to the bridge Call Control connection and set the inbound webhook URL to the expected bridge URL.' : 'Telnyx number and bridge connection IDs match. If calls still do not appear, inspect Telnyx webhook delivery attempts for signature or URL errors.',
  };
}

function normalizeInstantlySenderRecord(record = {}) {
  const email = String(record.email || record.email_address || record.address || record.username || record.smtp_username || '').trim();
  const warmupStatus = record.warmupStatus ?? record.warmup_status ?? '';
  const setupPending = record.setupPending ?? record.setup_pending ?? false;
  return {
    id: record.id || record.uuid || email,
    email,
    provider: record.provider || record.provider_name || record.type || record.smtp_provider || 'instantly',
    status: record.status ?? '',
    warmupStatus,
    warmup_status: warmupStatus,
    setupPending,
    setup_pending: setupPending,
  };
}

async function getInstantlySenderOptions() {
  const defaultEmail = INSTANTLY_DEFAULT_FROM_EMAIL || getSenderAddress('cold');
  const fallbackSenders = defaultEmail
    ? [
        normalizeInstantlySenderRecord({
          id: 'env-default',
          email: defaultEmail,
          provider: 'bridge default',
          status: 'default',
        }),
      ]
    : [];
  if (!INSTANTLY_API_KEY) {
    return {
      ok: false,
      result: 'provider_missing',
      verbiage: 'Email provider not configured - add PBK_INSTANTLY_API_KEY before loading live senders.',
      senders: fallbackSenders,
      defaultEmail,
      missing: ['PBK_INSTANTLY_API_KEY'],
    };
  }
  const instantlyResult = await fireInstantlyRequest(INSTANTLY_SENDERS_ENDPOINT, undefined, {
    method: 'GET',
  });
  if (!instantlyResult.ok) {
    return {
      ok: false,
      result: 'provider_missing',
      verbiage: instantlyResult.error || 'Instantly sender inboxes could not be loaded.',
      senders: fallbackSenders,
      defaultEmail,
      instantly: instantlyResult,
    };
  }
  const body = instantlyResult.body || {};
  const rawSenders = Array.isArray(body) ? body : Array.isArray(body.data) ? body.data : Array.isArray(body.inboxes) ? body.inboxes : Array.isArray(body.items) ? body.items : [];
  const senders = rawSenders.map(normalizeInstantlySenderRecord).filter((sender) => sender.email);
  if (defaultEmail && !senders.some((sender) => sender.email.toLowerCase() === defaultEmail.toLowerCase())) {
    senders.unshift(fallbackSenders[0]);
  }
  return {
    ok: true,
    result: 'live',
    verbiage: senders.length ? 'Instantly senders loaded' : 'Instantly is configured but no sender inboxes were returned.',
    senders,
    defaultEmail,
  };
}

