async function maybeRecordInboundTelnyxCall(callControlId = '', context = {}) {
  const traceBase = {
    callId: callControlId,
    phone: context.phone || context.from || '',
    leadId: context.leadId || '',
    leadName: context.leadName || '',
    route: context.route || '',
    stage: 'maybeRecordInboundTelnyxCall',
  };
  if (!PBK_TELNYX_RECORD_INBOUND_CALLS) {
    recordCallTrace('inbound_recording_start', {
      ...traceBase,
      result: 'disabled',
      status: 'skipped',
    });
    return { ok: true, skipped: true, result: 'recording_disabled' };
  }
  if (!callControlId) {
    recordCallTrace('inbound_recording_start', {
      ...traceBase,
      result: 'missing_call_control_id',
      status: 'skipped',
    });
    return {
      ok: false,
      skipped: true,
      result: 'missing_call_control_id',
      error: 'Missing Telnyx call_control_id.',
    };
  }
  const result = await recordTelnyxCall(callControlId);
  recordCallTrace('inbound_recording_start', {
    ...traceBase,
    result: result?.ok ? 'recording_requested' : result?.result || 'recording_request_failed',
    status: result?.ok ? 'recording' : 'warning',
    providerStatus: result?.status || 0,
    error: result?.error || '',
  });
  return result;
}

function buildTelnyxDeepgramLiveOptions(codec = DEEPGRAM_STREAM_CODEC) {
  const normalized = String(codec || 'PCMU')
    .trim()
    .toUpperCase();
  if (normalized === 'PCMA') {
    return { encoding: 'alaw', sampleRate: 8000 };
  }
  if (normalized === 'L16' || normalized === 'LINEAR16') {
    return {
      encoding: 'linear16',
      sampleRate: Number(process.env.PBK_DEEPGRAM_TELNYX_SAMPLE_RATE || 16000),
    };
  }
  return { encoding: 'mulaw', sampleRate: 8000 };
}

function normalizeTelnyxMediaCodec(codec = '', fallback = DEEPGRAM_STREAM_CODEC) {
  const normalized = String(codec || fallback || 'PCMU')
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '');
  if (normalized === 'PCMA' || normalized === 'ALAW') return 'PCMA';
  if (normalized === 'L16' || normalized === 'LINEAR16' || normalized === 'PCM' || normalized === 'PCM16') return 'L16';
  return 'PCMU';
}

async function createDeepgramLiveConnectionWithCircuit(options = {}, env = process.env) {
  const connection = await executeProviderCircuitGuard(
    'deepgram',
    () => createDeepgramLiveConnection(options, env),
    async () => buildProviderCircuitOpenResult('deepgram')
  );
  if (!connection || typeof connection.connect !== 'function') {
    throw new Error(connection?.error || 'Deepgram circuit is open or live connection is unavailable.');
  }
  return connection;
}

async function transcribeDeepgramFileWithCircuit(params = {}, env = process.env) {
  return executeProviderCircuitGuard(
    'deepgram',
    () => transcribeDeepgramFile(params, env),
    async () => buildProviderCircuitOpenResult('deepgram')
  );
}

async function transcribeDeepgramUrlWithCircuit(params = {}, env = process.env) {
  return executeProviderCircuitGuard(
    'deepgram',
    () => transcribeDeepgramUrl(params, env),
    async () => buildProviderCircuitOpenResult('deepgram')
  );
}

function decodeMulawByteToLinear16(byte = 0) {
  const mu = (Number(byte) & 0xff) ^ 0xff;
  let sample = ((mu & 0x0f) << 3) + 0x84;
  sample <<= (mu & 0x70) >> 4;
  return mu & 0x80 ? 0x84 - sample : sample - 0x84;
}

function decodeAlawByteToLinear16(byte = 0) {
  const value = (Number(byte) & 0xff) ^ 0x55;
  let sample = (value & 0x0f) << 4;
  const segment = (value & 0x70) >> 4;
  if (segment === 0) sample += 8;
  else if (segment === 1) sample += 0x108;
  else {
    sample += 0x108;
    sample <<= segment - 1;
  }
  return value & 0x80 ? sample : -sample;
}

function decodeG711FrameToLinear16(frame, codec = DEEPGRAM_STREAM_CODEC) {
  const input = Buffer.isBuffer(frame) ? frame : Buffer.from(frame || []);
  const output = Buffer.alloc(input.length * 2);
  const normalized = String(codec || 'PCMU')
    .trim()
    .toUpperCase();
  for (let index = 0; index < input.length; index += 1) {
    const sample = normalized === 'PCMA' ? decodeAlawByteToLinear16(input[index]) : decodeMulawByteToLinear16(input[index]);
    output.writeInt16LE(Math.max(-32768, Math.min(32767, sample)), index * 2);
  }
  return output;
}

function getTelnyxDeepgramLiveModel() {
  return String(process.env.PBK_DEEPGRAM_TELNYX_LIVE_MODEL || process.env.DEEPGRAM_TELNYX_LIVE_MODEL || 'nova-2-phonecall').trim();
}

function shouldStartTelnyxHostedAiAssistant() {
  if (!TELNYX_AI_ASSISTANT_ID || !TELNYX_AI_ASSISTANT_ACTION_ENABLED) return false;
  return !PBK_TELNYX_BRIDGE_AVA_REPLY_ENABLED || PBK_TELNYX_ALLOW_HOSTED_AI_ASSISTANT_WITH_BRIDGE;
}

async function startTelnyxMediaStream(callControlId = '', params = {}) {
  if (!callControlId) {
    recordCallTrace('telnyx_stream_start_skipped', {
      ...params,
      result: 'missing_call_control_id',
      stage: 'startTelnyxMediaStream',
    });
    return { ok: false, skipped: true, error: 'Missing Telnyx call_control_id.' };
  }
  const streamUrl = getTelnyxDeepgramStreamUrl(params);
  if (!streamUrl) {
    recordCallTrace('telnyx_stream_start_skipped', {
      callId: callControlId,
      ...params,
      result: 'provider_missing',
      stage: 'startTelnyxMediaStream',
    });
    return {
      ok: false,
      skipped: true,
      result: 'provider_missing',
      error: 'PBK_PUBLIC_BASE_URL or PBK_BRIDGE_PUBLIC_URL is required before Telnyx can stream media to PBK.',
    };
  }
  recordCallTrace('telnyx_stream_start_request', {
    callId: callControlId,
    ...params,
    streamUrl: streamUrl.replace(/^wss?:\/\/([^/]+).*/i, 'wss://$1/...'),
    stage: 'startTelnyxMediaStream',
  });
  const result = await fireTelnyxRequest('POST', `/calls/${encodeURIComponent(callControlId)}/actions/streaming_start`, {
    stream_url: streamUrl,
    stream_track: params.streamTrack || DEEPGRAM_STREAM_TRACK || 'inbound_track',
    stream_codec: params.streamCodec || DEEPGRAM_STREAM_CODEC || 'PCMU',
    ...getTelnyxBidirectionalMediaParams(),
    ...(TELNYX_MEDIA_STREAM_TOKEN ? { stream_auth_token: TELNYX_MEDIA_STREAM_TOKEN } : {}),
    client_state: encodeClientState({
      source: 'pbk-inbound',
      callControlId,
      route: params.route || '',
      leadId: params.leadId || '',
      leadName: getSpokenLeadName(params.leadName || ''),
      address: params.address || '',
      phone: normalizePhone(params.phone || ''),
      leadSource: params.leadSource || '',
      telnyxAiAssistantStarted: shouldStartTelnyxHostedAiAssistant(),
      streamCodec: params.streamCodec || DEEPGRAM_STREAM_CODEC || 'PCMU',
      streamBidirectionalMode: getTelnyxBidirectionalMediaParams().stream_bidirectional_mode || '',
      startedAt: isoNow(),
    }),
  });
  recordCallTrace('telnyx_stream_start_result', {
    callId: callControlId,
    ...params,
    result: result.result || (result.ok ? 'ok' : 'failed'),
    status: result.status || '',
    error: result.error || '',
    stage: 'startTelnyxMediaStream',
  });
  return result;
}

async function startTelnyxAiAssistant(callControlId = '', promptOverride = '') {
  if (!callControlId)
    return {
      ok: false,
      skipped: true,
      result: 'unavailable',
      error: 'Missing Telnyx call_control_id.',
    };
  if (PBK_TELNYX_BRIDGE_AVA_REPLY_ENABLED && !PBK_TELNYX_ALLOW_HOSTED_AI_ASSISTANT_WITH_BRIDGE) {
    return {
      ok: false,
      skipped: true,
      result: 'bridge_ava_primary',
      error: 'PBK bridge Ava is the primary live voice lane, so the hosted Telnyx AI Assistant was not started. Set PBK_TELNYX_ALLOW_HOSTED_AI_ASSISTANT_WITH_BRIDGE=true only if you intentionally want both.',
      assistantId: TELNYX_AI_ASSISTANT_ID,
      promptOverride,
    };
  }
  if (!TELNYX_AI_ASSISTANT_ID) {
    return {
      ok: false,
      skipped: true,
      result: 'provider_missing',
      error: 'TELNYX_AI_ASSISTANT_ID is not configured.',
      promptOverride,
    };
  }
  if (!TELNYX_AI_ASSISTANT_ACTION_ENABLED) {
    return {
      ok: false,
      skipped: true,
      result: 'queued_for_approval',
      error: 'Telnyx hosted AI Assistant prompt is prepared but provider-side start is disabled. Set PBK_TELNYX_AI_ASSISTANT_ACTION_ENABLED=true after portal verification.',
      assistantId: TELNYX_AI_ASSISTANT_ID,
      promptOverride,
    };
  }
  return fireTelnyxRequest('POST', `/calls/${encodeURIComponent(callControlId)}/actions/ai_assistant_start`, {
    assistant_id: TELNYX_AI_ASSISTANT_ID,
    prompt: promptOverride,
  });
}

