const mcpRuntimeClients = new Map();

function normalizeGeneratedToolName(value = '') {
  return (
    String(value || '')
      .trim()
      .replace(/[^a-zA-Z0-9_.:-]+/g, '_')
      .replace(/^_+|_+$/g, '')
      .slice(0, 120) || `generated_tool_${Date.now()}`
  );
}

async function summarizeAgentOpsMetrics(params = {}) {
  const days = Math.max(1, Math.min(30, Number(params.days || params.windowDays || 1)));
  const rows = await queryPgRows(
    `SELECT
       agent_name,
       step,
       tool_name,
       COUNT(*)::int AS calls,
       COUNT(*) FILTER (WHERE success IS TRUE)::int AS successes,
       ROUND(AVG(latency_ms))::int AS avg_latency_ms,
       MAX(created_at) AS last_seen_at
     FROM public.agent_ops
     WHERE tenant_id = 'pbk'
       AND created_at >= NOW() - ($1::int * INTERVAL '1 day')
     GROUP BY agent_name, step, tool_name
     ORDER BY calls DESC, last_seen_at DESC
     LIMIT 100`,
    [days]
  );
  if (!rows.ok) return rows;
  const metrics = rows.rows.map((row) => ({
    agentName: row.agent_name || 'PBK',
    step: row.step || '',
    toolName: row.tool_name || '',
    calls: Number(row.calls || 0),
    successes: Number(row.successes || 0),
    successRate: row.calls ? Number(((Number(row.successes || 0) / Number(row.calls || 1)) * 100).toFixed(1)) : 0,
    avgLatencyMs: Number(row.avg_latency_ms || 0),
    lastSeenAt: row.last_seen_at,
  }));
  return {
    ok: true,
    result: 'live',
    days,
    metrics,
  };
}

async function persistGeneratedTool(params = {}) {
  const name = normalizeGeneratedToolName(params.name || params.toolName || params.description || '');
  const result = await queryPgRows(
    `INSERT INTO public.generated_tools (
       tenant_id, name, description, input_schema, output_schema, code, status, risk, approval_id, metadata, created_at, updated_at
     )
     VALUES ('pbk',$1,$2,$3::jsonb,$4::jsonb,$5,$6,$7,$8,$9::jsonb,NOW(),NOW())
     RETURNING *`,
    [name, String(params.description || '').slice(0, 2000), JSON.stringify(params.inputSchema || params.input_schema || {}), JSON.stringify(params.outputSchema || params.output_schema || {}), String(params.code || '').slice(0, 50000), String(params.status || 'pending_review'), String(params.risk || 'medium'), String(params.approvalId || params.approval_id || ''), JSON.stringify(params.metadata && typeof params.metadata === 'object' ? params.metadata : {})]
  );
  return result.ok ? result.rows[0] : null;
}

async function getGeneratedToolByIdOrName(idOrName = '') {
  const key = String(idOrName || '').trim();
  if (!key) return null;
  const result = await queryPgRows(
    `SELECT * FROM public.generated_tools
     WHERE tenant_id = 'pbk' AND (id = $1 OR name = $1)
     ORDER BY updated_at DESC
     LIMIT 1`,
    [key]
  );
  return result.ok ? result.rows[0] || null : null;
}

async function connectMcpRuntimeServer(params = {}) {
  const serverName = normalizeGeneratedToolName(params.serverName || params.name || 'mcp-server');
  const command = String(params.command || '').trim();
  const args = Array.isArray(params.args) ? params.args.map((arg) => String(arg)) : [];
  if (!command) return { ok: false, result: 'missing_command', error: 'MCP server command is required.' };
  if (!/^(npx|node|python|python3|uvx)$/i.test(command)) {
    return {
      ok: false,
      result: 'command_not_allowed',
      error: `MCP command ${command} is not allowed.`,
    };
  }
  const { Client } = await import('@modelcontextprotocol/sdk/client/index.js');
  const { StdioClientTransport } = await import('@modelcontextprotocol/sdk/client/stdio.js');
  const transport = new StdioClientTransport({ command, args });
  const client = new Client({ name: `pbk-${serverName}`, version: BUILD_REVISION });
  await client.connect(transport);
  const listed = await client.listTools();
  const tools = Array.isArray(listed?.tools) ? listed.tools : Array.isArray(listed) ? listed : [];
  mcpRuntimeClients.set(serverName, {
    serverName,
    client,
    connectedAt: isoNow(),
    command,
    args,
    tools,
  });
  return {
    ok: true,
    result: 'connected',
    serverName,
    tools: tools.map((tool) => ({
      name: tool.name,
      description: tool.description || '',
      inputSchema: tool.inputSchema || tool.input_schema || null,
    })),
  };
}

function listMcpRuntimeServers() {
  return [...mcpRuntimeClients.values()].map((entry) => ({
    serverName: entry.serverName,
    connectedAt: entry.connectedAt,
    command: entry.command,
    args: entry.args,
    toolCount: entry.tools?.length || 0,
    tools: (entry.tools || []).map((tool) => ({
      name: tool.name,
      description: tool.description || '',
    })),
  }));
}

async function callMcpRuntimeTool(params = {}) {
  const serverName = String(params.serverName || params.server || '').trim();
  const toolName = String(params.toolName || params.tool || params.name || '').trim();
  if (!serverName || !toolName) return { ok: false, result: 'missing_server_or_tool' };
  const entry = mcpRuntimeClients.get(serverName);
  if (!entry) return { ok: false, result: 'mcp_server_not_connected', serverName };
  const toolArgs = params.arguments && typeof params.arguments === 'object' ? params.arguments : params.params && typeof params.params === 'object' ? params.params : {};
  const result = await entry.client.callTool({ name: toolName, arguments: toolArgs });
  return {
    ok: true,
    result: 'tool_called',
    serverName,
    toolName,
    response: result,
  };
}

function parseReadonlyCliCommand(command = '') {
  const text = String(command || '').trim();
  if (!text) return null;
  const parts = text.match(/(?:[^\s"]+|"[^"]*")+/g)?.map((part) => part.replace(/^"|"$/g, '')) || [];
  const base = parts[0] || '';
  const args = parts.slice(1);
  if (base === 'node' && args.length === 1 && ['--version', '-v'].includes(args[0])) return { file: 'node', args };
  if (base === 'npm' && args.length === 1 && ['--version', '-v'].includes(args[0])) return { file: 'npm', args };
  if (base === 'git') {
    const allowed = [
      ['status', '--short'],
      ['status', '--porcelain'],
      ['log', '-1', '--oneline'],
      ['diff', '--stat'],
    ];
    if (allowed.some((pattern) => pattern.length === args.length && pattern.every((value, index) => value === args[index]))) {
      return { file: 'git', args };
    }
  }
  if (base === 'rg' && args.length >= 1 && args.length <= 4 && !args.some((arg) => /^-/.test(arg) && !['--files', '-n', '--glob'].includes(arg))) {
    return { file: 'rg', args };
  }
  return null;
}

function runReadonlyCliCommand(params = {}) {
  const command = String(params.command || '').trim();
  const parsed = parseReadonlyCliCommand(command);
  if (!parsed) {
    return {
      ok: false,
      result: 'command_not_allowed',
      error: 'Only read-only diagnostics are allowed: node --version, npm --version, git status --short, git log -1 --oneline, git diff --stat, or rg searches.',
    };
  }
  const cwdRaw = String(params.cwd || params.workdir || ROOT_DIR).trim();
  const cwd = path.resolve(cwdRaw || ROOT_DIR);
  if (!cwd.startsWith(ROOT_DIR)) {
    return {
      ok: false,
      result: 'cwd_not_allowed',
      error: 'CLI diagnostics must stay inside the PBK workspace.',
    };
  }
  try {
    const stdout = execFileSync(parsed.file, parsed.args, {
      cwd,
      encoding: 'utf8',
      timeout: Math.max(1000, Math.min(30000, Number(params.timeoutMs || params.timeout_ms || 10000))),
      windowsHide: true,
      maxBuffer: 1024 * 512,
    });
    return { ok: true, result: 'completed', command, stdout: stdout.slice(0, 12000), stderr: '' };
  } catch (error) {
    return {
      ok: false,
      result: 'failed',
      command,
      stdout: String(error?.stdout || '').slice(0, 12000),
      stderr: String(error?.stderr || error?.message || '').slice(0, 4000),
      error: error?.message || String(error),
    };
  }
}

async function recordResearchAdditiveRun(additiveId, toolName, input = {}, output = {}, safety = {}) {
  const pool = getPgPool();
  if (!pool) return null;
  try {
    const result = await queryPgRows(
      `INSERT INTO public.pbk_research_additive_runs (
         tenant_id, additive_id, tool_name, input, output, status, safety, source, created_at
       )
       VALUES ('pbk',$1,$2,$3::jsonb,$4::jsonb,$5,$6::jsonb,'pbk-bridge',NOW())
       RETURNING id, created_at`,
      [String(additiveId || '').slice(0, 120), String(toolName || '').slice(0, 120), JSON.stringify(input || {}), JSON.stringify(compactAgentOpsPayload(output || {}, 12000)), output?.ok === false ? 'failed' : 'completed', JSON.stringify(safety || {})]
    );
    return result.ok ? result.rows?.[0] || null : null;
  } catch (error) {
    console.warn('[pbk-local-openclaw] research additive run persistence skipped:', error?.message || error);
    return null;
  }
}

async function recordResearchAdditiveProviderChecks(providerChecks = {}, source = 'pbk-bridge') {
  const pool = getPgPool();
  const providers = Array.isArray(providerChecks.providers) ? providerChecks.providers : [];
  if (!pool || providers.length === 0) return [];
  const saved = [];
  for (const provider of providers) {
    try {
      const result = await queryPgRows(
        `INSERT INTO public.pbk_research_additive_provider_checks (
           tenant_id, additive_id, provider_id, configured, ready, status, endpoint_env, endpoint,
           latency_ms, response, error, source, created_at
         )
         VALUES ('pbk',$1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10,$11,NOW())
         RETURNING id, created_at`,
        [String(provider.additiveId || '').slice(0, 120), String(provider.providerId || '').slice(0, 120), Boolean(provider.configured), Boolean(provider.ready), String(provider.status || '').slice(0, 120), String(provider.endpointEnv || '').slice(0, 120), String(provider.endpoint || '').slice(0, 500), Number(provider.latencyMs || 0), JSON.stringify(compactAgentOpsPayload(provider.response || {}, 4000)), String(provider.error || '').slice(0, 1000), String(source || 'pbk-bridge').slice(0, 120)]
      );
      if (result.ok && result.rows?.[0]) saved.push(result.rows[0]);
    } catch (error) {
      console.warn('[pbk-local-openclaw] research provider check persistence skipped:', error?.message || error);
    }
  }
  return saved;
}

function enrichNurtureLeadParams(params = {}) {
  const requestedId = String(params.leadId || params.lead_id || params.id || '').trim();
  if (!requestedId) return params;
  const lead = (state.leadImports || []).find((item) => {
    const ids = [item.id, item.leadId, item.lead_id, item.externalId, item.external_id, item.phone, item.seller?.phone].map((value) => String(value || '').trim()).filter(Boolean);
    return ids.includes(requestedId);
  });
  if (!lead) return params;
  const seller = lead.seller || {};
  const property = lead.property || {};
  return {
    ...params,
    leadId: lead.leadId || lead.lead_id || lead.id || requestedId,
    externalId: lead.id || lead.externalId || lead.external_id || requestedId,
    leadName: seller.name || lead.leadName || lead.lead_name || lead.name || params.leadName,
    firstName: String(seller.name || lead.leadName || '').split(/\s+/)[0] || params.firstName,
    email: seller.email || lead.email || params.email,
    phone: seller.phone || lead.phone || params.phone,
    address: property.address || lead.address || params.address,
    city: property.city || lead.city || params.city,
    state: property.state || lead.state || params.state,
    postalCode: property.zip || property.postalCode || property.postal_code || lead.zip || params.postalCode,
    stage: lead.stage || lead.temperature || params.stage || 'warm',
    temperature: lead.temperature || lead.stage || params.temperature || 'warm',
    score: lead.engagementScore || lead.engagement_score || lead.motivationScore || lead.score || params.score || 0,
    source: params.source || 'bridge-state-lead-import',
  };
}

async function executeFastCommandIntent(classification = {}, params = {}) {
  switch (classification.intent) {
    case 'status.bridge': {
      const result = await toolHandlers.admin_check_health({
        requestedBy: 'PBK command intent router',
        source: params.source || 'agent-command-fast-path',
      });
      return {
        ok: true,
        routedTo: classification.route,
        answer: 'PBK bridge health came directly from the live runtime snapshot.',
        source: 'live PBK bridge state',
        result,
      };
    }
    case 'status.openclaw_gateway': {
      const result = await buildOpenClawGatewayStatus({ force: false });
      return {
        ok: true,
        routedTo: classification.route,
        answer: result?.ready
          ? 'OpenClaw gateway is responding to the bridge.'
          : 'OpenClaw gateway status needs attention.',
        source: 'OpenClaw HTTP and WebSocket probes',
        result,
      };
    }
    case 'status.desktop_sidecar': {
      const result = buildDesktopSidecarStatus();
      return {
        ok: true,
        routedTo: classification.route,
        answer: result.connected
          ? `${result.connectedCount} desktop sidecar connection${result.connectedCount === 1 ? '' : 's'} active.`
          : 'No desktop sidecar is connected.',
        source: 'live desktop sidecar socket registry',
        result,
      };
    }
    case 'status.tooling': {
      const result = await buildToolingStatus();
      return {
        ok: true,
        routedTo: classification.route,
        answer: result.summary?.note || 'PBK tooling readiness was read from the live bridge.',
        source: 'PBK tooling status builder',
        result,
      };
    }
    case 'status.provider_quotas': {
      const result = buildQuotasSnapshot();
      return {
        ok: true,
        routedTo: classification.route,
        answer: 'Provider readiness and operating quotas came from the current PBK runtime.',
        source: 'PBK provider and quota snapshot',
        result,
      };
    }
    case 'status.vector_memory': {
      const result = await buildVectorCapacityStatus();
      return {
        ok: true,
        routedTo: classification.route,
        answer: result.rexResearchReady
          ? 'Rex semantic memory and pgvector capacity are ready.'
          : 'Rex semantic memory status was checked and still has readiness work.',
        source: 'Postgres catalog and pgvector canary',
        result,
      };
    }
    default:
      return null;
  }
}

async function routeFastCommandIntent(command = '', params = {}) {
  if (!COMMAND_INTENT_ROUTER_ENABLED) return null;
  const classification = classifyCommandIntent(command);
  if (!classification.matched || classification.confidence !== 1) return null;

  const startedAt = performance.now();
  let response = await getCachedCommandIntentResult(classification);
  const cacheHit = Boolean(response);
  if (!response) {
    response = await executeFastCommandIntent(classification, params);
    if (!response) return null;
    setCachedCommandIntentResult(classification, response);
  }
  const latencyMs = Math.max(0, Math.round(performance.now() - startedAt));
  incrementObservabilityCounter('command_intent_router_requests', 1, {
    intent: classification.intent,
    cache: cacheHit ? 'hit' : 'miss',
  });
  recordLatencyMetric('command_intent_router_latency_ms', latencyMs, {
    intent: classification.intent,
    cache: cacheHit ? 'hit' : 'miss',
  });

  return {
    routedTo: response.routedTo || classification.route,
    response,
    intentRouter: {
      version: COMMAND_INTENT_ROUTER_VERSION,
      category: classification.category,
      intent: classification.intent,
      confidence: classification.confidence,
      reason: classification.reason,
      cache: cacheHit ? 'hit' : 'miss',
      cacheTtlSeconds: classification.ttlSeconds,
      providerBypassed: true,
      requestedBy: params.actor || params.requestedBy || 'PBK operator',
      latencyMs,
    },
  };
}

