  async pbk_kill_switch(params = {}) {
    recordToolUse('pbk_kill_switch');
    const action = String(params.action || params.mode || 'disable_provider_writes')
      .trim()
      .toLowerCase();
    const enableWrites = ['restore', 'enable', 'clear', 'off'].includes(action);
    const confirm = String(params.confirm || params.passcode || '').trim();
    const passcodeOk = PROTECTED_OPS_PASSCODE && confirm.toLowerCase() === PROTECTED_OPS_PASSCODE.toLowerCase();
    if (enableWrites && confirm !== 'RESTORE_PROVIDER_WRITES' && !passcodeOk) {
      return {
        ok: false,
        result: 'confirmation_required',
        message: 'To clear the kill switch, pass confirm: RESTORE_PROVIDER_WRITES or the protected ops passcode.',
      };
    }
    if (!enableWrites && confirm && confirm !== 'DISABLE_PROVIDER_WRITES' && !passcodeOk) {
      return {
        ok: false,
        result: 'confirmation_required',
        message: 'To activate the kill switch, pass confirm: DISABLE_PROVIDER_WRITES, the protected ops passcode, or omit confirm for the safe default.',
      };
    }
    const active = !enableWrites;
    const settings = ensureRuntimeSettings(state);
    const nextSwitch = {
      active,
      reason: String(params.reason || (active ? 'Manual PBK safety stop requested.' : 'Provider writes restored by operator.')).trim(),
      activatedAt: active ? isoNow() : null,
      activatedBy: params.actor || params.requestedBy || 'PBK operator',
      clearedAt: active ? null : isoNow(),
    };
    state.status.providerKillSwitch = nextSwitch;
    state.settings = {
      ...settings,
      providerKillSwitch: nextSwitch,
      ui: {
        ...(settings.ui || {}),
        providerKillSwitch: nextSwitch,
        operatingMode: active ? 'manual' : settings.ui?.operatingMode || settings.operatingMode || 'approval',
      },
      updatedAt: isoNow(),
      updatedBy: nextSwitch.activatedBy,
    };
    addActivity(
      state,
      makeActivity({
        actor: nextSwitch.activatedBy,
        category: 'GUARDRAIL',
        status: active ? 'blocked' : 'saved',
        text: active ? `Provider kill switch activated: ${nextSwitch.reason}` : `Provider kill switch cleared: ${nextSwitch.reason}`,
        target: 'provider-writes',
      })
    );
    await persistState(state);
    return {
      ok: true,
      result: active ? 'provider_writes_disabled' : 'provider_writes_restored',
      killSwitch: nextSwitch,
      mode: getRuntimeOperatingMode(),
    };
  },

  async analyzeDeal(params = {}) {
    recordToolUse('analyzeDeal');
    const mtValidation = validateMortgageTakeoverInputs(params);
    if (!mtValidation.ok) {
      return mtValidation;
    }
    if (shouldEnforceBantForAnalyze(params)) {
      const leadImport = findLatestLeadImport(params);
      const bant = normalizeBantInfo(params.bant || {}, params, leadImport?.bant || {}, leadImport?.callContext?.bant || {});
      const missingBant = getMissingBantFields(bant);
      if (missingBant.length) {
        const result = buildBantRequiredResult(params, missingBant, bant);
        addActivity(
          state,
          makeActivity({
            actor: 'Ava Guardrail',
            category: 'QUALIFY',
            status: 'blocked',
            text: result.error,
            target: params.address || params.propertyAddress || leadImport?.property?.address || params.leadName || 'seller-facing analyzer',
          })
        );
        await persistState(state);
        return result;
      }
    }
    const cached = getAnalyzerResultCache(params);
    if (cached) return cached.result;

    const propertyResolution = await resolvePropertyDataForAnalyzer(params);
    const run = buildAnalyzerSummary({
      ...params,
      propertyData: propertyResolution.propertyData,
      enrichment: propertyResolution.enrichment,
    });
    const bant = normalizeBantInfo(params.bant || {}, params);
    if (Object.keys(bant).length) {
      run.bant = bant;
      run.bantComplete = getMissingBantFields(bant).length === 0;
    }
    addAnalyzerRun(state, run);
    const syncedLead = syncAnalyzerRunToLeadProfile(params, run);
    let leadProfilePersistence = null;
    if (syncedLead) {
      try {
        leadProfilePersistence = await persistLeadProfileRowToDb(syncedLead, 'analyzer-deal-sync');
      } catch (error) {
        leadProfilePersistence = {
          ok: false,
          result: 'analyzer_lead_profile_persist_failed',
          error: error?.message || String(error || 'unknown error'),
        };
      }
    }
    addActivity(
      state,
      makeActivity({
        actor: 'System',
        category: 'ANALYZE',
        status: 'success',
        text: `Analyzer ran - ARV ${currency(run.arv)} - MAO ${currency(run.mao)} - target ${currency(run.targetOffer)} (${propertyResolution.enrichment.cache} property cache)`,
        target: run.address,
      })
    );
    await persistState(state);
    setAnalyzerResultCache(params, run);
    return {
      ...run,
      leadSynced: Boolean(syncedLead),
      leadId: syncedLead?.leadId || run.leadId,
      leadProfilePersistence,
    };
  },

  async getPropertyData(params = {}) {
    recordToolUse('getPropertyData');
    const address = params.address || params.propertyAddress || params.deal?.address || '';
    const cache = findPropertyCacheEntry(address);
    let browserResearch = null;
    if (!cache.hit && params.queueBrowserResearch) {
      browserResearch = await queueBrowserPropertyResearch({
        address,
        requestedBy: params.requestedBy || 'Rex',
        source: params.source || 'property-cache-miss',
      });
      await persistState(state);
    }
    return {
      ok: Boolean(cache.hit),
      address,
      cache: {
        hit: cache.hit,
        expired: cache.expired,
        key: cache.key,
        ageMs: cache.ageMs,
        ttlDays: PROPERTY_CACHE_TTL_DAYS,
      },
      propertyData: cache.entry || null,
      browserResearch: browserResearch
        ? {
            ready: browserResearch.ready,
            job: browserResearch.job,
          }
        : null,
    };
  },

