        text: report.readiness?.readyForPbk ? `Streak pipeline ${report.pipeline?.key || 'unknown'} is ready for PBK transitions.` : report.provider?.configured ? `Streak pipeline ${report.pipeline?.key || 'unknown'} needs schema alignment before full PBK sync.` : 'Streak pipeline inspection requested before provider credentials were fully configured.',
        target: report.pipeline?.key || 'streak',
