  async updateCRM(params = {}) {
    recordToolUse('updateCRM');
    if (isProfileOnlyCrmUpdate('updateCRM', params)) {
      return updateLeadProfileOnlyFromCrm(params);
    }
    const syncResult = await syncCrmTransition(params);
    if (syncResult?.provider === 'streak' && syncResult?.boxKey) {
      patchLeadImport(
        state,
        {
          leadId: params.leadId || params.lead?.leadId || params.transition?.leadId || '',
          leadName: params.leadName || params.lead?.leadName || params.transition?.leadName || '',
          address: params.address || params.lead?.address || params.transition?.address || '',
          email: params.email || params.lead?.email || '',
        },
        {
          streakBoxKey: syncResult.boxKey,
          streakPipelineKey: syncResult.pipelineKey || '',
          streakStageKey: syncResult.stageKey || '',
          streakStageName: syncResult.stageName || '',
          lastCrmSyncProvider: syncResult.provider || 'streak',
          lastCrmSyncStatus: syncResult.ok ? 'synced' : syncResult.skipped ? 'skipped' : 'warning',
          lastCrmSyncAt: isoNow(),
        }
      );
    }
    addActivity(
      state,
      makeActivity({
        actor: 'System',
        category: 'CRM',
        status: syncResult?.ok ? 'synced' : syncResult?.skipped ? 'pending' : 'warning',
        text: syncResult?.ok ? params.message || `CRM sync completed through ${syncResult.provider || 'crm'}.` : syncResult?.skipped ? params.message || `CRM sync skipped: ${syncResult.error || 'provider not configured'}.` : params.message || `CRM sync failed: ${syncResult.error || 'unknown error'}.`,
        target: params.target || params.leadId || 'crm',
      })
    );
    await persistState(state);
    return {
      ok: true,
      result: syncResult?.ok ? 'live' : syncResult?.skipped ? 'local_view_only' : 'provider_missing',
      updatedAt: isoNow(),
      target: params.target || params.leadId || 'crm',
      provider: syncResult?.provider || '',
      sync: syncResult,
    };
  },

  async ingestResearchDoc(params = {}) {
    recordToolUse('ingestResearchDoc');
    const hydrated = await hydrateResearchIngestParams(params);
    const doc = {
      id: hydrated.id || randomUUID(),
      kind: hydrated.kind || 'note',
      topic: hydrated.topic || 'Wholesaling',
      title: hydrated.title || 'Untitled source',
      source: hydrated.source || hydrated.sourceUrl || 'Manual ingest',
      sourceUrl: hydrated.sourceUrl || getIngestSourceUrl(hydrated),
      excerpt: hydrated.excerpt || hydrated.summary || 'No excerpt provided.',
      summary: hydrated.summary || hydrated.excerpt || 'No summary provided.',
      citation: hydrated.citation || `${hydrated.source || hydrated.sourceUrl || 'Manual ingest'} - ${new Date().toLocaleDateString()}`,
      createdAt: isoNow(),
      tags: normalizeStringList(hydrated.tags || [hydrated.topic || 'Wholesaling']),
      metadata: hydrated.metadata && typeof hydrated.metadata === 'object' ? hydrated.metadata : {},
    };

    addBrainDoc(state, doc);
    const post = normalizeBrainBlogPost({
      ...hydrated,
      id: doc.id,
      title: doc.title,
      sourceUrl: doc.sourceUrl,
      sourceType: doc.kind,
      sourceName: doc.source,
      content: hydrated.content || hydrated.body || hydrated.transcript || doc.summary,
      summary: doc.summary,
      tags: doc.tags,
      metadata: {
        ...doc.metadata,
        brainDocId: doc.id,
        ingestedThrough: 'ingestResearchDoc',
      },
      createdAt: doc.createdAt,
    });
    addBrainBlogPost(state, post);
    const vectorMemory = await embedAndPersistBrainBlogPost(post, {
      workspaceId: hydrated.workspaceId || hydrated.workspace_id,
      source: 'ingestResearchDoc',
    });
    addActivity(
      state,
      makeActivity({
        actor: 'Rex',
        category: 'RESEARCH',
        status: vectorMemory.ok ? 'indexed' : 'stored',
        text: vectorMemory.ok
          ? `Embedded new ${doc.kind} source into Rex pgvector memory: ${doc.title}`
          : `Stored ${doc.kind} source without a Rex embedding: ${doc.title}`,
        target: doc.topic,
      })
    );
    state.status.weeklySources = toNumber(state.status.weeklySources, 0) + 1;
    await persistState(state);
    return {
      ok: true,
      result:
        doc.metadata?.extraction?.ok === false
          ? 'queued_for_review'
          : vectorMemory.ok
            ? 'live'
            : 'stored_without_embedding',
      doc,
      post,
      vectorMemory,
      extraction: doc.metadata?.extraction || null,
    };
  },

