    if (request.method === 'GET' && pathname === '/api/communication-identities') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const payload = await getCachedReadResponse('communication-identities', BRIDGE_READ_CACHE_TTL_MS.communicationIdentities, async () => {
          const store = createConversationStore(pool);
          const [summary, items] = await Promise.all([
            store.getSenderIdentitySummary({
              workspaceId: CONVERSATION_WORKSPACE_ID,
            }),
            store.listSenderIdentities({
              workspaceId: CONVERSATION_WORKSPACE_ID,
              channel: url.searchParams.get('channel') || undefined,
              provider: url.searchParams.get('provider') || undefined,
              lifecycleStatus:
                url.searchParams.get('lifecycle') ||
                url.searchParams.get('lifecycleStatus') ||
                undefined,
            }),
          ]);
          return {
            ok: true,
            result: 'postgres',
            summary,
            items,
          };
        }, url.searchParams.toString());
        json(response, 200, payload);
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to list communication identities.'
        );
      }
      return;
    }

    if (
      request.method === 'POST' &&
      pathname === '/api/communication-identities/sync'
    ) {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        parseCommunicationIdentitySyncBody(await readBody(request));
        const store = createConversationStore(pool);
        const providerResults = await Promise.allSettled([
          getTelnyxNumberOptions(),
          getInstantlySenderOptions(),
        ]);
        const providerSync = {};
        const synced = [];
        const providers = [
          {
            name: 'telnyx',
            settlement: providerResults[0],
            recordsKey: 'numbers',
            normalize: normalizeTelnyxSenderIdentity,
            defaultKey: 'defaultNumber',
          },
          {
            name: 'instantly',
            settlement: providerResults[1],
            recordsKey: 'senders',
            normalize: normalizeInstantlySenderIdentity,
            defaultKey: 'defaultEmail',
          },
        ];

        for (const provider of providers) {
          if (provider.settlement.status === 'rejected') {
            providerSync[provider.name] = {
              ok: false,
              result: 'provider_error',
              error:
                provider.settlement.reason?.message ||
                `${provider.name} sender inventory failed.`,
              received: 0,
              valid: 0,
              synced: 0,
            };
            continue;
          }

          const providerResult = provider.settlement.value || {};
          const records = Array.isArray(providerResult[provider.recordsKey])
            ? providerResult[provider.recordsKey]
            : [];
          if (providerResult.ok !== true) {
            providerSync[provider.name] = {
              ok: false,
              result: providerResult.result || 'provider_error',
              error:
                providerResult.error ||
                providerResult.verbiage ||
                `${provider.name} sender inventory failed.`,
              received: records.length,
              valid: 0,
              synced: 0,
              fallbackAvailable: records.length,
            };
            continue;
          }
          const identities = records
            .map((record) =>
              provider.normalize(record, providerResult[provider.defaultKey] || '')
            )
            .filter(Boolean);
          let syncedCount = 0;
          for (const identity of identities) {
            const stored = await store.syncSenderIdentity({
              ...identity,
              workspaceId: CONVERSATION_WORKSPACE_ID,
            });
            if (stored) {
              synced.push(stored);
              syncedCount += 1;
            }
          }
          providerSync[provider.name] = {
            ok: providerResult.ok !== false,
            result:
              providerResult.result ||
              (providerResult.ok === false ? 'provider_error' : 'live'),
            error:
              providerResult.ok === false
                ? providerResult.error || providerResult.verbiage || ''
                : '',
            received: records.length,
            valid: identities.length,
            synced: syncedCount,
          };
        }

        json(response, 200, {
          ok: true,
          result: 'postgres',
          providers: providerSync,
          synced,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to sync communication identities.'
        );
      }
      return;
    }

    const communicationIdentityReleaseRequestMatch = matchPath(
      pathname,
      '/api/communication-identities/:identityId/release-request'
    );
    const communicationIdentityReleaseMatch = matchPath(
      pathname,
      '/api/communication-identities/:identityId/release'
    );
    const communicationIdentityMatch = matchPath(
      pathname,
      '/api/communication-identities/:identityId'
    );

    if (communicationIdentityMatch && request.method === 'PATCH') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const identityId = decodeCommunicationIdentityPathId(
          communicationIdentityMatch.groups.identityId
        );
        const requested = parseCommunicationIdentityPatchBody(await readBody(request));
        const store = createConversationStore(pool);
        const identity = await store.getSenderIdentity(identityId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!identity) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Communication identity not found.',
          });
          return;
        }
        if (['released', 'release_pending'].includes(identity.lifecycleStatus)) {
          throw Object.assign(
            new Error(
              `Communication identity in ${identity.lifecycleStatus} cannot be changed by lifecycle PATCH.`
            ),
            { statusCode: 409 }
          );
        }

        const changedAt = isoNow();
        const patch = {
          lifecycleStatus: requested.lifecycleStatus,
          metadata: buildCommunicationIdentityLifecycleMetadata(
            identity,
            requested.lifecycleStatus,
            requested.reason,
            changedAt
          ),
        };
        if (requested.lifecycleStatus === 'retired') {
          patch.retiredAt = changedAt;
          patch.inboundGraceUntil = new Date(
            Date.parse(changedAt) +
              COMMUNICATION_IDENTITY_INBOUND_GRACE_DAYS * 24 * 60 * 60 * 1000
          ).toISOString();
        }
        const updatedIdentity = await store.patchSenderIdentity(identityId, patch, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        json(response, updatedIdentity ? 200 : 404, {
          ok: Boolean(updatedIdentity),
          result: 'postgres',
          identity: updatedIdentity,
          error: updatedIdentity ? undefined : 'Communication identity not found.',
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to update the communication identity.'
        );
      }
      return;
    }

    if (communicationIdentityReleaseRequestMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const identityId = decodeCommunicationIdentityPathId(
          communicationIdentityReleaseRequestMatch.groups.identityId
        );
        const { reason } = parseCommunicationIdentityReleaseRequestBody(
          await readBody(request)
        );
        const store = createConversationStore(pool);
        const approvalId = randomUUID();
        const changedAt = isoNow();
        const reservation = await store.reserveSenderIdentityRelease(identityId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
          approvalId,
          reason,
          changedAt,
        });
        const identity = reservation.identity;
        if (!identity) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Communication identity not found.',
          });
          return;
        }
        if (!reservation.reserved) {
          const existingApproval = state.approvals.find(
            (item) =>
              item.id === reservation.existingApprovalId &&
              String(item.status || '').toLowerCase() === 'pending'
          );
          if (existingApproval) {
            json(response, 202, {
              ok: true,
              result: 'queued_for_approval',
              approval: existingApproval,
              identity,
              replayed: true,
            });
            return;
          }
          json(response, 409, {
            ok: false,
            result: 'release_already_pending',
            existingApprovalId: reservation.existingApprovalId,
            error: 'Communication identity already has a pending release reservation.',
          });
          return;
        }

        let approvalResult;
        try {
          approvalResult = await toolHandlers.createApproval({
            id: approvalId,
            type: 'provider_identity_release',
            approvalAction: 'release_communication_identity',
            provider: identity.provider,
            address: identity.address,
            payload: {
              identityId,
              provider: identity.provider,
              address: identity.address,
            },
            notes: reason,
            metadata: {
              identityId,
              provider: identity.provider,
              address: identity.address,
              reason,
            },
          });
          if (!approvalResult?.approval) {
            throw new Error('Communication identity release approval was not created.');
          }
        } catch (error) {
          const cancellation = store.cancelSenderIdentityReleaseReservation(identityId, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
            approvalId,
            changedAt: isoNow(),
          });
          await cancellation.catch(() => {});
          throw error;
        }
        const approval = approvalResult.approval;
        json(response, 202, {
          ok: true,
          result: 'queued_for_approval',
          approval,
          identity,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to request communication identity release.'
        );
      }
      return;
    }

    if (communicationIdentityReleaseMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const identityId = decodeCommunicationIdentityPathId(
          communicationIdentityReleaseMatch.groups.identityId
        );
        const { approvalId } = parseCommunicationIdentityReleaseBody(
          await readBody(request)
        );
        const store = createConversationStore(pool);
        const identity = await store.getSenderIdentity(identityId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!identity) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Communication identity not found.',
          });
          return;
        }
        if (identity.lifecycleStatus !== 'release_pending') {
          json(response, 409, {
            ok: false,
            result: 'release_not_pending',
            error: 'Communication identity is not pending provider release.',
          });
          return;
        }

        const approval = state.approvals.find((item) => item.id === approvalId);
        if (!approval) {
          json(response, 404, {
            ok: false,
            result: 'approval_not_found',
            error: 'Communication identity release approval was not found.',
          });
          return;
        }
        const approvalMatches =
          identity.metadata?.releaseApprovalId === approvalId &&
          String(approval.status || '').toLowerCase() === 'approved' &&
          String(approval.type || '').toLowerCase() === 'provider_identity_release' &&
          String(approval.approvalAction || '').toLowerCase() ===
            'release_communication_identity' &&
          approval.payload?.identityId === identityId &&
          approval.payload?.provider === identity.provider &&
          approval.payload?.address === identity.address;
        if (!approvalMatches) {
          json(response, 403, {
            ok: false,
            result: 'approval_mismatch',
            error: 'Approved release payload does not match this communication identity.',
          });
          return;
        }

        json(response, 501, {
          ok: false,
          result: 'provider_release_not_configured',
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to release the communication identity.'
        );
      }
      return;
    }

    if (request.method === 'POST' && pathname === '/api/conversations/resolve') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const { leadId } = parseConversationResolveBody(await readBody(request));
        const lead = await loadConversationLeadForResolve(pool, leadId);
        if (!lead) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Lead not found.',
          });
          return;
        }
        const store = createConversationStore(pool);
        const thread = await store.resolveThread({
          workspaceId: CONVERSATION_WORKSPACE_ID,
          leadId: lead.id,
          phone: lead.phone || '',
          email: lead.email || '',
          title: lead.lead_name || lead.address || 'Seller conversation',
          source: 'unified-inbox-compose',
          metadata: {
            openedBy: getConversationRequestActor(request),
            openedFrom: 'unified-inbox',
          },
        });
        const [leadSummary, senderSummary, recipientSummary] = await Promise.all([
          buildConversationLeadSummary(pool, thread),
          buildConversationSenderSummary(store, thread),
          store.getThreadContactIdentities(thread.id, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
          }),
        ]);
        json(response, 200, {
          ok: true,
          result: 'postgres',
          thread,
          leadSummary,
          senderSummary,
          recipientSummary,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to open the seller conversation.'
        );
      }
      return;
    }

    if (request.method === 'GET' && pathname === '/api/conversations') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const store = createConversationStore(pool);
        const filters = {
          workspaceId: CONVERSATION_WORKSPACE_ID,
          cursor: url.searchParams.get('cursor') || undefined,
          search: url.searchParams.get('search') || undefined,
          unread: parseConversationBooleanQuery(url.searchParams, 'unread'),
          pinned: parseConversationBooleanQuery(url.searchParams, 'pinned'),
          archived: parseConversationBooleanQuery(url.searchParams, 'archived'),
          channel: url.searchParams.get('channel') || undefined,
          activity: url.searchParams.get('activity') || undefined,
          status: url.searchParams.get('status') || url.searchParams.get('stage') || undefined,
          assignedAgent: url.searchParams.get('assignedAgent') || undefined,
          leadId: url.searchParams.get('leadId') || undefined,
          limit: url.searchParams.get('limit') || undefined,
        };
        const page = await store.listThreads(filters);
        json(response, 200, {
          ok: true,
          result: 'postgres',
          ...page,
        });
      } catch (error) {
        sendConversationStoreError(response, error, 'Unable to list unified conversations.');
      }
      return;
    }

    if (
      request.method === 'POST' &&
      pathname === '/api/conversations/messages/run-due'
    ) {
      try {
        const parsed = parseConversationRunDueBody(await readBody(request));
        const result = await runDueConversationMessages(parsed);
        json(
          response,
          result.result === 'postgres_unavailable'
            ? 503
            : result.ok
              ? 200
              : 207,
          result
        );
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to run due conversation messages.'
        );
      }
      return;
    }

    const conversationSenderRecommendationMatch = matchPath(
      pathname,
      '/api/conversations/:threadId/sender-recommendation'
    );
    if (conversationSenderRecommendationMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(
          conversationSenderRecommendationMatch.groups.threadId
        );
        const { channel } = parseConversationSenderRecommendationBody(
          await readBody(request)
        );
        const store = createConversationStore(pool);
        const thread = await store.getThread(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!thread) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation thread not found.',
          });
          return;
        }
        const [identities, previousSenderIdentityId, recipientContext] =
          await Promise.all([
            store.listSenderIdentities({
              workspaceId: CONVERSATION_WORKSPACE_ID,
              channel,
              limit: 100,
            }),
            store.getPreviousSuccessfulSenderIdentityId(threadId, channel, {
              workspaceId: CONVERSATION_WORKSPACE_ID,
            }),
            buildConversationRecipientContext(store, pool, thread),
          ]);
        const dnc = getConversationDncStatus(recipientContext);
        const compliance = evaluateConversationSenderRecommendationCompliance({
          channel,
          dncBlocked: dnc.blocked,
          consentStatus: getConversationConsentStatus(
            recipientContext.runtimeLead
          ),
        });
        if (!compliance.allowed) {
          json(response, 200, {
            ok: true,
            result: 'postgres',
            recommended: null,
            alternatives: [],
            reasonCodes: compliance.reasonCodes,
          });
          return;
        }
        const ranked = rankEligibleSenderIdentities(identities, {
          previousSenderIdentityId,
          leadRegion: recipientContext.leadRegion,
        });
        const publicRanked = ranked.map((identity) => ({
          ...mapPublicConversationSenderIdentity(identity),
          reasonCodes: identity.reasonCodes || [],
        }));
        const recommended = publicRanked[0] || null;
        const reasonCodes = [
          ...new Set([
            ...(compliance.reasonCodes || []),
            ...(recommended?.reasonCodes || []),
          ]),
        ];
        json(response, 200, {
          ok: true,
          result: 'postgres',
          recommended,
          alternatives: publicRanked.slice(1),
          reasonCodes: reasonCodes.length ? reasonCodes : ['no_eligible_sender'],
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to recommend a conversation sender.'
        );
      }
      return;
    }

    const conversationMessagesMatch = matchPath(
      pathname,
      '/api/conversations/:threadId/messages'
    );
    if (conversationMessagesMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(
          conversationMessagesMatch.groups.threadId
        );
        const parsed = parseConversationSendBody(await readBody(request));
        const store = createConversationStore(pool);
        const thread = await store.getThread(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!thread) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation thread not found.',
          });
          return;
        }
        const [senderIdentity, recipientContext] = await Promise.all([
          store.getSenderIdentity(parsed.senderIdentityId, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
          }),
          buildConversationRecipientContext(store, pool, thread),
        ]);
        if (!senderIdentity) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Communication identity not found.',
          });
          return;
        }
        if (senderIdentity.channel !== parsed.channel) {
          json(response, 400, {
            ok: false,
            result: 'invalid_sender_channel',
            error: 'Selected sender identity does not match the requested channel.',
          });
          return;
        }
        if (!rankEligibleSenderIdentities([senderIdentity]).length) {
          json(response, 409, {
            ok: false,
            result: 'sender_ineligible',
            error: 'Selected sender identity is not currently eligible.',
          });
          return;
        }
        const recipient =
          parsed.channel === 'sms' ? recipientContext.phone : recipientContext.email;
        if (!recipient) {
          json(response, 409, {
            ok: false,
            result: 'recipient_unavailable',
            error:
              parsed.channel === 'sms'
                ? 'The canonical conversation has no destination phone number.'
                : 'The canonical conversation has no destination email address.',
          });
          return;
        }

        const requestId = randomUUID();
        const actor = parsed.actor || getConversationRequestActor(request);
        const dnc = getConversationDncStatus(recipientContext);
        if (dnc.blocked) {
          const providerResult = {
            ok: false,
            blocked: true,
            dnc: dnc.entry || { status: dnc.status || 'dnc' },
            result: 'dnc_blocked',
            reason: dnc.entry?.reason || 'The lead is marked do not contact.',
          };
          const event = await projectConversationSendOutcome(store, {
            thread,
            requestId,
            channel: parsed.channel,
            senderIdentity,
            recipient,
            body: parsed.body,
            subject: parsed.subject,
            status: 'dnc_blocked',
            result: providerResult,
            scheduledFor: parsed.scheduledFor,
            actor,
            reason: providerResult.reason,
            source: parsed.source,
            manual: parsed.manual,
            manualSend: parsed.manualSend,
            requestedBy: parsed.requestedBy,
          });
          json(response, 409, {
            ok: false,
            result: 'dnc_blocked',
            error: providerResult.reason,
            event,
          });
          return;
        }

        const consentStatus = getConversationConsentStatus(
          recipientContext.runtimeLead
        );
        const sendCompliance = evaluateConversationSenderRecommendationCompliance({
          channel: parsed.channel,
          dncBlocked: false,
          consentStatus,
        });
        const manualOneToOneSend = parsed.manual === true && parsed.manualSend === true;
        const reviewableSmsConsent = (sendCompliance.reasonCodes || []).includes('approval_required');
        if (!sendCompliance.allowed) {
          const reason = `SMS consent is ${consentStatus.replace(/_/g, ' ')}. Update the lead compliance record before messaging.`;
          const providerResult = {
            ok: false,
            blocked: true,
            result: 'sms_consent_blocked',
            reason,
            reasonCodes: sendCompliance.reasonCodes,
          };
          const event = await projectConversationSendOutcome(store, {
            thread,
            requestId,
            channel: parsed.channel,
            senderIdentity,
            recipient,
            body: parsed.body,
            subject: parsed.subject,
            status: 'blocked',
            result: providerResult,
            scheduledFor: parsed.scheduledFor,
            actor,
            reason,
            source: parsed.source,
            manual: parsed.manual,
            manualSend: parsed.manualSend,
            requestedBy: parsed.requestedBy,
          });
          json(response, 409, {
            ...providerResult,
            event,
          });
          return;
        }

        const conversationSendBinding = buildConversationSendBinding({
          workspaceId: CONVERSATION_WORKSPACE_ID,
          threadId: thread.id,
          channel: parsed.channel,
          senderIdentityId: senderIdentity.id,
          senderAddress: senderIdentity.address,
          recipient,
          subject: parsed.subject,
          body: parsed.body,
          requestId,
        });
        const providerParams = {
          leadId: thread.leadId || '',
          leadName: recipientContext.leadName,
          address: recipientContext.address,
          body: parsed.body,
          message: parsed.body,
          subject: parsed.subject,
          actor,
          requestedBy: parsed.requestedBy || actor,
          source: parsed.source || (parsed.manualSend ? 'unified_conversation_manual' : 'unified_conversation'),
          manual: parsed.manual,
          manualSend: parsed.manualSend,
          senderIdentityId: senderIdentity.id,
          metadata: {
            conversationSendBinding,
            source: parsed.source || (parsed.manualSend ? 'unified_conversation_manual' : 'unified_conversation'),
            manual: parsed.manual,
            manualSend: parsed.manualSend,
            manualOneToOneSend,
            leadConsentStatus: consentStatus,
          },
          ...(parsed.channel === 'sms'
            ? {
                phone: recipient,
                to: recipient,
                from: senderIdentity.address,
                fromNumber: senderIdentity.address,
                consentStatus,
              }
            : {
                email: recipient,
                to: recipient,
                fromEmail: senderIdentity.address,
                senderEmail: senderIdentity.address,
                customBody: parsed.body,
                templateId: 'custom',
                allowResendFallback: false,
                requireSelectedProvider: true,
              }),
        };

        if (
          parsed.channel === 'sms' &&
          reviewableSmsConsent &&
          !manualOneToOneSend
        ) {
          const guarded = await enforceOperatingModeForTool('telnyx_sms', {
            ...providerParams,
            forceApproval: true,
          });
          if (guarded) {
            let event = await projectConversationSendOutcome(store, {
              thread,
              requestId,
              channel: parsed.channel,
              senderIdentity,
              recipient,
              body: parsed.body,
              subject: parsed.subject,
              status:
                guarded.ok === false ? 'blocked' : 'approval_required',
              result: guarded,
              scheduledFor: parsed.scheduledFor,
              actor,
              source: parsed.source,
              manual: parsed.manual,
              manualSend: parsed.manualSend,
              requestedBy: parsed.requestedBy,
            });
            event = await bindConversationApprovalToEvent(store, {
              providerResult: guarded,
              event,
              conversationSendBinding,
            });
            json(response, guarded.ok === false ? 409 : 202, {
              ...guarded,
              event,
            });
            return;
          }
        }

        if (parsed.scheduledFor) {
          const message = createMessageRecord({
            id: `conversation-scheduled-${requestId}`,
            leadId: thread.leadId || '',
            leadProfileId: thread.leadId || null,
            workspaceId: CONVERSATION_WORKSPACE_ID,
            leadName: recipientContext.leadName,
            address: recipientContext.address,
            channel: parsed.channel,
            direction: 'outbound',
            body: parsed.body,
            subject: parsed.subject,
            status: 'scheduled',
            provider: 'PBK Scheduler',
            senderIdentityId: senderIdentity.id,
            ...(parsed.channel === 'sms'
              ? {
                  phone: recipient,
                  from: senderIdentity.address,
                  fromPhone: senderIdentity.address,
                  toPhone: recipient,
                }
              : {
                  email: recipient,
                  fromEmail: senderIdentity.address,
                  toEmail: recipient,
                }),
            payload: {
              scheduled: true,
              scheduledFor: parsed.scheduledFor,
              senderIdentityId: senderIdentity.id,
              senderAddress: senderIdentity.address,
              recipient,
              requestId,
              actor,
              conversationThreadId: thread.id,
              conversationSendBinding,
              requestedFrom: parsed.source || 'unified-conversation',
              manual: parsed.manual,
              manualSend: parsed.manualSend,
              source: parsed.source,
              requestedBy: parsed.requestedBy,
            },
          });
          message.scheduledFor = parsed.scheduledFor;
          message.sendAt = parsed.scheduledFor;
          message.senderIdentityId = senderIdentity.id;
          upsertMessage(state, message);
          const persisted = await persistUnifiedMessageRecord(message);
          await persistState(state);
          if (!persisted) {
            const failedResult = {
              ok: false,
              result: 'schedule_persistence_failed',
              error: 'Unable to persist the scheduled message.',
            };
            const event = await projectConversationSendOutcome(store, {
              thread,
              requestId,
              channel: parsed.channel,
              senderIdentity,
              recipient,
              body: parsed.body,
              subject: parsed.subject,
              status: 'failed',
              result: failedResult,
              scheduledFor: parsed.scheduledFor,
              actor,
              source: parsed.source,
              manual: parsed.manual,
              manualSend: parsed.manualSend,
              requestedBy: parsed.requestedBy,
            });
            json(response, 503, { ...failedResult, event });
            return;
          }
          const scheduledResult = {
            ok: true,
            result: 'scheduled',
            scheduled: true,
            scheduledFor: parsed.scheduledFor,
            message,
          };
          const event = await projectConversationSendOutcome(store, {
            thread,
            requestId,
            channel: parsed.channel,
            senderIdentity,
            recipient,
            body: parsed.body,
            subject: parsed.subject,
            status: 'scheduled',
            result: scheduledResult,
            scheduledFor: parsed.scheduledFor,
            sourceTable: 'unified_messages',
            sourceId: message.id,
            actor,
            source: parsed.source,
            manual: parsed.manual,
            manualSend: parsed.manualSend,
            requestedBy: parsed.requestedBy,
          });
          message.payload = {
            ...(message.payload || {}),
            conversationEventId: event.id,
          };
          await persistUnifiedMessageRecord(message);
          json(response, 202, {
            ...scheduledResult,
            providerDeliveryClaimed: false,
            event,
          });
          return;
        }

        const send = await executeManualProviderRouteWithOutbox({
          toolName: parsed.channel === 'sms' ? 'telnyx_sms' : 'sendColdEmail',
          provider: parsed.channel === 'sms' ? 'telnyx' : 'instantly',
          channel: parsed.channel,
          params:
            parsed.channel === 'sms'
              ? {
                  ...providerParams,
                  from: senderIdentity.address,
                  fromNumber: senderIdentity.address,
                }
              : {
                  ...providerParams,
                  fromEmail: senderIdentity.address,
                  senderEmail: senderIdentity.address,
                  requireSelectedProvider: true,
                },
          source: 'unified-conversation-send',
          leadId: thread.leadId || '',
          recipient,
          messageBody: parsed.body,
          subject: parsed.subject,
          requestedBy: parsed.requestedBy || actor,
        });
        const providerResult = send.response || {};
        const qaValidation = providerResult.qaValidation || providerResult.qa || null;
        const safetyValidation = providerResult.safetyValidation || providerResult.safety || null;
        const classification = classifyConversationSendResult(
          parsed.channel,
          providerResult
        );
        let event = await projectConversationSendOutcome(store, {
          thread,
          requestId,
          channel: parsed.channel,
          senderIdentity,
          recipient,
          body: parsed.body,
          subject: parsed.subject,
          status: classification.status,
          result: providerResult,
          actor,
          source: parsed.source,
          manual: parsed.manual,
          manualSend: parsed.manualSend,
          requestedBy: parsed.requestedBy,
        });
        if (classification.status === 'approval_required') {
          event = await bindConversationApprovalToEvent(store, {
            providerResult,
            event,
            conversationSendBinding,
          });
        }
        json(response, classification.httpStatus, {
          ok: classification.ok,
          result: classification.result,
          approval: providerResult?.approval || null,
          providerResult,
          qaValidation,
          safetyValidation,
          outbox: send.outbox,
          idempotencyKey: send.idempotencyKey,
          retryable: send.outbox?.retryable === true,
          event,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to send the conversation message.'
        );
      }
      return;
    }

    const conversationRefineDraftMatch = matchPath(
      pathname,
      '/api/conversations/:threadId/refine-draft'
    );
    if (conversationRefineDraftMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(
          conversationRefineDraftMatch.groups.threadId
        );
        const parsed = parseConversationRefineDraftBody(await readBody(request));
        const store = createConversationStore(pool);
        const thread = await store.getThread(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!thread) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation thread not found.',
          });
          return;
        }
        const [recipientContext, timeline] = await Promise.all([
          buildConversationRecipientContext(store, pool, thread),
          store.listTimeline(threadId, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
            limit: 12,
            includeHidden: false,
          }),
        ]);
        const visibleEvents = timeline.items.slice(0, 12).map((event) => ({
          eventType: event.eventType,
          channel: event.channel,
          direction: event.direction,
          subject: event.subject,
          body: event.body,
          status: event.status,
          occurredAt: event.occurredAt,
        }));
        const firstName =
          String(recipientContext.leadName || '').trim().split(/\s+/)[0] || '';
        const instruction =
          "You are Ava, PBK's sales assistant. Rewrite only the operator's draft. " +
          'Preserve factual claims, numbers, consent boundaries, and requested channel. ' +
          'Improve grammar, warmth, clarity, and persuasion without inventing promises. ' +
          'Return only the revised draft.';
        const strategist = await askStrategistRecord({
          agentName: 'Ava',
          leadId: thread.leadId || '',
          firstName,
          address: recipientContext.address,
          responseFormat: 'text',
          temperature: 0.2,
          maxTokens: 500,
          storeRule: false,
          source: 'unified-conversation-refine-draft',
          textOnlyInstruction: instruction,
          situation: [
            instruction,
            `Channel: ${parsed.channel}`,
            parsed.subject ? `Subject: ${parsed.subject}` : '',
            `Lead: ${JSON.stringify({ firstName, address: recipientContext.address })}`,
            `Latest visible events: ${JSON.stringify(visibleEvents)}`,
            `Operator draft: ${parsed.draft}`,
          ]
            .filter(Boolean)
            .join('\n'),
        });
        const rawAnswer = String(
          strategist?.request?.metadata?.rawAnswer ||
            strategist?.rawAnswer ||
            ''
        ).trim();
        const degraded =
          !rawAnswer || String(strategist?.result || '').toLowerCase() === 'local_fallback';
        json(response, degraded ? 503 : 200, {
          ok: !degraded,
          result: degraded ? 'strategist_unavailable' : strategist.result || 'live',
          degraded,
          rawDraft: parsed.draft,
          refinedDraft: degraded ? parsed.draft : rawAnswer,
          provider: strategist?.provider || null,
          contextEventCount: visibleEvents.length,
          sent: false,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to refine the conversation draft.'
        );
      }
      return;
    }

    const conversationEventRestoreMatch = matchPath(
      pathname,
      '/api/conversation-events/:eventId/restore'
    );
    if (conversationEventRestoreMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const eventId = decodeConversationPathId(
          conversationEventRestoreMatch.groups.eventId
        );
        parseConversationRestoreBody(await readBody(request));
        const store = createConversationStore(pool);
        const current = await store.getEvent(eventId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!current) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation event not found.',
          });
          return;
        }
        const event = await store.patchEvent(
          eventId,
          { hiddenAt: null },
          { workspaceId: CONVERSATION_WORKSPACE_ID }
        );
        json(response, 200, {
          ok: true,
          result: 'restored',
          event,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to restore the conversation event.'
        );
      }
      return;
    }

    const conversationEventReportSpamMatch = matchPath(
      pathname,
      '/api/conversation-events/:eventId/report-spam'
    );
    if (conversationEventReportSpamMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const eventId = decodeConversationPathId(
          conversationEventReportSpamMatch.groups.eventId
        );
        const parsed = parseConversationReportSpamBody(await readBody(request));
        const store = createConversationStore(pool);
        const current = await store.getEvent(eventId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!current) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation event not found.',
          });
          return;
        }
        const report = await store.reportEventSpam(eventId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
          reportedAt: isoNow(),
        });
        const explicitOptOut = isExplicitConversationOptOut(
          current,
          parsed.explicitOptOut
        );
        let dnc = null;
        if (explicitOptOut) {
          const contacts = await store.getThreadContactIdentities(current.threadId, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
          });
          if (contacts.phone) {
            dnc = await handleEvent('dnc-add', {
              phone: contacts.phone,
              reason:
                parsed.reason ||
                `Explicit opt-out recorded from conversation event ${eventId}.`,
              source: 'conversation-spam-report',
              actor: parsed.actor || getConversationRequestActor(request),
            });
          }
        }
        json(response, 200, {
          ok: true,
          result: 'spam_reported',
          ...report,
          explicitOptOut,
          dncCreated: Boolean(dnc?.ok),
          dnc: dnc?.entry || null,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to report the conversation event.'
        );
      }
      return;
    }

    const conversationEventMatch = matchPath(
      pathname,
      '/api/conversation-events/:eventId'
    );
    if (conversationEventMatch && request.method === 'PATCH') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const eventId = decodeConversationPathId(
          conversationEventMatch.groups.eventId
        );
        const patch = parseConversationEventPatchBody(await readBody(request));
        const store = createConversationStore(pool);
        const current = await store.getEvent(eventId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!current) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation event not found.',
          });
          return;
        }
        const event = await store.patchEvent(eventId, patch, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        json(response, 200, {
          ok: true,
          result: 'updated',
          event,
        });
      } catch (error) {
        sendConversationStoreError(
          response,
          error,
          'Unable to update the conversation event.'
        );
      }
      return;
    }

    const conversationTimelineMatch = matchPath(pathname, '/api/conversations/:threadId/timeline');
    if (conversationTimelineMatch && request.method === 'GET') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(conversationTimelineMatch.groups.threadId);
        const store = createConversationStore(pool);
        const thread = await store.getThread(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!thread) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation thread not found.',
          });
          return;
        }
        const page = await store.listTimeline(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
          cursor: url.searchParams.get('cursor') || undefined,
          limit: url.searchParams.get('limit') || undefined,
          includeHidden: parseConversationBooleanQuery(url.searchParams, 'includeHidden'),
        });
        json(response, 200, {
          ok: true,
          result: 'postgres',
          ...page,
        });
      } catch (error) {
        sendConversationStoreError(response, error, 'Unable to load the conversation timeline.');
      }
      return;
    }

    const conversationMergeMatch = matchPath(pathname, '/api/conversations/:threadId/merge');
    if (conversationMergeMatch && request.method === 'POST') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(conversationMergeMatch.groups.threadId);
        const body = await readBody(request);
        const { canonicalThreadId, mergedThreadId } = parseConversationMergeBody(body, threadId);
        const actor = getConversationRequestActor(request);
        const store = createConversationStore(pool);
        const thread = await store.mergeThreads({
          workspaceId: CONVERSATION_WORKSPACE_ID,
          canonicalThreadId,
          mergedThreadId,
          actor,
        });
        json(response, 200, {
          ok: true,
          result: 'postgres',
          thread,
        });
      } catch (error) {
        sendConversationStoreError(response, error, 'Unable to merge conversation threads.');
      }
      return;
    }

    const conversationThreadMatch = matchPath(pathname, '/api/conversations/:threadId');
    if (conversationThreadMatch && request.method === 'GET') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(conversationThreadMatch.groups.threadId);
        const store = createConversationStore(pool);
        const thread = await store.getThread(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!thread) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            thread: null,
            leadSummary: null,
            senderSummary: null,
            recipientSummary: null,
            error: 'Conversation thread not found.',
          });
          return;
        }
        const [leadSummary, senderSummary, recipientSummary] = await Promise.all([
          buildConversationLeadSummary(pool, thread),
          buildConversationSenderSummary(store, thread),
          store.getThreadContactIdentities(thread.id, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
          }),
        ]);
        json(response, 200, {
          ok: true,
          result: 'postgres',
          thread,
          leadSummary,
          senderSummary,
          recipientSummary,
        });
      } catch (error) {
        sendConversationStoreError(response, error, 'Unable to load the conversation thread.');
      }
      return;
    }

    if (conversationThreadMatch && request.method === 'PATCH') {
      const pool = getPgPool();
      if (!pool) {
        sendConversationPostgresUnavailable(response);
        return;
      }
      try {
        const threadId = decodeConversationPathId(conversationThreadMatch.groups.threadId);
        const body = await readBody(request);
        const store = createConversationStore(pool);
        const currentThread = await store.getThread(threadId, {
          workspaceId: CONVERSATION_WORKSPACE_ID,
        });
        if (!currentThread) {
          json(response, 404, {
            ok: false,
            result: 'postgres',
            error: 'Conversation thread not found.',
          });
          return;
        }
        const patch = buildConversationThreadPatch(body, currentThread);
        let thread = currentThread;
        if (body.read === true) {
          thread = await store.markThreadRead(threadId, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
          });
          delete patch.unreadCount;
        }
        if (Object.keys(patch).length) {
          thread = await store.patchThread(threadId, patch, {
            workspaceId: CONVERSATION_WORKSPACE_ID,
          });
        }
        json(response, thread ? 200 : 404, {
          ok: Boolean(thread),
          result: 'postgres',
          thread,
          error: thread ? undefined : 'Conversation thread not found.',
        });
      } catch (error) {
        sendConversationStoreError(response, error, 'Unable to update the conversation thread.');
      }
      return;
    }

    if (request.method === 'GET' && pathname === '/api/campaigns/lead-sources') {
      json(response, 200, {
        ok: true,
        result: 'live',
        sources: getCampaignLeadSourceOptions(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/campaigns/templates/ranked') {
      json(response, 200, buildRankedCampaignTemplates({
        channel: url.searchParams.get('channel') || 'email',
        leadSource: url.searchParams.get('leadSource') || url.searchParams.get('lead_source') || 'all-imports',
        campaignId: url.searchParams.get('campaignId') || url.searchParams.get('campaign_id') || '',
        limit: url.searchParams.get('limit') || 8,
      }));
      return;
    }

    if (request.method === 'GET' && pathname === '/api/campaigns') {
      const campaigns = queryCampaignRecords(url.searchParams);
      const generatedAt = isoNow();
      const provenance = getRuntimeStateProvenance();
      json(response, 200, {
        ok: true,
        result: provenance.fallbackReason ? 'fallback' : 'live',
        source: provenance.source,
        fallbackReason: provenance.fallbackReason,
        provenance,
        generatedAt,
        summary: {
          dataState: campaigns.length ? 'populated' : 'empty',
          campaigns: campaigns.length,
          leads: (state.campaignLeads || []).length,
          events: (state.campaignEvents || []).length,
        },
        campaigns,
        leads: state.campaignLeads || [],
        events: state.campaignEvents || [],
        sources: getCampaignLeadSourceOptions(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/campaigns') {
      const body = await readBody(request);
      const result = await createCampaignRecord(body);
      json(response, result.ok ? 201 : 400, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/campaigns/executions') {
      json(response, 200, {
        ok: true,
        result: 'live',
        executions: sortNewest(state.campaignExecutions || []),
        state: buildStateSnapshot(),
      });
      return;
    }

    const campaignApprovalMatch = matchPath(pathname, '/api/campaigns/:campaignId/approval');
    if (campaignApprovalMatch && request.method === 'POST') {
      const body = await readBody(request);
      const result = await requestCampaignApproval(decodeURIComponent(campaignApprovalMatch.groups.campaignId || ''), body);
      json(response, result.ok ? 202 : 404, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const campaignActionMatch = matchPath(pathname, '/api/campaigns/:campaignId/actions');
    if (campaignActionMatch && request.method === 'POST') {
      const body = await readBody(request);
      const result = await runCampaignAction(decodeURIComponent(campaignActionMatch.groups.campaignId || ''), body);
      json(response, result.ok ? 202 : 400, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const campaignScriptMatch = matchPath(pathname, '/api/campaigns/:campaignId/script');
    if (campaignScriptMatch && ['POST', 'PATCH'].includes(request.method)) {
      const body = await readBody(request);
      const result = await updateCampaignScript(decodeURIComponent(campaignScriptMatch.groups.campaignId || ''), body, {
        actor: request.headers['x-rex-agent'] ? 'Rex Strategist' : body.actor || 'PBK Command Center',
      });
      json(response, result.ok ? 200 : 400, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const campaignSequenceMatch = matchPath(pathname, '/api/campaigns/:campaignId/sequence');
    if (campaignSequenceMatch && ['POST', 'PATCH'].includes(request.method)) {
      const body = await readBody(request);
      const result = await updateCampaignSequence(decodeURIComponent(campaignSequenceMatch.groups.campaignId || ''), body, {
        actor: request.headers['x-rex-agent'] ? 'Rex Strategist' : body.actor || 'PBK Command Center',
      });
      json(response, result.ok ? 200 : 400, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const campaignEventsMatch = matchPath(pathname, '/api/campaigns/:campaignId/events');
    if (campaignEventsMatch && request.method === 'POST') {
      const body = await readBody(request);
      const campaignId = decodeURIComponent(campaignEventsMatch.groups.campaignId || '');
      const campaign = (state.campaigns || []).find((item) => item.id === campaignId);
      if (!campaign) {
        json(response, 404, {
          ok: false,
          result: 'unavailable',
          verbiage: 'Campaign not found',
          error: 'Cannot attach an event to a missing campaign.',
        });
        return;
      }
      const event = recordCampaignEvent({
        ...body,
        campaignId,
        channel: body.channel || campaign.channel,
        provider: body.provider || campaign.provider,
      });
      upsertById(state, 'campaigns', {
        ...campaign,
        metrics: calculateCampaignMetrics(campaign),
        updatedAt: isoNow(),
      });
      addActivity(
        state,
        makeActivity({
          actor: body.actor || body.provider || 'Campaign provider',
          category: 'CAMPAIGN',
          status: body.status || body.eventType || 'event',
          text: `Campaign "${campaign.name}" received event ${event.eventType}.`,
          target: campaignId,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        result: 'live',
        verbiage: 'Campaign event recorded',
        event,
        state: buildStateSnapshot(),
      });
      return;
    }

    const campaignRecordMatch = matchPath(pathname, '/api/campaigns/:campaignId');
    if (campaignRecordMatch && request.method === 'GET') {
      const campaignId = decodeURIComponent(campaignRecordMatch.groups.campaignId || '');
      const campaign = (state.campaigns || []).find((item) => item.id === campaignId);
      json(response, campaign ? 200 : 404, {
        ok: Boolean(campaign),
        result: campaign ? 'live' : 'unavailable',
        verbiage: campaign ? 'Campaign loaded' : 'Campaign not found',
        campaign: campaign
          ? {
              ...campaign,
              metrics: calculateCampaignMetrics(campaign),
              leadCount: getCampaignLeads(campaignId).length || campaign.leadCount || 0,
            }
          : null,
        leads: getCampaignLeads(campaignId),
        events: getCampaignEvents(campaignId),
        state: buildStateSnapshot(),
      });
      return;
    }

    if (campaignRecordMatch && request.method === 'PATCH') {
      const body = await readBody(request);
      const result = await patchCampaignRecord(decodeURIComponent(campaignRecordMatch.groups.campaignId || ''), body);
      json(response, result.ok ? 200 : 404, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/campaigns/run-due', '/api/workers/campaigns/run-due'])) {
      const body = await readBody(request);
      const result = await runCampaignScheduler({
        dryRun: body.dryRun,
        confirmProviderWrites: Boolean(body.confirmProviderWrites),
        limit: body.limit,
        actor: body.actor || 'Campaign worker',
      });
      json(response, 200, result);
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/campaigns/execute-approved', '/api/workers/campaigns/run'])) {
      const body = await readBody(request);
      const approvalId = String(body.approvalId || body.id || '').trim();
      const approval = approvalId ? state.approvals.find((item) => item.id === approvalId) : sortNewest(state.approvals || []).find((item) => String(item.type || '').toLowerCase() === 'campaign' && String(item.status || '').toLowerCase() === 'approved');
      if (!approval) {
        json(response, 404, {
          ok: false,
          result: 'unavailable',
          verbiage: 'Campaign execution unavailable - no approved campaign found',
          error: 'No approved campaign approval was found for execution.',
        });
        return;
      }
      const result = await executeApprovedCampaign(approval, {
        actor: body.actor || 'Campaign worker',
      });
      await persistState(state);
      json(response, result.ok ? 200 : 202, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/prompts/applications') {
      json(response, 200, {
        ok: true,
        result: 'live',
        applications: sortNewest(state.promptPatchApplications || []),
        settings: ensureRuntimeSettings(state).agentPrompts || {},
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/prompts/apply-approved', '/api/workers/prompts/apply'])) {
      const body = await readBody(request);
      const approvalId = String(body.approvalId || body.id || '').trim();
      const approval = approvalId ? state.approvals.find((item) => item.id === approvalId) : sortNewest(state.approvals || []).find((item) => String(item.status || '').toLowerCase() === 'approved' && (String(item.type || '').toLowerCase() === 'prompt-edit' || String(item.approvalAction || '').toLowerCase() === 'prompt_patch'));
      if (!approval) {
        json(response, 404, {
          ok: false,
          result: 'unavailable',
          verbiage: 'Prompt apply unavailable - no approved prompt edit found',
          error: 'No approved prompt edit was found for application.',
        });
        return;
      }
      const result = await applyApprovedPromptPatch(approval, {
        actor: body.actor || 'Prompt worker',
      });
      await persistState(state);
      json(response, result.ok ? 200 : 202, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/invoke', '/api/invoke'])) {
      const invokeRateLimit = await checkInvokeRateLimit(request);
      setRateLimitResponseHeaders(response, invokeRateLimit);
      if (!invokeRateLimit.ok) {
        incrementObservabilityCounter('invoke_rate_limit_rejections', 1, {
          source: invokeRateLimit.source,
        });
        json(response, 429, {
          ok: false,
          error: 'Bridge tool rate limit exceeded. Please retry shortly.',
          code: 'invoke_rate_limit_exceeded',
          retryAfterSeconds: invokeRateLimit.retryAfterSeconds,
        });
        return;
      }
      const body = await readBody(request);
      const toolName = body.toolName;
      const params = body.params || {};
      if (!toolHandlers[toolName]) {
        json(response, 404, {
          ok: false,
          error: `Unknown tool: ${toolName}`,
          tools: Object.keys(toolHandlers),
        });
        return;
      }

      const guarded = await enforceOperatingModeForTool(toolName, params);
      if (guarded) {
        json(response, 200, {
          ok: Boolean(guarded.ok),
          toolName,
          result: guarded,
          state: buildStateSnapshot(),
        });
        return;
      }

      const { result, qaValidation, safetyValidation } = await executeToolHandlerWithQa(toolName, params, 'bridge-invoke');
      json(response, 200, {
        ok: result?.ok !== false && qaValidation?.ok !== false && safetyValidation?.ok !== false,
        toolName,
        result,
        qa: qaValidation?.qa || null,
        safety: safetyValidation || null,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/events/bus/status', '/api/event-bus/status'])) {
      const status = await getEventBusStatus();
      recordEventBusBacklogMetric(status.backlog || status.streamLength || status.pendingMemoryEvents || 0, {
        streamName: status.streamName || '',
        mode: status.mode || '',
      });
      json(response, 200, status);
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/observability/status', '/api/v1/observability/status'])) {
      const eventBus = await getEventBusStatus();
      recordEventBusBacklogMetric(eventBus.backlog || eventBus.streamLength || eventBus.pendingMemoryEvents || 0, {
        streamName: eventBus.streamName || '',
        mode: eventBus.mode || '',
      });
      json(response, 200, {
        ...getPbkObservabilityStatus(),
        eventBus,
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/events/bus/publish-test', '/api/event-bus/publish-test'])) {
      const body = await readBody(request);
      const result = await publishPbkEvent(
        body.type || 'debug.test',
        {
          message: body.message || 'PBK event bus test',
          requestedBy: body.requestedBy || body.actor || 'operator',
          createdAt: isoNow(),
        },
        body.source || 'debug-api'
      );
      json(response, result.ok ? 200 : 202, result);
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/events', '/api/events'])) {
      const body = await readBody(request);
      const eventType = body.eventType || body.type || body.event || '';
      const payload = body.payload || body.data || body;

      if (!eventType) {
        json(response, 400, {
          ok: false,
          error: 'eventType is required',
        });
        return;
      }

      const result = await handleEvent(eventType, payload);
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/admin/tasks') {
      json(response, 200, {
        ok: true,
        adminTasks: state.adminTasks,
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/admin/audit') {
      json(response, 200, {
        ok: true,
        adminAudit: state.adminAudit,
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/admin/tool-usage') {
      const result = await getPbkToolUsageSummary({
        days: url.searchParams.get('days') || 7,
      });
      json(response, result.ok ? 200 : 503, result);
      return;
    }

    if (request.method === 'GET' && pathname === '/api/admin/persistence') {
      const result = await toolHandlers.getAdminPersistenceStatus();
      json(response, 200, {
        ...result,
        state: {
          status: buildStateSnapshot().status,
        },
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/admin/reconcile-inbound-leads', '/api/admin/leads/reconcile-inbound'])) {
      const body = await readBody(request);
      const result = await reconcileInboundLeadProfiles(body);
      json(response, result.ok ? 200 : 207, result);
      return;
    }

    if (request.method === 'GET' && pathname === '/api/admin/activity-log/status') {
      const pool = getPgPool();
      if (!pool) {
        json(response, 200, {
          ok: false,
          result: 'no_database',
          stateBackend: DATABASE_URL ? 'postgres_unavailable' : 'file',
          activityLog: null,
          smokeRows: [],
          state: {
            status: buildStateSnapshot().status,
          },
        });
        return;
      }

      try {
        await ensureActivityLogSchema(pool);
        const summary = await pool.query(
          `SELECT
             to_regclass('public.activity_log')::text AS table_name,
             COUNT(*)::int AS row_count,
             MAX(created_at) AS last_created_at
           FROM public.activity_log`
        );
        const smoke = await pool.query(
          `SELECT id, lead_id, lead_name, category, status, text, created_at
           FROM public.activity_log
           WHERE lead_id = $1
           ORDER BY created_at DESC
           LIMIT 5`,
          ['hosted-activity-smoke']
        );

        json(response, 200, {
          ok: true,
          result: 'live',
          activityLog: summary.rows[0] || null,
          smokeRows: smoke.rows || [],
          state: {
            status: buildStateSnapshot().status,
          },
        });
      } catch (error) {
        json(response, 500, {
          ok: false,
          result: 'error',
          error: error?.message || String(error),
          state: {
            status: buildStateSnapshot().status,
          },
        });
      }
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/agentops/metrics', '/api/agent-ops/metrics'])) {
      const result = await summarizeAgentOpsMetrics({
        days: url.searchParams.get('days') || url.searchParams.get('windowDays') || 1,
      });
      json(response, result.ok ? 200 : 503, {
        ...result,
        state: {
          status: buildStateSnapshot().status,
        },
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/nurture/run-due', '/api/nurture/process-due'])) {
      const body = await readBody(request);
      const result = await toolHandlers.processDueNurtureSteps(body);
      json(response, result.ok ? 200 : 202, {
        ...result,
        state: {
          status: buildStateSnapshot().status,
        },
      });
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/nurture/health', '/api/v1/nurture/health'])) {
      json(response, 200, {
        ...buildNurtureComplianceHealth(process.env),
        generatedAt: isoNow(),
        state: {
          status: buildStateSnapshot().status,
        },
      });
      return;
    }

    if (['GET', 'POST'].includes(request.method) && matchesPath(pathname, ['/api/admin/schema/status', '/api/admin/schema/ensure'])) {
      const pool = getPgPool();
      const requiredTables = ['bridge_state', 'approvals', 'pbk_memories', 'pbk_feedback', 'pbk_intent_events', 'pbk_knowledge', 'pbk_tool_usage', 'pbk_local_commands', 'pbk_tasks', 'pbk_qa_audit', 'agent_registry', 'event_dead_letters', 'pbk_rex_autonomy_runs', 'pbk_safety_audit', 'pbk_eval_runs', 'test_cases', 'pbk_turn_latency', 'pbk_observability_alerts', 'pbk_goal_trajectories', 'pbk_action_intents', 'pbk_memory_curation_events', 'pbk_mission_resilience_eval_runs', 'agent_ops', 'generated_tools', 'agent_teams', 'skills', 'skill_usage', 'skill_definitions', 'skill_versions', 'skill_approvals', 'agent_skill_assignments', 'skill_activations', 'skill_audit_events', 'skill_projection_outbox', 'lead_profiles', 'lead_imports', 'calls', 'contract_path_templates', 'contracts', 'nurture_sequence_templates', 'nurture_instances', 'nurture_step_logs', 'pbk_research_additive_runs', 'pbk_research_additive_provider_checks', 'conversation_threads', 'conversation_thread_identities', 'conversation_events', 'communication_sender_identities', 'provider_action_dispatches'];
      if (!pool) {
        json(response, 200, {
          ok: false,
          result: 'no_database',
          requiredTables: requiredTables.map((table) => ({ table, exists: false })),
          skillGovernance: getSkillGovernanceHealthMeta(),
          error: 'PBK_DATABASE_URL/DATABASE_URL is not configured for this bridge.',
          state: {
            status: buildStateSnapshot().status,
          },
        });
        return;
      }

      try {
        if (request.method === 'POST' || pathname.endsWith('/ensure')) {
          await ensurePgSchema();
        }
        const result = await pool.query(
          `SELECT table_name AS table, to_regclass('public.' || table_name)::text AS regclass
           FROM unnest($1::text[]) AS table_name`,
          [requiredTables]
        );
        const tables = (result.rows || []).map((row) => ({
          table: row.table,
          exists: Boolean(row.regclass),
          regclass: row.regclass || null,
        }));
        json(response, 200, {
          ok: tables.every((row) => row.exists),
          result: tables.every((row) => row.exists) ? 'live' : 'missing_tables',
          ensured: request.method === 'POST' || pathname.endsWith('/ensure'),
          requiredTables: tables,
          skillGovernance: getSkillGovernanceHealthMeta(),
          state: {
            status: buildStateSnapshot().status,
          },
        });
      } catch (error) {
        json(response, 500, {
          ok: false,
          result: 'error',
          error: error?.message || String(error),
          state: {
            status: buildStateSnapshot().status,
          },
        });
      }
      return;
    }

    if (request.method === 'GET' && pathname === '/api/admin/docusign/status') {
      const result = await toolHandlers.getDocuSignProviderStatus({
        liveAuth: ['1', 'true', 'yes'].includes(String(url.searchParams.get('liveAuth') || url.searchParams.get('live') || '').toLowerCase()),
      });
      json(response, 200, {
        ...result,
        state: {
          status: buildStateSnapshot().status,
        },
      });
      return;
    }

    const telnyxMessageStatusMatch = matchPath(pathname, '/api/admin/telnyx/messages/:id/status');
    if (request.method === 'GET' && telnyxMessageStatusMatch) {
      const result = await getTelnyxMessageDeliveryStatus(telnyxMessageStatusMatch.groups.id);
      json(response, result.ok ? 200 : Number(result.status || 502), {
        ...result,
        state: {
          status: buildStateSnapshot().status,
        },
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/admin/route') {
      const body = await readBody(request);
      const result = await toolHandlers.routeAdminCommand(body);
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/admin/request') {
      const body = await readBody(request);
      const result = await toolHandlers.requestAdminAction(body);
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const adminTaskMatch = matchPath(pathname, '/api/admin/tasks/:id');
    if (adminTaskMatch && request.method === 'PUT') {
      const body = await readBody(request);
      const task = state.adminTasks.find((item) => item.id === adminTaskMatch.groups.id);
      if (!task) {
        json(response, 404, {
          ok: false,
          error: `Admin task ${adminTaskMatch.groups.id} was not found.`,
        });
        return;
      }

      const requestedStatus = normalizeApprovalDecisionStatus(body.status || body.action || task.status);
      const statusBefore = task.status;
      task.status = requestedStatus;
      task.updatedAt = isoNow();
      task.actor = body.actor || 'api';
      task.notes = body.notes || task.notes || '';

      let execution = null;
      if (['approved', 'executing', 'complete'].includes(String(task.status).toLowerCase())) {
        const executionOverrides = {
          ...body,
          dryRun: body.dryRun ?? (String(requestedStatus).toLowerCase() === 'approved' ? false : task.dryRun),
        };
        execution = await executeAdminTask(task, executionOverrides);
        if (String(task.status).toLowerCase() === 'approved') task.status = execution.ok ? 'complete' : 'warning';
        recordAdminExecution(task, execution, {
          statusBefore,
          statusAfter: task.status,
          requestedBy: task.actor,
        });
      }

      addAdminAudit(state, {
        id: `audit-${task.id}-${Date.now()}`,
        action: task.action,
        provider: task.provider,
        actor: task.actor,
        status: task.status,
        summary: `${task.notes || `${task.provider}:${task.action} moved to ${task.status}`}${execution?.details ? ` · ${execution.details}` : ''}`,
        createdAt: isoNow(),
        updatedAt: isoNow(),
      });
      addActivity(
        state,
        makeActivity({
          actor: task.actor || 'api',
          category: 'ADMIN',
          status: task.status === 'complete' ? 'success' : task.status,
          text: `${task.provider}:${task.action} is now ${task.status}.`,
          target: task.command || `${task.provider}:${task.action}`,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        task,
        execution,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/approvals') {
      const statusFilter = String(url.searchParams.get('status') || '')
        .trim()
        .toLowerCase();
      const limit = Math.max(1, Math.min(100, Number(url.searchParams.get('limit') || 60)));
      const includeState = ['1', 'true', 'yes'].includes(
        String(url.searchParams.get('includeState') || '')
          .trim()
          .toLowerCase()
      );
      const includeDemo = ['1', 'true', 'yes'].includes(
        String(url.searchParams.get('includeDemo') || url.searchParams.get('includeFixtures') || '')
          .trim()
          .toLowerCase()
      );
      const postgresApprovals = await loadApprovalRecordsFromPg({
        statusFilter,
        limit,
      });
      const stateApprovals = sortNewest(Array.isArray(state.approvals) ? state.approvals : []);
      const mergedApprovalMap = new Map();
      for (const approval of stateApprovals) {
        if (approval?.id) mergedApprovalMap.set(String(approval.id), approval);
      }
      if (postgresApprovals.ok) {
        for (const approval of postgresApprovals.rows || []) {
          if (approval?.id) {
            mergedApprovalMap.set(String(approval.id), {
              ...(mergedApprovalMap.get(String(approval.id)) || {}),
              ...approval,
              source: approval.source || mergedApprovalMap.get(String(approval.id))?.source || 'postgres:approvals',
            });
          }
        }
      }
      const allApprovals = sortNewest(Array.from(mergedApprovalMap.values()));
      const visibleApprovals = includeDemo ? allApprovals : allApprovals.filter((approval) => !isDemoRuntimeApproval(approval));
      const filteredApprovals = sortNewest(allApprovals)
        .filter((approval) => includeDemo || !isDemoRuntimeApproval(approval))
        .filter((approval) => !statusFilter || String(approval.status || '').toLowerCase() === statusFilter)
        .slice(0, limit);
      const pendingAdminTasks = sortNewest(Array.isArray(state.adminTasks) ? state.adminTasks : [])
        .filter((task) => String(task.status || '').toLowerCase() === 'pending')
        .slice(0, limit);
      json(response, 200, {
        ok: true,
        result: 'live',
        source: postgresApprovals.ok ? 'postgres:approvals+bridge-state' : 'bridge-state',
        warning: postgresApprovals.ok ? '' : `Postgres approvals unavailable (${postgresApprovals.error || postgresApprovals.reason || 'unknown_error'}); showing bridge-state approvals.`,
        status: statusFilter || 'all',
        count: filteredApprovals.length,
        rawApprovalCount: allApprovals.length,
        hiddenDemoApprovalCount: includeDemo ? 0 : allApprovals.length - visibleApprovals.length,
        includeDemo,
        approvals: filteredApprovals,
        adminTasks: pendingAdminTasks,
        stateIncluded: includeState,
        ...(includeState ? { state: buildStateSnapshot() } : {}),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/approvals') {
      const body = await readBody(request);
      const result = await toolHandlers.createApproval(body);
      json(response, 200, {
        ok: true,
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const approvalDecisionMatch = matchPath(pathname, '/api/approvals/:id/:decision');
    if (approvalDecisionMatch && request.method === 'POST') {
      const decision = String(approvalDecisionMatch.groups.decision || '')
        .trim()
        .toLowerCase();
      const status = normalizeApprovalDecisionStatus(decision);
      if (!status || (status === decision && !/^(approve|approved|deny|decline|declined|reject|rejected|needs[-_]?revision|modify|review|cancel|canceled|cancelled|dismiss|void)$/i.test(decision))) {
        json(response, 404, {
          ok: false,
          error: `Unsupported approval decision ${decision || '(missing)'}.`,
          state: buildStateSnapshot(),
        });
        return;
      }

      const body = await readBody(request);
      const approval = state.approvals.find((item) => item.id === approvalDecisionMatch.groups.id);
      const teamAuthPresented = hasTeamAuthCredentials(request, body);
      if (teamAuthPresented) {
        const teamAuth = getTeamAuthMeta(request, body);
        if (!teamAuth.ok) {
          json(response, 403, {
            ok: false,
            error: teamAuth.error || 'Team passcode required.',
            configured: Boolean(TEAM_PASSCODE),
            permissions: getTeamPermissions(),
          });
          return;
        }
        const restriction = getTeamApprovalRestriction(approval || {}, status, getTeamPermissions());
        if (restriction) {
          json(response, 403, {
            ok: false,
            error: restriction,
            adminRequired: true,
            permissions: getTeamPermissions(),
          });
          return;
        }
        body.actor = body.actor || teamAuth.actor || 'PBK team';
        body.teamAuth = {
          role: teamAuth.role,
          source: teamAuth.source,
          expiresAt: teamAuth.expiresAt,
        };
      }

      const result = await handleEvent('approval-callback', {
        id: approvalDecisionMatch.groups.id,
        status,
        actor: body.actor || 'api',
        actedAt: body.actedAt || isoNow(),
        notes: body.notes || '',
        reviewReason: body.reviewReason || '',
        falsePositiveTag: body.falsePositiveTag || body.reviewReason || '',
        teamAuth: body.teamAuth || null,
      });
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const approvalMatch = matchPath(pathname, '/api/approvals/:id');
    if (approvalMatch && request.method === 'PUT') {
      const body = await readBody(request);
      const approval = state.approvals.find((item) => item.id === approvalMatch.groups.id);
      const requestedStatus = normalizeApprovalDecisionStatus(body.status || body.action || 'approved');
      const teamAuthPresented = hasTeamAuthCredentials(request, body);
      if (teamAuthPresented) {
        const teamAuth = getTeamAuthMeta(request, body);
        if (!teamAuth.ok) {
          json(response, 403, {
            ok: false,
            error: teamAuth.error || 'Team passcode required.',
            configured: Boolean(TEAM_PASSCODE),
            permissions: getTeamPermissions(),
          });
          return;
        }
        const restriction = getTeamApprovalRestriction(approval || {}, requestedStatus, getTeamPermissions());
        if (restriction) {
          json(response, 403, {
            ok: false,
            error: restriction,
            adminRequired: true,
            permissions: getTeamPermissions(),
          });
          return;
        }
        body.actor = body.actor || teamAuth.actor || 'PBK team';
        body.teamAuth = {
          role: teamAuth.role,
          source: teamAuth.source,
          expiresAt: teamAuth.expiresAt,
        };
      }
      const result = await handleEvent('approval-callback', {
        id: approvalMatch.groups.id,
        status: requestedStatus,
        actor: body.actor || 'api',
        actedAt: body.actedAt || isoNow(),
        notes: body.notes || '',
        reviewReason: body.reviewReason || '',
        falsePositiveTag: body.falsePositiveTag || body.reviewReason || '',
        teamAuth: body.teamAuth || null,
      });
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/dnc') {
      json(response, 200, {
        ok: true,
        dncEntries: state.dncEntries,
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/dnc') {
      const body = await readBody(request);
      const result = await handleEvent('dnc-add', body);
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const dncMatch = matchPath(pathname, '/api/dnc/:id');
    if (dncMatch && request.method === 'DELETE') {
      const result = await handleEvent('dnc-remove', {
        id: dncMatch.groups.id,
        actor: 'api',
      });
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/calls/summary', '/api/v1/calls/summary'])) {
      const kpis = buildRexAutonomyKpiSnapshot({
        targetMonthlyRevenue: url.searchParams.get('targetMonthlyRevenue') || url.searchParams.get('target_monthly_revenue') || undefined,
        revenueDays: url.searchParams.get('revenueDays') || url.searchParams.get('revenue_days') || 30,
      });
      const allCalls = sortNewest(Array.isArray(state.calls) ? state.calls : []);
      json(response, 200, {
        ok: true,
        result: 'calls_summary',
        generatedAt: isoNow(),
        count: allCalls.length,
        calls: {
          total: kpis.totalCalls,
          acceptedOffers: kpis.acceptedOffers,
          conversionRate: kpis.conversionRate,
          recent: allCalls.slice(0, 12),
        },
        rexKpis: kpis,
        topFailureTags: kpis.topFailureTags || [],
        onnxTraining: kpis.onnxTraining || null,
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/calls') {
      const limit = Math.max(1, Math.min(200, Number(url.searchParams.get('limit') || 80)));
      const offset = Math.max(0, Number(url.searchParams.get('offset') || 0));
      const allCalls = sortNewest(Array.isArray(state.calls) ? state.calls : []);
      json(response, 200, {
        ok: true,
        result: 'live',
        count: allCalls.length,
        limit,
        offset,
        calls: allCalls.slice(offset, offset + limit),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/calls') {
      const body = await readBody(request);
      const manualCallBody = {
        ...body,
        manual: body.manual === false ? false : true,
        manualSend: body.manualSend === false ? false : true,
        requestedBy: body.requestedBy || body.requested_by || body.actor || 'PBK operator',
        source: body.source || 'command_center_manual',
      };
      const call = await executeManualProviderRouteWithOutbox({
        toolName: 'telnyx_call',
        provider: 'telnyx',
        channel: 'call',
        params: manualCallBody,
        source: 'calls-route',
        leadId: body.leadId || body.lead_id || body.id || '',
        recipient: body.phone || body.to || body.number || '',
        messageBody: body.reason || body.notes || 'manual call',
        requestedBy: manualCallBody.requestedBy,
      });
      json(response, call.statusCode, call.response);
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/operator/call', '/api/ava/call-operator'])) {
      const body = await readBody(request);
      const routeTool = await executeRouteToolHandler('pbk_call_operator', body, 'operator-call-route');
      json(response, getRouteToolStatusCode(routeTool, { failureStatus: 409 }), buildRouteToolResponse(routeTool));
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/operator/update', '/api/ava/send-update', '/api/updates/send'])) {
      const body = await readBody(request);
      const result = await toolHandlers.pbk_send_update(body);
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/safety/kill-switch', '/api/provider-writes/kill-switch'])) {
      const body = await readBody(request);
      const result = await toolHandlers.pbk_kill_switch(body);
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const callReplayMatch = matchPath(pathname, '/api/calls/:id/replay') || matchPath(pathname, '/api/v1/calls/:id/replay');
    if (callReplayMatch && request.method === 'GET') {
      const result = buildCallReplayBundle(decodeURIComponent(callReplayMatch.groups.id || ''), url.searchParams.get('limit') || 200);
      json(response, result.ok ? 200 : 404, result);
      return;
    }

    const callActionMatch = matchPath(pathname, '/api/calls/:id/action');
    if (callActionMatch && request.method === 'POST') {
      const body = await readBody(request);
      const result = await handleEvent('call-control', {
        id: callActionMatch.groups.id,
        action: body.action,
        target: body.target,
        actor: body.actor || 'api',
      });
      json(response, result.ok === false ? result.statusCode || 502 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/messages') {
      const limit = Math.max(1, Math.min(200, Number(url.searchParams.get('limit') || 80)));
      const offset = Math.max(0, Number(url.searchParams.get('offset') || 0));
      const allMessages = sortNewest(Array.isArray(state.messages) ? state.messages : []);
      json(response, 200, {
        ok: true,
        result: 'live',
        count: allMessages.length,
        limit,
        offset,
        messages: allMessages.slice(offset, offset + limit),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/messages') {
      const body = await readBody(request);
      const scheduledFor = String(body.scheduledFor || body.sendAt || body.scheduled_at || '').trim();
      const wantsSchedule =
        String(body.status || '')
          .trim()
          .toLowerCase() === 'scheduled' ||
        Boolean(body.sendLater && scheduledFor);
      if (wantsSchedule) {
        const context = findLeadContext(body);
        const channel =
          String(body.channel || 'sms')
            .trim()
            .toLowerCase() === 'email'
            ? 'email'
            : 'sms';
        const messageBody = String(body.message || body.body || '').trim();
        const scheduledTime = Date.parse(scheduledFor);
        if (!messageBody) {
          json(response, 400, { ok: false, error: 'Message body is required.' });
          return;
        }
        if (!scheduledFor || Number.isNaN(scheduledTime)) {
          json(response, 400, { ok: false, error: 'A valid scheduledFor datetime is required.' });
          return;
        }
        const recipient =
          channel === 'email'
            ? String(body.email || body.to || context.email || inferSkipTraceContact(context).email || '').trim()
            : normalizePhone(body.phone || body.to || context.phone || inferSkipTraceContact(context).phone);
        if (!recipient) {
          json(response, 400, {
            ok: false,
            error: channel === 'email' ? 'No destination email was available.' : 'No destination phone number was available.',
          });
          return;
        }
        const message = createMessageRecord({
          ...body,
          ...context,
          channel,
          direction: 'outbound',
          body: messageBody,
          status: 'scheduled',
          provider: 'PBK Scheduler',
          ...(channel === 'email' ? { email: recipient } : { phone: recipient }),
        });
        message.to = recipient;
        message.scheduledFor = scheduledFor;
        message.sendAt = scheduledFor;
        message.payload = {
          ...(message.payload || {}),
          scheduled: true,
          scheduledFor,
          requestedFrom: 'inbox-compose',
        };
        upsertMessage(state, message);
        addActivity(
          state,
          makeActivity({
            actor: 'Command Center',
            category: channel === 'email' ? 'EMAIL' : 'SMS',
            status: 'scheduled',
            text: `Outbound ${channel.toUpperCase()} scheduled for ${context.leadName || recipient} at ${scheduledFor}.`,
            target: context.address || recipient,
          })
        );
        await persistState(state);
        json(response, 202, {
          ok: true,
          result: 'scheduled',
          message,
          state: buildStateSnapshot(),
        });
        return;
      }
      const immediateChannel =
        String(body.channel || 'sms')
          .trim()
          .toLowerCase() === 'email'
          ? 'email'
          : 'sms';
      const context = findLeadContext(body);
      const messageBody = String(body.message || body.body || '').trim();
      if (!messageBody) {
        json(response, 400, { ok: false, error: 'Message body is required.' });
        return;
      }
      const manualBody = {
        ...body,
        manual: body.manual === false ? false : true,
        manualSend: body.manualSend === false ? false : true,
        requestedBy: body.requestedBy || body.requested_by || body.actor || 'PBK operator',
        source: body.source || 'unified_inbox_manual',
      };
      if (immediateChannel === 'email') {
        const explicitSubjectMatch = messageBody.match(/^subject:\s*(.+)$/im);
        const subject = body.subject || explicitSubjectMatch?.[1]?.trim() || `Message from Probono Key Realty`;
        const cleanText = messageBody.replace(/^subject:\s*.+\r?\n*/i, '').trim();
        const recipient = body.email || context.email || inferSkipTraceContact(context).email;
        const send = await executeManualProviderRouteWithOutbox({
          toolName: 'sendColdEmail',
          provider: 'instantly',
          channel: 'email',
          params: {
            ...manualBody,
            ...context,
            email: recipient,
            subject,
            body: cleanText,
            customBody: cleanText,
            templateId: body.templateId || 'custom',
          },
          source: 'messages-route',
          leadId: context.leadId,
          recipient,
          messageBody: cleanText,
          subject,
          requestedBy: manualBody.requestedBy,
        });
        json(response, send.statusCode, {
          ...send.response,
          result: send.outbox.status === 'sent' ? 'live' : send.response.result || 'provider_missing',
          verbiage:
            send.outbox.status === 'sent'
              ? 'Email sent or prepared.'
              : send.outbox.error || 'Provider key missing.',
        });
        return;
      }
      const smsRecipient = normalizePhone(body.phone || body.to || context.phone || '');
      const send = await executeManualProviderRouteWithOutbox({
        toolName: 'telnyx_sms',
        provider: 'telnyx',
        channel: 'sms',
        params: {
          ...manualBody,
          ...context,
          phone: smsRecipient,
          to: smsRecipient,
          body: messageBody,
        },
        source: 'messages-route',
        leadId: context.leadId,
        recipient: smsRecipient,
        messageBody,
        requestedBy: manualBody.requestedBy,
      });
      json(response, send.statusCode, {
        ...send.response,
        result: send.outbox.status === 'sent' ? 'live' : send.response.result || 'provider_missing',
        verbiage:
          send.outbox.status === 'sent'
            ? 'SMS sent or queued through Telnyx.'
            : send.outbox.error || 'SMS was recorded without claiming carrier delivery.',
      });
      return;
    }

    const messageArchiveMatch = matchPath(pathname, '/api/messages/:id/archive');
    if (messageArchiveMatch && request.method === 'PATCH') {
      const id = decodeURIComponent(messageArchiveMatch.groups.id || '');
      const body = await readBody(request);
      const existing = findMessageById(id);
      if (!existing) {
        json(response, 404, {
          ok: false,
          result: 'unavailable',
          archived: false,
          messageId: id,
          error: 'Message not found.',
          state: buildStateSnapshot(),
        });
        return;
      }
      const archivedAt = body.archivedAt || body.archived_at || isoNow();
      const message = {
        ...existing,
        status: 'archived',
        archivedAt,
        updatedAt: isoNow(),
        payload: {
          ...(existing.payload || {}),
          archived: true,
          archivedAt,
          archivedBy: body.actor || 'PBK Command Center',
          archiveReason: body.reason || body.archiveReason || 'operator_archive',
        },
      };
      upsertMessage(state, message);
      await persistUnifiedMessageRecord(message);
      addActivity(
        state,
        makeActivity({
          actor: body.actor || 'Command Center',
          category: 'INBOX',
          status: 'archived',
          text: `Archived inbox item for ${existing.leadName || existing.from || existing.email || id}.`,
          target: existing.address || existing.subject || id,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        result: 'archived',
        archived: true,
        message,
        state: buildStateSnapshot(),
      });
      return;
    }

    const messageDeleteMatch = matchPath(pathname, '/api/messages/:id');
    if (messageDeleteMatch && request.method === 'DELETE') {
      const id = decodeURIComponent(messageDeleteMatch.groups.id || '');
      const existing = findMessageById(id);
      if (!existing) {
        json(response, 404, {
          ok: false,
          deleted: false,
          messageId: id,
          error: 'Message not found.',
          state: buildStateSnapshot(),
        });
        return;
      }
      const messageIdentifiers = uniqueLeadLookupValues([existing.id, existing.messageId, existing.callId, existing.telnyxCallControlId, existing.telnyxCallSessionId, id]);
      state.messages = (state.messages || []).filter((message) => {
        const candidates = [message?.id, message?.messageId, message?.callId, message?.telnyxCallControlId, message?.telnyxCallSessionId].map((value) => String(value || '').trim()).filter(Boolean);
        return !candidates.some((value) => messageIdentifiers.includes(value));
      });
      const dbDelete = await deleteUnifiedMessageRecordFromDb(existing, id);
      addActivity(
        state,
        makeActivity({
          actor: 'Command Center',
          category: 'INBOX',
          status: 'deleted',
          text: `Deleted inbox item for ${existing.leadName || existing.from || existing.email || id}.`,
          target: existing.address || existing.subject || id,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        deleted: true,
        messageId: id,
        dbDelete,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/recordings/fixture') {
      const body = await readBody(request);
      const messageId = body.messageId || body.id || 'pbk-recording-fixture';
      const storagePath = buildRecordingStoragePath({
        ...body,
        messageId,
        leadName: body.leadName || 'PBK Sandbox Lead',
        extension: 'wav',
      });
      const audioBytes = createSilentWavBuffer(toNumber(body.durationSeconds || body.duration_seconds, 0.6));
      const upload = await uploadSupabaseRecording({
        storagePath,
        contentType: 'audio/wav',
        bytes: audioBytes,
      });
      if (upload.ok === false) {
        json(response, 501, {
          ...upload,
          messageId,
          storagePath,
          fixture: true,
        });
        return;
      }
      const existing = findMessageById(messageId);
      const message = {
        ...(existing ||
          createMessageRecord({
            ...body,
            id: messageId,
            channel: 'call',
            direction: 'recording',
            provider: 'PBK Fixture',
            status: 'recorded',
            body: 'Sandbox call recording fixture.',
          })),
        ...body,
        id: messageId,
        leadId: body.leadId || existing?.leadId || 'sandbox-lead',
        leadName: body.leadName || existing?.leadName || 'PBK Sandbox Lead',
        address: body.address || existing?.address || 'Sandbox property',
        channel: 'call',
        direction: 'recording',
        provider: 'PBK Fixture',
        status: 'recorded',
        storagePath,
        storageBucket: SUPABASE_CALL_RECORDINGS_BUCKET,
        audioContentType: 'audio/wav',
        durationSeconds: toNumber(body.durationSeconds || body.duration_seconds, 0.6),
        recordingUrl: '',
        payload: {
          ...(existing?.payload && typeof existing.payload === 'object' ? existing.payload : {}),
          fixture: true,
          storagePath,
          storageBucket: SUPABASE_CALL_RECORDINGS_BUCKET,
          contentType: 'audio/wav',
          upload,
        },
        updatedAt: isoNow(),
      };
      upsertMessage(state, message);
      await persistUnifiedMessageRecord(message);
      addActivity(
        state,
        makeActivity({
          actor: body.actor || 'Command Center',
          category: 'CALL',
          status: 'uploaded',
          text: `Sandbox recording fixture uploaded for ${message.leadName}.`,
          target: storagePath,
        })
      );
      await persistState(state);
      const signed = await createSupabaseRecordingSignedUrl(storagePath);
      json(response, 200, {
        ok: true,
        fixture: true,
        message,
        upload,
        signedUrl: signed.ok ? signed.signedUrl : '',
        signed,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/recordings/send-email') {
      const body = await readBody(request);
      const messageId = String(body.messageId || body.id || '').trim();
      const recipientEmail = String(body.email || body.to || body.recipientEmail || '').trim();
      if (!messageId) {
        json(response, 400, { ok: false, error: 'messageId is required.' });
        return;
      }
      if (!recipientEmail || !recipientEmail.includes('@')) {
        json(response, 400, { ok: false, error: 'A valid recipient email is required.' });
        return;
      }

      const message = findMessageById(messageId);
      if (!message) {
        json(response, 404, { ok: false, messageId, error: 'Recording message not found.' });
        return;
      }

      const directUrl = getMessageRecordingUrl(message);
      let signed = null;
      const storagePath = getMessageRecordingPath(message);
      if (!directUrl && isMetadataOnlySmokeRecording(message)) {
        json(response, 501, {
          ok: false,
          configured: true,
          skipped: true,
          reason: 'metadata_only_smoke_recording',
          messageId,
          storagePath,
          error: 'Smoke recording metadata has no uploaded audio object, so PBK skipped Supabase signed URL creation.',
        });
        return;
      }
      if (!directUrl) {
        signed = await createSupabaseRecordingSignedUrl(storagePath, Number(body.expiresIn || body.expiresInSeconds || 7 * 24 * 60 * 60));
        if (signed.ok === false) {
          json(response, 501, {
            ...signed,
            messageId,
            storagePath,
            error: signed.error || 'Could not create a signed recording URL.',
          });
          return;
        }
      }

      const recordingUrl = directUrl || signed?.signedUrl || '';
      const leadName = body.leadName || message.leadName || 'there';
      const note = String(body.message || body.note || 'Here is the secure call recording package we discussed.').trim();
      const subject = String(body.subject || `PBK call recording for ${leadName}`).trim();
      const delivery = await sendTransactionalEmail({
        from: getSenderAddress(body.senderProfile || 'warm'),
        to: recipientEmail,
        subject,
        text: `${note}\n\nSecure recording link: ${recordingUrl}\n\nThis link expires automatically for security.`,
        html: `
          <p>${escapeHtml(note)}</p>
          <p><a href="${escapeHtml(recordingUrl)}">Listen to the secure recording</a></p>
          <p style="color:#6b7280;font-size:12px;">This link expires automatically for security.</p>
        `,
      });

      const deliveryRecord = {
        id: `recording-email-${Date.now()}-${randomUUID().slice(0, 8)}`,
        type: 'recording-email',
        messageId,
        leadId: body.leadId || message.leadId || '',
        leadName,
        to: recipientEmail,
        subject,
        storagePath,
        signedUrlExpiresIn: signed?.expiresIn || 0,
        provider: delivery.provider || 'email',
        live: Boolean(delivery.live),
        ok: Boolean(delivery.ok),
        status: delivery.ok ? 'sent' : 'failed',
        createdAt: isoNow(),
        updatedAt: isoNow(),
      };
      addDocumentDelivery(state, deliveryRecord);
      await persistEmailLogRecord(deliveryRecord);
      upsertMessage(
        state,
        createMessageRecord({
          id: `msg-${deliveryRecord.id}`,
          leadId: deliveryRecord.leadId,
          leadName,
          address: body.address || message.address || '',
          channel: 'email',
          direction: 'outbound',
          provider: delivery.provider || 'Resend',
          status: delivery.ok ? 'sent' : 'failed',
          body: `Recording package sent to ${recipientEmail}.`,
          payload: {
            type: 'recording-email',
            messageId,
            delivery: deliveryRecord,
          },
        })
      );
      addActivity(
        state,
        makeActivity({
          actor: body.actor || 'Command Center',
          category: 'EMAIL',
          status: delivery.ok ? 'sent' : 'failed',
          text: `Recording package ${delivery.ok ? 'sent' : 'attempted'} for ${leadName}.`,
          target: recipientEmail,
        })
      );
      await persistState(state);
      json(response, delivery.ok ? 200 : 502, {
        ok: Boolean(delivery.ok),
        delivery,
        deliveryRecord,
        signed,
        signedUrl: recordingUrl,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/recordings/retention/preview') {
      const result = await runRecordingRetentionCleanup({
        dryRun: true,
        days: Number(url.searchParams.get('days') || 0),
        actor: url.searchParams.get('actor') || 'Command Center',
      });
      json(response, 200, result);
      return;
    }

    if (request.method === 'POST' && pathname === '/api/recordings/retention/run') {
      const body = await readBody(request);
      const result = await runRecordingRetentionCleanup({
        dryRun: body.dryRun ?? true,
        days: Number(body.days || body.retentionDays || 0),
        actor: body.actor || 'Retention worker',
      });
      json(response, 200, result);
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/storage/s3/status', '/api/recordings/s3/status'])) {
      const verify = /^(1|true|yes)$/i.test(String(url.searchParams.get('verify') || '').trim());
      const meta = getS3ArchiveProviderMeta();
      const bucketCheck = verify ? await verifyS3ArchiveBucket() : null;
      json(response, bucketCheck?.ok === false ? 503 : 200, {
        ok: verify ? Boolean(bucketCheck?.ok) : true,
        result: 's3_archive_status',
        s3Archive: meta,
        bucketCheck,
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/recordings/capture') {
      const body = await readBody(request);
      const result = await captureRecordingFromPayload(body);
      json(response, result.ok ? 200 : 501, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const recordingMatch = matchPath(pathname, '/api/recordings/:messageId');
    if (recordingMatch && request.method === 'DELETE') {
      const messageId = decodeURIComponent(recordingMatch.groups.messageId || '');
      const existing = findMessageById(messageId);
      if (!existing) {
        json(response, 404, {
          ok: false,
          deleted: false,
          messageId,
          error: 'Recording message not found.',
          state: buildStateSnapshot(),
        });
        return;
      }
      const storagePath = getMessageRecordingPath(existing);
      const storageDelete = storagePath
        ? await deleteSupabaseRecording(storagePath).catch((error) => ({
            ok: false,
            error: error?.message || String(error),
          }))
        : { ok: true, skipped: true, reason: 'no_storage_path' };
      const s3Archive = getMessageS3Archive(existing);
      const s3Delete = s3Archive?.key
        ? await deleteS3RecordingArchive(s3Archive.key).catch((error) => ({
            ok: false,
            error: error?.message || String(error),
          }))
        : { ok: true, skipped: true, reason: 'no_s3_archive_key' };
      const identifiers = uniqueLeadLookupValues([existing.id, existing.messageId, existing.callId, existing.recordingMessageId, existing.telnyxCallControlId, existing.telnyxCallSessionId, messageId]);
      state.messages = (state.messages || []).filter((message) => {
        const candidates = [message?.id, message?.messageId, message?.callId, message?.recordingMessageId, message?.telnyxCallControlId, message?.telnyxCallSessionId].map((value) => String(value || '').trim()).filter(Boolean);
        return !candidates.some((value) => identifiers.includes(value));
      });
      state.calls = (state.calls || []).map((call) => {
        const candidates = [call?.recordingMessageId, call?.recordingUrl, call?.audioUrl, call?.id].map((value) => String(value || '').trim()).filter(Boolean);
        if (!candidates.some((value) => identifiers.includes(value))) return call;
        return {
          ...call,
          recordingMessageId: '',
          recordingUrl: '',
          audioUrl: '',
          transcript: call.transcript || '',
          updatedAt: isoNow(),
        };
      });
      const dbDelete = await deleteUnifiedMessageRecordFromDb(existing, messageId);
      addActivity(
        state,
        makeActivity({
          actor: 'Command Center',
          category: 'CALL',
          status: 'deleted',
          text: `Deleted recording for ${existing.leadName || existing.from || existing.email || messageId}.`,
          target: storagePath || existing.address || existing.subject || messageId,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        deleted: true,
        messageId,
        storageDelete,
        s3Delete,
        dbDelete,
        state: buildStateSnapshot(),
      });
      return;
    }
    if (recordingMatch && request.method === 'GET') {
      const messageId = decodeURIComponent(recordingMatch.groups.messageId || '');
      const message = findMessageById(messageId);
      if (!message) {
        json(response, 404, { ok: false, messageId, error: 'Recording message not found.' });
        return;
      }
      const directUrl = getMessageRecordingUrl(message);
      if (directUrl) {
        json(response, 200, {
          ok: true,
          messageId,
          source: 'direct-url',
          url: directUrl,
          message,
        });
        return;
      }
      const storagePath = getMessageRecordingPath(message);
      const s3Archive = getMessageS3Archive(message);
      const preferS3 = /^(1|true|yes|s3)$/i.test(String(url.searchParams.get('s3') || url.searchParams.get('source') || '').trim());
      if (preferS3 && s3Archive?.key) {
        const s3Signed = await createS3RecordingSignedUrl(s3Archive.key, Number(url.searchParams.get('expiresIn') || S3_RECORDING_SIGNED_URL_TTL_SECONDS));
        json(response, s3Signed.ok ? 200 : 501, {
          ...s3Signed,
          source: 's3-archive',
          messageId,
          message,
        });
        return;
      }
      if (isMetadataOnlySmokeRecording(message)) {
        json(response, 501, {
          ok: false,
          configured: true,
          skipped: true,
          reason: 'metadata_only_smoke_recording',
          messageId,
          storagePath,
          error: 'Smoke recording metadata has no uploaded audio object, so PBK skipped Supabase signed URL creation.',
          message,
        });
        return;
      }
      const signed = await createSupabaseRecordingSignedUrl(storagePath, Number(url.searchParams.get('expiresIn') || SUPABASE_RECORDING_SIGNED_URL_TTL_SECONDS));
      json(response, signed.ok ? 200 : 501, {
        ...signed,
        s3Archive,
        messageId,
        message,
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/recordings') {
      const body = await readBody(request);
      const recordingIdentitySeed = [
        body.callId || body.call_id || body.telnyxCallControlId || body.call_control_id || '',
        body.providerRecordingId || body.provider_recording_id || '',
        body.recordingUrl || body.audioUrl || body.url || '',
        body.storagePath || body.storage_path || '',
        body.createdAt || body.created_at || body.timestamp || '',
        body.durationSeconds || body.duration_seconds || '',
        body.audioBase64 ? hashString(String(body.audioBase64)) : '',
        body.provider || 'Telnyx',
      ].join('|');
      const messageId =
        body.messageId ||
        body.id ||
        `msg-recording-${Math.abs(hashString(recordingIdentitySeed))}`;
      const recordingCallId =
        body.callId ||
        body.call_id ||
        body.telnyxCallControlId ||
        body.call_control_id ||
        '';
      const contextCall = recordingCallId ? getCallById(recordingCallId) : null;
      const recordingCallDirection = String(
        body.callDirection ||
          body.call_direction ||
          body.payload?.callDirection ||
          contextCall?.direction ||
          (['inbound', 'outbound'].includes(String(body.direction || '').toLowerCase())
            ? body.direction
            : '')
      )
        .trim()
        .toLowerCase();
      const existing = findMessageById(messageId);
      const storagePath = buildRecordingStoragePath({ ...body, messageId });
      const contentType = body.contentType || body.audioContentType || 'audio/mpeg';
      let upload = null;
      if (body.audioBase64) {
        const base64 = String(body.audioBase64).replace(/^data:[^;]+;base64,/i, '');
        upload = await uploadSupabaseRecording({
          storagePath,
          contentType,
          bytes: Buffer.from(base64, 'base64'),
        });
        if (upload.ok === false) {
          json(response, 501, { ...upload, messageId, storagePath });
          return;
        }
      }
      const message = {
        ...(existing ||
          createMessageRecord({
            ...body,
            id: messageId,
            channel: body.channel || 'call',
            direction: 'recording',
            provider: body.provider || 'Telnyx',
            status: body.status || 'recorded',
            body: body.body || 'Call recording captured.',
            phone: body.phone || contextCall?.phone || '',
            from: body.from || contextCall?.from || '',
            to: body.to || contextCall?.to || contextCall?.phone || '',
            callId: recordingCallId || contextCall?.id || '',
            payload: {
              ...(body.payload && typeof body.payload === 'object' ? body.payload : {}),
              callDirection: recordingCallDirection,
            },
          })),
        ...body,
        id: messageId,
        channel: body.channel || existing?.channel || 'call',
        direction: 'recording',
        provider: body.provider || existing?.provider || 'Telnyx',
        status: body.status || existing?.status || 'recorded',
        storagePath,
        storageBucket: SUPABASE_CALL_RECORDINGS_BUCKET,
        audioContentType: contentType,
        durationSeconds: toNumber(body.durationSeconds || body.duration_seconds || existing?.durationSeconds, 0),
        recordingUrl: body.recordingUrl || body.audioUrl || existing?.recordingUrl || '',
        phone: body.phone || existing?.phone || contextCall?.phone || '',
        from: body.from || existing?.from || contextCall?.from || '',
        to: body.to || existing?.to || contextCall?.to || contextCall?.phone || '',
        fromPhone: body.fromPhone || body.from || existing?.fromPhone || existing?.from || contextCall?.from || '',
        toPhone: body.toPhone || body.to || existing?.toPhone || existing?.to || contextCall?.to || contextCall?.phone || '',
        callId: recordingCallId || existing?.callId || contextCall?.id || '',
        payload: {
          ...(existing?.payload && typeof existing.payload === 'object' ? existing.payload : {}),
          ...(body.payload && typeof body.payload === 'object' ? body.payload : {}),
          callDirection: recordingCallDirection || existing?.payload?.callDirection || '',
          storagePath,
          storageBucket: SUPABASE_CALL_RECORDINGS_BUCKET,
          contentType,
          upload,
        },
        updatedAt: isoNow(),
      };
      upsertMessage(state, message);
      await persistUnifiedMessageRecord(message);
      const recordingActivityId = `activity-recording-${messageId}`;
      if (!state.activity.some((entry) => entry.id === recordingActivityId)) {
        addActivity(
          state,
          {
            ...makeActivity({
              actor: body.actor || 'Telnyx',
              category: 'CALL',
              status: upload?.ok ? 'uploaded' : 'recorded',
              text: `Recording metadata saved for ${message.leadName || message.leadId || messageId}`,
              target: storagePath,
            }),
            id: recordingActivityId,
          }
        );
      }
      await persistState(state);
      json(response, 200, {
        ok: true,
        message,
        upload,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && pathname === '/api/contracts') {
      const statusFilter = String(url.searchParams.get('status') || url.searchParams.get('stage') || 'all')
        .trim()
        .toLowerCase();
      const postgresContracts = await loadContractRecordsFromPg({
        statusFilter,
        limit: url.searchParams.get('limit') || 200,
      });
      if (postgresContracts.ok && postgresContracts.rows.length) {
        json(response, 200, {
          ok: true,
          result: 'live',
          status: statusFilter,
          count: postgresContracts.rows.length,
          source: 'postgres:contracts',
          contractsSource: 'postgres:contracts',
          contracts: postgresContracts.rows,
        });
        return;
      }
      const fallbackContracts =
        statusFilter && statusFilter !== 'all'
          ? state.contracts.filter((contract) => {
              const stage = getRuntimeContractStage(contract);
              const status = String(contract.status || '').toLowerCase();
              return stage === statusFilter || status === statusFilter;
            })
          : state.contracts;
      json(response, 200, {
        ok: true,
        result: 'bridge_state_fallback',
        status: statusFilter,
        count: fallbackContracts.length,
        source: 'bridge-state',
        contractsSource: 'bridge-state',
        warning: postgresContracts.ok
          ? 'Postgres contracts is empty; showing bridge-state contract records.'
          : `Postgres contracts unavailable (${postgresContracts.error || postgresContracts.reason || 'unknown_error'}); showing bridge-state contract records.`,
        contracts: fallbackContracts,
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contracts/backfill') {
      const result = await backfillContractRecordsToPg();
      json(response, result.ok ? 200 : result.persisted > 0 ? 207 : 503, {
        ...result,
        source: 'bridge-state',
        target: 'postgres:contracts',
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contracts/draft') {
      const body = await readBody(request);
      const result = await toolHandlers.prepareContract({
        ...body,
        status: body.status || 'draft',
      });
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contracts') {
      const body = await readBody(request);
      const routeTool = await executeRouteToolHandler('sendDocuSign', body, 'contracts-route');
      json(response, getRouteToolStatusCode(routeTool), buildRouteToolResponse(routeTool));
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contracts/docusign/run-due') {
      const body = await readBody(request);
      const result = await runDueDocuSignEnvelopeJobs({
        limit: body.limit || body.max || 5,
      });
      json(response, result.ok ? 200 : result.count > 0 ? 207 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contract/send') {
      const body = await readBody(request);
      const routeTool = await executeRouteToolHandler('prepare_and_send_contract', body, 'contract-send-route');
      json(response, getRouteToolStatusCode(routeTool), buildRouteToolResponse(routeTool));
      return;
    }

    const contractPdfMatch = matchPath(pathname, '/api/contracts/:id/pdf');
    if (contractPdfMatch && request.method === 'GET') {
      const contract = findContractByLookup(contractPdfMatch.groups.id);
      if (!contract) {
        json(response, 404, {
          ok: false,
          error: 'Contract not found.',
          state: buildStateSnapshot(),
        });
        return;
      }

      const pdf = await generatePdfDocument(buildContractPdfPayload(contract));
      const filename = `${safeFilename(contract.documentTitle || contract.leadName || contract.address || contract.id || 'PBK_Contract')}.pdf`;
      sendBinary(response, 200, pdf, {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-store',
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contracts/prepare') {
      const body = await readBody(request);
      const result = await toolHandlers.prepareContract(body);
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/contracts/lawyer-review') {
      const body = await readBody(request);
      const result = await toolHandlers.contractLawyerReview(body);
      json(response, result.ok === false ? 400 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const contractAliasActionMatch = matchPath(pathname, '/api/contracts/:id/:action');
    if (contractAliasActionMatch && request.method === 'POST') {
      const action = String(contractAliasActionMatch.groups.action || '')
        .trim()
        .toLowerCase();
      if (['send', 'remind', 'void'].includes(action)) {
        const body = await readBody(request);
        const contract = findContractByLookup(contractAliasActionMatch.groups.id);
        if (!contract) {
          json(response, 404, {
            ok: false,
            error: 'Contract not found.',
            state: buildStateSnapshot(),
          });
          return;
        }

        if (action === 'send') {
          const payload = {
            ...contract,
            ...body,
            id: contract.id,
            leadId: contract.leadId,
            leadName: contract.leadName,
            address: contract.address,
            email: body.email || contract.email,
            amount: body.amount ?? contract.amount,
          };
          const routeTool = await executeRouteToolHandler('sendDocuSign', payload, 'contract-action-send-route');
          json(response, getRouteToolStatusCode(routeTool), buildRouteToolResponse(routeTool));
          return;
        }

        if (action === 'void') {
          const result = await handleEvent('contract-status', {
            ...body,
            id: contract.id,
            contractId: contract.id,
            envelopeId: contract.envelopeId,
            status: 'void',
            actor: body.actor || 'api',
            leadName: body.leadName || contract.leadName,
            address: body.address || contract.address,
            amount: body.amount ?? contract.amount,
          });
          json(response, result.ok === false ? 404 : 200, {
            ...result,
            state: buildStateSnapshot(),
          });
          return;
        }

        contract.lastReminderAt = isoNow();
        contract.lastReminderActor = body.actor || 'api';
        contract.updatedAt = isoNow();
        await upsertContract(state, contract);
        addActivity(
          state,
          makeActivity({
            actor: body.actor || 'Contracts',
            category: 'CONTRACT',
            status: 'reminder',
            text: `Reminder requested for ${contract.leadName || contract.address || contract.id}.`,
            target: contract.address || contract.leadName || contract.id,
          })
        );
        await persistState(state);
        json(response, 200, {
          ok: true,
          result: 'recorded',
          verbiage: 'Contract reminder recorded in PBK. DocuSign reminder delivery can be attached when provider support is enabled.',
          contract,
          state: buildStateSnapshot(),
        });
        return;
      }
    }

    const contractDocuSignProcessMatch = matchPath(pathname, '/api/contracts/:id/process-docusign');
    if (contractDocuSignProcessMatch && request.method === 'POST') {
      const body = await readBody(request);
      const contractId = contractDocuSignProcessMatch.groups.id;
      const scheduled = docusignEnvelopeJobs.get(String(contractId || '').trim());
      if (scheduled && body.force !== true) {
        json(response, 202, {
          ok: true,
          result: 'docusign_job_already_scheduled',
          queued: true,
          jobId: scheduled.jobId,
          state: buildStateSnapshot(),
        });
        return;
      }
      const result = await processDocuSignEnvelopeJob({
        contractId,
        params: {
          ...body,
          id: contractId,
        },
        jobId: body.docusignJobId || body.jobId || '',
      });
      json(response, result.ok ? 200 : 207, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const contractActionMatch = matchPath(pathname, '/api/contracts/:id/action');
    if (contractActionMatch && request.method === 'POST') {
      const body = await readBody(request);
      const result = await handleEvent('contract-status', {
        id: contractActionMatch.groups.id,
        status: body.status || body.action || 'updated',
        actor: body.actor || 'api',
        leadName: body.leadName,
        address: body.address,
        amount: body.amount,
      });
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    const contractDeleteMatch = matchPath(pathname, '/api/contracts/:id');
    if (contractDeleteMatch && request.method === 'GET') {
      const contract = await loadContractForDocuSignJob(contractDeleteMatch.groups.id);
      if (!contract) {
        json(response, 404, {
          ok: false,
          error: 'Contract not found.',
          state: buildStateSnapshot(),
        });
        return;
      }
      json(response, 200, {
        ok: true,
        result: 'live',
        source: 'postgres:contracts',
        contract,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (contractDeleteMatch && request.method === 'DELETE') {
      const body = await readBody(request);
      const contractId = contractDeleteMatch.groups.id;
      const existingIndex = state.contracts.findIndex((item) => item.id === contractId || item.envelopeId === contractId || item.contractId === contractId);
      if (existingIndex < 0) {
        json(response, 404, {
          ok: false,
          error: 'Contract not found.',
          state: buildStateSnapshot(),
        });
        return;
      }
      const contract = state.contracts[existingIndex];
      const stage = getRuntimeContractStage(contract);
      const removeRecord = body.force === true || ['draft', 'void'].includes(stage);
      if (removeRecord) {
        const deletion = await queryPgRows(`DELETE FROM public.contracts WHERE id = $1`, [
          contract.id,
        ]);
        if (!deletion.ok && deletion.reason !== 'no_database') {
          json(response, 503, {
            ok: false,
            error: deletion.error || 'Canonical contract deletion failed.',
            contract,
            state: buildStateSnapshot(),
          });
          return;
        }
        state.contracts.splice(existingIndex, 1);
      } else {
        const voidedContract = {
          ...contract,
          status: 'void',
          voidReason: body.reason || 'Deleted from PBK Command Center.',
          updatedAt: isoNow(),
        };
        await upsertContract(state, voidedContract);
      }
      addActivity(
        state,
        makeActivity({
          actor: body.actor || 'Contracts',
          category: 'CONTRACT',
          status: removeRecord ? 'deleted' : 'void',
          text: removeRecord ? `${stage === 'draft' ? 'Deleted draft contract' : 'Removed voided contract'} for ${contract.leadName || contract.address || contractId}.` : `Voided contract for ${contract.leadName || contract.address || contractId}.`,
          target: contract.address || contract.leadName || contractId,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        deleted: removeRecord,
        contract: removeRecord ? contract : state.contracts[existingIndex],
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/underwriting/sign') {
      const body = await readBody(request);
      const contractId = body.contractId || body.id;
      const contract = state.contracts.find((item) => item.id === contractId);
      if (!contract) {
        json(response, 404, {
          ok: false,
          error: 'Contract not found for underwriting sign-off.',
        });
        return;
      }

      const signers = [];
      const reviewerEmail = String(body.reviewerEmail || body.underwriterEmail || MAIN_BUSINESS_EMAIL).trim();
      if (reviewerEmail) {
        signers.push({
          name: body.reviewerName || body.underwriterName || 'PBK Underwriting',
          email: reviewerEmail,
        });
      }
      if (contract.email) {
        signers.push({
          name: contract.leadName || 'Seller',
          email: contract.email,
        });
      }

      const routeTool = await executeRouteToolHandler('sendDocuSign', {
        ...contract,
        ...body,
        id: contract.id,
        leadId: contract.leadId,
        leadName: contract.leadName,
        address: contract.address,
        email: contract.email,
        amount: contract.amount,
        notes: body.notes || contract.notes || 'Prepared for underwriting sign-off.',
        signers,
      });
      const result = routeTool.result || {};
      const responseContract = result.contract && typeof result.contract === 'object' ? result.contract : contract;

      const updatedContract = {
        ...responseContract,
        underwritingStatus:
          result.result === 'queued_for_approval' || result.result === 'docusign_queued' || result.queued
            ? 'pending'
            : result.ok
              ? 'sent'
              : 'pending',
        updatedAt: isoNow(),
      };
      await upsertContract(state, updatedContract);
      json(response, getRouteToolStatusCode(routeTool), {
        ...buildRouteToolResponse(routeTool),
        contract: updatedContract,
      });
      return;
    }

    const leadFullMatch = matchPath(pathname, '/api/leads/:id/full');
    if (leadFullMatch && request.method === 'GET') {
      const full = buildLeadFullView(leadFullMatch.groups.id);
      if (!full) {
        json(response, 404, {
          ok: false,
          error: 'Lead not found.',
        });
        return;
      }
      json(response, 200, full);
      return;
    }

    const leadLastCallMatch = matchPath(pathname, '/api/leads/:id/last-call');
    if (leadLastCallMatch && request.method === 'GET') {
      const details = buildLeadLastCallDetails(leadLastCallMatch.groups.id);
      if (!details) {
        json(response, 404, {
          ok: false,
          error: 'Lead not found.',
        });
        return;
      }
      json(response, 200, details);
      return;
    }

    const leadPatchMatch = matchPath(pathname, '/api/leads/:id');
    if (leadPatchMatch && request.method === 'DELETE') {
      const body = await readBody(request);
      const existing = findLeadImportByLookup(leadPatchMatch.groups.id);
      if (!existing) {
        json(response, 404, {
          ok: false,
          error: 'Lead not found.',
          leadId: leadPatchMatch.groups.id,
        });
        return;
      }
      const identifiers = {
        leadId: existing.leadId || leadPatchMatch.groups.id,
        id: existing.id,
        email: existing.seller?.email,
        phone: existing.seller?.phone,
        address: existing.property?.address,
        leadName: existing.seller?.name,
      };
      state.leadImports = (state.leadImports || []).filter((lead) => !leadMatchesIdentifiers(lead, identifiers));
      state.messages = (state.messages || []).filter(
        (item) =>
          !leadMatchesIdentifiers(
            {
              id: item.id,
              leadId: item.leadId,
              seller: { email: item.email, phone: item.phone, name: item.leadName },
              property: { address: item.address },
            },
            identifiers
          )
      );
      state.calls = (state.calls || []).filter(
        (item) =>
          !leadMatchesIdentifiers(
            {
              id: item.id,
              leadId: item.leadId,
              seller: { phone: item.phone, name: item.leadName },
              property: { address: item.address },
            },
            identifiers
          )
      );
      state.appointments = (state.appointments || []).filter(
        (item) =>
          !leadMatchesIdentifiers(
            {
              id: item.id,
              leadId: item.leadId,
              seller: { email: item.email, phone: item.phone, name: item.leadName },
              property: { address: item.address },
            },
            identifiers
          )
      );
      state.contracts = (state.contracts || []).filter(
        (item) =>
          !leadMatchesIdentifiers(
            {
              id: item.id,
              leadId: item.leadId,
              seller: { email: item.email, phone: item.phone, name: item.leadName },
              property: { address: item.address },
            },
            identifiers
          )
      );
      state.analyzerRuns = (state.analyzerRuns || []).filter(
        (item) =>
          !leadMatchesIdentifiers(
            {
              id: item.id,
              leadId: item.leadId,
              seller: { name: item.leadName },
              property: { address: item.address },
            },
            identifiers
          )
      );
      (state.campaigns || []).forEach((campaign) => {
        if (Array.isArray(campaign.leads)) {
          campaign.leads = campaign.leads.filter((lead) => !leadMatchesIdentifiers(lead, identifiers));
          campaign.updatedAt = isoNow();
        }
      });
      await deleteLeadProfileRowFromDb(existing, leadPatchMatch.groups.id);
      addActivity(
        state,
        makeActivity({
          actor: body.actor || 'Lead Detail',
          category: 'CRM',
          status: 'deleted',
          text: `Deleted lead ${existing.seller?.name || existing.leadId || leadPatchMatch.groups.id}.`,
          target: existing.property?.address || existing.seller?.email || existing.seller?.phone || leadPatchMatch.groups.id,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        deleted: true,
        leadId: existing.leadId || existing.id,
        rosterCount: (state.leadImports || []).length,
      });
      return;
    }

    if (leadPatchMatch && request.method === 'PATCH') {
      const body = await readBody(request);
      const existing = findLeadImportByLookup(leadPatchMatch.groups.id);
      const sellerPatch =
        body.seller && typeof body.seller === 'object' && !Array.isArray(body.seller)
          ? body.seller
          : {};
      const propertyPatch =
        body.property && typeof body.property === 'object' && !Array.isArray(body.property)
          ? body.property
          : {};
      const motivationPatch =
        body.motivation &&
        typeof body.motivation === 'object' &&
        !Array.isArray(body.motivation)
          ? body.motivation
          : {};
      const compliancePatch =
        body.compliance &&
        typeof body.compliance === 'object' &&
        !Array.isArray(body.compliance)
          ? body.compliance
          : {};
      const assignmentPatch =
        body.assignment &&
        typeof body.assignment === 'object' &&
        !Array.isArray(body.assignment)
          ? body.assignment
          : {};
      const analyzerPatch =
        body.analyzer && typeof body.analyzer === 'object' && !Array.isArray(body.analyzer)
          ? body.analyzer
          : {};
      const dealPatch =
        body.deal && typeof body.deal === 'object' && !Array.isArray(body.deal)
          ? body.deal
          : {};
      const agentDealContextPatch =
        body.agentDealContext &&
        typeof body.agentDealContext === 'object' &&
        !Array.isArray(body.agentDealContext)
          ? body.agentDealContext
          : {};
      const incomingCallContext =
        body.call_metadata || body.callMetadata || body.callContext || body.call_context;
      const callMetadataPatch =
        incomingCallContext &&
        typeof incomingCallContext === 'object' &&
        !Array.isArray(incomingCallContext)
          ? incomingCallContext
          : {};
      const existingNotesRecord =
        existing?.notes &&
        typeof existing.notes === 'object' &&
        !Array.isArray(existing.notes)
          ? existing.notes
          : null;
      const incomingNotesRecord =
        body.notes && typeof body.notes === 'object' && !Array.isArray(body.notes)
          ? body.notes
          : null;
      const nextNotes =
        existingNotesRecord || incomingNotesRecord
          ? {
              ...(existingNotesRecord || {}),
              ...(incomingNotesRecord || {}),
              ...(body.sellerNotes !== undefined ? { seller: body.sellerNotes } : {}),
              ...(body.internalNotes !== undefined
                ? { internal: body.internalNotes }
                : typeof body.notes === 'string'
                  ? { internal: body.notes }
                  : {}),
            }
          : body.internalNotes !== undefined
            ? body.internalNotes
            : body.notes !== undefined
              ? body.notes
              : existing?.notes;
      const currentCallContext = existing?.callContext || existing?.call_context || {};
      const selectedPath = normalizePbkDealPath(body.selected_path || body.selectedPath || body.path || currentCallContext.selected_path || currentCallContext.selectedPath, existing ? inferLeadSelectedPath(existing) : 'cash');
      const nextBant = parseBantPayload(body.bant, existing?.bant || {});
      const callContextPatch = {
        ...currentCallContext,
        ...callMetadataPatch,
        bant: parseBantPayload(callMetadataPatch.bant, nextBant),
        selected_path: selectedPath,
        selectedPath,
        selectedPathLabel: getPathDisplayLabel(selectedPath),
      };
      if (body.last_offer !== undefined || body.lastOffer !== undefined) {
        callContextPatch.last_offer = body.last_offer ?? body.lastOffer;
        callContextPatch.lastOffer = body.last_offer ?? body.lastOffer;
      }
      if (body.sentiment !== undefined) {
        callContextPatch.sentiment = body.sentiment;
      }
      if (body.summary !== undefined || body.callSummary !== undefined) {
        callContextPatch.summary = body.summary ?? body.callSummary;
      }
      const nextLead = normalizeLeadIntake({
        ...(existing || {}),
        id: existing?.id || leadPatchMatch.groups.id,
        leadId: existing?.leadId || leadPatchMatch.groups.id,
        source: body.source || existing?.source || 'manual',
        leadSource: body.leadSource || body.lead_source || body.source || existing?.leadSource || existing?.lead_source || existing?.source || 'manual',
        status: body.status || existing?.status || existing?.stage || 'working',
        stage: body.stage || existing?.stage || existing?.status || 'working',
        score: body.motivation_score ?? body.motivationScore ?? existing?.score,
        seller: {
          ...(existing?.seller || {}),
          ...sellerPatch,
          ...compactObject({
            name: body.name ?? body.leadName,
            phone: body.phone,
            email: body.email,
            notes: body.sellerNotes,
            preferredChannel: body.preferredChannel,
            bestTimeToCall: body.bestTimeToCall,
            relationshipToProperty: body.relationship,
          }),
        },
        property: {
          ...(existing?.property || {}),
          ...propertyPatch,
          ...compactObject({
            address: body.address ?? body.propertyAddress,
            propertyType: body.property_type ?? body.propertyType,
            type: body.property_type ?? body.propertyType,
            askingPrice: body.askingPrice,
            city: body.city,
            state: body.state,
            zip: body.zip ?? body.zipCode,
            occupancy: body.occupancy,
            condition: body.condition,
            beds: body.beds,
            baths: body.baths,
            sqft: body.sqft,
            yearBuilt: body.yearBuilt,
            arv: body.arv,
            mao: body.mao,
            estimatedRepairs: body.estimatedRepairs,
            mortgageBalance: body.mortgageBalance,
          }),
        },
        motivation: {
          ...(existing?.motivation || {}),
          ...motivationPatch,
          ...compactObject({
            summary:
              typeof body.motivation === 'string'
                ? body.motivation
                : body.motivation_summary,
            timeline: body.timeline,
            askingPrice: body.askingPrice,
          }),
        },
        compliance: {
          ...(existing?.compliance || {}),
          ...compliancePatch,
          ...compactObject({
            tcpaConsent: body.tcpaConsent,
            consentStatus: body.tcpaConsent,
            dncStatus: body.dncStatus,
          }),
        },
        assignment: {
          ...(existing?.assignment || {}),
          ...assignmentPatch,
          ...compactObject({
            assignedAgent: body.assignedAgent,
            stage: body.stage,
          }),
        },
        tags: body.tags !== undefined ? normalizeLeadTags(body.tags) : existing?.tags,
        notes:
          typeof nextNotes === 'string'
            ? nextNotes
            : body.internalNotes ?? existing?.internalNotes ?? '',
        sellerNotes:
          body.sellerNotes !== undefined ? body.sellerNotes : existing?.sellerNotes,
        internalNotes:
          body.internalNotes !== undefined ? body.internalNotes : existing?.internalNotes,
        assignedAgent:
          body.assignedAgent !== undefined ? body.assignedAgent : existing?.assignedAgent,
        preferredChannel:
          body.preferredChannel !== undefined
            ? body.preferredChannel
            : existing?.preferredChannel,
        bestTimeToCall:
          body.bestTimeToCall !== undefined ? body.bestTimeToCall : existing?.bestTimeToCall,
        relationship:
          body.relationship !== undefined ? body.relationship : existing?.relationship,
        tcpaConsent:
          body.tcpaConsent !== undefined ? body.tcpaConsent : existing?.tcpaConsent,
        dncStatus: body.dncStatus !== undefined ? body.dncStatus : existing?.dncStatus,
        askingPrice:
          body.askingPrice !== undefined ? body.askingPrice : existing?.askingPrice,
        arv: body.arv !== undefined ? body.arv : existing?.arv,
        mao: body.mao !== undefined ? body.mao : existing?.mao,
        estimatedRepairs:
          body.estimatedRepairs !== undefined
            ? body.estimatedRepairs
            : existing?.estimatedRepairs,
        mortgageBalance:
          body.mortgageBalance !== undefined
            ? body.mortgageBalance
            : existing?.mortgageBalance,
        bant: nextBant,
        callContext: callContextPatch,
        analyzer: Object.keys(analyzerPatch).length
          ? {
              ...(existing?.analyzer || {}),
              ...analyzerPatch,
            }
          : existing?.analyzer,
        deal: Object.keys(dealPatch).length
          ? {
              ...(existing?.deal || {}),
              ...dealPatch,
            }
          : existing?.deal,
        agentDealContext: Object.keys(agentDealContextPatch).length
          ? {
              ...(existing?.agentDealContext || {}),
              ...agentDealContextPatch,
            }
          : existing?.agentDealContext,
        selectedPath,
        selected_path: selectedPath,
        updatedAt: isoNow(),
      });
      nextLead.notes = nextNotes;
      nextLead.motivation = {
        ...(existing?.motivation || {}),
        ...motivationPatch,
        ...(nextLead.motivation || {}),
      };
      nextLead.compliance = {
        ...(existing?.compliance || {}),
        ...compliancePatch,
        ...(nextLead.compliance || {}),
        ...(body.tcpaConsent !== undefined ? { tcpaConsent: body.tcpaConsent } : {}),
      };
      nextLead.assignment = {
        ...(existing?.assignment || {}),
        ...assignmentPatch,
        ...(nextLead.assignment || {}),
        ...(body.stage !== undefined ? { stage: body.stage } : {}),
      };
      syncLeadCompatibilityAliases(nextLead);
      ensureLeadCommitEnvelope(nextLead, body.source || 'lead-detail-edit', {
        actorType: body.actor || 'Lead Detail',
        reason: 'Lead/analyzer profile patch saved to the canonical lead record.',
        patch: {
          seller: sellerPatch,
          property: propertyPatch,
          motivation: motivationPatch,
          compliance: compliancePatch,
          assignment: assignmentPatch,
          analyzer: analyzerPatch,
          deal: dealPatch,
          agentDealContext: agentDealContextPatch,
          callContext: callContextPatch,
          contractContext: nextLead.contractContext || nextLead.contracts,
          approvalContext: nextLead.approvalContext || nextLead.approvals,
        },
        forceNew: true,
      });

      const patched = existing
        ? patchLeadImport(
            state,
            {
              leadId: existing.leadId || leadPatchMatch.groups.id,
              address: existing.property?.address,
              email: existing.seller?.email,
              leadName: existing.seller?.name,
            },
            {
              ...nextLead,
              callContext: callContextPatch,
              call_context: callContextPatch,
              selectedPath,
              selected_path: selectedPath,
            }
          )
        : (addLeadImport(state, nextLead), nextLead);

      await persistLeadProfileRowToDb(patched || nextLead, 'lead-detail-edit');
      const activity = makeActivity({
        actor: body.actor || 'Lead Detail',
        category: 'CRM',
        status: 'saved',
        text: `Updated lead details for ${patched?.seller?.name || nextLead.seller?.name || 'seller'}.`,
        target: patched?.property?.address || nextLead.property?.address || patched?.seller?.email || nextLead.seller?.email || '',
      });
      activity.id = String(
        body.eventId ||
          body.event_id ||
          body.idempotencyKey ||
          request.headers['idempotency-key'] ||
          activity.id
      );
      activity.action = 'updated';
      activity.leadId = patched?.leadId || nextLead.leadId;
      activity.leadName = patched?.seller?.name || nextLead.seller?.name;
      activity.address = patched?.property?.address || nextLead.property?.address;
      addActivity(state, activity);
      await persistState(state);
      await projectLiveConversationRecord({
        record: activity,
        projector: projectActivityEvent,
        source: 'lead-updated',
      });
      json(response, 200, {
        ok: true,
        lead: buildLeadFullView((patched || nextLead).leadId || (patched || nextLead).id)?.lead || patched || nextLead,
        leadCommitEnvelope: (patched || nextLead).leadCommitEnvelope,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/leads/search', '/api/v1/leads/search'])) {
      const query = url.searchParams.get('q') || url.searchParams.get('query') || url.searchParams.get('search') || '';
      const limit = url.searchParams.get('limit') || '8';
      const threshold = url.searchParams.get('threshold') || url.searchParams.get('minSimilarity') || '0.3';
      const postgresLookup = await runFuzzyLeadLookupFromDb({ query, limit, threshold });
      if (postgresLookup.ok) {
        json(response, 200, {
          ...postgresLookup,
          stateOmitted: true,
        });
        return;
      }
      const fallback = searchLeadImports({ query, limit });
      json(response, 200, {
        ...fallback,
        result: 'runtime_fallback',
        postgres: {
          ok: false,
          reason: postgresLookup.reason || postgresLookup.result || 'postgres_unavailable',
          error: postgresLookup.error || '',
        },
        stateOmitted: true,
      });
      return;
    }

    if (request.method === 'GET' && matchesPath(pathname, ['/api/leads', '/api/leads/import'])) {
      json(response, 200, {
        ok: true,
        leadImports: state.leadImports,
        leads: state.leadImports,
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/lead/generate-message') {
      const body = await readBody(request);
      const context = findLeadContext(body);
      const stage = String(body.stage || 'followup')
        .trim()
        .toLowerCase();
      const channel =
        String(body.channel || 'sms')
          .trim()
          .toLowerCase() === 'email'
          ? 'email'
          : 'sms';
      const activity = getRecentLeadActivity(context, body.includeActivity ? body.activity : '');
      const message = buildLeadMessageDraft({ context, channel, stage, activity });
      addActivity(
        state,
        makeActivity({
          actor: 'Ava',
          category: 'MESSAGE',
          status: 'drafted',
          text: `Generated ${channel.toUpperCase()} ${stage} draft for ${context.leadName}.`,
          target: context.address || context.email || context.phone,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        message,
        channel,
        stage,
        activity,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/lead/send-message') {
      const body = await readBody(request);
      const manualBody = {
        ...body,
        manual: body.manual === false ? false : true,
        manualSend: body.manualSend === false ? false : true,
        requestedBy: body.requestedBy || body.requested_by || body.actor || 'PBK operator',
        source: body.source || 'lead_portal_manual',
      };
      const context = findLeadContext(body);
      const channel =
        String(body.channel || 'sms')
          .trim()
          .toLowerCase() === 'email'
          ? 'email'
          : 'sms';
      const messageBody = String(body.message || body.body || '').trim();
      if (!messageBody) {
        json(response, 400, { ok: false, error: 'Message body is required.' });
        return;
      }
      if (channel === 'sms') {
        const send = await executeManualProviderRouteWithOutbox({
          toolName: 'telnyx_sms',
          provider: 'telnyx',
          channel: 'sms',
          params: {
            ...manualBody,
            ...context,
            body: messageBody,
          },
          source: 'lead-send-message',
          leadId: context.leadId,
          recipient: body.phone || context.phone || '',
          messageBody,
          requestedBy: manualBody.requestedBy,
        });
        json(response, send.statusCode, {
          ...send.response,
          result: send.outbox.status === 'sent' ? 'live' : send.response.result || 'provider_missing',
          verbiage:
            send.outbox.status === 'sent'
              ? 'SMS sent or queued through Telnyx.'
              : send.outbox.error || 'SMS was recorded without claiming carrier delivery.',
        });
        return;
      }

      const explicitSubjectMatch = messageBody.match(/^subject:\s*(.+)$/im);
      const subject = body.subject || explicitSubjectMatch?.[1]?.trim() || `Message from Probono Key Realty`;
      const cleanText = messageBody.replace(/^subject:\s*.+\r?\n*/i, '').trim();
      const recipient = body.email || context.email || inferSkipTraceContact(context).email;
      const send = await executeManualProviderRouteWithOutbox({
        toolName: 'sendColdEmail',
        provider: 'instantly',
        channel: 'email',
        params: {
          ...manualBody,
          ...context,
          email: recipient,
          subject,
          body: cleanText,
          customBody: cleanText,
          templateId: body.templateId || 'custom',
        },
        source: 'lead-send-message',
        leadId: context.leadId,
        recipient,
        messageBody: cleanText,
        subject,
        requestedBy: manualBody.requestedBy,
      });
      json(response, send.statusCode, {
        ...send.response,
        result: send.outbox.status === 'sent' ? 'live' : send.response.result || 'provider_missing',
        verbiage:
          send.outbox.status === 'sent'
            ? 'Email sent or prepared.'
            : send.outbox.error || 'Provider key missing.',
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/leads/add-note') {
      const body = await readBody(request);
      const note = String(body.note || '').trim();
      if (!note) {
        json(response, 400, { ok: false, error: 'Missing note.' });
        return;
      }
      const context = findLeadContext(body);
      const activity = makeActivity({
        actor: body.actor || 'Analyzer',
        category: 'NOTE',
        status: 'saved',
        text: note,
        target: context.address || context.leadName,
      });
      activity.id = String(
        body.eventId ||
          body.event_id ||
          body.idempotencyKey ||
          request.headers['idempotency-key'] ||
          activity.id
      );
      activity.leadId = context.leadId;
      activity.leadName = context.leadName;
      activity.phone = context.phone;
      activity.email = context.email;
      activity.callId = String(body.callId || body.call_id || '').trim();
      activity.important = body.important === true;
      activity.source = String(body.source || 'lead-note').trim();
      activity.metadata = {
        ...(body.metadata && typeof body.metadata === 'object' ? body.metadata : {}),
        important: activity.important,
        ...(activity.callId ? { callId: activity.callId } : {}),
      };
      addActivity(state, activity);
      await persistState(state);
      let projection;
      try {
        projection = await projectLiveConversationRecord({
          record: activity,
          projector: projectActivityEvent,
          source: 'lead-note',
        });
      } catch (error) {
        projection = {
          ok: false,
          result: 'projection_failed',
          error: error instanceof Error ? error.message : String(error || 'unknown error'),
        };
        console.warn('[pbk-local-openclaw] lead note timeline projection failed:', projection.error);
      }
      json(response, 200, {
        ok: true,
        activity,
        timelineProjected: projection?.ok === true,
        projectionResult: projection?.result || '',
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/leads/set-followup') {
      const body = await readBody(request);
      const dueDate = String(body.dueDate || body.due_date || '').trim();
      if (!dueDate) {
        json(response, 400, { ok: false, error: 'Missing dueDate.' });
        return;
      }
      const context = findLeadContext(body);
      const reminderType = String(body.reminderType || body.reminder_type || 'call')
        .trim()
        .toLowerCase();
      const followUp = createAppointmentRecord({
        ...body,
        ...context,
        id: body.id || `followup-${slugify(context.leadName || context.address || 'lead')}-${Date.now()}`,
        startTime: dueDate,
        source: 'analyzer-followup',
        status: 'pending',
        notes: `Follow-up via ${reminderType}`,
      });
      upsertAppointment(state, followUp);
      const activity = makeActivity({
        actor: body.actor || 'Analyzer',
        category: 'FOLLOWUP',
        status: 'pending',
        text: `Follow-up set for ${dueDate} via ${reminderType}.`,
        target: context.address || context.leadName,
      });
      activity.leadId = context.leadId;
      activity.leadName = context.leadName;
      addActivity(state, activity);
      await persistState(state);
      json(response, 200, {
        ok: true,
        followUp,
        activity,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/leads', '/api/leads/import'])) {
      const body = await readBody(request);
      const result = await handleManualLeadCreate(body);
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        outcome: 'live',
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/appointments') {
      const body = await readBody(request);
      const routeTool = await executeRouteToolHandler(
        'scheduleAppointment',
        body,
        'appointments-route'
      );
      json(response, getRouteToolStatusCode(routeTool, { failureStatus: 400 }), buildRouteToolResponse(routeTool));
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/api/webhooks/external-events', '/api/v1/webhooks/external-events'])) {
      const auth = verifyExternalWebhookRequest(request);
      if (!auth.ok) {
        json(response, 401, {
          ok: false,
          error: auth.error,
        });
        return;
      }
      const body = await readBody(request);
      const eventType = String(body.eventType || body.event_type || body.event || body.type || 'external-event').trim();
      const result = await handleEvent(eventType, {
        ...(body.payload && typeof body.payload === 'object' ? body.payload : body),
        _source: body._source || body.source || 'external-webhook',
        externalWebhookAuth: auth.method,
      });
      json(response, result.ok === false ? 400 : 202, {
        ok: result.ok !== false,
        accepted: result.ok !== false,
        eventType,
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/webhooks/booking') {
      const body = await readBody(request);
      const result = await handleEvent('booking-confirmed', body);
      json(response, result.ok === false ? 404 : 200, {
        ...result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/webhooks/instantly') {
      const body = await readBody(request);
      const eventType = String(body.event || body.type || body.status || '').toLowerCase();
      const campaignWebhook = recordCampaignWebhookFromPayload('Instantly', body, eventType);
      const context = findLeadContext({
        leadId: body.leadId || body.contact?.leadId,
        leadName: body.name || body.contact?.name,
        email: body.email || body.contact?.email,
        address: body.address || body.contact?.address,
      });

      if (eventType.includes('reply')) {
        const replyBody = getInstantlyReplyText(body);
        const lead = await upsertLeadFromInstantlyReply(body, context, replyBody);
        const leadContext = findLeadContext({
          leadId: lead.leadId || context.leadId,
          leadName: lead.seller?.name || context.leadName,
          email: lead.seller?.email || body.email || context.email,
          phone: lead.seller?.phone || body.phone || body.contact?.phone || '',
          address: lead.property?.address || context.address,
        });
        const messageId =
          body.id ||
          body.message_id ||
          body.messageId ||
          body.event_id ||
          body.eventId ||
          campaignWebhook?.event?.providerEventId ||
          `instantly-reply-${Math.abs(
            hashString(
              [
                body.email || body.contact?.email || context.email,
                body.timestamp || body.occurredAt || '',
                replyBody,
              ].join('|')
            )
          )}`;
        if (await unifiedMessageAlreadyPersisted(messageId)) {
          json(response, 200, {
            ok: true,
            replayed: true,
            result: 'instantly_reply_already_processed',
            leadId: leadContext.leadId,
            messageId,
            campaignWebhook,
            state: buildStateSnapshot(),
          });
          return;
        }
        const message = createMessageRecord({
          id: messageId,
          leadId: leadContext.leadId,
          leadName: leadContext.leadName,
          address: leadContext.address,
          email: leadContext.email || body.email || context.email,
          channel: 'email',
          direction: 'inbound',
          body: replyBody,
          status: 'received',
          provider: 'Instantly',
          payload: {
            eventType,
            campaignWebhookId: campaignWebhook?.id || '',
            source: 'instantly-reply',
          },
        });
        upsertMessage(state, message);
        await persistUnifiedMessageRecord(message);

        await toolHandlers.handleReplyIntent({
          leadId: leadContext.leadId,
          leadName: leadContext.leadName,
          address: leadContext.address,
          email: leadContext.email || body.email || context.email,
          phone: leadContext.phone || body.phone || body.contact?.phone || '',
          body: replyBody,
          channel: 'email',
          provider: 'Instantly',
          startTime: body.startTime || body.bookingTime || '',
          timezone: body.timezone || '',
          bookingUrl: body.bookingUrl || body.calendarUrl || '',
        });
      }

      const instantlyActivity = makeActivity({
        actor: 'Instantly',
        category: 'EMAIL',
        status: eventType.includes('reply') ? 'received' : eventType.includes('open') ? 'opened' : eventType.includes('click') ? 'clicked' : 'queued',
        text: eventType.includes('reply') ? `Cold email reply received from ${context.leadName || body.email || 'lead'}.` : `Instantly webhook: ${eventType || 'event'} for ${context.leadName || body.email || 'lead'}.`,
        target: context.address || body.email || context.leadName,
      });
      instantlyActivity.id =
        body.id ||
        body.event_id ||
        body.eventId ||
        campaignWebhook?.event?.providerEventId ||
        `instantly-event-${Math.abs(
          hashString(
            [
              eventType,
              body.email || body.contact?.email || context.email,
              body.timestamp || body.occurredAt || '',
              body.campaignId || body.campaign_id || '',
            ].join('|')
          )
        )}`;
      instantlyActivity.leadId =
        campaignWebhook?.campaignLead?.leadId ||
        body.leadId ||
        body.contact?.leadId ||
        context.leadId;
      instantlyActivity.email = body.email || body.contact?.email || context.email;
      addActivity(state, instantlyActivity);
      await persistState(state);
      if (!eventType.includes('reply')) {
        await projectLiveConversationRecord({
          record: instantlyActivity,
          projector: projectActivityEvent,
          source: 'instantly-webhook',
        });
      }
      json(response, 200, {
        ok: true,
        campaignWebhook,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/webhooks/email') {
      const body = await readBody(request);
      const context = findLeadContext({
        leadId: body.leadId,
        leadName: body.name || body.fromName,
        email: body.email || body.from,
        address: body.address,
      });
      const messageBody = String(body.body || body.text || body.message || '').trim();

      const message = createMessageRecord({
        id:
          body.id ||
          body.message_id ||
          body.messageId ||
          body.event_id ||
          body.eventId ||
          `email-webhook-${Math.abs(
            hashString(
              [
                body.provider || 'email-webhook',
                body.email || body.from || context.email,
                body.timestamp || body.occurredAt || '',
                messageBody,
              ].join('|')
            )
          )}`,
        leadId: context.leadId,
        leadName: context.leadName,
        address: context.address,
        email: body.email || body.from || context.email,
        from: body.from || body.email || context.email,
        to: body.to || '',
        channel: 'email',
        direction: 'inbound',
        body: messageBody,
        status: 'received',
        provider: body.provider || 'email-webhook',
      });
      upsertMessage(state, message);
      await persistUnifiedMessageRecord(message);

      const replyResult = await toolHandlers.handleReplyIntent({
        leadId: context.leadId,
        leadName: context.leadName,
        address: context.address,
        email: body.email || context.email,
        phone: body.phone || '',
        body: messageBody,
        channel: 'email',
        provider: body.provider || 'email-webhook',
        startTime: body.startTime || body.bookingTime || '',
        timezone: body.timezone || '',
        bookingUrl: body.bookingUrl || body.calendarUrl || '',
      });

      addActivity(
        state,
        makeActivity({
          actor: context.leadName || 'Seller',
          category: 'EMAIL',
          status: replyResult?.reply?.temperature === 'hot' ? 'queued' : 'received',
          text: `Warm email reply received: ${messageBody || '(empty email)'}`,
          target: context.address || body.email || context.leadName,
        })
      );
      await persistState(state);
      json(response, 200, {
        ok: true,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/webhooks/telnyx') {
      const telnyxRequest = await readTelnyxWebhookRequest(request);
      if (!telnyxRequest.ok) {
        json(response, telnyxRequest.status || 401, {
          ok: false,
          error: telnyxRequest.error || telnyxRequest.signature?.error || 'Telnyx webhook rejected.',
          signature: {
            verified: false,
            skipped: Boolean(telnyxRequest.signature?.skipped),
          },
        });
        return;
      }
      const body = telnyxRequest.payload || {};
      if (isTelnyxInboundCallWebhook(body)) {
        const result = await handleAvaInboundRoute(body, { actor: 'Telnyx inbound webhook' });
        json(response, result.result === 'provider_missing' ? 202 : 200, {
          ok: true,
          mappedEvent: 'inbound-call-route',
          result,
          state: buildStateSnapshot(),
        });
        return;
      }
      const mapped = mapTelnyxWebhook(body);
      const campaignWebhook = recordCampaignWebhookFromPayload(
        'Telnyx',
        {
          ...body,
          ...(mapped.payload || {}),
        },
        mapped.eventType
      );
      const result = await handleEvent(mapped.eventType, mapped.payload);
      json(response, result.ok === false ? 404 : 200, {
        ok: true,
        mappedEvent: mapped.eventType,
        campaignWebhook,
        result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && matchesPath(pathname, ['/webhooks/telnyx/recording', '/api/webhooks/telnyx/recording'])) {
      const telnyxRequest = await readTelnyxWebhookRequest(request);
      if (!telnyxRequest.ok) {
        json(response, telnyxRequest.status || 401, {
          ok: false,
          error: telnyxRequest.error || telnyxRequest.signature?.error || 'Telnyx webhook rejected.',
          signature: {
            verified: false,
            skipped: Boolean(telnyxRequest.signature?.skipped),
          },
        });
        return;
      }
      const body = telnyxRequest.payload || {};
      const result = await captureRecordingFromPayload(body);
      json(response, result.ok ? 200 : 501, {
        ok: Boolean(result.ok),
        mappedEvent: 'recording-capture',
        result,
        state: buildStateSnapshot(),
      });
      return;
    }

    if (request.method === 'POST' && pathname === '/api/webhooks/docusign') {
      const docusignRequest = await readDocuSignWebhookRequest(request);
      if (!docusignRequest.ok) {
        json(response, docusignRequest.status || 401, {
          ok: false,
          error: docusignRequest.error || 'DocuSign Connect webhook rejected.',
          signature: {
            verified: false,
            skipped: Boolean(docusignRequest.skipped),
          },
        });
        return;
      }
      const body = docusignRequest.payload || {};
      const mapped = mapDocuSignWebhook(body);
      const campaignWebhook = recordCampaignWebhookFromPayload('DocuSign', body, mapped.eventType);
      const result = await handleEvent(mapped.eventType, mapped.payload);
      json(response, result.ok === false ? 404 : 200, {
        ok: true,
        mappedEvent: mapped.eventType,
        campaignWebhook,
        signature: {
          verified: !docusignRequest.signature?.skipped,
          skipped: Boolean(docusignRequest.signature?.skipped),
        },
        result,
        state: buildStateSnapshot(),
      });
      return;
    }

