const desktopSidecarSockets = new Map();
const pendingSidecarCommands = new Map();
const desktopSidecarEvents = [];
const DESKTOP_SIDECAR_ALLOWED_ACTIONS = new Set(['ping', 'status', 'read_file', 'list_dir', 'screenshot', 'screenshot_ocr', 'type_text', 'llm_query', 'watch_folder']);
const DESKTOP_SIDECAR_STALE_MS = 45 * 1000;
const DESKTOP_SIDECAR_BRIDGE_PING_INTERVAL_MS = 15 * 1000;

function pushDesktopSidecarEvent(event = {}) {
  desktopSidecarEvents.unshift({
    ...event,
    at: event.at || isoNow(),
  });
  desktopSidecarEvents.splice(120);
}

function sendDesktopSidecarSocketMessage(socket, message = {}) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return false;
  try {
    socket.send(JSON.stringify(message));
    return true;
  } catch {
    return false;
  }
}

function parseSidecarTime(value = '') {
  const time = new Date(value || 0).getTime();
  return Number.isFinite(time) ? time : 0;
}

function getDesktopSidecarLastSeenAt(socket) {
  const meta = socket?.meta || {};
  return Math.max(
    parseSidecarTime(meta.lastHeartbeatAt),
    parseSidecarTime(meta.lastMessageAt),
    parseSidecarTime(meta.connectedAt)
  );
}

function isDesktopSidecarSocketFresh(socket) {
  if (!socket || socket.readyState !== WebSocket.OPEN) return false;
  const lastSeen = getDesktopSidecarLastSeenAt(socket);
  return lastSeen > 0 && Date.now() - lastSeen <= DESKTOP_SIDECAR_STALE_MS;
}

function unregisterDesktopSidecarSocket(socket, fallbackSidecarId = '') {
  const sidecarId = String(socket?.meta?.sidecarId || fallbackSidecarId || '').trim();
  if (sidecarId && desktopSidecarSockets.get(sidecarId) === socket) {
    desktopSidecarSockets.delete(sidecarId);
    return sidecarId;
  }
  for (const [id, registeredSocket] of desktopSidecarSockets.entries()) {
    if (registeredSocket === socket) {
      desktopSidecarSockets.delete(id);
      return id;
    }
  }
  return sidecarId;
}

function getDesktopSidecarAuthToken(request, upgradeUrl) {
  return (
    upgradeUrl.searchParams.get('token') ||
    String(request.headers.authorization || '')
      .replace(/^Bearer\s+/i, '')
      .trim() ||
    String(request.headers['x-pbk-sidecar-token'] || '').trim() ||
    String(request.headers['sec-websocket-protocol'] || '')
      .split(',')
      .map((item) => item.trim())
      .find(Boolean) ||
    ''
  );
}

function buildDesktopSidecarStatus() {
  const sidecars = [...desktopSidecarSockets.entries()].map(([sidecarId, socket]) => {
    const lastSeenAt = getDesktopSidecarLastSeenAt(socket);
    const connected = isDesktopSidecarSocketFresh(socket);
    return {
      sidecarId,
      connected,
      stale: socket.readyState !== WebSocket.OPEN || !connected,
      machineName: socket.meta?.machineName || '',
      capabilities: socket.meta?.capabilities || {},
      allowedRootLabels: socket.meta?.allowedRootLabels || [],
      connectedAt: socket.meta?.connectedAt || '',
      lastMessageAt: socket.meta?.lastMessageAt || '',
      lastHeartbeatAt: socket.meta?.lastHeartbeatAt || '',
      lastCommandAt: socket.meta?.lastCommandAt || '',
      ageMs: lastSeenAt ? Math.max(0, Date.now() - lastSeenAt) : null,
    };
  });
  return {
    ok: true,
    result: 'desktop_sidecar_status',
    connected: sidecars.some((sidecar) => sidecar.connected),
    connectedCount: sidecars.filter((sidecar) => sidecar.connected).length,
    sidecars,
    pendingCommands: pendingSidecarCommands.size,
    recentEvents: desktopSidecarEvents.slice(0, 20),
  };
}

function getActiveDesktopSidecar(sidecarId = '') {
  const requested = String(sidecarId || '').trim();
  if (requested) {
    const socket = desktopSidecarSockets.get(requested);
    return isDesktopSidecarSocketFresh(socket) ? socket : null;
  }
  return [...desktopSidecarSockets.values()].find((socket) => isDesktopSidecarSocketFresh(socket)) || null;
}

function validateDesktopSidecarBridgeCommand(params = {}) {
  const action = String(params.action || params.command || '')
    .trim()
    .toLowerCase();
  if (!action || !DESKTOP_SIDECAR_ALLOWED_ACTIONS.has(action)) {
    return { ok: false, error: 'unsupported_sidecar_action', action };
  }
  if (action === 'type_text' && params.allowAutomation !== true && params.allow_automation !== true) {
    return {
      ok: false,
      error: 'automation_requires_explicit_allow',
      action,
      hint: 'Pass allowAutomation:true after human approval before sending desktop automation commands.',
    };
  }
  return { ok: true, action };
}

async function sendDesktopSidecarCommand(params = {}) {
  const validation = validateDesktopSidecarBridgeCommand(params);
  if (!validation.ok) {
    return {
      ok: false,
      result: 'sidecar_command_rejected',
      ...validation,
    };
  }
  const socket = getActiveDesktopSidecar(params.sidecarId || params.sidecar_id);
  if (!socket) {
    return {
      ok: false,
      result: 'no_sidecar_connected',
      connected: false,
      status: buildDesktopSidecarStatus(),
    };
  }
  const commandId = params.id || `sidecar-command-${Date.now()}-${randomUUID().slice(0, 8)}`;
  const payload = {
    ...params,
    id: commandId,
    action: validation.action,
  };
  const waitForResult = params.wait !== false;
  socket.meta = {
    ...(socket.meta || {}),
    lastCommandAt: isoNow(),
  };
  const sent = sendDesktopSidecarSocketMessage(socket, {
    type: 'sidecar.command',
    commandId,
    payload,
    at: isoNow(),
  });
  if (!sent) {
    return { ok: false, result: 'sidecar_send_failed', commandId };
  }
  pushDesktopSidecarEvent({
    type: 'command_sent',
    sidecarId: socket.meta?.sidecarId || '',
    commandId,
    action: validation.action,
  });
  if (!waitForResult) {
    return {
      ok: true,
      result: 'sidecar_command_sent',
      commandId,
      sidecarId: socket.meta?.sidecarId || '',
    };
  }
  return new Promise((resolve) => {
    const timeoutMs = Math.max(1000, Math.min(30000, Number(params.timeoutMs || params.timeout_ms || 12000)));
    const timer = setTimeout(() => {
      pendingSidecarCommands.delete(commandId);
      resolve({
        ok: false,
        result: 'sidecar_command_timeout',
        commandId,
        timeoutMs,
      });
    }, timeoutMs);
    timer.unref?.();
    pendingSidecarCommands.set(commandId, {
      resolve: (message) => {
        clearTimeout(timer);
        resolve({
          ok: message.ok !== false,
          result: message.result || 'sidecar_command_result',
          commandId,
          sidecarId: socket.meta?.sidecarId || '',
          action: validation.action,
          payload: message.payload || {},
          error: message.error || '',
        });
      },
      createdAt: isoNow(),
    });
  });
}

function registerDesktopSidecarPresence(socket, message = {}) {
  const status = message.status || {};
  const sidecarId = String(
    message.sidecarId ||
      status.sidecarId ||
      socket.meta?.sidecarId ||
      `sidecar-${randomUUID().slice(0, 8)}`
  ).trim();
  const previousSocket = desktopSidecarSockets.get(sidecarId);
  if (previousSocket && previousSocket !== socket) {
    unregisterDesktopSidecarSocket(previousSocket, sidecarId);
    try {
      previousSocket.close?.();
    } catch {
      // Best-effort eviction of stale duplicate sidecar registrations.
    }
  }
  if (socket.meta?.sidecarId && socket.meta.sidecarId !== sidecarId) {
    unregisterDesktopSidecarSocket(socket, socket.meta.sidecarId);
  }
  socket.meta = {
    ...(socket.meta || {}),
    sidecarId,
    machineName: status.machineName || message.machineName || socket.meta?.machineName || '',
    capabilities: status.capabilities || socket.meta?.capabilities || {},
    allowedRootLabels: status.allowedRootLabels || socket.meta?.allowedRootLabels || [],
    connectedAt: socket.meta?.connectedAt || isoNow(),
    lastMessageAt: isoNow(),
    lastHeartbeatAt: isoNow(),
  };
  desktopSidecarSockets.set(sidecarId, socket);
  return sidecarId;
}

function handleDesktopSidecarMessage(socket, raw) {
  socket.meta = {
    ...(socket.meta || {}),
    lastMessageAt: isoNow(),
  };
  const message = safeJsonParse(String(raw || ''), {});
  if (message.type === 'sidecar.hello') {
    const sidecarId = registerDesktopSidecarPresence(socket, message);
    pushDesktopSidecarEvent({
      type: 'sidecar_connected',
      sidecarId,
      machineName: socket.meta.machineName,
    });
    sendDesktopSidecarSocketMessage(socket, {
      type: 'sidecar.ready',
      sidecarId,
      bridgeRevision: BUILD_REVISION,
      at: isoNow(),
    });
    return;
  }
  if (message.type === 'sidecar.heartbeat' || message.type === 'sidecar.pong') {
    const sidecarId = registerDesktopSidecarPresence(socket, message);
    if (message.type === 'sidecar.pong') {
      pushDesktopSidecarEvent({
        type: 'sidecar_pong',
        sidecarId,
      });
    }
    return;
  }
  if (message.type === 'sidecar.command.result') {
    const commandId = String(message.commandId || message.id || '').trim();
    const pending = pendingSidecarCommands.get(commandId);
    if (pending) {
      pendingSidecarCommands.delete(commandId);
      pending.resolve(message);
    }
    pushDesktopSidecarEvent({
      type: 'command_result',
      sidecarId: socket.meta?.sidecarId || '',
      commandId,
      action: message.action || '',
      ok: message.ok !== false,
    });
    return;
  }
  if (message.type === 'sidecar.event') {
    pushDesktopSidecarEvent({
      type: message.event || 'sidecar_event',
      sidecarId: socket.meta?.sidecarId || '',
      payload: message.payload || {},
    });
    return;
  }
  if (message.type === 'ping') {
    sendDesktopSidecarSocketMessage(socket, { type: 'pong', at: isoNow() });
  }
}

const desktopSidecarWss = new WebSocketServer({ noServer: true });
desktopSidecarWss.on('connection', (socket, request) => {
  const sidecarId = `sidecar-${Date.now()}-${randomUUID().slice(0, 8)}`;
  socket.meta = {
    sidecarId,
    connectedAt: isoNow(),
    lastMessageAt: '',
  };
  desktopSidecarSockets.set(sidecarId, socket);
  sendDesktopSidecarSocketMessage(socket, {
    type: 'sidecar.bridge_ready',
    sidecarId,
    bridgeRevision: BUILD_REVISION,
    at: isoNow(),
  });
  socket.on('message', (raw) => handleDesktopSidecarMessage(socket, raw));
  socket.on('close', () => {
    const disconnectedSidecarId = unregisterDesktopSidecarSocket(socket, sidecarId);
    pushDesktopSidecarEvent({
      type: 'sidecar_disconnected',
      sidecarId: disconnectedSidecarId,
    });
  });
  socket.on('error', () => {
    unregisterDesktopSidecarSocket(socket, sidecarId);
  });
});

const desktopSidecarHeartbeatTimer = setInterval(() => {
  for (const socket of desktopSidecarWss.clients) {
    if (!isDesktopSidecarSocketFresh(socket)) {
      const sidecarId = unregisterDesktopSidecarSocket(socket);
      pushDesktopSidecarEvent({
        type: 'sidecar_stale_terminated',
        sidecarId,
      });
      try {
        socket.terminate();
      } catch {
        // Socket was already gone.
      }
      continue;
    }
    sendDesktopSidecarSocketMessage(socket, {
      type: 'sidecar.ping',
      at: isoNow(),
    });
  }
}, DESKTOP_SIDECAR_BRIDGE_PING_INTERVAL_MS);
desktopSidecarHeartbeatTimer.unref?.();

const runtimeBrowserWss = new WebSocketServer({
  noServer: true,
  perMessageDeflate: {
    threshold: 1024,
    zlibDeflateOptions: { level: 3 },
  },
});
runtimeBrowserWss.on('connection', (socket) => {
  socket.isAlive = true;
  runtimeWebSocketStats.lastOpenAt = isoNow();
  runtimeBrowserSockets.add(socket);
  sendRuntimeSocketMessage(socket, {
    type: 'ready',
    at: isoNow(),
    service: 'pbk-local-openclaw',
    revision: BUILD_REVISION,
  });
  sendRuntimeSocketMessage(socket, {
    type: 'state',
    reason: 'connected',
    at: isoNow(),
    snapshot: buildStateSnapshot(),
  });
  socket.on('pong', () => {
    socket.isAlive = true;
    runtimeWebSocketStats.lastMessageAt = isoNow();
  });
  socket.on('close', () => {
    runtimeWebSocketStats.lastCloseAt = isoNow();
    runtimeBrowserSockets.delete(socket);
  });
  socket.on('error', () => runtimeBrowserSockets.delete(socket));
  socket.on('message', (raw) => {
    runtimeWebSocketStats.lastMessageAt = isoNow();
    const message = safeJsonParse(String(raw || ''), {});
    if (message?.type === 'ping') {
      sendRuntimeSocketMessage(socket, { type: 'pong', at: isoNow() });
    }
  });
});

const runtimeWsHeartbeatTimer = setInterval(() => {
  for (const socket of runtimeBrowserWss.clients) {
    if (socket.isAlive === false) {
      runtimeWebSocketStats.staleTerminations += 1;
      runtimeBrowserSockets.delete(socket);
      try {
        socket.terminate();
      } catch {
        // Socket was already gone.
      }
      continue;
    }
    socket.isAlive = false;
    try {
      socket.ping();
    } catch {
      runtimeBrowserSockets.delete(socket);
    }
  }
}, OPENCLAW_GATEWAY_HEARTBEAT_INTERVAL_MS);
runtimeWsHeartbeatTimer.unref?.();

server.on('upgrade', (request, socket, head) => {
  const upgradeUrl = new URL(request.url || '/', `http://${request.headers.host || `${HOST}:${PORT}`}`);
  const upgradePath = upgradeUrl.pathname.replace(/\/+$/, '') || '/';
  if (matchesPath(upgradePath, ['/api/webhooks/telnyx/media', '/webhooks/telnyx/media'])) {
    if (TELNYX_MEDIA_STREAM_TOKEN) {
      const providedToken =
        upgradeUrl.searchParams.get('token') ||
        String(request.headers['x-pbk-stream-token'] || '').trim() ||
        String(request.headers.authorization || '')
          .replace(/^Bearer\s+/i, '')
          .trim() ||
        String(request.headers['sec-websocket-protocol'] || '')
          .split(',')
          .map((item) => item.trim())
          .find(Boolean) ||
        '';
      if (providedToken !== TELNYX_MEDIA_STREAM_TOKEN) {
        socket.write('HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n');
        socket.destroy();
        return;
      }
    }

    telnyxDeepgramWss.handleUpgrade(request, socket, head, (ws) => {
      telnyxDeepgramWss.emit('connection', ws, request);
    });
    return;
  }

  if (matchesPath(upgradePath, ['/api/voice/browser/stream', '/api/browser-voice/stream'])) {
    const token = upgradeUrl.searchParams.get('token') || '';
    pruneBrowserVoiceSessions();
    if (!isBrowserVoiceRuntimeEnabled() || !browserVoiceSessions.has(token)) {
      socket.write('HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n');
      socket.destroy();
      return;
    }
    browserVoiceWss.handleUpgrade(request, socket, head, (ws) => {
      browserVoiceWss.emit('connection', ws, request);
    });
    return;
  }

  if (matchesPath(upgradePath, ['/ws/browser', '/api/ws/browser', '/ws/state', '/api/state/stream'])) {
    if (BRIDGE_API_KEY) {
      pruneRuntimeBrowserSessions();
      const providedToken =
        upgradeUrl.searchParams.get('token') ||
        String(request.headers.authorization || '')
          .replace(/^Bearer\s+/i, '')
          .trim();
      const sessionAuthorized = providedToken && runtimeBrowserSessions.has(providedToken);
      const bridgeAuthorized = providedToken && safeCompareString(providedToken, BRIDGE_API_KEY);
      if (!sessionAuthorized && !bridgeAuthorized) {
        socket.write('HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n');
        socket.destroy();
        return;
      }
      if (sessionAuthorized) runtimeBrowserSessions.delete(providedToken);
    }
    runtimeBrowserWss.handleUpgrade(request, socket, head, (ws) => {
      runtimeBrowserWss.emit('connection', ws, request);
    });
    return;
  }

  if (matchesPath(upgradePath, ['/ws/sidecar', '/api/ws/sidecar', '/api/desktop-sidecar/ws'])) {
    const requiredSidecarToken = DESKTOP_SIDECAR_TOKEN || BRIDGE_API_KEY;
    if (requiredSidecarToken) {
      const providedToken = getDesktopSidecarAuthToken(request, upgradeUrl);
      if (!providedToken || !safeCompareString(providedToken, requiredSidecarToken)) {
        socket.write('HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n');
        socket.destroy();
        return;
      }
    }
    desktopSidecarWss.handleUpgrade(request, socket, head, (ws) => {
      desktopSidecarWss.emit('connection', ws, request);
    });
    return;
  }

  socket.destroy();
});

async function withPrewarmTimeout(task, ms, label) {
  let timer = null;
  try {
    return await Promise.race([
      task,
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error(`${label} prewarm timed out`)), ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function prewarmVoiceProviders() {
  if (!VOICE_PREWARM_ENABLED) return;
  const deepgramMeta = getDeepgramProviderMeta(process.env);
  if (deepgramMeta.ready) {
    try {
      const connection = await createDeepgramLiveConnectionWithCircuit(buildBrowserVoiceDeepgramOptions(BROWSER_VOICE_DEEPGRAM_MODEL), process.env);
      await withPrewarmTimeout(
        (async () => {
          connection.connect();
          await connection.waitForOpen();
          connection.close?.();
        })(),
        5000,
        'Deepgram'
      );
      console.log('[pbk-local-openclaw] Deepgram browser voice prewarm ok');
    } catch (error) {
      console.warn('[pbk-local-openclaw] Deepgram prewarm skipped:', error?.message || error);
    }
  }

  const elevenLabsMeta = getElevenLabsProviderMeta();
  if (elevenLabsMeta.ready) {
    try {
      const ttsResponse = await withPrewarmTimeout(
        fetch(`${ELEVENLABS_BASE_URL}/v1/text-to-speech/${encodeURIComponent(ELEVENLABS_VOICE_ID)}`, {
          method: 'POST',
          headers: {
            Accept: 'audio/mpeg',
            'Content-Type': 'application/json',
            'xi-api-key': ELEVENLABS_API_KEY,
          },
          body: JSON.stringify({
            text: String(process.env.PBK_ELEVENLABS_PREWARM_TEXT || 'PBK voice ready.').slice(0, 120),
            model_id: ELEVENLABS_MODEL_ID,
          }),
        }),
        8000,
        'ElevenLabs'
      );
      if (ttsResponse.ok) {
        await ttsResponse.arrayBuffer();
        recordElevenLabsValidation({ ok: true, status: 200, voiceId: ELEVENLABS_VOICE_ID });
        console.log('[pbk-local-openclaw] ElevenLabs TTS prewarm ok');
      } else {
        const errorText = await ttsResponse.text().catch(() => '');
        recordElevenLabsValidation({
          ok: false,
          status: ttsResponse.status,
          voiceId: ELEVENLABS_VOICE_ID,
          error: errorText || `ElevenLabs prewarm returned ${ttsResponse.status}`,
        });
        console.warn('[pbk-local-openclaw] ElevenLabs prewarm returned:', ttsResponse.status);
      }
    } catch (error) {
      console.warn('[pbk-local-openclaw] ElevenLabs prewarm skipped:', error?.message || error);
    }
  }
}

function startEmotionalLearningAutoImprove() {
  const enabled = !/^(0|false|no)$/i.test(String(process.env.PBK_EMOTIONAL_LEARNING_AUTO_IMPROVE || 'true').trim());
  if (!enabled) return;
  const intervalMs = Math.max(60 * 60 * 1000, Number(process.env.PBK_EMOTIONAL_LEARNING_IMPROVE_INTERVAL_MS || 24 * 60 * 60 * 1000));
  const firstDelayMs = Math.max(60 * 1000, Number(process.env.PBK_EMOTIONAL_LEARNING_IMPROVE_FIRST_DELAY_MS || 5 * 60 * 1000));
  const minWeight = Math.max(0.1, Math.min(1, Number(process.env.PBK_EMOTIONAL_LEARNING_PROMOTE_MIN_WEIGHT || 0.65)));
  const run = async (reason = 'scheduled') => {
    try {
      const result = await improveEmotionalLearningMemoryRecord({ minWeight, source: reason });
      if (result.promoted) {
        console.log(`[pbk-local-openclaw] emotional learning ${reason}: promoted ${result.promoted} pattern(s)`);
      }
    } catch (error) {
      console.warn('[pbk-local-openclaw] emotional learning auto-improve skipped:', error?.message || error);
    }
  };
  const firstTimer = setTimeout(() => {
    void run('startup-delay');
  }, firstDelayMs);
  firstTimer.unref?.();
  const interval = setInterval(() => {
    void run('daily');
  }, intervalMs);
  interval.unref?.();
}

let commandCenterClosedLoopSchedulerStarted = false;

function isCommandCenterClosedLoopEnabled() {
  return Boolean(getCommandCenterClosedLoopSettings().enabled);
}

function startCommandCenterClosedLoopScheduler() {
  if (commandCenterClosedLoopSchedulerStarted || !isCommandCenterClosedLoopEnabled()) return;
  commandCenterClosedLoopSchedulerStarted = true;
  const runSafely = async (label, fn) => {
    try {
      const lease = await redisAcquireLease(`closed-loop:${label}`, REDIS_LEASE_TTL_SECONDS);
      if (!lease.ok) {
        console.log(`[pbk-local-openclaw] closed-loop ${label}: skipped, lease held by ${lease.owner || 'another instance'}`);
        return { ok: true, result: 'skipped_redis_lease_held', owner: lease.owner || '' };
      }
      const result = await fn();
      console.log(`[pbk-local-openclaw] closed-loop ${label}: ${result?.result || 'ok'}`);
      return result;
    } catch (error) {
      console.warn(`[pbk-local-openclaw] closed-loop ${label} skipped:`, error?.message || error);
      return null;
    }
  };
  const firstTimer = setTimeout(() => {
    void runSafely('startup-call-analysis', () => analyzeRecentAvaCalls({ actor: 'Rex Call Analyzer', source: 'scheduled-startup', limit: 20 }));
    void runSafely('startup-goal-alignment', () => buildRevenueGoalAlignment({ actor: 'Rex Goal Alignment', source: 'scheduled-startup' }));
    void runSafely('startup-rex-autonomy', () => runAutonomousRexGoalDiscoveryRecord({ actor: 'Rex Autonomy', source: 'scheduled-startup' }));
  }, COMMAND_CENTER_CLOSED_LOOP_FIRST_DELAY_MS);
  firstTimer.unref?.();

  const callTimer = setInterval(() => {
    void runSafely('hourly-call-analysis', () => analyzeRecentAvaCalls({ actor: 'Rex Call Analyzer', source: 'scheduled-hourly', limit: 30 }));
  }, CALL_ANALYZER_INTERVAL_MS);
  callTimer.unref?.();

  const rexTimer = setInterval(() => {
    void runSafely('daily-goal-alignment', () => buildRevenueGoalAlignment({ actor: 'Rex Goal Alignment', source: 'scheduled-daily' }));
    void runSafely('daily-rex-autonomy', () => runAutonomousRexGoalDiscoveryRecord({ actor: 'Rex Autonomy', source: 'scheduled-daily' }));
  }, REX_GOAL_ALIGNMENT_INTERVAL_MS);
  rexTimer.unref?.();

  const prosodyTimer = setInterval(() => {
    void runSafely('weekly-prosody-training', () => trainAndPersistProsodyModel({ minSamples: 25, source: 'scheduled-weekly' }));
  }, PROSODY_TRAIN_INTERVAL_MS);
  prosodyTimer.unref?.();

  const emotionModelTimer = setInterval(() => {
    void runSafely('weekly-emotion-world-model-export', () => runEmotionWorldModelExportJob({ source: 'scheduled-weekly' }));
  }, PROSODY_TRAIN_INTERVAL_MS);
  emotionModelTimer.unref?.();

  const syntheticEdgeCaseTimer = setInterval(() => {
    void runSafely('weekly-synthetic-edge-cases', () => generateSyntheticEdgeCasesRecord({ count: 50, source: 'scheduled-weekly' }));
  }, SYNTHETIC_EDGE_CASE_INTERVAL_MS);
  syntheticEdgeCaseTimer.unref?.();
}

function startAgentRegistryHealthScheduler() {
  const enabled = !/^(0|false|no)$/i.test(String(process.env.PBK_AGENT_REGISTRY_HEALTH_ENABLED || 'true').trim());
  if (!enabled) return;
  const intervalMs = Math.max(30_000, Number(process.env.PBK_AGENT_REGISTRY_HEALTH_INTERVAL_MS || 60_000));
  const firstDelayMs = Math.max(5_000, Number(process.env.PBK_AGENT_REGISTRY_HEALTH_FIRST_DELAY_MS || 15_000));
  const firstTimer = setTimeout(() => {
    void checkAgentRegistryHealth({ persist: false })
      .then((result) => console.log(`[pbk-local-openclaw] agent registry health: ${result.result}`))
      .catch((error) => console.warn('[pbk-local-openclaw] agent registry health skipped:', error?.message || error));
  }, firstDelayMs);
  firstTimer.unref?.();
  const interval = setInterval(() => {
    void checkAgentRegistryHealth({ persist: false }).catch((error) => console.warn('[pbk-local-openclaw] agent registry health skipped:', error?.message || error));
  }, intervalMs);
  interval.unref?.();
}

server.listen(PORT, HOST, () => {
  startPostgresKeepAlive();
  startContractTemplateWatcher();
  refreshContextAwareScriptCatalog()
    .then((result) => {
      if (result.ok) {
        console.log(
          `[pbk-local-openclaw] context-aware script catalog ready (${result.count}).`
        );
      }
    })
    .catch((error) => {
      console.warn(
        '[pbk-local-openclaw] context-aware script catalog refresh skipped:',
        error?.message || error
      );
    });
  reloadContractTemplateLibrary('startup').catch((error) => {
    console.warn('[pbk-local-openclaw] contract template startup load failed:', error instanceof Error ? error.message : error);
  });
  prewarmVoiceProviders().catch((error) => {
    console.warn('[pbk-local-openclaw] voice provider prewarm failed:', error?.message || error);
  });
  prewarmEmbeddingProvider({ includeFallback: true })
    .then((status) => {
      embeddingProviderRuntimeStatus = {
        ...embeddingProviderRuntimeStatus,
        ...status,
        ready: Boolean(status.ok),
        error: '',
        validatedAt: isoNow(),
      };
      console.log(
        `[pbk-local-openclaw] embedding provider ready: ${status.provider} (${status.model}, ${status.dimensions} dimensions).`
      );
    })
    .catch((error) => {
      embeddingProviderRuntimeStatus = {
        ...embeddingProviderRuntimeStatus,
        ready: false,
        result: 'prewarm_failed',
        error: error?.message || String(error),
        validatedAt: isoNow(),
      };
      console.warn(
        '[pbk-local-openclaw] embedding provider prewarm failed:',
        error?.message || error
      );
    });
  startEmotionalLearningAutoImprove();
  startCommandCenterClosedLoopScheduler();
  startAgentRegistryHealthScheduler();
  if (REDIS_ENABLED) {
    getSharedRedisClient()
      .then((client) => {
        console.log(`[pbk-local-openclaw] Redis shared state ${client?.isOpen ? 'ready' : 'not connected'} (${REDIS_NAMESPACE}).`);
      })
      .catch((error) => {
        console.warn('[pbk-local-openclaw] Redis shared state unavailable:', error?.message || error);
      });
  }
  buildOpenClawGatewayStatus({
    force: true,
    timeoutMs: Math.min(2500, OPENCLAW_GATEWAY_PROBE_TIMEOUT_MS),
  })
    .then((status) => {
      const label = status.ready ? 'ok' : status.directProbeConfigured ? 'degraded' : 'standby';
      const probeLabel = status.directProbeConfigured ? 'gateway probe' : 'gateway heartbeat mode';
      console.log(`[pbk-local-openclaw] OpenClaw ${probeLabel} ${label}: ${status.note}`);
    })
    .catch((error) => {
      console.warn('[pbk-local-openclaw] OpenClaw gateway probe skipped:', error?.message || error);
    });
  console.log(`[pbk-local-openclaw] listening on http://${HOST}:${PORT}`);
  console.log(`[pbk-local-openclaw] state backend: ${STATE_BACKEND}${DATABASE_URL ? ' (postgres)' : ` (file: ${STATE_FILE})`}`);
  console.log(`[pbk-local-openclaw] state file: ${STATE_FILE}`);
  console.log(`[pbk-local-openclaw] tools: ${state.status.tools.join(', ')}`);
  if (APPROVAL_WEBHOOK_URL) {
    console.log(`[pbk-local-openclaw] approval webhook -> ${APPROVAL_WEBHOOK_URL}`);
  }
  if (LEAD_WEBHOOK_URL) {
    console.log(`[pbk-local-openclaw] lead webhook -> ${LEAD_WEBHOOK_URL}`);
  }
});
